window.GRIMORIO_LYRE_SPELLS=[{"id":"lyre-absorb-energy","name":"Absorver Energia","originalName":"Absorb Energy","level":1,"school":"Abjuração","time":"1 reação, realizada quando você sofre dano de ácido, frio, fogo, elétrico ou trovejante","range":"Pessoal","comp":"S","material":"","duration":"1 rodada","classes":"Alma Favorecida, Cavaleiro das Pétalas, Patrulheiro, Druida, Feiticeiro, Mago","ritual":false,"concentration":false,"desc":"A magia captura parte da energia recebida, reduzindo seu efeito sobre você e armazenando-a para o seu próximo ataque corpo a corpo. Você tem resistência ao tipo de dano que desencadeou a reação até o início do seu próximo turno. Além disso, na primeira vez que você acertar um ataque corpo a corpo no seu próximo turno, o alvo sofre 1d6 de dano adicional do tipo que desencadeou a magia, e a magia termina.","higher":"Quando você conjura esta magia usando um espaço de magia de 2º nível ou superior, pode escolher entre os efeitos a seguir para cada nível do espaço acima do 1º:\n• (1 nível de espaço) O dano adicional aumenta em 1d6.\n• (2 níveis de espaço) Sua resistência se torna imunidade.\n• (3 níveis de espaço) Sua resistência se torna absorção parcial: em vez de sofrer dano, você recebe pontos de vida temporários iguais à metade do dano que sofreria do tipo que desencadeou a magia.","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":534,"category":"Lyre's Guide to Retia","traits":["Legado 5.19"],"sourceNote":"A fonte identifica esta entrada como uma magia Legacy/revisada da edição 5.19; suas regras foram preservadas como uma versão própria de Lyre."},{"id":"lyre-acceleration","name":"Aceleração","originalName":"Acceleration","level":2,"school":"Transmutação","time":"1 ação","range":"4,5 metros","comp":"V, S","material":"","duration":"Concentração, até 10 minutos","classes":"Patrulheiro, Bardo, Clérigo, Feiticeiro","ritual":false,"concentration":true,"desc":"Escolha uma criatura dentro do alcance. O deslocamento dela aumenta em 9 metros. Esse aumento é considerado separadamente de quaisquer efeitos que multipliquem ou dividam o deslocamento de uma criatura.","higher":"Quando esta magia é conjurada no 3º nível ou superior, você pode escolher um dos efeitos a seguir para cada nível do espaço acima do 2º:\n• Você pode escolher um alvo adicional.\n• O deslocamento dos seus alvos aumenta em mais 1,5 metro.","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":534,"category":"Lyre's Guide to Retia","traits":["Arcana da Guardiã dos Céus"]},{"id":"lyre-acid-arrow","name":"Flecha Ácida","originalName":"Acid Arrow","level":2,"school":"Evocação","time":"1 ação","range":"27 metros","comp":"V, S, M (folha de ruibarbo em pó e o estômago de uma víbora)","material":"folha de ruibarbo em pó e o estômago de uma víbora","duration":"Instantânea","classes":"Mago","ritual":false,"concentration":false,"desc":"Uma flecha verde cintilante dispara em direção a um alvo dentro do alcance e explode em um jato de ácido. Faça um ataque à distância com magia contra o alvo. Se acertar, o alvo sofre imediatamente 4d4 de dano ácido e mais 2d4 de dano ácido ao final do próximo turno dele. Se errar, a flecha respinga ácido no alvo, causando metade do dano inicial e nenhum dano ao final do próximo turno dele.","higher":"Quando você conjura esta magia usando um espaço de magia de 3º nível ou superior, pode escolher um dos efeitos a seguir para cada nível do espaço acima do 2º:\n• O dano inicial e o dano posterior aumentam em 1d4.\n• Você pode escolher um alvo adicional dentro do alcance para uma flecha separada.\n• Se errar, o respingo também força cada criatura a até 1,5 metro do alvo a realizar um teste de resistência de Destreza, sofrendo o mesmo dano reduzido do alvo em caso de falha.","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":534,"category":"Lyre's Guide to Retia","traits":["Legado 5.19"],"sourceNote":"A fonte identifica esta entrada como uma magia Legacy/revisada da edição 5.19; suas regras foram preservadas como uma versão própria de Lyre."},{"id":"lyre-agitated-pulse","name":"Pulso Agitado","originalName":"Agitated Pulse","level":3,"school":"Evocação","time":"1 ação","range":"Pessoal","comp":"S","material":"","duration":"Concentração, até 1 minuto","classes":"Cavaleiro das Pétalas, Druida, Bruxo","ritual":false,"concentration":true,"desc":"Você libera uma onda rodopiante de energia de força em um raio de 1,5 metro ao seu redor. Cada criatura hostil nessa área deve realizar um teste de resistência de Força. Em uma falha, a criatura é empurrada para fora do raio e sofre 4d6 de dano de energia. Uma criatura que seja movida à força ou teletransportada para dentro da área durante a duração deve realizar o mesmo teste; em uma falha, também fica caída ou impedida, à sua escolha, até sair da área. Ataques feitos contra você por criaturas que estejam fora da área têm desvantagem.","higher":"Quando você conjura esta magia usando um espaço de magia de nível superior, escolha um dos efeitos a seguir para cada nível do espaço acima do nível base:\n• O raio aumenta em 1,5 metro.\n• O dano aumenta em 2d6.","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":534,"category":"Lyre's Guide to Retia","traits":["Grimório do Espreitador"]},{"id":"lyre-animal-commune","name":"Comunhão Animal","originalName":"Animal Commune","level":1,"school":"Adivinhação","time":"1 ação","range":"Toque","comp":"V, S, M (um pouco de pelo envolto em um pano)","material":"um pouco de pelo envolto em um pano","duration":"Concentração, até 10 minutos","classes":"Druida","ritual":false,"concentration":true,"desc":"Você estabelece um elo telepático com uma besta amistosa ou enfeitiçada que possa ver e que tenha Inteligência inferior a 4. Enquanto vocês permanecerem na linha de visão um do outro, você pode enviar mensagens e emoções telepaticamente à besta e compreender as respostas dela, mesmo que ela não compartilhe um idioma com você. Além disso, a besta tem vantagem em jogadas de ataque contra criaturas a até 1,5 metro de você que você possa ver.","higher":"Quando você conjura esta magia usando um espaço de magia de nível superior, pode escolher um dos efeitos a seguir para cada nível do espaço acima do nível base:\n• A besta recebe 5 pontos de vida temporários.\n• (2 níveis de espaço) Você pode incluir uma besta adicional no elo.\n• A duração aumenta para 1 hora, 8 horas, 24 horas ou 1 semana, avançando um passo para cada escolha deste benefício.\n• O elo pode ser mantido sem linha de visão enquanto vocês estiverem a até 18 metros um do outro; cada escolha adicional deste benefício dobra esse alcance.","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":534,"category":"Lyre's Guide to Retia","traits":["Legado 5.19","Tomo da Madeira Sussurrante"],"sourceNote":"A fonte identifica esta entrada como uma magia Legacy/revisada da edição 5.19; suas regras foram preservadas como uma versão própria de Lyre."},{"id":"lyre-anger-of-the-sky-keeper","name":"Ira da Guardiã do Céu","originalName":"Anger of the Sky-Keeper","level":5,"school":"Conjuração","time":"1 ação","range":"raio de 6 metros","comp":"V, S, M (uma haste de obsidiana com pelo menos 30 centímetros de comprimento)","material":"uma haste de obsidiana com pelo menos 30 centímetros de comprimento","duration":"Concentração, até 1 minuto","classes":"Alma Favorecida, Inscritor, Feiticeiro, Mago","ritual":false,"concentration":true,"desc":"Uma tempestade de relâmpagos carmesins irrompe ao seu redor em um raio de 6 metros. A área fica fortemente obscurecida para criaturas que não sejam você, embora criaturas na borda possam ser percebidas normalmente por sentidos que não dependam de visão. Ataques à distância feitos através da tempestade têm desvantagem. Enquanto a magia durar, você pode usar uma ação bônus para escolher um dos efeitos a seguir:\n• Surto da Tempestade. Criaturas à sua escolha na área devem realizar um teste de resistência de Destreza, sofrendo 3d6 de dano elétrico em uma falha ou metade em um sucesso.\n• Lança de Relâmpago. Faça um ataque à distância com magia contra uma criatura a até o dobro do raio da magia. Em um acerto, ela sofre 3d10 de dano elétrico. Você tem vantagem no ataque se o alvo estiver dentro do raio normal da tempestade.","higher":"Quando você conjura esta magia usando um espaço de magia de nível superior, pode escolher um dos efeitos a seguir para cada nível do espaço acima do nível base:\n• O raio aumenta em 3 metros.\n• O dano do Surto da Tempestade aumenta em 1d6 e o da Lança de Relâmpago em 1d10.\n• Você pode escolher um alvo adicional para a Lança de Relâmpago.\n• Se a magia for conjurada usando um espaço de 7º nível ou superior, criaturas hostis que terminarem o turno dentro da esfera sofrem dano elétrico igual à metade dos dados de dano do Surto da Tempestade.","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":535,"category":"Lyre's Guide to Retia","traits":["Arcana da Guardiã dos Céus"]},{"id":"lyre-antigravity-zone","name":"Zona Antigravidade","originalName":"Antigravity Zone","level":1,"school":"Transmutação","time":"1 ação","range":"36 metros","comp":"V, S","material":"","duration":"Concentração, até 1 minuto","classes":"Inscritor, Cavaleiro das Pétalas, Bardo, Feiticeiro, Bruxo, Mago","ritual":true,"concentration":true,"desc":"Escolha um ponto dentro do alcance. Uma esfera de 4,5 metros de raio centrada nesse ponto passa a ter gravidade reduzida ou nula, conforme sua escolha, durante a duração. Criaturas e objetos dentro da área interagem com a gravidade de acordo com as regras de ambientes de baixa ou zero gravidade do sistema.","higher":"Quando você conjura esta magia usando espaços de nível superior, pode ampliar seus efeitos. Para cada nível do espaço acima do nível base, escolha um benefício: aumentar o raio para 9, 18, 36, 72, 144, 288, 576 ou 1.152 metros; aumentar a duração para 1 hora, 10 horas, 1 dia, 30 dias, 1 ano ou permanente; remover a concentração e permitir encerrar o efeito com uma ação; ou criar pontos adicionais de gravidade alterada, dividindo o raio de cada esfera pela metade para cada ponto extra, arredondando para cima até os 3 metros mais próximos.","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":535,"category":"Lyre's Guide to Retia","traits":["Ritual"]},{"id":"lyre-aphris-fixed-gaze","name":"Olhar Fixo de Aphris","originalName":"Aphris’ Fixed Gaze","level":4,"school":"Adivinhação","time":"1 ação","range":"9 metros","comp":"V, S, M (um pequeno medalhão de prata)","material":"um pequeno medalhão de prata","duration":"Concentração, até 1 dia","classes":"Inscritor, Cavaleiro das Pétalas, Patrulheiro, Clérigo, Bruxo","ritual":false,"concentration":true,"desc":"Escolha criaturas que você possa ver dentro do alcance. Durante a duração, você sempre sabe a direção e a distância de cada alvo e, se ele estiver a até 36 metros de você, sua localização exata. Invisibilidade e tentativas de se esconder não impedem que você o perceba dessa forma. Se você escolher apenas uma criatura como alvo, ela deve realizar um teste de resistência de Carisma. Em uma falha, fica amaldiçoada por sua adoração: você tem vantagem em jogadas de ataque contra ela e em testes de resistência que ela o obrigue a realizar, e você não pode sofrer desvantagem nesses testes e ataques enquanto a magia durar.","higher":"","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":535,"category":"Lyre's Guide to Retia","traits":[]},{"id":"lyre-arbitrary-adaptation","name":"Adaptação Arbitrária","originalName":"Arbitrary Adaptation","level":4,"school":"Abjuração","time":"1 ação","range":"9 metros","comp":"V, S","material":"","duration":"Concentração, até 1 minuto","classes":"Inscritor, Cavaleiro das Pétalas, Druida, Feiticeiro","ritual":false,"concentration":true,"desc":"Escolha você e até três criaturas dentro do alcance, além de uma criatura que você possa ver a até 36 metros. Cada criatura escolhida recebe +1 na Classe de Armadura e em testes de resistência contra efeitos originados pela criatura designada. Quando uma criatura beneficiada for atingida por um ataque ou falhar em um teste de resistência provocado pela criatura designada, ela pode usar a reação para encerrar a magia sobre si e rolar um d20, substituindo o resultado original pelo novo resultado caso ele seja mais favorável.","higher":"Quando você conjura esta magia usando um espaço de nível superior, escolha um benefício para cada nível do espaço acima do nível base:\n• O bônus de CA aumenta em +1.\n• A cada duas escolhas deste benefício, o bônus nos testes de resistência aumenta em +1.\n• Você pode beneficiar uma criatura adicional.\n• Você pode designar uma ameaça adicional.","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":535,"category":"Lyre's Guide to Retia","traits":["Sangue de Cineris"]},{"id":"lyre-arcana-abjurative","name":"Arcano Abjurativo","originalName":"Arcana Abjurative","level":3,"school":"Abjuração","time":"1 ação","range":"3 metros","comp":"V, S, M (um pergaminho de magia contendo uma magia de 3º nível ou superior, que esta magia consome)","material":"um pergaminho de magia contendo uma magia de 3º nível ou superior, que esta magia consome","duration":"1 hora","classes":"Inscritor, Bardo, Mago","ritual":false,"concentration":false,"desc":"Escolha uma criatura dentro do alcance. Durante 1 hora, ela tem vantagem em testes de resistência contra magias e outros efeitos mágicos.","higher":"Quando você conjura esta magia usando um espaço de magia de 4º nível ou superior, pode escolher uma criatura adicional para cada nível do espaço acima do 3º.","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":536,"category":"Lyre's Guide to Retia","traits":["Arcana da Guardiã dos Céus"]},{"id":"lyre-arcane-lucubration","name":"Lucubração Arcana","originalName":"Arcane Lucubration","level":2,"school":"Adivinhação","time":"1 ação bônus","range":"Pessoal","comp":"V, S","material":"","duration":"1 hora","classes":"Alma Favorecida, Inscritor, Mago","ritual":false,"concentration":false,"desc":"Escolha duas magias que você poderia preparar, mas que não estão preparadas no momento. Durante a duração desta magia, você pode conjurá-las como se estivessem preparadas, seguindo normalmente todas as outras regras de conjuração.","higher":"Quando você conjura esta magia usando um espaço de magia de nível superior, pode escolher uma magia adicional para cada nível do espaço acima do nível base.","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":536,"category":"Lyre's Guide to Retia","traits":["Memórias de Ossenheimer"]},{"id":"lyre-archfiend-step","name":"Passo do Arquidiabo","originalName":"Archfiend Step","level":6,"school":"Conjuração","time":"1 ação","range":"15 metros","comp":"V, S, M (um pequeno saco de pó de carvão e um único fósforo)","material":"um pequeno saco de pó de carvão e um único fósforo","duration":"1 rodada","classes":"Inscritor, Feiticeiro, Bruxo","ritual":false,"concentration":false,"desc":"Você se teletransporta para um espaço desocupado adjacente a uma criatura que possa ver dentro do alcance e realiza um ataque corpo a corpo com magia contra ela. Em um acerto, o alvo sofre 10d12 de dano de energia cromática. Depois do ataque, você se torna etéreo à armamentação mundana até o início do seu próximo turno: você é imune a dano de concussão, perfurante e cortante causado por ataques não eidólicos.","higher":"","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":536,"category":"Lyre's Guide to Retia","traits":["Convocação Cromática"],"sourceNote":"Regra de grupo — Convocação Cromática: quando a magia mencionar energia ou dano cromático, escolha fogo, frio, ácido, elétrico ou veneno; a escolha vale para todas as ocorrências daquela invocação. Ao conjurar uma magia da Convocação Cromática, faça um teste com o atributo de conjuração (CD 10 + nível da magia). Em uma falha, seu máximo de pontos de vida é reduzido em duas vezes o nível da magia até concluir um Descanso Longo; a fonte chama esse efeito de Queima da Alma. A característica de conjuração da criatura pode dispensá-la desse teste."},{"id":"lyre-arteminas-hunting-bow","name":"Arco de Caça de Artemina","originalName":"Artemina’s Hunting Bow","level":9,"school":"Conjuração","time":"1 ação","range":"Pessoal","comp":"V, S","material":"","duration":"Concentração, até 1 hora","classes":"Inscritor, Druida, Feiticeiro, Bruxo","ritual":false,"concentration":true,"desc":"Você conjura um arco longo mágico e três flechas de mithral. Ao conjurar a magia, e novamente conforme permitido por seus efeitos, você pode disparar essas flechas contra alvos que possa ver a até 180 metros, realizando um ataque à distância com magia para cada uma. Em um acerto, uma flecha causa 4d10 de dano perfurante mais 4d10 de dano de veneno. Na primeira vez em cada turno que uma criatura é atingida, ela deve realizar um teste de resistência de Destreza ou ficar impedida por vinhas que irrompem ao seu redor. Uma criatura Enorme ou maior só fica impedida se for atingida por duas flechas no mesmo turno. Uma criatura impedida pode usar uma ação para realizar um teste de Força contra sua CD de resistência de magia, libertando-se em um sucesso.","higher":"","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":536,"category":"Lyre's Guide to Retia","traits":[]},{"id":"lyre-ash-coat","name":"Manto de Cinzas","originalName":"Ash Coat","level":0,"school":"Encantamento","time":"1 ação bônus","range":"Pessoal","comp":"S","material":"","duration":"Concentração, até 1 minuto","classes":"Inscritor, Bruxo","ritual":false,"concentration":true,"desc":"Cinzas mágicas envolvem sua pele e roupas. Na primeira vez em cada um dos seus turnos que você acertar uma criatura com um ataque corpo a corpo, esse ataque causa 1d6 de dano de fogo adicional. O dado aumenta para 1d8 no 5º nível, 1d10 no 11º nível e 1d12 no 17º nível.","higher":"","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":536,"category":"Lyre's Guide to Retia","traits":["Sangue de Cineris"]},{"id":"lyre-aura-of-returning-glory","name":"Aura da Glória Retornada","originalName":"Aura of Returning Glory","level":4,"school":"Abjuração","time":"1 ação bônus","range":"Pessoal","comp":"V, S","material":"","duration":"1 minuto","classes":"Cavaleiro das Pétalas, Paladino","ritual":false,"concentration":false,"desc":"Uma aura carmesim de glória restaurada o envolve. No início de cada um dos seus turnos, se estiver consciente, você recebe pontos de vida temporários iguais à metade do dano que sofreu desde o início do seu turno anterior; se não tiver sofrido dano nesse período, recebe 2d10 pontos de vida temporários. Enquanto a magia durar, você obtém sucesso automaticamente em testes de resistência contra as condições amedrontado, enfeitiçado e atordoado. Quando você sofrer dano, pode usar sua reação para encerrar esta magia e tornar-se imune a essa instância de dano.","higher":"","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":537,"category":"Lyre's Guide to Retia","traits":["Legado do Ouro"]},{"id":"lyre-avernate-focus","name":"Foco Averniano","originalName":"Avernate Focus","level":4,"school":"Abjuração","time":"1 ação","range":"Pessoal","comp":"V, S, M (uma gema de obsidiana finamente lapidada com sigilos Dracônicos gravados, no valor de pelo menos 500 po, que a magia consome)","material":"uma gema de obsidiana finamente lapidada com sigilos Dracônicos gravados, no valor de pelo menos 500 po, que a magia consome","duration":"Concentração, até 8 horas","classes":"Clérigo, Feiticeiro, Mago","ritual":false,"concentration":true,"desc":"Durante a duração, suas magias são tratadas como se tivessem sido conjuradas usando um espaço de magia dois níveis acima do espaço realmente gasto, até o máximo de 9º nível, para efeitos como dissipar magia, contramágica e outros que verificam o nível da magia. Isso não ativa nem melhora benefícios descritos em seções de “Em Níveis Superiores”. Se você estiver usando um foco arcano que não seja artefato nem item lendário e perder a concentração nesta magia em razão de dano ou de outro efeito externo, role d100. Em 51 ou mais, o foco é destruído.","higher":"","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":537,"category":"Lyre's Guide to Retia","traits":["Convocação Cromática"],"sourceNote":"Regra de grupo — Convocação Cromática: quando a magia mencionar energia ou dano cromático, escolha fogo, frio, ácido, elétrico ou veneno; a escolha vale para todas as ocorrências daquela invocação. Ao conjurar uma magia da Convocação Cromática, faça um teste com o atributo de conjuração (CD 10 + nível da magia). Em uma falha, seu máximo de pontos de vida é reduzido em duas vezes o nível da magia até concluir um Descanso Longo; a fonte chama esse efeito de Queima da Alma. A característica de conjuração da criatura pode dispensá-la desse teste."},{"id":"lyre-bestial-ravage","name":"Devastação Bestial","originalName":"Bestial Ravage","level":0,"school":"Transmutação","time":"1 ação","range":"Pessoal","comp":"S","material":"","duration":"Instantânea","classes":"Lista especial / não especificada","ritual":false,"concentration":false,"desc":"Sua magia primal faz seus dentes, unhas ou outra parte natural do corpo se tornar uma arma brutal. Faça um ataque corpo a corpo com magia contra uma criatura a até 1,5 metro. Em um acerto, ela sofre 1d10 de dano ácido. O dano aumenta para 2d10 no 5º nível, 3d10 no 11º nível e 4d10 no 17º nível.","higher":"","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":537,"category":"Lyre's Guide to Retia","traits":["Legado 5.19"],"sourceNote":"A fonte identifica esta entrada como uma magia Legacy/revisada da edição 5.19; suas regras foram preservadas como uma versão própria de Lyre."},{"id":"lyre-bestow-expertise","name":"Conceder Especialização","originalName":"Bestow Expertise","level":5,"school":"Transmutação","time":"1 ação","range":"Toque","comp":"V, S","material":"","duration":"Concentração, até 1 hora","classes":"Alma Favorecida, Inscritor, Cavaleiro das Pétalas, Bardo, Feiticeiro, Mago","ritual":false,"concentration":true,"desc":"Você toca uma criatura voluntária. Escolha uma perícia na qual ela já seja proficiente. Pela duração da magia, ela possui Especialização nessa perícia, dobrando seu bônus de proficiência nos testes apropriados.","higher":"","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":537,"category":"Lyre's Guide to Retia","traits":["Legado 5.19"],"sourceNote":"A fonte identifica esta entrada como uma magia Legacy/revisada da edição 5.19; suas regras foram preservadas como uma versão própria de Lyre."},{"id":"lyre-blessed-circle","name":"Círculo Abençoado","originalName":"Blessed Circle","level":5,"school":"Abjuração","time":"1 ação","range":"Pessoal (9 metros)","comp":"V, S, M (um amuleto de papel com letras douradas, simbolizando boa sorte)","material":"um amuleto de papel com letras douradas, simbolizando boa sorte","duration":"Concentração, até 10 minutos","classes":"Patrulheiro, Clérigo, Druida","ritual":false,"concentration":true,"desc":"Você cria uma esfera abençoada de 9 metros de raio centrada em você. A esfera impede que gases ou líquidos ambientais indesejados atravessem seus limites, embora ar respirável e gases moderados possam passar. Se você estiver submerso quando a magia for conjurada, você desce com segurança até a superfície sólida mais próxima. Elementais, fadas e yokais — exceto você — ficam protegidos contra a área. Quando uma dessas criaturas tenta entrar na esfera, tenta escolher um alvo dentro dela ou começa o turno no interior, deve realizar um teste de resistência de Carisma. Em uma falha, é forçada para o espaço mais próximo fora da esfera e não pode escolher alvos dentro dela até o início do próximo turno. Se não puder sair, sofre 3d10 de dano psíquico. Se você voluntariamente mover a esfera de modo a sobrepor uma dessas criaturas e terminar seu turno nessa situação, deve realizar um teste de concentração cuja CD é determinada pelo maior ND ou nível entre as criaturas protegidas sobrepostas; em uma falha, a magia termina.","higher":"Quando você conjura esta magia usando um espaço de magia de 6º nível ou superior, o raio da esfera dobra para cada nível do espaço acima do 5º.","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":537,"category":"Lyre's Guide to Retia","traits":["Artes dos Nove Ramos"]},{"id":"lyre-binding-madness","name":"Loucura Vinculante","originalName":"Binding Madness","level":2,"school":"Encantamento","time":"1 ação","range":"36 metros","comp":"V, S","material":"","duration":"Concentração, até 1 minuto","classes":"Bardo, Feiticeiro, Bruxo, Mago","ritual":false,"concentration":true,"desc":"Escolha um humanoide dentro do alcance. Ele deve realizar um teste de resistência de Sabedoria. Em uma falha, fica enfeitiçado por você e uma coroa irregular de ferro e loucura se manifesta ao redor de sua cabeça. No início de cada turno do alvo, antes de ele se mover, você escolhe outra criatura ao alcance corpo a corpo dele; o alvo deve usar sua ação para fazer um ataque corpo a corpo contra essa criatura. Se não houver uma criatura adequada, ele age normalmente. Em cada um dos seus turnos após conjurar a magia, você deve usar sua ação para sustentar a loucura; se não fizer isso, a magia termina. O alvo repete o teste de resistência de Sabedoria ao final de cada um dos turnos, encerrando a magia sobre si em um sucesso.","higher":"Quando você conjura esta magia usando um espaço de magia de nível superior, pode escolher um dos efeitos a seguir para cada nível do espaço acima do nível base:\n• Escolha um alvo adicional.\n• Se uma criatura afetada atacar outra criatura também afetada, a magia termina sobre a criatura atacada.\n• (3 níveis de espaço) Você pode escolher criaturas que não sejam humanoides como alvos.","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":538,"category":"Lyre's Guide to Retia","traits":["Legado 5.19"],"sourceNote":"A fonte identifica esta entrada como uma magia Legacy/revisada da edição 5.19; suas regras foram preservadas como uma versão própria de Lyre."},{"id":"lyre-biting-curse","name":"Maldição Mordaz","originalName":"Biting Curse","level":3,"school":"Necromancia","time":"1 ação","range":"Toque","comp":"V, S","material":"","duration":"Concentração, até 1 minuto","classes":"Alma Favorecida, Bardo, Clérigo, Mago","ritual":false,"concentration":true,"desc":"Você toca uma criatura, que deve ser bem-sucedida em um teste de resistência de Sabedoria ou fica amaldiçoada pela duração da magia. Ao conjurar esta magia, escolha uma das opções a seguir para determinar a natureza da maldição:\n• Escolha um atributo. Enquanto estiver amaldiçoado, o alvo tem desvantagem em testes de atributo e testes de resistência feitos com esse atributo.\n• Enquanto estiver amaldiçoado, o alvo tem desvantagem em jogadas de ataque contra você.\n• Enquanto estiver amaldiçoado, o alvo deve realizar um teste de resistência de Sabedoria no início de cada um de seus turnos. Em uma falha, ele desperdiça sua ação naquele turno sem fazer nada.\n• Enquanto o alvo estiver amaldiçoado, seus ataques e magias causam 1d8 de dano necrótico adicional a ele.\n• Enquanto o alvo estiver amaldiçoado, ele fica cego para qualquer coisa a 9 metros ou mais de distância de si, independentemente de seus sentidos.\n• Enquanto estiver amaldiçoado, o alvo recebe apenas metade da cura que receberia normalmente, e qualquer efeito que restauraria 10 ou menos pontos de vida não restaura nenhum.\nUma magia remover maldição encerra este efeito. Seus efeitos não podem ser removidos por magias que normalmente removam ou dissipem efeitos mágicos, a menos que também afetem maldições. O Mestre pode permitir que você crie efeitos adicionais de maldição além daqueles listados, ou no lugar deles.","higher":"Se você conjurar esta magia no 4º nível ou superior, pode escolher um dos benefícios a seguir para cada nível do espaço acima do 3º:\n• Você pode manter a concentração por até 10 minutos, até 8 horas (2 níveis de espaço), até 24 horas (4 níveis de espaço), ou tornar a magia permanente até ser dissipada (6 níveis de espaço). Se a magia durar 8 horas ou mais, ela não exige concentração.\n• Você pode escolher um alvo adicional, que sofre os mesmos efeitos.\n• (2 níveis de espaço) Você pode escolher um efeito adicional para aplicar ao alvo da magia.","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":538,"category":"Lyre's Guide to Retia","traits":["Legado 5.19"],"sourceNote":"A fonte identifica esta entrada como uma magia Legacy/revisada da edição 5.19; suas regras foram preservadas como uma versão própria de Lyre."},{"id":"lyre-blood-of-cineris","name":"Sangue de Cineris","originalName":"Blood of Cineris","level":1,"school":"Evocação","time":"1 ação","range":"Pessoal (raio de 3 metros)","comp":"S","material":"","duration":"1 rodada","classes":"Feiticeiro, Bruxo","ritual":false,"concentration":false,"desc":"Você conjura o sangue ardente de Cineris Clade, espalhando-o em um anel ao seu redor sobre todas as criaturas dentro do alcance da magia. Cada criatura nessa área deve realizar um teste de resistência de Destreza, sofrendo 2d6 de dano de fogo em uma falha ou metade em um sucesso. Qualquer criatura que falhar fica envenenada até o início do seu próximo turno.","higher":"Quando você conjura esta magia no 2º nível ou superior, pode escolher um dos efeitos a seguir para cada nível do espaço acima do 1º:\n• O raio da magia aumenta em 1,5 metro.\n• O dano inicial aumenta em 1d6.\n• Se conjurada no 6º nível ou superior, qualquer criatura que falhar fica envenenada por 1 minuto e sofre 1d6 de dano de fogo no início de cada um de seus turnos enquanto estiver envenenada dessa forma. Ela pode repetir um teste de resistência de Constituição ao final de cada turno, encerrando o efeito em um sucesso.","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":538,"category":"Lyre's Guide to Retia","traits":["Sangue de Cineris"]},{"id":"lyre-boomerang-weapon","name":"Arma Bumerangue","originalName":"Boomerang Weapon","level":2,"school":"Encantamento","time":"1 ação bônus","range":"Toque","comp":"S","material":"","duration":"10 minutos","classes":"Alma Favorecida, Inscritor, Cavaleiro das Pétalas, Patrulheiro, Bardo, Paladino, Mago","ritual":false,"concentration":false,"desc":"Você toca uma arma com a propriedade arremesso, empunhada por você ou por uma criatura voluntária. Pela duração da magia, essa arma é considerada mágica. Sempre que ela for usada para um ataque com arma arremessada e errar, você ou o atacante pode usar a reação para fazer a arma desviar no ar e voar contra outra criatura dentro do alcance normal de arremesso da arma e próxima do alvo inicial. A criatura que a arremessou realiza então outra jogada de ataque contra o novo alvo. Se esse ataque errar, você ou o atacante pode usar a reação para repetir este efeito. Depois de um ataque ser feito com a arma, ela desvia no ar e retorna à criatura que a arremessou, desde que essa criatura ainda esteja dentro do alcance longo da arma.","higher":"Quando você conjura esta magia usando um espaço de magia de 4º nível ou superior, os alcances normal e longo da arma arremessada dobram; eles dobram novamente para cada dois níveis do espaço acima do 4º.","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":538,"category":"Lyre's Guide to Retia","traits":["Grimório do Espreitador"]},{"id":"lyre-burdened-blood","name":"Sangue Sobrecarregado","originalName":"Burdened Blood","level":1,"school":"Evocação","time":"1 ação","range":"9 metros","comp":"V, S","material":"","duration":"Instantânea","classes":"Cavaleiro das Pétalas, Patrulheiro, Clérigo, Feiticeiro, Bruxo","ritual":false,"concentration":false,"desc":"Uma criatura à sua escolha recebe fortitude ampliada, ganhando pontos de vida temporários iguais a 2d6 + seu modificador do atributo de conjuração. Esses pontos de vida temporários desaparecem após 1 minuto. Sempre que essa criatura fizer uma jogada de ataque, ela pode escolher perder 5 desses pontos de vida temporários para obter vantagem nesse ataque e/ou perder outros 5 para anular qualquer desvantagem que teria.","higher":"Quando você conjura esta magia usando um espaço de magia de 2º nível ou superior, os pontos de vida temporários recebidos aumentam em 1d6 para cada nível do espaço acima do 1º.","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":539,"category":"Lyre's Guide to Retia","traits":["Daemoturgia"]},{"id":"lyre-burning-ammunition","name":"Munição Incendiária","originalName":"Burning Ammunition","level":3,"school":"Transmutação","time":"1 ação","range":"27 metros","comp":"V, S","material":"","duration":"Concentração, até 1 hora","classes":"Cavaleiro das Pétalas, Patrulheiro, Druida, Feiticeiro, Mago","ritual":false,"concentration":true,"desc":"Você toca um recipiente ou cinturão de munição contendo flechas ou virotes. Quando um alvo é atingido por um ataque com arma à distância usando uma munição retirada desse recipiente ou cinturão, ele sofre 1d6 de dano de fogo adicional. A magia termina sobre uma munição quando ela acerta ou erra, e a magia inteira termina depois que doze peças de munição forem retiradas.","higher":"Quando você conjura esta magia no 4º nível ou superior, pode escolher um dos efeitos a seguir para cada nível do espaço acima do 3º:\n• O número de munições que você pode afetar aumenta em 2.\n• O dano de fogo adicional passa a 1d8 (1 nível de espaço), 1d10 (2 níveis adicionais de espaço), 1d12 (3 níveis de espaço) ou 2d8 (4 níveis de espaço).","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":539,"category":"Lyre's Guide to Retia","traits":["Legado 5.19"],"sourceNote":"A fonte identifica esta entrada como uma magia Legacy/revisada da edição 5.19; suas regras foram preservadas como uma versão própria de Lyre."},{"id":"lyre-burning-web","name":"Teia Ardente","originalName":"Burning Web","level":5,"school":"Conjuração","time":"1 ação","range":"27 metros","comp":"V, S, M (fio de prata que é queimado durante a conjuração)","material":"fio de prata que é queimado durante a conjuração","duration":"Concentração, até 1 minuto","classes":"Cavaleiro das Pétalas, Druida, Feiticeiro, Mago","ritual":false,"concentration":true,"desc":"Você conjura uma teia de fios ardentes que preenche um cubo de 6 metros centrado em um ponto à sua escolha dentro do alcance, permanecendo pela duração da magia. Qualquer criatura que começar o turno nesse espaço ou entrar nele pela primeira vez em um turno sofre 3d6 de dano de fogo e deve realizar um teste de resistência de Destreza. Em uma falha, a criatura fica impedida até ser bem-sucedida no teste ou começar seu turno fora da teia.","higher":"Quando você conjura esta magia no 6º nível ou superior, pode escolher um dos efeitos a seguir para cada nível do espaço acima do 5º:\n• O dano aumenta em 1d6.\n• Cada lado do cubo aumenta em 3 metros.","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":539,"category":"Lyre's Guide to Retia","traits":["Sangue de Cineris"]},{"id":"lyre-catastrophic-shield","name":"Escudo Catastrófico","originalName":"Catastrophic Shield","level":5,"school":"Abjuração","time":"1 reação, realizada quando dano reduziria você a 0 pontos de vida ou menos","range":"Pessoal","comp":"S","material":"","duration":"Concentração, até 1 rodada","classes":"Cavaleiro das Pétalas, Feiticeiro, Mago","ritual":false,"concentration":true,"desc":"Quando o dano que desencadeia esta magia seria sofrido, você invoca uma barreira esférica de símbolos arcanos laranja e vermelhos. Pela duração, nenhuma fonte de dano pode reduzir você abaixo de 1 ponto de vida. Se um dano o reduziria a 0 pontos de vida, você fica com 1 em vez disso. Você ainda deve realizar testes de concentração como se tivesse sofrido todo o dano, mas permanece protegido contra essas fontes de dano mesmo que falhe no teste de concentração provocado por elas.","higher":"","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":539,"category":"Lyre's Guide to Retia","traits":["Artes dos Nove Ramos"]},{"id":"lyre-caustic-resolution","name":"Resolução Cáustica","originalName":"Caustic Resolution","level":3,"school":"Transmutação","time":"1 ação bônus","range":"36 metros","comp":"V, S, M (uma pequena escultura de uma cabeça atravessada por um prego)","material":"uma pequena escultura de uma cabeça atravessada por um prego","duration":"Concentração, até 1 minuto","classes":"Cavaleiro das Pétalas, Patrulheiro, Bardo, Feiticeiro, Mago","ritual":false,"concentration":true,"desc":"Se uma criatura estiver se concentrando em uma magia ou beneficiando-se de um efeito mágico que tenha apenas ela como alvo, você pode tentar fazer o acúmulo de energia mágica corroer sua carne. O alvo deve ser bem-sucedido em um teste de resistência de Constituição. Em uma falha, no início de cada turno em que estiver se concentrando em uma magia ou se beneficiando de um efeito mágico proveniente de magia, ele sofre 1d6 de dano ácido. Durante esse período, a criatura tem desvantagem em testes de concentração. Se perder a concentração ou deixar de se beneficiar de qualquer efeito mágico, esta magia termina imediatamente.","higher":"Quando você conjura esta magia no 5º nível ou superior, o dano sofrido pelo alvo aumenta em 1d6 para cada dois níveis do espaço acima do 3º.","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":539,"category":"Lyre's Guide to Retia","traits":["Daemoturgia"]},{"id":"lyre-ceremonial-rite","name":"Rito Cerimonial","originalName":"Ceremonial Rite","level":1,"school":"Abjuração","time":"1 hora","range":"Toque","comp":"V, S, M (25 po de prata em pó, que a magia consome)","material":"25 po de prata em pó, que a magia consome","duration":"Instantânea","classes":"Alma Favorecida, Clérigo, Paladino","ritual":false,"concentration":false,"desc":"Você realiza uma cerimônia religiosa especial imbuída de magia. Ao conjurar a magia, escolha um dos ritos a seguir; o alvo deve permanecer a até 3 metros de você durante toda a conjuração.\nExpiação. Você toca uma criatura voluntária cujo alinhamento tenha sido alterado e realiza um teste de Sabedoria (Intuição) CD 20. Em um sucesso, restaura o alinhamento original do alvo.\nDespertar. Você toca uma criatura que esteja com 0 pontos de vida, mas estável. Ela desperta, recuperando pontos de vida iguais a 2d8 × o nível em que esta magia foi conjurada, e imediatamente recebe os benefícios de um Descanso Curto.\nAbençoar Água. Você toca um frasco de água e o transforma em água benta.\nMaioridade. Você toca um humanoide jovem adulto. Pelas próximas 24 horas, sempre que o alvo fizer um teste de atributo, pode rolar 1d4 e adicionar o resultado ao teste. Uma criatura só pode se beneficiar deste rito uma vez.\nDedicação. Você toca um humanoide que deseja se dedicar ao serviço de seu deus. Pelas próximas 24 horas, sempre que o alvo fizer um teste de resistência, pode rolar 1d4 e adicionar o resultado. Uma criatura só pode se beneficiar deste rito uma vez.\nRito Funerário. Você toca um cadáver e, pelos próximos 7 dias, o alvo não pode se tornar um morto-vivo por nenhum meio inferior a uma magia desejo.\nSantificar. Durante a conjuração, você se concentra em um cubo centrado em você cujo lado mede 3 metros × o nível em que a magia foi conjurada. Ao completar a magia, mortos-vivos invisíveis nesse cubo podem ser vistos claramente por 24 horas, e mortos-vivos no Plano Etéreo podem ser afetados e interagidos como se estivessem no Plano Material.\nTratamento. Você toca um frasco de água enquanto estiver a até 3 metros de uma criatura enferma que sofra de veneno ou doença. A água se torna uma bebida medicinal; depois de consumi-la, uma criatura tem vantagem em testes de resistência contra esse veneno ou doença por 7 dias.\nCasamento. Você toca humanoides adultos dispostos a se unirem em matrimônio. Pelos próximos 7 dias, cada alvo recebe +2 na CA enquanto estiver a até 9 metros dos demais. Uma criatura só pode se beneficiar novamente deste rito se tiver ficado viúva; para os fins da magia, esses indivíduos são considerados casados.","higher":"","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":540,"category":"Lyre's Guide to Retia","traits":["Legado 5.19"],"sourceNote":"A fonte identifica esta entrada como uma magia Legacy/revisada da edição 5.19; suas regras foram preservadas como uma versão própria de Lyre."},{"id":"lyre-cernunnos-eye","name":"Olho de Cernunnos","originalName":"Cernunnos Eye","level":1,"school":"Adivinhação","time":"1 ação bônus","range":"18 metros","comp":"S, M (uma esmeralda no valor de pelo menos 100 po)","material":"uma esmeralda no valor de pelo menos 100 po","duration":"Instantânea","classes":"Inscritor, Cavaleiro das Pétalas, Patrulheiro, Druida","ritual":false,"concentration":false,"desc":"Você olha através do componente material da magia para uma criatura a até 18 metros, tentando obter informações sobre ela. Escolha uma das opções a seguir:\n• Imunidades a condições.\n• Classe de Armadura atual.\n• Pontos de vida atuais, arredondados para o múltiplo de 25 mais próximo.\n• Vulnerabilidades a dano.\n• Imunidades e resistências a dano.\n• Tipos e valores de deslocamento.\n• Bônus de proficiência.\n• Proficiências em testes de resistência, sem os modificadores.\n• Proficiências em perícias, sem os modificadores.\n• Sentidos especiais.\nO alvo deve então realizar um teste de resistência de Carisma. Em uma falha, você descobre as propriedades escolhidas.","higher":"Ao conjurar esta magia no 2º nível ou superior, você pode escolher uma opção adicional da lista para cada nível do espaço acima do 1º.","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":540,"category":"Lyre's Guide to Retia","traits":[]},{"id":"lyre-chainfield","name":"Campo de Correntes","originalName":"Chainfield","level":5,"school":"Conjuração","time":"1 ação","range":"36 metros","comp":"V, S, M (uma adaga com lâmina de obsidiana, no valor de pelo menos 300 po)","material":"uma adaga com lâmina de obsidiana, no valor de pelo menos 300 po","duration":"10 minutos","classes":"Inscritor, Feiticeiro, Bruxo","ritual":false,"concentration":false,"desc":"Escolha cinco pontos que você possa ver dentro do alcance. Em cada ponto, uma estaca de obsidiana e fogo com 3 metros de comprimento irrompe de rasgos no espaço, envolta por correntes ardentes vermelho-sangue. Cada criatura a até 1,5 metro de uma estaca quando ela surge deve realizar um teste de resistência de Destreza, sofrendo 6d6 de dano de fogo em uma falha ou metade em um sucesso. As estacas permanecem até a magia terminar ou você conjurá-la novamente. Enquanto permanecerem, na primeira vez em cada turno que uma criatura tentar sair do raio de 1,5 metro de uma estaca, as correntes tentam prendê-la; ela deve ser bem-sucedida em um teste de resistência de Força ou fica impedida até o início do próximo turno. Criaturas que terminarem o turno a até 1,5 metro de uma estaca, ou estiverem impedidas por uma estaca ao fim do turno, sofrem 2d6 de dano de fogo. Uma criatura que superar a CD do teste de Força contra uma estaca por 5 ou mais, ou obtiver 20 natural no teste, destrói automaticamente essa estaca, tornando-a inútil.","higher":"Se você conjurar esta magia no 6º nível ou superior, escolha um dos efeitos a seguir para cada nível do espaço acima do 5º:\n• Você cria uma estaca adicional.\n• O dano inicial de cada estaca aumenta em 1d6.\n• A área afetada pelo surgimento inicial de cada estaca aumenta em 1,5 metro.","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":541,"category":"Lyre's Guide to Retia","traits":["Daemoturgia","Eidomancia"],"sourceNote":"Regra de grupo — Eidomancia: todo dano causado por uma magia de eidomancia é considerado dano eidólico. Após conjurar a magia, realize um teste de resistência de Constituição de CD 10 + o nível em que a magia foi conjurada + o número de turnos após o primeiro em que ela permaneceu ativa sob concentração. Se não exigir concentração, o teste é feito imediatamente após a conjuração. Em uma falha, você sofre níveis de exaustão iguais à metade do nível da magia, arredondado para baixo (mínimo 1), e não pode conjurá-la novamente por sete dias. Se a falha elevaria a exaustão a 6, ela fica em 5 e você é imediatamente reduzido a 0 pontos de vida. Se falhar em um teste de concentração para manter uma magia de eidomancia, você pode usar sua reação para rolar um d20 e usar esse resultado no lugar do d20 do teste de concentração."},{"id":"lyre-chaos-burst","name":"Explosão Caótica","originalName":"Chaos Burst","level":1,"school":"Evocação","time":"1 ação","range":"36 metros","comp":"V, S","material":"","duration":"Instantânea","classes":"Inscritor, Feiticeiro","ritual":false,"concentration":false,"desc":"Você arremessa uma massa ondulante e oscilante de energia caótica contra uma criatura dentro do alcance. Faça um ataque à distância com magia contra o alvo. Em um acerto, ele sofre 2d8 + 1d6 de dano. Depois de rolar, escolha um dos d8; o número desse dado determina o tipo de dano: 1 ácido, 2 frio, 3 fogo, 4 energia, 5 elétrico, 6 veneno, 7 psíquico, 8 trovejante. Se os dois d8 mostrarem o mesmo número, a energia caótica salta para outra criatura à sua escolha a até 9 metros do alvo. Faça uma nova jogada de ataque contra o novo alvo e uma nova rolagem de dano, que também pode provocar outro salto. Uma criatura só pode ser alvo uma vez por conjuração desta magia.","higher":"Quando você conjura esta magia usando um espaço de magia de 2º nível ou superior, escolha um dos efeitos a seguir para cada nível do espaço acima do 1º:\n• Cause 1d6 de dano adicional do tipo rolado.\n• Role um d8 adicional; ele não é somado ao dano, mas você pode usar o resultado para determinar o tipo de dano.\n• A magia mira uma criatura adicional, disparando outro raio contra ela. Esse raio exige sua própria rolagem de dano e pode ter um tipo de dano diferente.","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":541,"category":"Lyre's Guide to Retia","traits":["Legado 5.19"],"sourceNote":"A fonte identifica esta entrada como uma magia Legacy/revisada da edição 5.19; suas regras foram preservadas como uma versão própria de Lyre."},{"id":"lyre-chromatic-arrow","name":"Flecha Cromática","originalName":"Chromatic Arrow","level":1,"school":"Evocação","time":"1 ação","range":"27 metros","comp":"V, S, M (um diamante no valor de pelo menos 50 po)","material":"um diamante no valor de pelo menos 50 po","duration":"Instantânea","classes":"Feiticeiro, Mago","ritual":false,"concentration":false,"desc":"Você arremessa uma esfera de energia com cerca de 10 centímetros de diâmetro contra uma criatura que possa ver dentro do alcance. Escolha ácido, frio, fogo, elétrico, veneno ou trovejante como o tipo da esfera e faça um ataque à distância com magia contra o alvo. Em um acerto, a criatura sofre 3d8 de dano do tipo escolhido.","higher":"Quando você conjura esta magia no 2º nível ou superior, escolha um dos efeitos a seguir para cada nível do espaço acima do 1º:\n• O dano aumenta em 1d8.\n• Você pode escolher um alvo adicional dentro do alcance e pode usar um tipo de energia diferente para cada alvo.\n• Se um alvo tiver resistência ou imunidade ao tipo de dano que você causaria, você percebe isso e pode usar sua reação para mudar o dano para outro tipo no último instante.\n• O alcance da magia aumenta em 27 metros.","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":541,"category":"Lyre's Guide to Retia","traits":["Legado 5.19"],"sourceNote":"A fonte identifica esta entrada como uma magia Legacy/revisada da edição 5.19; suas regras foram preservadas como uma versão própria de Lyre."},{"id":"lyre-chromatic-ward","name":"Proteção Cromática","originalName":"Chromatic Ward","level":4,"school":"Abjuração","time":"1 ação","range":"Pessoal","comp":"V, S, M (um anel de bronze com um diamante, rubi, pérola, safira e esmeralda incrustados, no valor de pelo menos 500 po)","material":"um anel de bronze com um diamante, rubi, pérola, safira e esmeralda incrustados, no valor de pelo menos 500 po","duration":"1 minuto","classes":"Bardo, Clérigo, Druida","ritual":false,"concentration":false,"desc":"Sigilos arcanos cobrem sua pele e se entrelaçam em padrões complexos. Você se torna imune a todos os tipos de dano de energia cromática. Na primeira vez que sofrer dano de qualquer tipo de energia cromática, essas imunidades se tornam resistências pela duração da magia e, sempre que sofrer dano do tipo de energia cromática que desencadeou essa mudança, você sofre 10 pontos a menos desse dano. Além disso, até a magia terminar, sempre que acertar uma criatura com um ataque com arma, você causa 10 pontos de dano desse tipo de energia cromática.","higher":"","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":541,"category":"Lyre's Guide to Retia","traits":["Convocação Cromática"],"sourceNote":"Regra de grupo — Convocação Cromática: quando a magia mencionar energia ou dano cromático, escolha fogo, frio, ácido, elétrico ou veneno; a escolha vale para todas as ocorrências daquela invocação. Ao conjurar uma magia da Convocação Cromática, faça um teste com o atributo de conjuração (CD 10 + nível da magia). Em uma falha, seu máximo de pontos de vida é reduzido em duas vezes o nível da magia até concluir um Descanso Longo; a fonte chama esse efeito de Queima da Alma. A característica de conjuração da criatura pode dispensá-la desse teste."},{"id":"lyre-chughlihns-ink-void","name":"Vazio de Tinta de Chughlihn","originalName":"Chughlihn’s Ink Void","level":5,"school":"Conjuração","time":"1 ação","range":"45 metros","comp":"V, S","material":"","duration":"Instantânea","classes":"Inscritor, Druida, Bruxo","ritual":false,"concentration":false,"desc":"Uma pequena gota de tinta aparece na ponta dos seus dedos e voa até um ponto à sua escolha dentro do alcance. Ela explode em uma esfera de 9 metros de raio de tinta negro-abissal e vermes contorcidos, que grudam à pele como tinta adesiva. Todas as criaturas na área devem realizar um teste de resistência de Constituição, sofrendo 10d6 de dano de veneno e ficando cegas em uma falha, ou sofrendo metade do dano em um sucesso. Ao final de cada turno, uma criatura cega pode repetir o teste de Constituição, encerrando o efeito em um sucesso. Qualquer criatura que obtenha um resultado 5 ou menor no d20 em qualquer um desses testes de Constituição e falhe sofre um nível de exaustão.","higher":"Quando você conjura esta magia no 6º nível ou superior, escolha um dos efeitos a seguir para cada nível do espaço acima do 5º:\n• O dano de veneno aumenta em 1d6.\n• O raio da esfera aumenta em 3 metros.","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":542,"category":"Lyre's Guide to Retia","traits":[]},{"id":"lyre-circle-of-inverse-evolution","name":"Círculo de Evolução Inversa","originalName":"Circle of Inverse Evolution","level":6,"school":"Abjuração","time":"1 ação","range":"18 metros","comp":"V, S, M (um diamante negro no valor de pelo menos 1.000 po)","material":"um diamante negro no valor de pelo menos 1.000 po","duration":"Concentração, até 1 minuto","classes":"Inscritor, Bruxo","ritual":false,"concentration":true,"desc":"Escolha um ponto que você possa ver dentro do alcance e um dos seguintes tipos de rolagem de d20: jogadas de ataque, testes de atributo ou testes de resistência. Um círculo de influência surge desse ponto, preenchendo uma esfera de 9 metros de raio. Sempre que uma criatura entrar na esfera ou começar o turno nela, deve realizar um teste de resistência de Carisma. Em uma falha, ela subtrai seu bônus de proficiência do tipo de rolagem de d20 escolhido, exceto dos testes feitos para resistir a esta magia, até a próxima vez que começar o turno fora da esfera.","higher":"Quando você conjura esta magia no 7º nível ou superior, escolha um dos efeitos a seguir para cada nível do espaço acima do 6º:\n• A duração aumenta para 10 minutos (1 nível de espaço), 1 hora (2 níveis) ou 24 horas (3 níveis).\n• Você pode escolher um tipo adicional de rolagem de d20.\n• O raio da esfera aumenta em 3 metros.","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":542,"category":"Lyre's Guide to Retia","traits":["Sangue de Cineris"]},{"id":"lyre-cloud-canvas","name":"Tela de Nuvens","originalName":"Cloud Canvas","level":2,"school":"Transmutação","time":"1 ação","range":"Visão","comp":"V, S","material":"","duration":"Concentração, até 1 hora","classes":"Alma Favorecida, Inscritor, Bardo, Druida, Mago","ritual":true,"concentration":true,"desc":"Você faz até dez palavras se formarem em uma parte do céu que possa ver. As palavras parecem feitas de nuvens e permanecem pela duração da magia. Elas se dissipam quando a magia termina, e um vento forte pode dispersar as nuvens e encerrá-la prematuramente. Você também pode usar esta magia para moldar as nuvens em um desenho limitado, como um símbolo sagrado ou brasão.","higher":"","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":542,"category":"Lyre's Guide to Retia","traits":["Legado 5.19","Ritual"],"sourceNote":"A fonte identifica esta entrada como uma magia Legacy/revisada da edição 5.19; suas regras foram preservadas como uma versão própria de Lyre."},{"id":"lyre-corrosive-smite","name":"Destruição Corrosiva","originalName":"Corrosive Smite","level":3,"school":"Evocação","time":"1 ação bônus","range":"Pessoal","comp":"V","material":"","duration":"Concentração, até 1 minuto","classes":"Cavaleiro das Pétalas, Paladino","ritual":false,"concentration":true,"desc":"Na próxima vez que você acertar um ataque com arma corpo a corpo durante a duração desta magia, o ataque causa 3d8 de dano ácido adicional. Além disso, se o alvo for uma criatura, deve realizar um teste de resistência de Constituição. Em uma falha, fica envenenado até a magia terminar. Enquanto estiver envenenado, repete o teste de Constituição ao final de cada um de seus turnos, encerrando a magia em um sucesso.","higher":"","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":542,"category":"Lyre's Guide to Retia","traits":["Tomo da Madeira Sussurrante"]},{"id":"lyre-conjure-bestial-echo","name":"Conjurar Eco Bestial","originalName":"Conjure Bestial Echo","level":2,"school":"Conjuração","time":"1 ação","range":"27 metros","comp":"V, S, M (uma pena, um tufo de pelo e uma cauda de peixe dentro de uma bolota dourada no valor de pelo menos 200 po)","material":"uma pena, um tufo de pelo e uma cauda de peixe dentro de uma bolota dourada no valor de pelo menos 200 po","duration":"Concentração, até 1 hora","classes":"Druida","ritual":false,"concentration":true,"desc":"Você invoca um eco bestial que se manifesta em um espaço desocupado que possa ver dentro do alcance. Essa forma corpórea usa o bloco de estatísticas Eco Bestial. Ao conjurar a magia, escolha um ambiente: Ar, Terra ou Água. A criatura se parece com um animal à sua escolha nativo do ambiente escolhido, que determina certos traços do bloco. Ela desaparece ao chegar a 0 pontos de vida ou quando a magia termina.\nEco Bestial — Besta Pequena, sem alinhamento. CA 11 + o nível da magia. PV 30 + 5 para cada nível da magia acima do 2º. Deslocamento 9 m; escalar 9 m (somente Terra); voo 18 m (somente Ar); natação 9 m (somente Água). For 18 (+4), Des 11 (+0), Con 16 (+3), Int 4 (-3), Sab 14 (+2), Car 5 (-3). Sentidos: visão no escuro 18 m, Percepção passiva 12. Idiomas: compreende os idiomas que você fala. Bônus de Proficiência: igual ao do conjurador.\nSobrevoo (Somente Ar). A besta não provoca ataques de oportunidade ao voar para fora do alcance de um inimigo.\nTáticas de Matilha (Somente Terra e Água). A besta tem vantagem em uma jogada de ataque contra uma criatura se ao menos um aliado da besta estiver a até 1,5 metro da criatura e o aliado não estiver incapacitado.\nRespiração Aquática (Somente Água). A besta só pode respirar debaixo d'água.\nAções — Ataques Múltiplos. A besta realiza um número de ataques igual à metade do nível desta magia, arredondado para baixo.\nDilacerar. Ataque Corpo a Corpo com Arma: seu modificador de ataque com magia para acertar, alcance 1,5 m, um alvo. Acerto: 1d8 + 4 + o nível da magia de dano perfurante.\nA criatura é aliada sua e de seus companheiros. Em combate, compartilha sua contagem de iniciativa, mas realiza o turno imediatamente depois do seu. Ela obedece seus comandos verbais, sem exigir ação sua. Se você não der nenhum comando, ela usa a ação Esquivar e seu movimento para evitar perigo. Se o eco morrer fora da sua linha de visão, você enxerga brevemente através dos sentidos dele e recebe um vislumbre do que ocorreu no momento da morte, a menos que esteja inconsciente.","higher":"Quando você conjura esta magia usando um espaço de magia de 3º nível ou superior, use o nível superior sempre que o nível da magia aparecer no bloco de estatísticas.","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":543,"category":"Lyre's Guide to Retia","traits":["Legado 5.19"],"sourceNote":"A fonte identifica esta entrada como uma magia Legacy/revisada da edição 5.19; suas regras foram preservadas como uma versão própria de Lyre."},{"id":"lyre-conjure-draconic-echo","name":"Conjurar Eco Dracônico","originalName":"Conjure Draconic Echo","level":5,"school":"Conjuração","time":"1 ação","range":"18 metros","comp":"V, S, M (um objeto com a imagem de um dragão gravada, no valor de pelo menos 500 po)","material":"um objeto com a imagem de um dragão gravada, no valor de pelo menos 500 po","duration":"Concentração, até 1 hora","classes":"Druida, Feiticeiro, Mago","ritual":false,"concentration":true,"desc":"Você invoca um eco dracônico: uma semelhança de outro dragão com o qual esteja familiarizado ou de um dragão de uma realidade limítrofe à sua. Ele se manifesta em um espaço desocupado que você possa ver dentro do alcance. Essa forma corpórea usa o bloco de estatísticas Eco Dracônico. Ao conjurar a magia, escolha uma família de dragões: cromática, gema ou metálica. A criatura se parece com um dragão da família escolhida, que determina alguns de seus traços. Ela desaparece ao chegar a 0 pontos de vida ou quando a magia termina. A criatura é aliada sua e de seus companheiros. Em combate, compartilha sua contagem de iniciativa, mas realiza o turno imediatamente depois do seu. Obedece seus comandos verbais, sem exigir ação sua. Se você não der comando, usa Esquivar e seu movimento para evitar perigo. Se seu eco dracônico for reduzido a 0 pontos de vida fora da sua visão, você recebe um vislumbre momentâneo dos instantes finais dele como se enxergasse por seus sentidos, a menos que esteja inconsciente, e então percebe que a magia terminou.","higher":"Quando você conjura esta magia usando um espaço de magia de 6º nível ou superior, use o nível superior sempre que o nível da magia aparecer no bloco de estatísticas.\nEco Dracônico — Dragão Grande, neutro. CA 14 + o nível da magia. PV 50 + 10 para cada nível do espaço acima do 5º. Deslocamento 9 m, voo 18 m, natação 9 m. For 19 (+4), Des 14 (+2), Con 17 (+3), Int 10 (+0), Sab 14 (+2), Car 14 (+2). Resistências (Cromático e Metálico): ácido, frio, fogo, elétrico, veneno. Resistências (Gema): energia, necrótico, psíquico, radiante, trovejante. Imunidades a Condição: enfeitiçado, amedrontado, envenenado. Sentidos: percepção às cegas 9 m, visão no escuro 18 m, Percepção passiva 12. Idiomas: Dracônico e compreende os idiomas que você fala. Bônus de Proficiência: igual ao do conjurador.\nResistência Compartilhada. Ao invocar o dragão, escolha uma das resistências a dano dele. Você possui resistência ao tipo escolhido até a magia terminar.\nAções — Ataques Múltiplos. O dragão realiza um número de ataques Dilacerar igual à metade do nível da magia, arredondado para baixo, e usa Arma de Sopro.\nDilacerar. Ataque Corpo a Corpo com Arma: seu modificador de ataque com magia para acertar, alcance 3 m, um alvo. Acerto: 1d6 + 4 + o nível da magia de dano perfurante.\nArma de Sopro. O dragão exala energia destrutiva em um cone de 9 metros. Cada criatura na área deve realizar um teste de resistência de Destreza contra sua CD de magia, sofrendo 2d6 de dano de um tipo ao qual este dragão possua resistência, à sua escolha, em uma falha ou metade em um sucesso.","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":544,"category":"Lyre's Guide to Retia","traits":["Legado 5.19"],"sourceNote":"A fonte identifica esta entrada como uma magia Legacy/revisada da edição 5.19; suas regras foram preservadas como uma versão própria de Lyre."},{"id":"lyre-conjure-major-steed","name":"Conjurar Montaria Maior","originalName":"Conjure Major Steed","level":4,"school":"Conjuração","time":"10 minutos","range":"9 metros","comp":"V, S","material":"","duration":"Instantânea","classes":"Alma Favorecida, Paladino","ritual":false,"concentration":false,"desc":"Você invoca um espírito que assume a forma de uma montaria leal e majestosa. Surgindo em um espaço desocupado dentro do alcance, o espírito assume uma forma à sua escolha: aranha gigante, águia gigante, grifo, pégaso, peryton, lobo atroz, rinoceronte ou tigre-dentes-de-sabre. A criatura usa as estatísticas do Manual dos Monstros para a forma escolhida, mas seu tipo é celestial, fada ou corruptor, à sua escolha, em vez do tipo normal. Além disso, se sua Inteligência for 5 ou menor, ela passa a ser 6 e a criatura passa a compreender um idioma à sua escolha que você fale. Se já não for o caso, a montaria sempre é invocada com pelo menos uma categoria de tamanho acima de você; isso não altera suas estatísticas, a menos que elas dependam explicitamente do tamanho.\nVocê controla a montaria em combate. Enquanto ela estiver a até 1,6 quilômetro de você, vocês podem se comunicar telepaticamente. Enquanto estiver montado nela, qualquer magia que você conjurar e que tenha apenas você como alvo também pode afetar a montaria. Ela desaparece temporariamente ao chegar a 0 pontos de vida ou quando você a dispensa com uma ação. Conjurar esta magia novamente invoca de volta a montaria vinculada com todos os pontos de vida restaurados e todas as condições removidas. Você não pode ter mais de uma montaria vinculada por esta magia ou encontrar montaria ao mesmo tempo. Com uma ação, você pode romper o vínculo, fazendo a montaria desaparecer permanentemente. Sempre que ela desaparece, deixa para trás quaisquer objetos que estivesse vestindo ou carregando.","higher":"Quando você conjura esta magia usando um espaço de magia de 5º nível ou superior, pode invocar uma besta superior de acordo com a lista a seguir, desde que o nível do espaço seja igual ou superior ao indicado: aranha de fase (5º); anquilossauro, baleia assassina e lobo invernal (6º); crocodilo gigante, mantícora, pesadelo e estegossauro (7º); barghest, bulette e tricerátops (8º); quimera, dragão jovem e wyvern (9º).","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":545,"category":"Lyre's Guide to Retia","traits":["Legado 5.19","Tomo da Madeira Sussurrante"],"sourceNote":"A fonte identifica esta entrada como uma magia Legacy/revisada da edição 5.19; suas regras foram preservadas como uma versão própria de Lyre."},{"id":"lyre-conquering-winds","name":"Ventos Conquistadores","originalName":"Conquering Winds","level":5,"school":"Transmutação","time":"1 ação","range":"90 metros","comp":"V, S","material":"","duration":"Concentração, até 1 hora","classes":"Alma Favorecida, Inscritor, Cavaleiro das Pétalas, Druida, Feiticeiro, Mago","ritual":false,"concentration":true,"desc":"Você assume o controle do ar em um cubo de 30 metros que possa ver dentro do alcance. Ao conjurar a magia, escolha um dos efeitos a seguir. O efeito dura enquanto a magia durar, a menos que você use sua ação em um turno posterior para mudar para outro efeito. Você também pode usar sua ação para interromper temporariamente o efeito ou reiniciar um efeito interrompido.\nBarreira. O vento sopra em direção ao centro do cubo, tentando conter as criaturas nele. Sempre que uma criatura dentro do cubo tentar cruzar seus limites, deve realizar um teste de resistência de Força. Em uma falha, ela é puxada (1d4 × 1,5) + 1,5 metro em direção ao lado oposto do cubo e seu deslocamento se torna 0. Em um sucesso, pode sair da área.\nCorrente Descendente. Uma rajada contínua de vento forte sopra para baixo a partir do topo do cubo. Ataques com armas à distância que atravessem o cubo ou sejam feitos contra alvos dentro dele têm desvantagem. Uma criatura deve realizar um teste de resistência de Força se voar para dentro do cubo pela primeira vez em um turno ou começar seu turno voando ali. Em uma falha, fica caída.\nRajadas. Um vento contínuo sopra horizontalmente na direção que você designar. Escolha a intensidade: calmo, moderado ou forte. Se for moderado ou forte, ataques com armas à distância que entrem ou atravessem o cubo têm desvantagem. Se for forte, uma criatura que se mova contra o vento gasta 0,3 metro adicional de movimento para cada 0,3 metro percorrido.\nUivante. Um vento rugidor dificulta a comunicação. Criaturas dentro da área que tentem falar alto o suficiente para serem ouvidas sobre o vento devem realizar um teste de Constituição. Em uma falha, não são ouvidas; em um sucesso, podem se comunicar normalmente pelo restante do turno.\nSufocante. O ar se torna difícil de respirar, pois o vento o arranca dos pulmões. Cada criatura que começar o turno na área deve realizar um teste de resistência de Constituição ou fica incapaz de respirar naquele turno, caso precise respirar. Ela repete o teste a cada turno que começar na área, com desvantagem se o teste anterior tiver sido uma falha. Em um sucesso, consegue respirar durante aquele turno.\nCorrente Ascendente. Uma corrente de ar contínua sobe da base do cubo. Criaturas que terminarem uma queda dentro dele sofrem apenas metade do dano de queda. Quando uma criatura no cubo fizer um salto vertical, pode saltar até 3 metros mais alto que o normal.","higher":"Quando você conjura esta magia usando um espaço de magia de 6º nível ou superior, escolha um dos efeitos a seguir para cada nível do espaço acima do 5º:\n• O cubo controlado aumenta em 15 metros de lado.\n• O alcance da magia aumenta em 30 metros.\n• Você pode dividir o efeito em várias instâncias dos efeitos acima. Cada instância é um cubo de 15 metros que não pode se sobrepor aos demais. Você pode combinar vários cubos de 15 metros para formar um cubo maior e escolher um efeito diferente para cada cubo. A soma dos tamanhos dos cubos criados deve ser igual ao tamanho que o cubo original teria.","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":545,"category":"Lyre's Guide to Retia","traits":["Legado 5.19"],"sourceNote":"A fonte identifica esta entrada como uma magia Legacy/revisada da edição 5.19; suas regras foram preservadas como uma versão própria de Lyre."},{"id":"lyre-crashing-ice","name":"Gelo Devastador","originalName":"Crashing Ice","level":5,"school":"Conjuração","time":"1 ação","range":"Pessoal (linha de 15 metros)","comp":"V, S","material":"","duration":"Instantânea","classes":"Cavaleiro das Pétalas, Druida, Feiticeiro, Bruxo","ritual":false,"concentration":false,"desc":"Com um movimento da mão, uma torrente de água congelante e gelo explode a partir de você em uma linha de 15 metros de comprimento por 3 metros de largura e altura. Todas as criaturas na área devem realizar um teste de resistência de Destreza, sofrendo 4d8 de dano de concussão e 4d8 de dano de frio em uma falha ou metade em um sucesso. Criaturas bem-sucedidas podem escolher se mover para fora da linha, surgindo no espaço desocupado mais próximo. Depois disso, a água e o gelo congelam no lugar. Criaturas que falharam no teste ficam parcialmente presas e impedidas no gelo, precisando usar uma ação e ser bem-sucedidas em um teste de Força contra sua CD de magia para escapar.","higher":"Quando você conjura esta magia no 6º nível ou superior, os danos de concussão e de frio aumentam, cada um, em 1d8 para cada nível do espaço acima do 5º.","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":546,"category":"Lyre's Guide to Retia","traits":["Artes Arcanas de Altissima-Cor"]},{"id":"lyre-crystal-gate","name":"Portal de Cristal","originalName":"Crystal Gate","level":7,"school":"Conjuração","time":"10 minutos","range":"6 metros","comp":"V, S, M (um item ou uma criatura voluntária proveniente do destino)","material":"um item ou uma criatura voluntária proveniente do destino","duration":"6 horas","classes":"Inscritor, Bardo, Feiticeiro, Bruxo, Mago","ritual":false,"concentration":false,"desc":"Você e até oito criaturas voluntárias dentro do alcance ficam inconscientes pela duração da magia e vivenciam visões de outro mundo. Isso pode ter diferentes resultados conforme a natureza desse outro mundo:\n• O mundo-alvo é outra realidade, separada do Plano Material e conectada a Somnus Domina pelos fios do tempo. Pode ser uma camada alternativa do mundo, como o Caldeirão ou a Espiral Radiante.\n• O mundo-alvo pode ser o mesmo que o seu, mas em outro ponto do tempo; o objeto ou pessoa usado para conjurar a magia deve estar deslocado no tempo, e esta magia ajusta seus alvos para a posição temporal correta relativa a esse alvo.\n• O mundo-alvo é outro plano da cosmologia de Somnus Domina, que pode estar impedido de ser acessado por algum meio.\nSe a magia alcançar sua duração completa, as visões terminam com todos vocês testemunhando o estilhaçar de um véu de cristal que separa as realidades. A magia termina e vocês são transportados mental e fisicamente para o mundo visto nas visões. Para conjurá-la, você deve possuir um item mágico ou objeto importante que tenha se originado no mundo que deseja alcançar. Se for outra realidade, você deve saber que ela existe, ainda que não conheça seu nome. Seu destino é um local seguro a até 1,6 quilômetro de onde o item foi criado ou algum lugar relevante a ele. Como alternativa, você pode conjurar a magia se uma das criaturas afetadas tiver nascido no outro mundo; nesse caso, o destino é um local seguro a até 1,6 quilômetro de onde ela nasceu. A magia termina antecipadamente para uma criatura se ela sofrer qualquer dano, e essa criatura não é transportada. Se você sofrer qualquer dano, a magia termina para você e para todas as demais criaturas, e ninguém é transportado. Se você falhar na queimadura de eidomancia causada pela conjuração desta magia, ela também termina sem efeito.","higher":"","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":546,"category":"Lyre's Guide to Retia","traits":["Eidomancia","Legado 5.19"],"sourceNote":"A fonte identifica esta entrada como uma magia Legacy/revisada da edição 5.19; suas regras foram preservadas como uma versão própria de Lyre. Regra de grupo — Eidomancia: todo dano causado por uma magia de eidomancia é considerado dano eidólico. Após conjurar a magia, realize um teste de resistência de Constituição de CD 10 + o nível em que a magia foi conjurada + o número de turnos após o primeiro em que ela permaneceu ativa sob concentração. Se não exigir concentração, o teste é feito imediatamente após a conjuração. Em uma falha, você sofre níveis de exaustão iguais à metade do nível da magia, arredondado para baixo (mínimo 1), e não pode conjurá-la novamente por sete dias. Se a falha elevaria a exaustão a 6, ela fica em 5 e você é imediatamente reduzido a 0 pontos de vida. Se falhar em um teste de concentração para manter uma magia de eidomancia, você pode usar sua reação para rolar um d20 e usar esse resultado no lugar do d20 do teste de concentração."},{"id":"lyre-crystal-nightmare","name":"Pesadelo de Cristal","originalName":"Crystal Nightmare","level":9,"school":"Abjuração","time":"1 ação","range":"18 metros","comp":"V, S, M (uma gema no valor de pelo menos 1.500 po, que a magia consome)","material":"uma gema no valor de pelo menos 1.500 po, que a magia consome","duration":"Concentração, até 1 minuto","classes":"Feiticeiro, Bruxo","ritual":false,"concentration":true,"desc":"Escolha uma criatura dentro do alcance, que você tenta aprisionar em um semiplano de formações cristalinas complexas e reflexos infinitos enlouquecedores. Ela deve realizar um teste de resistência de Carisma. Em uma falha, é banida para esse semiplano, onde fica suspensa no ar; todos os efeitos mágicos sobre ela ou originados por ela terminam ou são suprimidos, e sempre que tentar conjurar uma magia você pode realizar um teste de atributo contra ela como se tivesse conjurado contramágica para impedi-la. Enquanto estiver nessa dimensão, ela deve realizar um teste de resistência de Inteligência no início de cada turno, sofrendo 4d10 de dano psíquico em uma falha devido ao ambiente enlouquecedor. Criaturas com Inteligência igual ou inferior à metade da sua falham automaticamente nesse teste. Uma criatura que obtenha três sucessos nesse teste é libertada e transportada de volta. Ela também é libertada se lançar banimento sobre si ou usar na área uma magia que negue ou anule magia, como dissipar magia ou campo antimagia. Magias de teletransporte ou viagem planar têm 50% de chance de falhar automaticamente. Caso contrário, a criatura só é libertada quando a magia termina ou quando é reduzida a 0 pontos de vida.\nQuando retorna do semiplano, a criatura reaparece no mesmo local de onde desapareceu ou no espaço desocupado mais próximo. Uma criatura que retorne por ter sido reduzida a 0 pontos de vida entra em animação suspensa e fica presa em uma gema do tamanho de um punho em sua posse. A gema só se rompe e liberta a criatura se você usar uma ação para fazê-lo ou se uma magia como dissipar magia a negar, tratando-a como uma magia de 9º nível. Enquanto possuir essa gema, uma vez por dia você pode tocá-la e fazer uma pergunta à mente da criatura. Ela deve realizar um teste de resistência de Inteligência; em uma falha, você aprende tudo que ela sabe que poderia servir como resposta.","higher":"","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":546,"category":"Lyre's Guide to Retia","traits":["Artes Arcanas de Altissima-Cor"]},{"id":"lyre-curse","name":"Maldição","originalName":"Curse","level":1,"school":"Encantamento","time":"1 ação bônus","range":"27 metros","comp":"V, S, M (o olho petrificado de um tritão)","material":"o olho petrificado de um tritão","duration":"Concentração, até 1 hora","classes":"Alma Favorecida, Inscritor, Cavaleiro das Pétalas, Patrulheiro, Bardo, Clérigo, Druida, Paladino, Feiticeiro, Bruxo, Mago","ritual":false,"concentration":true,"desc":"Você coloca uma maldição em uma criatura que possa ver dentro do alcance; ela permanece amaldiçoada pela duração da magia. Enquanto estiver amaldiçoada dessa forma, sempre que você a atingir com um ataque causa 1d6 de dano necrótico adicional. Além disso, escolha uma das debilitações a seguir ao conjurar a magia:\n• Escolha um atributo. O alvo tem desvantagem em testes feitos com o atributo escolhido.\n• Escolha um atributo. Na primeira vez que o alvo fizer um teste de resistência desse tipo depois de ser afetado pela magia, ele tem desvantagem na rolagem.\n• Escolha ataques corpo a corpo ou à distância. O alvo tem desvantagem na primeira vez que fizer um ataque do tipo escolhido em cada turno.\nSe o alvo cair a 0 pontos de vida antes de a magia terminar, você pode usar uma ação bônus em um turno posterior para amaldiçoar uma nova criatura.","higher":"Quando você conjura esta magia no 2º nível ou superior, escolha um dos efeitos a seguir para cada nível do espaço acima do 2º:\n• Você pode escolher uma debilitação adicional. Todos os alvos sofrem as mesmas escolhas de debilitação.\n• (2 níveis de espaço) Você pode escolher um alvo adicional dentro do alcance. A ação bônus usada para mover a maldição para uma nova criatura pode redistribuir quaisquer instâncias da maldição que não estejam afetando uma criatura.\n• (2 níveis de espaço) A duração aumenta para 8 horas.\n• (4 níveis de espaço) A duração aumenta para 24 horas.","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":547,"category":"Lyre's Guide to Retia","traits":["Legado 5.19"],"sourceNote":"A fonte identifica esta entrada como uma magia Legacy/revisada da edição 5.19; suas regras foram preservadas como uma versão própria de Lyre."},{"id":"lyre-cursed-dragon-spears","name":"Lanças Dracônicas Amaldiçoadas","originalName":"Cursed Dragon Spears","level":3,"school":"Conjuração","time":"1 ação bônus","range":"Pessoal","comp":"V, S, M (uma pequena barra de obsidiana coberta de pó de carvão)","material":"","duration":"10 minutos","classes":"Inscritor, Cavaleiro das Pétalas, Clérigo, Paladino, Bruxo","ritual":false,"concentration":false,"desc":"Você invoca uma série de lanças brilhantes de cinza e obsidiana que flutuam ao seu redor pela duração da magia. Essas lanças são intangíveis até que você tente usá-las. Uma vez ao conjurá-las e novamente em cada um de seus turnos como uma ação bônus, você pode fazer um ataque corpo a corpo com magia contra uma criatura a até 1,5 metro de você ou um ataque à distância com magia contra um alvo a até 9 metros. Em um acerto, o alvo sofre dano perfurante igual a 2d8 + seu modificador do atributo de conjuração. Além disso, ao acertar uma dessas lanças, escolha um dos efeitos a seguir; efeitos que removem maldições podem remover qualquer um deles:\nQuebra-Armadura. Se a criatura tiver bônus de CA causado por uma armadura que não seja natural, o bônus fornecido por essa armadura sofre -1 por 1 hora. O efeito pode ser aplicado várias vezes.\nClarão Explosivo. O ataque causa 2d8 de dano de energia cromática adicional.\nPasso Desajeitado. O deslocamento do alvo é reduzido à metade até o início do seu próximo turno.\nQueimadura de Força. O alvo deve realizar um teste de resistência de Força ou tem desvantagem em jogadas de ataque até o final do próximo turno dele.\nEspeto de Magia. Se o alvo estiver se concentrando em uma magia, deve realizar um teste de concentração contra sua CD de magia. Em uma falha, perde a concentração.\nMaldição Enfraquecedora. O alvo deve realizar um teste de resistência de Carisma ou fica amaldiçoado por 1 minuto. Você tem resistência ao dano causado por uma criatura amaldiçoada dessa forma. Ela pode repetir o teste ao final de cada turno, encerrando o efeito em um sucesso.","higher":"Quando você conjura esta magia no 4º nível ou superior, escolha um dos efeitos a seguir para cada nível do espaço acima do 3º:\n• As lanças recebem bônus de aprimoramento +1. Você pode escolher este efeito até quatro vezes, aumentando o bônus em +1 a cada escolha após a primeira.\n• (2 níveis de espaço) Sempre que realizar um ataque com uma dessas lanças, realize também um ataque adicional com elas.","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":547,"category":"Lyre's Guide to Retia","traits":["Convocação Cromática"],"sourceNote":"Regra de grupo — Convocação Cromática: quando a magia mencionar energia ou dano cromático, escolha fogo, frio, ácido, elétrico ou veneno; a escolha vale para todas as ocorrências daquela invocação. Ao conjurar uma magia da Convocação Cromática, faça um teste com o atributo de conjuração (CD 10 + nível da magia). Em uma falha, seu máximo de pontos de vida é reduzido em duas vezes o nível da magia até concluir um Descanso Longo; a fonte chama esse efeito de Queima da Alma. A característica de conjuração da criatura pode dispensá-la desse teste."},{"id":"lyre-cursed-talon","name":"Garra Amaldiçoada","originalName":"Cursed Talon","level":8,"school":"Transmutação","time":"1 ação","range":"Pessoal","comp":"V, S, M (uma garra de corvo com garras de obsidiana, no valor de pelo menos 500 po)","material":"uma garra de corvo com garras de obsidiana, no valor de pelo menos 500 po","duration":"Concentração, até 1 minuto","classes":"Druida, Feiticeiro, Bruxo","ritual":false,"concentration":true,"desc":"Você retorce e transforma um de seus braços em uma forma demoníaca, com uma enorme garra monstruosa no lugar da mão. Uma vez em cada um dos seus turnos, como uma ação bônus, você pode realizar um ataque corpo a corpo com magia com o braço alterado contra uma criatura a até 3 metros, causando 4d10 de dano cortante e 4d10 de dano psíquico em um acerto. Esses ataques causam acerto crítico com resultado 19 ou 20 na jogada de ataque. Ao acertar uma criatura com esse ataque, você recupera pontos de vida iguais ao dano psíquico causado.","higher":"","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":547,"category":"Lyre's Guide to Retia","traits":["Daemoturgia"]},{"id":"lyre-deadly-target","name":"Alvo Mortal","originalName":"Deadly Target","level":3,"school":"Encantamento","time":"1 ação","range":"Toque (18 metros)","comp":"V, S","material":"","duration":"Concentração, até 1 minuto","classes":"Patrulheiro, Mago","ritual":false,"concentration":true,"desc":"Você toca uma criatura voluntária, exceto você, e escolhe um alvo dentro do alcance da magia. A criatura tocada recebe um bônus igual ao seu modificador do atributo de conjuração em todas as jogadas de ataque feitas contra o alvo escolhido até o início do seu próximo turno. Em cada um dos seus turnos, você pode usar uma ação bônus para designar um novo alvo.","higher":"","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":547,"category":"Lyre's Guide to Retia","traits":["Arcana da Guardiã dos Céus"]},{"id":"lyre-dedicated-enemy","name":"Inimigo Designado","originalName":"Dedicated Enemy","level":1,"school":"Encantamento","time":"1 ação bônus","range":"9 metros","comp":"V","material":"","duration":"Concentração, até 1 minuto","classes":"Cavaleiro das Pétalas, Paladino","ritual":false,"concentration":true,"desc":"Você tenta compelir uma criatura a duelar com você. Uma criatura que você possa ver dentro do alcance deve realizar um teste de resistência de Sabedoria. Em uma falha, ela é atraída para você, compelida por sua exigência divina. Pela duração, ela tem desvantagem em jogadas de ataque contra criaturas que não sejam você e deve realizar um teste de resistência de Sabedoria sempre que tentar se mover para um espaço a mais de 9 metros de você. Em um sucesso, a magia não restringe o movimento do alvo naquele turno. A magia termina se você atacar qualquer outra criatura, conjurar uma magia que tenha como alvo uma criatura hostil diferente do alvo, se uma criatura amistosa a você acertar o alvo ou conjurar uma magia nociva contra ele, ou se você terminar seu turno a mais de 9 metros do alvo.","higher":"","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":548,"category":"Lyre's Guide to Retia","traits":["Legado 5.19"],"sourceNote":"A fonte identifica esta entrada como uma magia Legacy/revisada da edição 5.19; suas regras foram preservadas como uma versão própria de Lyre."},{"id":"lyre-deflect","name":"Defletir","originalName":"Deflect","level":0,"school":"Abjuração","time":"1 ação bônus","range":"Pessoal","comp":"V, S","material":"","duration":"1 rodada","classes":"Inscritor, Bardo, Feiticeiro, Bruxo, Mago","ritual":false,"concentration":false,"desc":"Você estende a mão e traça no ar um sigilo de proteção. Até o final do seu próximo turno, você tem resistência a dano de concussão, perfurante e cortante causado por ataques com armas.","higher":"","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":548,"category":"Lyre's Guide to Retia","traits":["Legado 5.19"],"sourceNote":"A fonte identifica esta entrada como uma magia Legacy/revisada da edição 5.19; suas regras foram preservadas como uma versão própria de Lyre."},{"id":"lyre-desperate-retreat","name":"Retirada Desesperada","originalName":"Desperate Retreat","level":7,"school":"Conjuração","time":"1 reação, realizada quando você é atingido por um ataque que possa ver, antes da rolagem de dano","range":"18 metros","comp":"V","material":"","duration":"Instantânea","classes":"Inscritor, Druida, Feiticeiro, Bruxo","ritual":false,"concentration":false,"desc":"Em resposta ao ataque que desencadeou esta magia, você envolve o corpo em chamas e explode violentamente. Tudo a até 6 metros de você deve realizar um teste de resistência de Destreza, sofrendo 10d8 de dano de fogo em uma falha ou metade em um sucesso. Ao mesmo tempo, você se teletransporta ileso para um espaço desocupado que possa ver a até 18 metros e fica atordoado até o final do turno atual. Você não sofre o dano do ataque que desencadeou a magia, mas deve decidir conjurá-la antes da rolagem de dano ou da resolução de quaisquer efeitos provocados pelo acerto.","higher":"","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":548,"category":"Lyre's Guide to Retia","traits":["Artes dos Nove Ramos"]},{"id":"lyre-dire-restraints","name":"Amarras Terríveis","originalName":"Dire Restraints","level":9,"school":"Conjuração","time":"1 ação bônus","range":"Pessoal (9 metros)","comp":"V, S, M (um bracelete feito de elos de marfim no valor de pelo menos 5.000 po)","material":"um bracelete feito de elos de marfim no valor de pelo menos 5.000 po","duration":"Concentração, até 10 minutos","classes":"Druida, Feiticeiro, Bruxo","ritual":false,"concentration":true,"desc":"Você cria diversas correntes afiadas de marfim, sinuosas como serpentes, que se enrolam ao seu redor pela duração da magia e terminam em longas lâminas brancas. Com uma ação bônus, você pode comandar as correntes para realizar três ataques corpo a corpo com magia contra criaturas à sua escolha a até 9 metros. Em um acerto, uma criatura sofre 3d10 de dano perfurante e 3d12 de dano de frio. Se você escolher a mesma criatura como alvo de duas correntes e acertar com a primeira, em vez de fazer um ataque com a segunda, o alvo deve realizar um teste de resistência de Força. Em uma falha, fica impedido e uma nova corrente é criada para permitir novos ataques enquanto a primeira permanece ocupada. Uma criatura impedida pode usar uma ação para realizar um teste de Força contra sua CD de resistência de magia, libertando-se em um sucesso. Uma criatura que se libertar dessas amarras ou for bem-sucedida no teste inicial de Força não pode ser presa novamente por esta conjuração. Você só pode causar dano a uma mesma criatura uma vez por turno com os ataques desta magia.","higher":"","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":548,"category":"Lyre's Guide to Retia","traits":["Artes Arcanas de Altissima-Cor"]},{"id":"lyre-discombobulation","name":"Desorientação","originalName":"Discombobulation","level":5,"school":"Encantamento","time":"1 ação","range":"36 metros","comp":"V, S","material":"","duration":"Instantânea","classes":"Inscritor, Bardo, Feiticeiro, Bruxo, Mago","ritual":false,"concentration":false,"desc":"Você escolhe um ponto dentro do alcance e faz energia psíquica explodir ali. Cada criatura em uma esfera de 6 metros de raio centrada nesse ponto deve realizar um teste de resistência de Inteligência. Uma criatura com Inteligência 2 ou menor não pode ser afetada. Um alvo sofre 8d6 de dano psíquico em uma falha ou metade em um sucesso. Após falhar, o alvo fica com os pensamentos embaralhados por 1 minuto. Durante esse período, ele rola 1d6 e subtrai o resultado de todas as jogadas de ataque e testes de atributo, bem como de testes de resistência de Constituição para manter concentração. Ao final de cada um de seus turnos, o alvo pode repetir o teste de Inteligência, encerrando o efeito sobre si em um sucesso.","higher":"Quando você conjura esta magia usando um espaço de magia de 6º nível ou superior, escolha um dos efeitos a seguir para cada nível do espaço acima do 5º:\n• O dano aumenta em 1d6.\n• O raio da esfera aumenta em 3 metros.\n• (2 níveis de espaço) O dado subtraído de jogadas de ataque, testes de atributo e testes de concentração passa a ser d8.","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":548,"category":"Lyre's Guide to Retia","traits":["Legado 5.19"],"sourceNote":"A fonte identifica esta entrada como uma magia Legacy/revisada da edição 5.19; suas regras foram preservadas como uma versão própria de Lyre."},{"id":"lyre-disorienting-scatter","name":"Dispersão Desorientadora","originalName":"Disorienting Scatter","level":3,"school":"Conjuração","time":"1 ação","range":"9 metros (18 metros)","comp":"V, S","material":"","duration":"Instantânea","classes":"Inscritor, Cavaleiro das Pétalas, Bardo, Mago","ritual":false,"concentration":false,"desc":"Escolha qualquer número de criaturas voluntárias a até 9 metros de você. Elas são teletransportadas para espaços desocupados à sua escolha a até 18 metros de você e, se estiverem paralisadas, impedidas ou agarradas, esses efeitos terminam. Você não precisa ver os alvos nem os espaços para os quais eles se teletransportam, desde que saiba que estão ali. Se o espaço escolhido estiver ocupado, o alvo é desviado para o espaço desocupado mais próximo. Criaturas teletransportadas devem realizar um teste de resistência de Constituição com CD igual a 8 + o nível em que você conjurou a magia. Em uma falha, ficam atordoadas até o final do próximo turno delas.","higher":"Quando você conjura esta magia usando um espaço de magia de 4º nível ou superior, os alcances de 9 e 18 metros dobram para cada nível do espaço acima do 3º: 18/36 m no 4º, 36/72 m no 5º e assim por diante.","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":548,"category":"Lyre's Guide to Retia","traits":["Artes dos Nove Ramos"]},{"id":"lyre-divine-armor","name":"Armadura Divina","originalName":"Divine Armor","level":7,"school":"Abjuração","time":"1 ação","range":"Pessoal","comp":"V","material":"","duration":"1 minuto","classes":"Druida, Feiticeiro, Bruxo","ritual":false,"concentration":false,"desc":"Seu corpo é imediatamente reforçado por uma camada de gelo confortável e flexível para você, mas rígida e protetora contra os demais. Você recebe 15d10 pontos de vida temporários. Se o resultado for maior que seu máximo de pontos de vida, você recebe pontos de vida temporários iguais ao seu máximo em vez disso. Enquanto tiver esses pontos de vida temporários, possui resistência a dano perfurante, cortante e de concussão, e na primeira vez em cada turno que uma criatura o acerta com um ataque com arma corpo a corpo, ela sofre 2d10 de dano de frio. Contudo, enquanto estiver sob este efeito, você tem vulnerabilidade a dano de fogo. O efeito termina quando você perde esses pontos de vida temporários, que também desaparecem automaticamente quando a duração da magia termina.","higher":"","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":549,"category":"Lyre's Guide to Retia","traits":["Artes Arcanas de Altissima-Cor"]},{"id":"lyre-divine-frost","name":"Geada Divina","originalName":"Divine Frost","level":5,"school":"Encantamento","time":"1 ação","range":"9 metros","comp":"V, S, M (um nenúfar preservado ou congelado)","material":"um nenúfar preservado ou congelado","duration":"Concentração, até 1 — unidade não informada no PDF","classes":"Inscritor, Cavaleiro das Pétalas, Bardo, Clérigo, Paladino, Feiticeiro, Bruxo, Mago","ritual":false,"concentration":true,"desc":"Escolha uma criatura dentro do alcance. O corpo e as armas dela ficam cobertos por uma camada radiante de geada que escorre como fumaça. Pela duração da magia, os ataques com armas dessa criatura causam 2d10 de dano de frio adicional, e ela se torna imune a dano de frio e radiante. O alvo não pode ser agarrado nem impedido durante a duração, e qualquer criatura que tente fazê-lo falha automaticamente. Qualquer criatura que termine o turno em contato direto com o alvo durante a duração sofre 2d10 de dano de frio.","higher":"Quando você conjura esta magia no 7º nível ou superior, pode escolher uma criatura adicional dentro do alcance para cada dois níveis do espaço acima do 5º.","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":549,"category":"Lyre's Guide to Retia","traits":["Artes Arcanas de Altissima-Cor"],"sourceNote":"O PDF registra “Concentration, up to 1” sem informar a unidade de duração; a lacuna foi preservada."},{"id":"lyre-divine-weapon","name":"Arma Divina","originalName":"Divine Weapon","level":5,"school":"Evocação","time":"1 ação bônus","range":"Toque","comp":"V, S","material":"","duration":"Concentração, até 1 hora","classes":"Alma Favorecida, Cavaleiro das Pétalas, Clérigo, Paladino","ritual":false,"concentration":true,"desc":"Você imbui uma arma que toca com poder sagrado. Até a magia terminar, a arma emite luz plena em um raio de 9 metros e meia-luz por mais 9 metros. Além disso, ataques feitos com ela causam 2d8 de dano radiante adicional em um acerto. Se a arma ainda não for mágica, ela se torna mágica pela duração. Como uma ação bônus no seu turno, você pode encerrar esta magia e fazer a arma emitir uma explosão de radiância. Cada criatura à sua escolha que você possa ver a até 9 metros da arma deve realizar um teste de resistência de Constituição. Em uma falha, sofre 4d8 de dano radiante e fica cega por 1 minuto; em um sucesso, sofre metade do dano e não fica cega. Ao final de cada um de seus turnos, uma criatura cega pode repetir o teste, encerrando o efeito em um sucesso.","higher":"Quando você conjura esta magia usando um espaço de magia de 6º nível ou superior, escolha um dos efeitos a seguir para cada nível do espaço acima do 5º:\n• A duração aumenta para 8 horas (1 nível de espaço) ou 24 horas (2 níveis).\n• (2 níveis de espaço) O dano radiante adicional da arma aumenta em 1d8, e o dano da explosão de radiância aumenta em 2d6.\n• Na primeira vez em cada rodada que a arma encantada causar dano a um corruptor, causa 1d8 de dano radiante adicional.","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":549,"category":"Lyre's Guide to Retia","traits":["Legado 5.19"],"sourceNote":"A fonte identifica esta entrada como uma magia Legacy/revisada da edição 5.19; suas regras foram preservadas como uma versão própria de Lyre."},{"id":"lyre-dragonskin","name":"Pele de Dragão","originalName":"Dragonskin","level":3,"school":"Transmutação","time":"1 ação","range":"Pessoal","comp":"V, S, M (a escama de um dragão que possua a resistência que você deseja obter)","material":"a escama de um dragão que possua a resistência que você deseja obter","duration":"Concentração, até 1 hora","classes":"Inscritor, Cavaleiro das Pétalas, Druida, Feiticeiro, Bruxo","ritual":false,"concentration":true,"desc":"Sua pele fica revestida por escamas dracônicas de um tipo à sua escolha. Até a magia terminar, sua CA não pode ser inferior a 16, independentemente da armadura que esteja vestindo. Conforme o tipo de escama escolhido, você recebe resistência ao tipo de dano correspondente. Além disso, se for submetido à arma de sopro de um dragão correspondente ao tipo de escama escolhido, pode usar sua reação para obter sucesso automático no teste de resistência contra essa arma de sopro.\nAmetista: energia. Negro ou cobre: ácido. Azul ou bronze: elétrico. Latão, ouro ou vermelho: fogo. Caveira ou topázio: necrótico. Esmeralda: psíquico. Verde: veneno. Cristal, pedra-da-lua ou platina: radiante. Safira: trovejante. Prata ou branco: frio.","higher":"","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":550,"category":"Lyre's Guide to Retia","traits":[]},{"id":"lyre-dread-surge","name":"Surto de Pavor","originalName":"Dread Surge","level":5,"school":"Necromancia","time":"1 ação","range":"18 metros","comp":"V, M (um osso quebrado e um quadrado de seda negra)","material":"um osso quebrado e um quadrado de seda negra","duration":"Instantânea","classes":"Bruxo, Mago","ritual":false,"concentration":false,"desc":"Você lança faixas de energia negativa contra uma criatura que possa ver dentro do alcance. A menos que o alvo seja um morto-vivo, ele deve realizar um teste de resistência de Constituição, sofrendo 5d12 de dano necrótico em uma falha ou metade em um sucesso. Um alvo morto por esse dano se ergue como zumbi no início do seu próximo turno. O zumbi persegue a criatura mais próxima que possa ver. As estatísticas do zumbi estão no Manual dos Monstros. Se você escolher um morto-vivo como alvo, ele não realiza teste de resistência. Em vez disso, role 5d12; o alvo recebe pontos de vida temporários iguais à metade do total.","higher":"Se você conjurar esta magia usando um espaço de magia de 6º nível ou superior, escolha um dos efeitos a seguir para cada nível do espaço acima do 5º:\n• Se o alvo for morto-vivo, ele ainda é afetado, mas sofre metade do dano. Esse dano ignora resistências e imunidades. Um morto-vivo morto por este efeito ainda se ergue como zumbi, mas sob seu domínio conforme descrito.\n• O dano necrótico aumenta em 1d12, assim como a quantidade de pontos de vida temporários recebida por um morto-vivo.\n• (2 níveis de espaço) Você pode escolher uma criatura adicional dentro do alcance.","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":550,"category":"Lyre's Guide to Retia","traits":["Legado 5.19"],"sourceNote":"A fonte identifica esta entrada como uma magia Legacy/revisada da edição 5.19; suas regras foram preservadas como uma versão própria de Lyre."},{"id":"lyre-dream-walk","name":"Caminhar nos Sonhos","originalName":"Dream Walk","level":6,"school":"Ilusão","time":"1 hora","range":"Pessoal","comp":"V, S, M (um apanhador de sonhos feito com fios de prata e ouro, no valor de pelo menos 500 po)","material":"um apanhador de sonhos feito com fios de prata e ouro, no valor de pelo menos 500 po","duration":"7 horas","classes":"Druida, Mago","ritual":false,"concentration":false,"desc":"Você cai em sono profundo, permanecendo inconsciente pela duração e sendo difícil de despertar. Enquanto dorme, seu espírito se separa do corpo, aparecendo a até 15 metros, e pode se mover livremente. Sua forma espiritual não pode realizar ações, exceto Esconder-se e Desengajar, além de testes para resistir a ser agarrada ou impedida. A CA da forma espiritual é 10 + seu modificador de Destreza + seu modificador do atributo de conjuração, e ela pode se mover até seu deslocamento a cada rodada. Ela existe no Plano Etéreo, mas pode ver e ouvir o que ocorre no Plano Material ao redor e atravessar objetos e paredes não mágicos livremente.\nEnquanto estiver em forma espiritual, você sempre sabe a distância e direção do seu corpo e pode usar sua ação para projetar seus sentidos de volta a ele, ouvindo, cheirando e sentindo tudo que o corpo sente, mas sem enxergar a menos que os olhos estejam abertos. Criaturas capazes de ver o Plano Etéreo, auras mágicas ou criaturas invisíveis conseguem ver e interagir com sua forma espiritual, mesmo a partir do Plano Material.\nSe seu corpo ou forma espiritual sofrer dano, você deve realizar um teste de concentração como se estivesse mantendo esta magia. Em uma falha, a magia termina. Todo dano sofrido por sua forma espiritual é sofrido como dano psíquico por seu corpo e mente. Se a magia terminar dessa maneira, seu espírito é puxado de volta ao corpo e você desperta, sofrendo 1d10 de dano psíquico para cada 30 metros entre corpo e espírito. Se você for reduzido a 0 pontos de vida em forma espiritual, a magia termina, seu espírito retorna violentamente ao corpo e você falha imediatamente em um teste de resistência contra a morte.\nSe a duração terminar normalmente, seu espírito retorna ao corpo sem problemas e você continua descansando até despertar naturalmente; a duração desta magia conta como tempo de descanso. Se for puxado de volta à força, o descanso é interrompido. Se estiver separado do corpo, você pode passar 10 minutos concentrando-se em retornar por meio de meditação ininterrupta. Ao final, a magia termina sem dano, seu corpo desperta e seu espírito retorna.","higher":"","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":550,"category":"Lyre's Guide to Retia","traits":[]},{"id":"lyre-drowning-wave","name":"Onda Afogante","originalName":"Drowning Wave","level":3,"school":"Conjuração","time":"1 ação","range":"36 metros","comp":"V, S, M (uma gota de água)","material":"uma gota de água","duration":"Instantânea","classes":"Inscritor, Cavaleiro das Pétalas, Druida, Feiticeiro, Mago","ritual":false,"concentration":false,"desc":"Você conjura uma onda de água que desaba sobre uma área dentro do alcance. A área pode ter até 9 metros de comprimento, 3 metros de largura e 3 metros de altura. Cada criatura nela deve realizar um teste de resistência de Destreza. Em uma falha, sofre 4d8 de dano de concussão e fica caída; em um sucesso, sofre metade do dano e não fica caída. A água então se espalha pelo chão em todas as direções, apagando chamas desprotegidas na área e a até 9 metros dela, e desaparece.","higher":"Quando você conjura esta magia usando um espaço de magia de 4º nível ou superior, escolha um dos efeitos a seguir para cada nível do espaço acima do 3º:\n• O dano aumenta em 1d8.\n• O comprimento, altura ou largura da onda aumenta em 3 metros.","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":551,"category":"Lyre's Guide to Retia","traits":["Legado 5.19"],"sourceNote":"A fonte identifica esta entrada como uma magia Legacy/revisada da edição 5.19; suas regras foram preservadas como uma versão própria de Lyre."},{"id":"lyre-earth-geyser","name":"Gêiser de Terra","originalName":"Earth Geyser","level":3,"school":"Transmutação","time":"1 ação","range":"36 metros","comp":"V, S, M (um pedaço de obsidiana)","material":"um pedaço de obsidiana","duration":"Instantânea","classes":"Cavaleiro das Pétalas, Druida, Feiticeiro, Mago","ritual":false,"concentration":false,"desc":"Escolha um ponto no chão que possa ver dentro do alcance. Uma fonte de terra e pedra revolvidas irrompe em um cubo de 6 metros centrado nesse ponto. Cada criatura na área deve realizar um teste de resistência de Destreza, sofrendo 3d12 de dano de concussão em uma falha ou metade em um sucesso. Além disso, o solo da área se torna terreno difícil até ser limpo. Cada quadrado de 1,5 metro exige pelo menos 1 minuto de trabalho manual para ser limpo.","higher":"Quando você conjura esta magia no 4º nível ou superior, escolha um dos efeitos a seguir para cada nível do espaço acima do 3º:\n• O lado do cubo aumenta em 1,5 metro.\n• O dano aumenta em 1d12.","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":551,"category":"Lyre's Guide to Retia","traits":["Legado 5.19"],"sourceNote":"A fonte identifica esta entrada como uma magia Legacy/revisada da edição 5.19; suas regras foram preservadas como uma versão própria de Lyre."},{"id":"lyre-earthen-eruption","name":"Erupção Terrestre","originalName":"Earthen Eruption","level":1,"school":"Evocação","time":"1 ação","range":"3 metros","comp":"V, S","material":"","duration":"Instantânea","classes":"Cavaleiro das Pétalas, Bardo, Druida, Feiticeiro, Mago","ritual":false,"concentration":false,"desc":"Você provoca um tremor no solo dentro do alcance. Cada criatura na área, exceto você, deve realizar um teste de resistência de Destreza. Em uma falha, sofre 1d6 de dano de concussão e fica caída. Se o solo da área for terra ou pedra solta, ele se torna terreno difícil até ser limpo, e cada quadrado de 1,5 metro exige pelo menos 1 minuto de trabalho manual para ser removido.","higher":"Quando você conjura esta magia usando um espaço de magia de 2º nível ou superior, escolha um dos efeitos a seguir para cada nível do espaço acima do 1º:\n• O dano aumenta em 1d6.\n• O alcance aumenta em 3 metros.\n• Cada criatura que falhar no teste é empurrada 1,5 metro para longe do centro do efeito.","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":551,"category":"Lyre's Guide to Retia","traits":["Legado 5.19","Tomo da Madeira Sussurrante"],"sourceNote":"A fonte identifica esta entrada como uma magia Legacy/revisada da edição 5.19; suas regras foram preservadas como uma versão própria de Lyre."},{"id":"lyre-earthen-grasp","name":"Agarrão Terrestre","originalName":"Earthen Grasp","level":2,"school":"Transmutação","time":"1 ação","range":"9 metros","comp":"V, S, M (uma mão em miniatura esculpida a partir de uma garra)","material":"uma mão em miniatura esculpida a partir de uma garra","duration":"Concentração, até 1 minuto","classes":"Inscritor, Feiticeiro, Mago","ritual":false,"concentration":true,"desc":"Escolha um espaço desocupado de 1,5 metro no chão que possa ver dentro do alcance. Uma mão Média feita de terra compactada se ergue e tenta agarrar uma criatura que você possa ver a até 1,5 metro dela. O alvo deve realizar um teste de resistência de Força. Em uma falha, sofre 2d6 de dano de concussão e fica impedido pela duração da magia. Com uma ação, você pode fazer a mão esmagar o alvo impedido, que deve realizar um teste de resistência de Força, sofrendo 2d6 de dano de concussão em uma falha ou metade em um sucesso. Para escapar, o alvo impedido pode usar uma ação para realizar um teste de Força contra sua CD de resistência de magia, libertando-se em um sucesso. Com uma ação, você pode fazer a mão tentar alcançar outra criatura ou se mover para outro espaço desocupado dentro do alcance. Em qualquer caso, ela solta o alvo que estiver impedindo.","higher":"","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":551,"category":"Lyre's Guide to Retia","traits":["Legado 5.19"],"sourceNote":"A fonte identifica esta entrada como uma magia Legacy/revisada da edição 5.19; suas regras foram preservadas como uma versão própria de Lyre."},{"id":"lyre-eidomantic-weapon","name":"Arma Eidomântica","originalName":"Eidomantic Weapon","level":3,"school":"Transmutação","time":"1 ação bônus","range":"Toque","comp":"V, S","material":"","duration":"Concentração, até 10 minutos","classes":"Alma Favorecida, Inscritor, Paladino, Mago","ritual":false,"concentration":true,"desc":"Você toca uma arma não mágica e a preenche com energia eidomântica, transformando-a em uma arma mágica com bônus +2 nas jogadas de ataque e dano. Pela duração, a arma causa um dado de dano adicional; o dano dela e de sua munição é considerado eidólico e mágico; e, se você estiver empunhando a arma, pode realizar um ataque com ela como uma ação bônus. Você também pode conjurar esta magia sobre uma arma mágica, mas nesse caso o bônus nas jogadas de ataque e dano é reduzido em 2.","higher":"Quando você conjura esta magia no 5º nível ou superior, escolha um dos efeitos a seguir para cada dois níveis do espaço acima do 3º:\n• O bônus nas jogadas de ataque e dano aumenta em 1, até o máximo de +4.\n• Você pode afetar uma arma adicional que possa tocar.\n• A arma causa um dado de dano adicional em um acerto.","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":551,"category":"Lyre's Guide to Retia","traits":["Eidomancia"],"sourceNote":"Regra de grupo — Eidomancia: todo dano causado por uma magia de eidomancia é considerado dano eidólico. Após conjurar a magia, realize um teste de resistência de Constituição de CD 10 + o nível em que a magia foi conjurada + o número de turnos após o primeiro em que ela permaneceu ativa sob concentração. Se não exigir concentração, o teste é feito imediatamente após a conjuração. Em uma falha, você sofre níveis de exaustão iguais à metade do nível da magia, arredondado para baixo (mínimo 1), e não pode conjurá-la novamente por sete dias. Se a falha elevaria a exaustão a 6, ela fica em 5 e você é imediatamente reduzido a 0 pontos de vida. Se falhar em um teste de concentração para manter uma magia de eidomancia, você pode usar sua reação para rolar um d20 e usar esse resultado no lugar do d20 do teste de concentração."},{"id":"lyre-eidomantic-feedback","name":"Retorno Eidomântico","originalName":"Eidomantic Feedback","level":4,"school":"Abjuração","time":"1 reação, realizada quando uma criatura dentro do alcance conjura uma magia","range":"36 metros","comp":"V, S","material":"","duration":"Instantânea","classes":"Bardo, Feiticeiro, Mago","ritual":false,"concentration":false,"desc":"Seu alvo sofre uma reação de retorno da magia que está conjurando, fazendo o corpo dele se contorcer de dor. O alvo deve realizar um teste de resistência de Carisma. Em uma falha, sofre 2d10 de dano psíquico, mais 1d8 de dano psíquico adicional para cada nível em que a magia dele foi conjurada acima do 1º. Em um sucesso, sofre metade do dano. Se a magia que ele estiver conjurando exigir concentração, esse dano provoca um teste de concentração depois que os efeitos imediatos da magia forem resolvidos.","higher":"Quando você conjura esta magia no 5º nível ou superior, pode escolher uma criatura adicional a até 18 metros do alvo para cada nível do espaço acima do 4º. Cada uma dessas criaturas realiza um teste de resistência de Destreza, sofrendo o mesmo dano do alvo inicial em uma falha ou nenhum em um sucesso.","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":552,"category":"Lyre's Guide to Retia","traits":["Arcana da Tecelã dos Céus"]},{"id":"lyre-electric-arc","name":"Arco Elétrico","originalName":"Electric Arc","level":4,"school":"Evocação","time":"1 ação","range":"9 metros","comp":"V, S, M (uma haste de vidro e um pedaço de pelo)","material":"uma haste de vidro e um pedaço de pelo","duration":"Instantânea","classes":"Alma Favorecida, Inscritor, Mago","ritual":false,"concentration":false,"desc":"Energia elétrica salta das pontas dos seus dedos em direção a quatro criaturas à sua escolha dentro do alcance. Cada uma deve realizar um teste de resistência de Destreza; em uma falha, sofre 7d8 de dano elétrico.","higher":"Quando você conjura esta magia no 5º nível ou superior, pode escolher uma criatura adicional para cada nível do espaço acima do 4º.","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":552,"category":"Lyre's Guide to Retia","traits":["Memórias de Ossenheimer"]},{"id":"lyre-electric-chain","name":"Corrente Elétrica","originalName":"Electric Chain","level":0,"school":"Evocação","time":"1 ação","range":"Pessoal (raio de 4,5 metros)","comp":"V","material":"","duration":"Instantânea","classes":"Feiticeiro, Bruxo, Mago","ritual":false,"concentration":false,"desc":"Você cria uma corrente vinculante de energia elétrica que atinge uma criatura à sua escolha que possa ver a até 4,5 metros. O alvo deve ser bem-sucedido em um teste de resistência de Força ou é puxado até 3 metros em linha reta em sua direção e então sofre 1d8 de dano elétrico se estiver a até 1,5 metro de você. O dano aumenta em 1d8 no 5º nível (2d8), 11º (3d8) e 17º (4d8). O alcance também aumenta em 1,5 metro nesses níveis: 6 m no 5º, 7,5 m no 11º e 9 m no 17º. No 11º nível, a corrente pode puxar criaturas 4,5 metros em vez de 3 metros.","higher":"","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":552,"category":"Lyre's Guide to Retia","traits":["Legado 5.19"],"sourceNote":"A fonte identifica esta entrada como uma magia Legacy/revisada da edição 5.19; suas regras foram preservadas como uma versão própria de Lyre."},{"id":"lyre-elstrakins-instant-bounty","name":"Recompensa Instantânea de Elstrakin","originalName":"Elstrakin’s Instant Bounty","level":5,"school":"Conjuração","time":"1 ação","range":"9 metros","comp":"V, S, M (um cálice de prata no valor de pelo menos 1.000 po, que a magia consome)","material":"um cálice de prata no valor de pelo menos 1.000 po, que a magia consome","duration":"Instantânea","classes":"Alma Favorecida, Clérigo","ritual":false,"concentration":false,"desc":"Você faz os corpos de todas as criaturas à sua escolha dentro do alcance se tornarem saudáveis e renovados. Todos os alvos são imediatamente curados de qualquer exaustão ou veneno que os afete, ficam completamente alimentados e, se estiverem caídos, podem usar a reação para se levantar imediatamente. Além disso, todas as criaturas escolhidas têm vantagem em testes de resistência até o início do seu próximo turno.","higher":"","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":552,"category":"Lyre's Guide to Retia","traits":["Grimório do Espreitador"]},{"id":"lyre-elstrakins-loving-embrace","name":"Abraço Amoroso de Elstrakin","originalName":"Elstrakin’s Loving Embrace","level":7,"school":"Ilusão","time":"1 ação","range":"9 metros","comp":"V, S","material":"","duration":"1 dia","classes":"Lista especial / não especificada","ritual":false,"concentration":false,"desc":"Uma ilusão enganosa de alguém ou algo querido pelo alvo aparece apenas para uma criatura à sua escolha dentro do alcance e a envolve em seus braços. O alvo deve realizar um teste de resistência de Carisma. Em uma falha, a ilusão o deixa dócil e relaxado; a criatura fica paralisada pela duração da magia, incapaz de se concentrar em qualquer coisa além da ilusão. Ao final de cada um de seus turnos, ela pode repetir o teste de resistência, encerrando o efeito em um sucesso.","higher":"","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":552,"category":"Lyre's Guide to Retia","traits":["Grimório do Espreitador"]},{"id":"lyre-embedded-message","name":"Mensagem Embutida","originalName":"Embedded Message","level":2,"school":"Ilusão","time":"1 minuto","range":"9 metros","comp":"V, S, M (um pequeno pedaço de favo de mel e pó de jade no valor de pelo menos 10 po, que a magia consome)","material":"um pequeno pedaço de favo de mel e pó de jade no valor de pelo menos 10 po, que a magia consome","duration":"Até ser dissipada","classes":"Inscritor, Bardo, Mago","ritual":true,"concentration":false,"desc":"Você implanta em um objeto dentro do alcance uma mensagem que é pronunciada quando uma condição de gatilho é satisfeita. Escolha um objeto que possa ver e que não esteja sendo vestido nem carregado por outra criatura. Diga a mensagem, que deve ter até 25 palavras, embora possa ser pronunciada ao longo de até 10 minutos. Por fim, determine a circunstância que fará a magia entregar a mensagem. Quando essa circunstância ocorre, uma voz vinda do objeto recita a mensagem com sua voz e no mesmo volume em que você falou; uma boca pode aparecer para pronunciá-la. Se o objeto possuir uma boca ou algo semelhante, como a boca de uma estátua, a boca mágica aparece ali para que as palavras pareçam vir do próprio objeto. Ao conjurar a magia, você pode fazê-la terminar depois de transmitir a mensagem ou permanecer e repeti-la sempre que o gatilho ocorrer. Como alternativa, quando o objeto pronunciaria a mensagem, você pode fazê-la ser transmitida telepaticamente a uma criatura a até 9 metros; o alvo a ouve mentalmente com sua voz e no idioma usado. Nesse caso, o gatilho deve especificar quem deve ouvir. A circunstância pode ser tão geral ou detalhada quanto desejar, mas deve se basear em condições visuais ou audíveis que ocorram a até 9 metros do objeto. Por exemplo, a boca pode falar quando qualquer criatura se aproximar a 9 metros ou quando um sino de prata tocar a essa distância.","higher":"Quando você conjura esta magia usando um espaço de magia de 3º nível ou superior, escolha um dos efeitos a seguir para cada nível do espaço acima do 2º:\n• O número de palavras permitido na mensagem dobra.\n• O alcance da magia dobra, assim como os alcances dos gatilhos, das criaturas que podem receber a mensagem e de todas as demais distâncias descritas na magia.","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":552,"category":"Lyre's Guide to Retia","traits":["Legado 5.19","Ritual"],"sourceNote":"A fonte identifica esta entrada como uma magia Legacy/revisada da edição 5.19; suas regras foram preservadas como uma versão própria de Lyre."},{"id":"lyre-enamor","name":"Enamorar","originalName":"Enamor","level":2,"school":"Encantamento","time":"1 ação","range":"18 metros","comp":"V, S","material":"","duration":"1 minuto","classes":"Cavaleiro das Pétalas, Bardo, Druida, Feiticeiro, Bruxo, Mago","ritual":false,"concentration":false,"desc":"Você tece uma sequência de palavras distrativas. Criaturas à sua escolha que você possa ver dentro do alcance e que possam ouvi-lo devem realizar um teste de resistência de Sabedoria. Uma criatura imune a ser enfeitiçada obtém sucesso automaticamente; se você ou seus companheiros estiverem lutando contra ela, ela tem vantagem no teste. Em uma falha, o alvo tem desvantagem em testes de Sabedoria (Percepção) para perceber qualquer criatura que não seja você até a magia terminar ou até não poder mais ouvi-lo. A magia termina se você ficar incapacitado ou não puder mais falar.","higher":"Quando você conjura esta magia usando um espaço de magia de 3º nível ou superior, o número de criaturas que pode escolher como alvo dobra para cada nível do espaço acima do 2º.","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":553,"category":"Lyre's Guide to Retia","traits":["Legado 5.19"],"sourceNote":"A fonte identifica esta entrada como uma magia Legacy/revisada da edição 5.19; suas regras foram preservadas como uma versão própria de Lyre."},{"id":"lyre-enamor-monster","name":"Enamorar Monstro","originalName":"Enamor Monster","level":4,"school":"Encantamento","time":"1 ação","range":"9 metros","comp":"V, S","material":"","duration":"1 hora","classes":"Cavaleiro das Pétalas, Bardo, Druida, Feiticeiro, Bruxo, Mago","ritual":false,"concentration":false,"desc":"Você tenta enfeitiçar uma criatura que possa ver dentro do alcance. Ela deve realizar um teste de resistência de Sabedoria, com vantagem se você ou seus companheiros estiverem lutando contra ela. Em uma falha, fica enfeitiçada por você até a magia terminar ou até você ou seus companheiros causarem qualquer dano a ela. A criatura enfeitiçada é amistosa a você. Quando a magia termina, ela sabe que foi enfeitiçada por você.","higher":"Quando você conjura esta magia usando um espaço de magia de 5º nível ou superior, escolha um dos efeitos a seguir para cada nível do espaço acima do 4º:\n• O número de criaturas que você pode escolher como alvo dobra para cada nível de espaço gasto dessa forma. Cada alvo deve estar dentro do alcance.\n• O alcance aumenta em 9 metros.\n• Quando a magia termina, as criaturas não sabem que foram enfeitiçadas por você, a menos que isso tenha ficado óbvio por fatores externos.","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":553,"category":"Lyre's Guide to Retia","traits":["Legado 5.19"],"sourceNote":"A fonte identifica esta entrada como uma magia Legacy/revisada da edição 5.19; suas regras foram preservadas como uma versão própria de Lyre."},{"id":"lyre-energy-scourge","name":"Flagelo Energético","originalName":"Energy Scourge","level":4,"school":"Transmutação","time":"1 ação","range":"27 metros","comp":"V, S","material":"","duration":"Concentração, até 1 minuto","classes":"Alma Favorecida, Cavaleiro das Pétalas, Druida, Bruxo, Mago","ritual":false,"concentration":true,"desc":"Escolha uma criatura que possa ver dentro do alcance e um dos seguintes tipos de dano: ácido, frio, fogo, elétrico ou trovejante. O alvo deve ser bem-sucedido em um teste de resistência de Constituição ou é afetado pela magia durante a duração. Na primeira vez em cada turno que o alvo afetado sofrer dano do tipo escolhido, ele sofre 2d6 de dano adicional desse tipo. Além disso, ele perde qualquer resistência a esse tipo de dano até a magia terminar.","higher":"Quando você conjura esta magia usando um espaço de magia de 5º nível ou superior, escolha um dos efeitos a seguir para cada nível do espaço acima do 4º:\n• Você pode escolher uma criatura adicional; as criaturas devem estar a até 9 metros umas das outras quando forem escolhidas.\n• O efeito se aplica à primeira e à segunda vez que a criatura sofrer esse tipo de dano em cada turno.\n• Se o alvo for imune ao tipo de dano, ele passa a ser apenas resistente.\n• O dano desta magia aumenta em 1d6.","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":553,"category":"Lyre's Guide to Retia","traits":["Legado 5.19"],"sourceNote":"A fonte identifica esta entrada como uma magia Legacy/revisada da edição 5.19; suas regras foram preservadas como uma versão própria de Lyre."},{"id":"lyre-enlarge-reduce","name":"Aumentar/Reduzir","originalName":"Enlarge/Reduce","level":2,"school":"Transmutação","time":"1 ação","range":"9 metros","comp":"V, S, M (uma pitada de ferro em pó)","material":"uma pitada de ferro em pó","duration":"Concentração, até 1 minuto","classes":"Alma Favorecida, Inscritor, Bardo, Druida, Feiticeiro, Mago","ritual":false,"concentration":true,"desc":"Você faz uma criatura ou objeto que possa ver dentro do alcance aumentar ou diminuir de tamanho pela duração. Escolha uma criatura ou um objeto que não esteja sendo vestido nem carregado. Se o alvo não for voluntário, pode realizar um teste de resistência de Constituição. Em um sucesso, a magia não tem efeito. Se o alvo for uma criatura, tudo que ela estiver vestindo e carregando muda de tamanho com ela. Qualquer item largado por uma criatura afetada retorna imediatamente ao tamanho normal.\nAumentar. O tamanho do alvo dobra em todas as dimensões e seu peso é multiplicado por oito. Isso aumenta seu tamanho em uma categoria, de Médio para Grande, por exemplo. Se não houver espaço suficiente para dobrar de tamanho, a criatura ou objeto cresce até o máximo possível no espaço disponível. Até a magia terminar, o alvo tem vantagem em testes de Força e testes de resistência de Força. As armas do alvo também aumentam, e ataques com elas causam 1d4 de dano adicional.\nReduzir. O tamanho do alvo é reduzido pela metade em todas as dimensões, e seu peso cai para um oitavo do normal. Isso reduz seu tamanho em uma categoria, de Médio para Pequeno, por exemplo. Até a magia terminar, o alvo tem desvantagem em testes de Força e testes de resistência de Força. As armas do alvo também encolhem, e ataques com elas causam 1d4 de dano a menos, sem poder reduzir o dano abaixo de 1.","higher":"Quando você conjura esta magia em um nível superior ao 3º, pode aplicar novamente o efeito escolhido — Aumentar ou Reduzir — para cada dois níveis do espaço acima do 2º (4º, 6º e 8º).\nAumentar. As dimensões dobram novamente, o peso resultante é multiplicado por oito e o alvo aumenta mais uma categoria de tamanho, se possível. As armas e equipamentos crescem junto, e os ataques causam 1d4 de dano adicional para cada categoria de tamanho aumentada.\nReduzir. As dimensões são reduzidas pela metade novamente, o peso resultante cai para um oitavo e o alvo diminui mais uma categoria. Este efeito só pode reduzir uma criatura até Minúscula. Para cada categoria reduzida, os ataques causam 1d4 de dano a menos, com mínimo de 1.","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":553,"category":"Lyre's Guide to Retia","traits":["Legado 5.19"],"sourceNote":"A fonte identifica esta entrada como uma magia Legacy/revisada da edição 5.19; suas regras foram preservadas como uma versão própria de Lyre."},{"id":"lyre-entrap","name":"Aprisionar","originalName":"Entrap","level":1,"school":"Abjuração","time":"1 minuto","range":"Toque","comp":"S, M (7,5 metros de corda, que a magia consome)","material":"7,5 metros de corda, que a magia consome","duration":"8 horas","classes":"Cavaleiro das Pétalas, Patrulheiro, Druida, Mago","ritual":false,"concentration":false,"desc":"Ao conjurar esta magia, você usa a corda para formar um círculo de 1,5 metro de raio no chão ou piso. Quando termina, a corda desaparece e o círculo se torna uma armadilha mágica. Ela é quase invisível e exige um teste bem-sucedido de Inteligência (Investigação) contra sua CD de resistência de magia para ser percebida. A armadilha é acionada quando uma criatura entra no solo dentro do raio da magia, desde que o raio ocupe pelo menos metade dos espaços no chão em que ela se encontra. A criatura deve realizar um teste de resistência de Destreza. Em uma falha, é magicamente erguida no ar e fica pendurada de cabeça para baixo cerca de 1 metro acima do chão, impedida até a magia terminar. Uma criatura impedida pode repetir o teste de Destreza ao final de cada um de seus turnos, encerrando o efeito em um sucesso. Como alternativa, ela ou outra criatura que consiga alcançá-la pode usar uma ação para realizar um teste de Inteligência (Arcanismo) contra sua CD de magia, encerrando a condição impedido em um sucesso. Depois que a armadilha for acionada, a magia termina quando nenhuma criatura estiver impedida por ela.","higher":"Quando você conjura esta magia usando um espaço de magia de 2º nível ou superior, escolha um dos efeitos a seguir para cada nível do espaço acima do 1º:\n• O raio da armadilha aumenta em 1,5 metro.\n• Uma armadilha adicional é criada a até 3 metros de outra armadilha criada por você.","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":554,"category":"Lyre's Guide to Retia","traits":["Legado 5.19"],"sourceNote":"A fonte identifica esta entrada como uma magia Legacy/revisada da edição 5.19; suas regras foram preservadas como uma versão própria de Lyre."},{"id":"lyre-entropic-shield","name":"Escudo Entrópico","originalName":"Entropic Shield","level":4,"school":"Abjuração","time":"1 reação, realizada quando você é atingido por um ataque","range":"Pessoal","comp":"V","material":"","duration":"1 rodada","classes":"Inscritor, Cavaleiro das Pétalas, Clérigo, Feiticeiro, Mago","ritual":false,"concentration":false,"desc":"Uma barreira de energia congelante aparece entre você e o atacante. Até o início do seu próximo turno, você possui três quartos de cobertura, inclusive contra o ataque que desencadeou a magia. Se um ataque o atingir, o escudo se estilhaça e o efeito termina. Se o atacante estiver a até 9 metros, a energia do escudo o atinge, obrigando-o a realizar um teste de resistência de Constituição. Em uma falha, ele sofre 4d10 de dano de frio e fica incapacitado até o início do seu próximo turno.","higher":"Quando você conjura esta magia no 5º nível ou superior, para cada nível do espaço acima do 4º escolha um benefício:\n• O escudo concede +1 adicional à sua Classe de Armadura.\n• O dano de frio aumenta em 2d10.","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":554,"category":"Lyre's Guide to Retia","traits":["Artes Arcanas de Altissima-Cor"]},{"id":"lyre-everests-isolated-undoing","name":"Desfazer Isolado de Everest","originalName":"Everest’s Isolated Undoing","level":5,"school":"Abjuração","time":"1 ação","range":"Pessoal","comp":"V, S","material":"","duration":"Concentração, até 10 minutos","classes":"Inscritor, Mago","ritual":false,"concentration":true,"desc":"Você fica levemente deslocado para fora do Plano Material e recebe proteção especial contra ataques de ampla área. Se for alvo de um efeito que exija teste de resistência e afete mais de uma criatura ao mesmo tempo, como bola de fogo, você pode usar sua reação para ser ignorado pelo efeito, como se não estivesse presente, atravessando-o sem sofrer consequências. Se estiver dentro de um efeito contínuo que permaneça em uma área, como névoa mortal, você é ignorado por ele enquanto ao menos outra criatura estiver sendo afetada.","higher":"Quando você conjura esta magia usando um espaço de magia de 6º nível ou superior, pode escolher uma criatura adicional, além de você, para cada nível do espaço acima do 5º. Essas criaturas devem estar ao alcance de toque quando você conjura a magia. Se os efeitos desta magia vierem a se aplicar a todos os alvos de um mesmo efeito, ela não oferece proteção a nenhum deles.","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":554,"category":"Lyre's Guide to Retia","traits":["Grimório do Espreitador"]},{"id":"lyre-eviscerate","name":"Eviscerar","originalName":"Eviscerate","level":3,"school":"Necromancia","time":"1 reação, realizada quando uma criatura dentro do alcance morre","range":"18 metros","comp":"S","material":"","duration":"Instantânea","classes":"Druida, Feiticeiro, Mago","ritual":false,"concentration":false,"desc":"Quando uma criatura dentro do alcance morre, o sangue e os tecidos físicos dela se tornam explosivos e seu corpo detona em uma onda de energia necrótica. Criaturas a até 3 metros dela devem realizar um teste de resistência de Destreza, sofrendo 8d6 de dano necrótico em uma falha ou metade em um sucesso. Se essa explosão matar outra criatura, role 1d100 para cada uma. Com 61 ou mais, o corpo dessa criatura também explode em energia necrótica, mas afeta apenas criaturas a até 1,5 metro. Criaturas que falharem nesse teste secundário sofrem 2d6 de dano necrótico, e nenhuma quantidade em um sucesso. Criaturas que falharam no primeiro teste são excluídas do segundo. Esta magia só pode afetar criaturas Pequenas, Médias ou Grandes. Para cada categoria de tamanho acima de Médio que o alvo possua, o raio da detonação aumenta em 3 metros, ou 1,5 metro para detonações secundárias. Um corpo destruído por esta magia é tratado como se estivesse morto há um dia inteiro, pois fica ressequido e despedaçado.","higher":"Quando você conjura esta magia no 4º nível ou superior, escolha um dos efeitos a seguir para cada nível do espaço acima do 3º:\n• A maior categoria de tamanho que você pode afetar aumenta em uma.\n• Os danos necróticos primário e secundário aumentam em 1d8 e 1d6, respectivamente.","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":554,"category":"Lyre's Guide to Retia","traits":["Grimório da Guardiã dos Céus"]},{"id":"lyre-eye-of-eradication","name":"Olho da Erradicação","originalName":"Eye of Eradication","level":9,"school":"Necromancia","time":"1 ação bônus","range":"Pessoal","comp":"V, S, M (um olho de demônio seco)","material":"um olho de demônio seco","duration":"Concentração, até 1 minuto","classes":"Bardo, Druida, Feiticeiro, Bruxo","ritual":false,"concentration":true,"desc":"Pela duração da magia, um de seus olhos fica infundido com energia corruptora concentrada que rasga a mente de quem o vê, concedendo a você visão do diabo até 36 metros. Uma criatura à sua escolha que você possa ver nesse alcance deve realizar um teste de resistência de Carisma. Em uma falha, sofre 10d10 de dano psíquico. Se falhar por 5 ou mais, fica amedrontada por você até o início do seu próximo turno. Em cada turno posterior enquanto a magia durar, você pode usar uma ação bônus para escolher outra criatura que possa vê-lo a até 36 metros e repetir o efeito. Se você falhar em um teste de concentração causado por um ataque com arma e a magia terminar por isso, pode usar sua reação para forçar a criatura que realizou o ataque e cada criatura à sua escolha a até 4,5 metros dela a realizar o mesmo teste de Carisma enquanto a magia termina. Se qualquer efeito desta magia matar uma criatura, o corpo fica ressequido e retorcido de terror, impedindo sua ressurreição por qualquer magia que não seja ressurreição verdadeira ou intervenção divina.","higher":"","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":555,"category":"Lyre's Guide to Retia","traits":["Daemoturgia"]},{"id":"lyre-faithful-hound","name":"Cão Fiel","originalName":"Faithful Hound","level":4,"school":"Conjuração","time":"1 ação","range":"9 metros","comp":"V, S, M (um pequeno apito de prata, um pedaço de osso e um fio)","material":"um pequeno apito de prata, um pedaço de osso e um fio","duration":"8 horas","classes":"Inscritor, Cavaleiro das Pétalas, Mago","ritual":false,"concentration":false,"desc":"Você conjura um cão de guarda fantasma em um espaço desocupado que possa ver dentro do alcance. Ele permanece pela duração, até você dispensá-lo com uma ação ou até você se afastar mais de 30 metros dele. O cão é invisível para todas as criaturas exceto você e não pode ser ferido. Quando uma criatura Pequena ou maior chega a até 9 metros sem antes dizer a senha definida ao conjurar a magia, o cão começa a latir alto. Ele enxerga criaturas invisíveis, pode ver o Plano Etéreo e ignora ilusões. No início de cada um dos seus turnos, o cão tenta morder uma criatura hostil a você a até 1,5 metro dele. O bônus de ataque do cão é igual ao seu modificador do atributo de conjuração + seu bônus de proficiência. Em um acerto, causa 4d8 de dano perfurante.","higher":"","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":555,"category":"Lyre's Guide to Retia","traits":["Legado 5.19","Memórias de Ossenheimer"],"sourceNote":"A fonte identifica esta entrada como uma magia Legacy/revisada da edição 5.19; suas regras foram preservadas como uma versão própria de Lyre."},{"id":"lyre-falling-meteor","name":"Meteoro Cadente","originalName":"Falling Meteor","level":2,"school":"Transmutação","time":"1 reação, realizada quando você cai 3 metros ou mais","range":"Pessoal (raio de 4,5 metros)","comp":"S","material":"","duration":"1 minuto","classes":"Cavaleiro das Pétalas, Clérigo, Paladino","ritual":false,"concentration":false,"desc":"Ao cair de uma altura superior a 3 metros, você conjura uma proteção flamejante ao redor de si e se transforma em um meteoro de pura energia que despenca. Você pode escolher aterrissar em um espaço desocupado controlando a queda, caindo duas vezes mais rápido que o normal. Esse espaço pode estar afastado do ponto onde você normalmente cairia por uma distância de até metade do número de metros que irá descer, arredondada para baixo. Ao aterrissar, você libera uma onda de energia que atinge tudo a até 4,5 metros, inclusive você. Criaturas na área devem realizar um teste de resistência de Constituição, sofrendo como dano de energia a quantidade de dano de queda que você teria sofrido em uma falha, ou metade em um sucesso. Qualquer criatura que falhar, incluindo você, fica caída. A magia então termina. O dano desta magia não pode exceder seu máximo de pontos de vida. Se uma criatura conjurar queda suave em você durante a queda, você deve realizar um teste de concentração contra a CD de magia dela. Em uma falha, esta magia termina; em um sucesso, você ignora queda suave.","higher":"Se você conjurar esta magia no 3º nível ou superior, o raio da explosão aumenta em 3 metros para cada nível do espaço acima do 2º. Se conjurá-la no 5º nível ou superior, você obtém sucesso automático no seu teste de resistência de Constituição.","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":555,"category":"Lyre's Guide to Retia","traits":["Legado do Ouro"]},{"id":"lyre-fiendish-aspect","name":"Aspecto Infernal","originalName":"Fiendish Aspect","level":0,"school":"Transmutação","time":"1 ação","range":"Pessoal","comp":"V, S","material":"","duration":"Concentração, até 1 minuto","classes":"Bardo, Druida, Feiticeiro","ritual":false,"concentration":true,"desc":"Seu corpo se altera para adquirir as propriedades necessárias a um tipo de movimento à sua escolha. Escolha natação, escalada ou um efeito/aspecto ambiental que esteja tornando o terreno difícil. Seu deslocamento base passa a ser do tipo escolhido; se você escolher um efeito ou elemento ambiental, ele deixa de contar como terreno difícil para você. Se atravessar uma área usando esse novo tipo de movimento ou o efeito/ambiente designado normalmente causaria dano automaticamente, você ignora esse dano até o início do seu próximo turno.","higher":"","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":555,"category":"Lyre's Guide to Retia","traits":["Daemoturgia"]},{"id":"lyre-find-the-path","name":"Encontrar o Caminho","originalName":"Find the Path","level":6,"school":"Adivinhação","time":"1 minuto","range":"Pessoal","comp":"V, S, M (um conjunto de ferramentas de adivinhação — como ossos, varetas de marfim, cartas, dentes ou runas entalhadas — no valor de 100 po e um objeto do local que você deseja encontrar)","material":"um conjunto de ferramentas de adivinhação — como ossos, varetas de marfim, cartas, dentes ou runas entalhadas — no valor de 100 po e um objeto do local que você deseja encontrar","duration":"Concentração, até 1 dia","classes":"Bardo, Clérigo, Druida","ritual":false,"concentration":true,"desc":"Esta magia permite encontrar a rota física mais curta e direta até um local fixo específico com o qual você esteja familiarizado e que esteja no mesmo plano de existência. Se nomear um destino em outro plano, um destino móvel, como uma fortaleza ambulante, ou um destino impreciso, como “o covil de um dragão verde”, a magia falha. Pela duração, enquanto estiver no mesmo plano do destino, você sabe a distância e a direção até ele. Durante a viagem, sempre que houver uma escolha de caminhos, você determina automaticamente qual é a rota mais curta e direta, embora não necessariamente a mais segura. Ao viajar em direção ao destino por mais de uma hora usando esta magia, você e aqueles que seguem sua orientação percorrem 1,5 vez a distância normal, explorando rotas e atalhos ideais. Isso não permite ignorar algo que interromperia a viagem, a menos que a magia forneça outra rota que evite inteiramente esse obstáculo.","higher":"","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":556,"category":"Lyre's Guide to Retia","traits":["Legado 5.19"],"sourceNote":"A fonte identifica esta entrada como uma magia Legacy/revisada da edição 5.19; suas regras foram preservadas como uma versão própria de Lyre."},{"id":"lyre-fire-whip","name":"Chicote de Fogo","originalName":"Fire Whip","level":2,"school":"Conjuração","time":"1 ação","range":"4,5 metros","comp":"S, M (uma tira de couro queimado)","material":"uma tira de couro queimado","duration":"Instantânea","classes":"Patrulheiro, Druida, Feiticeiro, Bruxo","ritual":false,"concentration":false,"desc":"Você cria um chicote flamejante que atinge um alvo dentro do alcance como um ataque corpo a corpo com magia. Em um acerto, o alvo sofre 3d8 de dano de fogo e deve realizar um teste de resistência de Força. Em uma falha, você pode puxá-lo para qualquer espaço desocupado dentro do alcance da magia, onde ele fica caído. Movimento realizado dentro do alcance desta magia não conta para dano de queda.","higher":"Quando você conjura esta magia no 3º nível ou superior, escolha um dos efeitos a seguir para cada nível do espaço acima do 2º:\n• O dano aumenta em 1d10.\n• O alcance aumenta em 1,5 metro.\n• Você pode escolher um alvo adicional dentro do alcance, afetado por outro chicote de fogo. Todas as criaturas que você escolher e mover devem terminar em espaços adjacentes umas às outras; caso contrário, nenhuma delas é puxada.","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":556,"category":"Lyre's Guide to Retia","traits":["Sangue de Cineris"]},{"id":"lyre-fireball","name":"Bola de Fogo","originalName":"Fireball","level":3,"school":"Evocação","time":"1 ação","range":"45 metros","comp":"V, S, M (uma pequena esfera de guano de morcego e enxofre)","material":"uma pequena esfera de guano de morcego e enxofre","duration":"Instantânea","classes":"Alma Favorecida, Paladino, Feiticeiro, Mago","ritual":false,"concentration":false,"desc":"Um clarão brilhante parte de seu dedo apontado até um ponto à sua escolha dentro do alcance e então floresce com um rugido baixo em uma explosão de chamas. Cada criatura em uma esfera de 6 metros de raio centrada nesse ponto deve realizar um teste de resistência de Destreza. Um alvo sofre 8d6 de dano de fogo em uma falha ou metade em um sucesso. O fogo contorna esquinas e incendeia objetos inflamáveis na área que não estejam sendo vestidos nem carregados.","higher":"Quando você conjura esta magia no 4º nível ou superior, escolha um dos efeitos a seguir para cada nível do espaço acima do 3º:\n• O dano aumenta em 1d6.\n• O raio da esfera e o alcance da magia aumentam em 3 metros.\n• Cada criatura que falhar no teste de resistência fica Incendiada, conforme a condição do sistema.","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":556,"category":"Lyre's Guide to Retia","traits":["Legado 5.19"],"sourceNote":"A fonte identifica esta entrada como uma magia Legacy/revisada da edição 5.19; suas regras foram preservadas como uma versão própria de Lyre."},{"id":"lyre-firesage-robe","name":"Manto do Sábio do Fogo","originalName":"Firesage Robe","level":6,"school":"Encantamento","time":"1 ação bônus","range":"Pessoal","comp":"V, S, M (uma pedra de jade no valor de pelo menos 1.000 po, que a magia consome)","material":"uma pedra de jade no valor de pelo menos 1.000 po, que a magia consome","duration":"Concentração, até 1 hora","classes":"Inscritor, Druida, Bruxo","ritual":false,"concentration":true,"desc":"Você fica envolto por um manto de chamas vermelhas e esmeralda e recebe os benefícios a seguir pela duração da magia:\n• Sua CA passa a ser 8 + seu modificador do atributo de conjuração + seu bônus de proficiência, caso ainda não fosse maior.\n• Você recebe visão no escuro até 72 metros.\n• Você fica imune a dano de fogo.\n• Se uma criatura a até 1,5 metro acertar você com um ataque corpo a corpo, ela sofre 1d10 de dano de fogo.\n• Você não pode ser enfeitiçado nem amedrontado.\n• Seus ataques com armas causam 1d6 de dano de fogo adicional.","higher":"Quando você conjura esta magia usando um espaço de magia de 7º nível ou superior, os danos de 1d6 e 1d10 aumentam em 1d6 e 1d10, respectivamente, para cada dois níveis do espaço acima do 5º.","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":556,"category":"Lyre's Guide to Retia","traits":["Artes dos Nove Ramos"]},{"id":"lyre-flash-cure","name":"Cura Relâmpago","originalName":"Flash Cure","level":4,"school":"Evocação","time":"1 ação bônus","range":"9 metros","comp":"V, S","material":"","duration":"Instantânea","classes":"Alma Favorecida, Clérigo, Druida","ritual":false,"concentration":false,"desc":"Escolha um número de criaturas dentro do alcance igual ao nível em que esta magia foi conjurada. Esses alvos recuperam pontos de vida iguais a 1d4 + seu modificador do atributo de conjuração. Se estiverem envenenados, paralisados, atordoados ou incapacitados por um efeito que permita testes de resistência contínuos, podem imediatamente repetir esses testes com vantagem, encerrando os efeitos em um sucesso.","higher":"","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":556,"category":"Lyre's Guide to Retia","traits":[]},{"id":"lyre-floating-disc","name":"Disco Flutuante","originalName":"Floating Disc","level":1,"school":"Conjuração","time":"1 ação","range":"9 metros","comp":"V, S, M (uma gota de mercúrio)","material":"uma gota de mercúrio","duration":"1 hora","classes":"Lista especial / não especificada","ritual":false,"concentration":false,"desc":"Esta magia cria um plano circular e horizontal de energia, com cerca de 90 centímetros de diâmetro e 2,5 centímetros de espessura, que flutua 90 centímetros acima do chão em um espaço desocupado à sua escolha que possa ver dentro do alcance. O disco permanece pela duração e suporta até cerca de 225 kg. Se mais peso for colocado nele, a magia termina e tudo cai ao chão. O disco fica imóvel enquanto você estiver a até 6 metros dele. Se você se afastar mais de 6 metros, ele o segue para permanecer nessa distância. Pode atravessar terreno irregular, subir ou descer escadas e inclinações, mas não consegue atravessar uma diferença de elevação de 3 metros ou mais. Por exemplo, não pode atravessar um fosso de 3 metros de profundidade nem sair dele se tiver sido criado no fundo. Se você se afastar mais de 30 metros do disco, normalmente porque ele não consegue contornar um obstáculo, a magia termina.","higher":"","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":557,"category":"Lyre's Guide to Retia","traits":["Legado 5.19"],"sourceNote":"A fonte identifica esta entrada como uma magia Legacy/revisada da edição 5.19; suas regras foram preservadas como uma versão própria de Lyre."},{"id":"lyre-force-missile","name":"Míssil de Energia","originalName":"Force Missile","level":4,"school":"Evocação","time":"1 ação","range":"9 metros","comp":"V, S","material":"","duration":"Instantânea","classes":"Inscritor, Mago","ritual":false,"concentration":false,"desc":"Você conjura um grande míssil de energia e o dispara contra um ponto que possa ver dentro do alcance, onde ele explode em uma esfera de 1,5 metro de raio. Todas as criaturas na área sofrem 5d6 de dano de energia. Qualquer efeito capaz de anular, negar ou proteger contra mísseis mágicos pode tratar esta magia da mesma forma. Esta magia causa dano dobrado a estruturas.","higher":"Se conjurada no 5º nível ou superior, você cria um míssil adicional para cada nível do espaço acima do 4º. Cada míssil pode ser disparado contra um ponto diferente dentro do alcance. As áreas de dois mísseis não podem se sobrepor; se uma mesma criatura ficar em múltiplas áreas, ela só sofre dano uma vez.","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":557,"category":"Lyre's Guide to Retia","traits":["Memórias de Ossenheimer"]},{"id":"lyre-forgelords-chains","name":"Correntes do Senhor da Forja","originalName":"Forgelord’s Chains","level":5,"school":"Conjuração","time":"1 ação bônus","range":"Pessoal","comp":"V","material":"","duration":"Concentração, até 10 minutos","classes":"Inscritor, Cavaleiro das Pétalas, Clérigo, Paladino, Bruxo","ritual":false,"concentration":true,"desc":"Correntes incandescentes surgem em uma arma à sua escolha, envolvendo-a e seu braço. Até a magia terminar, você não pode ser desarmado dessa arma e, se ela estiver a até 9 metros, pode usar sua reação para puxá-la de volta à mão. Enquanto as correntes a prendem, a arma causa 2d8 de dano de fogo adicional em um acerto. Uma vez por turno, quando acertar uma criatura com essa arma, você pode obrigá-la a realizar um teste de resistência de Força enquanto correntes surgem e a prendem no lugar. Em uma falha, ela sofre 4d10 de dano de fogo e fica impedida até o início do seu próximo turno. Se uma ou mais criaturas estiverem presas dessa forma no início do seu turno, você pode usar uma ação bônus para fazê-las repetir o teste; em uma falha, sofrem mais 2d10 de dano de fogo e o efeito continua até o início do seu próximo turno.","higher":"","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":557,"category":"Lyre's Guide to Retia","traits":[]},{"id":"lyre-foxfire","name":"Fogo de Raposa","originalName":"Foxfire","level":2,"school":"Evocação","time":"1 ação","range":"18 metros","comp":"V, S","material":"","duration":"Concentração, até 1 minuto","classes":"Cavaleiro das Pétalas, Clérigo, Paladino, Bruxo, Mago","ritual":false,"concentration":true,"desc":"Uma rajada de chamas psíquicas surge ao redor de três criaturas que você possa ver dentro do alcance. Elas devem realizar um teste de resistência de Destreza, sofrendo 1d8 de dano de fogo e 1d8 de dano psíquico em uma falha, ou metade em um sucesso. Criaturas que falharem continuam queimando e, nos turnos seguintes, você pode usar sua ação para forçar as criaturas ainda em chamas a repetir o teste, seguindo as mesmas regras de dano. Em um sucesso, as chamas se apagam.","higher":"Quando você conjura esta magia usando um espaço de magia de 3º nível ou superior, escolha um dos efeitos a seguir para cada nível do espaço acima do 2º:\n• Você pode escolher um alvo adicional.\n• Os danos de fogo e psíquico aumentam, cada um, em 1d8.","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":557,"category":"Lyre's Guide to Retia","traits":["Grimório do Espreitador"]},{"id":"lyre-free-meadow","name":"Prado Livre","originalName":"Free Meadow","level":3,"school":"Transmutação","time":"1 ação","range":"18 metros","comp":"V, S","material":"","duration":"Concentração, até 10 minutos","classes":"Inscritor, Cavaleiro das Pétalas, Druida","ritual":false,"concentration":true,"desc":"Escolha um ponto dentro do alcance. Toda superfície em um raio de 9 metros fica coberta por grama macia e raízes, exceto superfícies líquidas ou que causariam dano de fogo ou necrótico por contato. Pela duração, a área permanece assim, removendo os efeitos de terreno difícil e permitindo que todas as criaturas escalem superfícies verticais como se tivessem deslocamento de escalada igual ao deslocamento base. Qualquer efeito que modifique as propriedades físicas do terreno dentro da área é suprimido. Se as alterações forem resultado de uma magia, só são suprimidas se tiverem sido criadas por uma magia de nível inferior ao espaço usado para conjurar esta magia. Quando a magia termina, a grama e as raízes desaparecem sem causar dano. Qualquer dano de fogo causado à área ou dentro dela destrói o efeito desta magia naquele espaço.","higher":"Quando você conjura esta magia no 4º nível ou superior, o raio afetado aumenta em 4,5 metros para cada nível do espaço acima do 5º, conforme indicado pela fonte.","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":557,"category":"Lyre's Guide to Retia","traits":["Grimório do Espreitador"]},{"id":"lyre-friend-as-foe","name":"Amigo como Inimigo","originalName":"Friend as Foe","level":3,"school":"Encantamento","time":"1 ação","range":"36 metros","comp":"V, S","material":"","duration":"Concentração, até 1 minuto","classes":"Inscritor, Bardo, Feiticeiro, Bruxo, Mago","ritual":false,"concentration":true,"desc":"Você alcança a mente de uma criatura que possa ver e a força a realizar um teste de resistência de Inteligência. Uma criatura imune a ser amedrontada obtém sucesso automaticamente. Em uma falha, o alvo perde a capacidade de distinguir aliados de inimigos e passa a considerar todas as criaturas que possa ver como inimigas até a magia terminar. Sempre que sofrer dano, pode repetir o teste, encerrando o efeito em um sucesso. Sempre que a criatura afetada escolher outra criatura como alvo, deve determinar aleatoriamente o alvo entre as criaturas que possa ver e que estejam no alcance do ataque, magia ou outra habilidade usada. Se um inimigo provocar um ataque de oportunidade da criatura afetada, ela deve realizá-lo se puder.","higher":"Quando você conjura esta magia usando um espaço de magia de 4º nível ou superior, escolha um dos efeitos a seguir para cada nível do espaço acima do 3º:\n• Você pode escolher um personagem adicional como alvo.\n• Você pode designar uma criatura adicional dentro do alcance; criaturas afetadas não incluem essa criatura na escolha aleatória de alvos se houver outra opção disponível.\n• Quando uma criatura afetada usaria sua reação para realizar um ataque de oportunidade enquanto você puder vê-la, você pode escolher impedir que ela faça isso.","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":557,"category":"Lyre's Guide to Retia","traits":["Épico da Dualidade","Legado 5.19"],"sourceNote":"A fonte identifica esta entrada como uma magia Legacy/revisada da edição 5.19; suas regras foram preservadas como uma versão própria de Lyre."},{"id":"lyre-frigid-banishment","name":"Banimento Gélido","originalName":"Frigid Banishment","level":8,"school":"Abjuração","time":"1 ação","range":"18 metros","comp":"V, S","material":"","duration":"Concentração, até 1 minuto","classes":"Inscritor, Feiticeiro, Bruxo","ritual":false,"concentration":true,"desc":"Escolha até dez criaturas dentro do alcance e tente forçá-las para um semiplano-prisão onde o tempo é lento e os sentidos são embotados. Cada criatura deve realizar um teste de resistência de Carisma. Em uma falha, é banida para um semiplano vazio, exceto por uma tundra fria e infinita, onde uma tempestade permanente a deixa cega. Enquanto estiver ali, sofre 2d8 de dano de frio no início de cada um de seus turnos, mas ainda pode agir normalmente. Criaturas que tentem se teletransportar para fora da prisão devem realizar um teste com o atributo de conjuração contra sua CD de resistência de magia; caso contrário, a tentativa falha. Elas podem escapar conjurando banimento sobre si mesmas, ou escolhendo a si mesmas ou a área ao redor como alvo de dissipar magia — ou outra magia que anule magia — e dissipando com sucesso o efeito. Quando retornam, surgem no espaço desocupado mais próximo de onde desapareceram. Criaturas banidas dessa forma podem repetir o teste de Carisma ao final de cada um de seus turnos, encerrando o efeito em um sucesso. Uma criatura que morrer no semiplano permanece ali até você desejar conjurar seus restos congelados, semelhantes a uma estátua, em um espaço a até 9 metros de você; se você morrer, os restos reaparecem onde ela desapareceu.","higher":"","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":558,"category":"Lyre's Guide to Retia","traits":["Artes Arcanas de Altissima-Cor"]},{"id":"lyre-gaius-avatar","name":"Avatar de Gaius","originalName":"Gaius Avatar","level":4,"school":"Transmutação","time":"1 ação bônus","range":"Pessoal","comp":"V","material":"","duration":"Concentração, até 1 minuto","classes":"Cavaleiro das Pétalas, Patrulheiro","ritual":false,"concentration":true,"desc":"Um espírito da natureza atende ao seu chamado e o transforma em um poderoso guardião. A transformação dura até a magia terminar. Escolha uma das formas a seguir: Besta Primal ou Grande Árvore.\nBesta Primal. Pelagem bestial cobre seu corpo, seus traços ficam ferozes e você recebe: deslocamento de caminhada +3 m; visão no escuro 36 m; vantagem em jogadas de ataque baseadas em Força; ataques com armas corpo a corpo causam 1d6 de dano de energia adicional em um acerto.\nGrande Árvore. Sua pele assume aspecto de casca, folhas brotam do cabelo e você recebe: 10 pontos de vida temporários; vantagem em testes de resistência de Constituição; vantagem em jogadas de ataque baseadas em Destreza e Sabedoria; enquanto estiver no chão, o solo a até 4,5 metros de você é terreno difícil para seus inimigos.","higher":"Quando você conjura esta magia usando um espaço de magia de 5º nível ou superior, escolha um dos efeitos a seguir para cada nível do espaço acima do 4º:\n• Besta Primal: seu deslocamento de caminhada aumenta em mais 1,5 metro.\n• Besta Primal: o dado de dano adicional das armas aumenta a cada escolha, nesta ordem: 1d8, 1d10, 2d6, 2d8 e 2d10.\n• Besta Primal ou Grande Árvore: você realiza todas as jogadas de ataque com vantagem.\n• Grande Árvore: você recebe mais 10 pontos de vida temporários.\n• Grande Árvore: você também tem vantagem em testes de resistência de Força.\n• Grande Árvore: o raio de terreno difícil aumenta em 1,5 metro.\n• (4 níveis de espaço) Você recebe simultaneamente os benefícios de Besta Primal e Grande Árvore.","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":558,"category":"Lyre's Guide to Retia","traits":["Legado 5.19","Tomo da Madeira Sussurrante"],"sourceNote":"A fonte identifica esta entrada como uma magia Legacy/revisada da edição 5.19; suas regras foram preservadas como uma versão própria de Lyre."},{"id":"lyre-gatestep","name":"Passo pelo Portal","originalName":"Gatestep","level":8,"school":"Conjuração","time":"1 ação","range":"Pessoal","comp":"V, S","material":"","duration":"Concentração, até 1 minuto","classes":"Inscritor, Feiticeiro, Bruxo, Mago","ritual":false,"concentration":true,"desc":"Você adquire a capacidade de se distorcer pelo espaço pela duração da magia. Como uma ação bônus, pode abrir um portal e atravessá-lo, teletransportando-se para um espaço desocupado que possa ver a até 36 metros. Você pode aumentar esse alcance em uma quantidade de metros até o seu movimento restante; essa distância adicional é descontada do seu movimento. Quando uma criatura fizer um ataque com arma contra você, você pode usar sua reação para abrir um portal e redirecionar o ataque para outra criatura a até 18 metros, obrigando o atacante a realizar um teste de resistência de Destreza para impedir o redirecionamento. Em uma falha, a outra criatura se torna o novo alvo, usando a mesma jogada de ataque e estatísticas do atacante.","higher":"","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":558,"category":"Lyre's Guide to Retia","traits":["Arcana da Guardiã dos Céus"]},{"id":"lyre-golden-spiral","name":"Espiral Dourada","originalName":"Golden Spiral","level":5,"school":"Evocação","time":"1 ação","range":"18 metros","comp":"V, S","material":"","duration":"Instantânea","classes":"Cavaleiro das Pétalas, Paladino","ritual":false,"concentration":false,"desc":"Escolha uma criatura dentro do alcance. Energia dourada gira ao redor de seu membro ou corpo, formando uma gigantesca broca arcana que você dispara contra o alvo, rasgando a paisagem e inimigos no caminho. O alvo principal e todas as criaturas à sua escolha em uma linha de 4,5 metros de largura entre você e ele devem realizar um teste de resistência de Destreza. Em uma falha, o alvo principal sofre 8d6 de dano de energia, ou metade em um sucesso. Os alvos secundários sofrem metade dessa quantidade em uma falha e nenhum dano em um sucesso. Esta magia causa dano dobrado a constructos e objetos. Se reduzir qualquer alvo a 0 pontos de vida, parte da energia retorna a você e você recebe 1d10 pontos de vida temporários para cada criatura que provoque esse efeito; eles desaparecem ao final do seu próximo turno. Ao conjurar a magia, você pode permanecer onde está ou se teletransportar para um espaço a até 3 metros do alvo principal.","higher":"Se você conjurar esta magia usando um espaço de magia de 6º nível ou superior, o dano de energia aumenta em 2d6 para cada nível do espaço acima do 5º.","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":559,"category":"Lyre's Guide to Retia","traits":["Legado do Ouro"]},{"id":"lyre-grand-aspect-of-flames","name":"Grande Aspecto das Chamas","originalName":"Grand Aspect of Flames","level":7,"school":"Transmutação","time":"1 ação","range":"Pessoal","comp":"V, S, M (uma adaga cerimonial de vidro vulcânico no valor de pelo menos 1.000 po, que a magia consome)","material":"uma adaga cerimonial de vidro vulcânico no valor de pelo menos 1.000 po, que a magia consome","duration":"Concentração, até 1 minuto","classes":"Druida, Feiticeiro, Bruxo, Mago","ritual":false,"concentration":true,"desc":"Você banha o corpo na radiação arcana de Cineris Clade, que assume a forma de chamas furiosas que não o ferem. Pela duração, recebe os benefícios a seguir:\n• Quando sofreria dano de fogo, não sofre dano e, em vez disso, recebe pontos de vida temporários iguais ao dano que teria sofrido. Esse dano não pode se originar de você.\n• Você recebe deslocamento de voo com pairar igual ao seu deslocamento base.\n• Qualquer criatura que o acerte com um ataque com arma a até 3 metros de você sofre 1d12 de dano de fogo.\n• Dano de fogo que você causa ignora resistência e trata imunidade a fogo como resistência, causando metade do dano.\n• Uma vez por rodada, como ação bônus, você provoca uma detonação de chamas em um raio de 3 metros centrado em um ponto que possa ver a até 18 metros. Cada criatura na área deve realizar um teste de resistência de Destreza, sofrendo 4d12 de dano de fogo em uma falha ou metade em um sucesso.\nVocê pode encerrar esta magia como uma ação bônus.","higher":"","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":559,"category":"Lyre's Guide to Retia","traits":["Sangue de Cineris","Eidomancia"],"sourceNote":"Regra de grupo — Eidomancia: todo dano causado por uma magia de eidomancia é considerado dano eidólico. Após conjurar a magia, realize um teste de resistência de Constituição de CD 10 + o nível em que a magia foi conjurada + o número de turnos após o primeiro em que ela permaneceu ativa sob concentração. Se não exigir concentração, o teste é feito imediatamente após a conjuração. Em uma falha, você sofre níveis de exaustão iguais à metade do nível da magia, arredondado para baixo (mínimo 1), e não pode conjurá-la novamente por sete dias. Se a falha elevaria a exaustão a 6, ela fica em 5 e você é imediatamente reduzido a 0 pontos de vida. Se falhar em um teste de concentração para manter uma magia de eidomancia, você pode usar sua reação para rolar um d20 e usar esse resultado no lugar do d20 do teste de concentração."},{"id":"lyre-gravity-bind","name":"Vínculo Gravitacional","originalName":"Gravity Bind","level":2,"school":"Transmutação","time":"1 ação","range":"90 metros","comp":"V","material":"","duration":"Concentração, até 1 minuto","classes":"Inscritor, Cavaleiro das Pétalas, Druida, Feiticeiro, Bruxo, Mago","ritual":false,"concentration":true,"desc":"Escolha uma criatura que possa ver dentro do alcance. Faixas amarelas de energia mágica se enrolam ao redor dela. Escolha um dos efeitos a seguir para o alvo:\nDespencar. As distâncias de salto em altura e em distância do alvo são reduzidas pela metade, arredondadas para baixo, e qualquer dano de queda que ele sofra é dobrado.\nAncorar. Se o alvo estiver em um ambiente de gravidade zero, ele é atraído até a superfície mais próxima sobre a qual possa ficar de pé e pode caminhar nela facilmente como se fosse o chão sob gravidade normal. Uma criatura afetada pode ativar e desativar este efeito à vontade durante seu movimento.\nPrender Asas. O alvo deve ser bem-sucedido em um teste de resistência de Força ou seus deslocamentos de voo e aceleração em gravidade zero, se houver, são reduzidos a 0 pela duração. Uma criatura no ar afetada desce com segurança 18 metros por rodada até tocar o chão ou a magia terminar; se também estiver sob Despencar, ela cai na velocidade normal em vez disso.","higher":"Quando você conjura esta magia usando um espaço de magia de 3º nível ou superior, escolha um dos efeitos a seguir para cada nível do espaço acima do 2º:\n• Você pode aplicar dois dos efeitos da magia aos alvos.\n• Você pode escolher uma criatura adicional. O efeito escolhido pode ser diferente para cada alvo.\n• A duração aumenta para 10 minutos (1 nível de espaço), 1 hora (2 níveis), 24 horas (3 níveis) ou até ser dissipada (4 níveis). Se durar 24 horas ou mais, a magia não exige concentração.","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":559,"category":"Lyre's Guide to Retia","traits":["Legado 5.19"],"sourceNote":"A fonte identifica esta entrada como uma magia Legacy/revisada da edição 5.19; suas regras foram preservadas como uma versão própria de Lyre."},{"id":"lyre-greatwyrms-stride","name":"Passo do Grande Dragão","originalName":"Greatwyrm’s Stride","level":3,"school":"Transmutação","time":"1 ação bônus","range":"Pessoal","comp":"V, S","material":"","duration":"Concentração, até 1 minuto","classes":"Inscritor, Patrulheiro, Feiticeiro, Mago","ritual":false,"concentration":true,"desc":"Chamas ondulantes de um dragão irrompem de seus pés, concedendo velocidade explosiva. Pela duração, seu deslocamento aumenta em 6 metros e seu movimento não provoca ataques de oportunidade. Quando você se move a até 1,5 metro de uma criatura ou objeto que não esteja sendo vestido nem carregado, ele sofre 1d6 de dano de fogo da trilha de calor. Uma criatura ou objeto só pode sofrer esse dano uma vez por turno.","higher":"Quando você conjura esta magia usando um espaço de magia de 4º nível ou superior, seu deslocamento aumenta em mais 1,5 metro para cada nível do espaço acima do 3º. O dano de fogo também aumenta em 1d6 para cada nível do espaço acima do 3º.","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":559,"category":"Lyre's Guide to Retia","traits":["Legado 5.19"],"sourceNote":"A fonte identifica esta entrada como uma magia Legacy/revisada da edição 5.19; suas regras foram preservadas como uma versão própria de Lyre."},{"id":"lyre-hathoyuras-feather-dance","name":"Dança das Penas de Hathoyura","originalName":"Hathoyura’s Feather Dance","level":7,"school":"Transmutação","time":"1 ação bônus","range":"Toque","comp":"V, S, M (um crânio de corvo com olhos de rubi no valor de pelo menos 200 po, que a magia consome)","material":"um crânio de corvo com olhos de rubi no valor de pelo menos 200 po, que a magia consome","duration":"Concentração, até 1 minuto","classes":"Lista especial / não especificada","ritual":false,"concentration":true,"desc":"A criatura que você toca recebe um manto de penas negras afiadas como lâminas. Pela duração, ela recebe os benefícios a seguir:\n• Deslocamento de voo de 18 metros.\n• Não pode ser enfeitiçada nem amedrontada.\n• Recebe um bônus na CA e nos testes de resistência de Destreza igual à metade do seu bônus de proficiência, arredondado para baixo.\n• Como ação bônus, pode se teletransportar até 18 metros para um espaço desocupado que possa ver e imediatamente realizar um ataque com arma corpo a corpo contra um alvo ao alcance. Se você for o alvo da magia, pode fazer isso como parte da mesma ação usada para conjurá-la.\nEnquanto estiver sob este efeito, o alvo pode usar uma reação especial quando for alvo de um ataque com arma para se teletransportar até 4,5 metros para um espaço desocupado que possa ver. Se fizer isso, o ataque contra ele — resolvido antes do teletransporte — é feito com desvantagem e causa metade do dano se acertar. Essa reação pode ser usada normalmente, mas também pode ser usada sem gastar a reação da criatura um número de vezes igual à metade do seu bônus de proficiência, arredondado para baixo, por conjuração desta magia.","higher":"","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":560,"category":"Lyre's Guide to Retia","traits":["Daemoturgia"]},{"id":"lyre-hand-of-the-blackwind","name":"Mão do Vento Negro","originalName":"Hand of the Blackwind","level":3,"school":"Encantamento","time":"1 ação bônus","range":"Pessoal","comp":"S","material":"","duration":"Concentração, até 1 minuto","classes":"Inscritor, Cavaleiro das Pétalas, Druida, Feiticeiro, Bruxo","ritual":false,"concentration":true,"desc":"Suas mãos se incendeiam com energia sombria, permitindo que atinjam a mente do alvo além do corpo. Pela duração, seus ataques desarmados causam 2d8 de dano psíquico adicional ao dano normal e você pode usar seu modificador do atributo de conjuração nas jogadas de ataque e dano dos ataques desarmados. Além disso, quando realizar um ataque desarmado usando a ação Atacar, você pode realizar dois ataques em vez de um, desde que ambos sejam desarmados. Quando o dano de seus ataques desarmados obrigar uma criatura a realizar um teste de concentração, a CD desse teste nunca é inferior à sua CD de resistência de magia.","higher":"Quando você conjura esta magia usando um espaço de magia de 4º nível ou superior, o dano psíquico aumenta em 1d8 para cada dois níveis do espaço acima do 3º. Se conjurada usando um espaço de 7º nível ou superior, quando você usar a ação Atacar e fizer apenas ataques desarmados, pode atacar três vezes em vez de uma.","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":560,"category":"Lyre's Guide to Retia","traits":["Daemoturgia"]},{"id":"lyre-hastened-quiver","name":"Aljava Acelerada","originalName":"Hastened Quiver","level":5,"school":"Transmutação","time":"1 ação bônus","range":"Toque","comp":"V, S, M (uma aljava, cinto ou recipiente contendo pelo menos uma unidade de munição)","material":"uma aljava, cinto ou recipiente contendo pelo menos uma unidade de munição","duration":"Concentração, até 1 minuto","classes":"Alma Favorecida, Cavaleiro das Pétalas","ritual":false,"concentration":true,"desc":"Você transmuta sua aljava, cinturão ou recipiente de munição para produzir uma reserva infinita de munição não mágica, que parece saltar para sua mão quando você a procura. Em cada um de seus turnos até a magia terminar, você pode usar uma ação bônus para realizar dois ataques com uma arma que use munição do mesmo tipo e da mesma fonte. Sempre que fizer um desses ataques à distância, o recipiente substitui magicamente a munição usada por uma peça semelhante não mágica. Toda munição criada por esta magia se desintegra quando a magia termina. Se o recipiente deixar sua posse, a magia termina. Esta magia também pode ser conjurada sobre uma arma de fogo com capacidade de pelo menos quatro munições; nesse caso, ela não precisa ser recarregada pela duração, pois novas balas surgem magicamente sempre que a arma fica vazia.","higher":"","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":560,"category":"Lyre's Guide to Retia","traits":[]},{"id":"lyre-hideous-laughter","name":"Risada Horrível","originalName":"Hideous Laughter","level":1,"school":"Encantamento","time":"1 ação","range":"9 metros","comp":"V, S, M (pequenas tortas e uma pena agitada no ar)","material":"pequenas tortas e uma pena agitada no ar","duration":"Concentração, até 1 minuto","classes":"Bardo, Mago","ritual":false,"concentration":true,"desc":"Uma criatura à sua escolha que possa ver dentro do alcance passa a perceber tudo como absurdamente engraçado e é tomada por acessos de riso. O alvo deve ser bem-sucedido em um teste de resistência de Sabedoria ou fica caído, incapacitado e incapaz de se levantar pela duração. Uma criatura com Inteligência 4 ou menor não é afetada. Ao final de cada um de seus turnos e sempre que sofrer dano, o alvo pode repetir o teste de Sabedoria. Ele tem vantagem no teste quando este for provocado por dano. Em um sucesso, a magia termina.","higher":"","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":560,"category":"Lyre's Guide to Retia","traits":[]},{"id":"lyre-hold-attacker","name":"Conter Atacante","originalName":"Hold Attacker","level":3,"school":"Encantamento","time":"1 reação, realizada quando uma criatura humanoide que não seja morta-viva, dentro do alcance da magia, erra um ataque contra você","range":"9 metros","comp":"V, S, M (um pequeno pedaço reto de ferro)","material":"um pequeno pedaço reto de ferro","duration":"Concentração, até 1 minuto","classes":"Inscritor, Cavaleiro das Pétalas, Bardo, Bruxo","ritual":false,"concentration":true,"desc":"A criatura que desencadeou esta reação deve ser bem-sucedida em um teste de resistência de Sabedoria ou fica paralisada pela duração. Ao final de cada um de seus turnos, o alvo pode repetir o teste de resistência de Sabedoria, encerrando os efeitos da magia em um sucesso.","higher":"Quando você conjura esta magia usando um espaço de magia de 6º nível ou superior, pode usá-la contra qualquer atacante, independentemente do tipo de criatura. Se conjurada no 8º nível ou superior, o alvo fica paralisado até o final do próprio turno independentemente do resultado do teste de resistência.","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":561,"category":"Lyre's Guide to Retia","traits":["Grimório do Espreitador"]},{"id":"lyre-hungering-vortex","name":"Vórtice Faminto","originalName":"Hungering Vortex","level":2,"school":"Evocação","time":"1 ação","range":"36 metros","comp":"V, S, M (uma luva embebida em sangue de corruptor)","material":"uma luva embebida em sangue de corruptor","duration":"Concentração, até 1 minuto","classes":"Cavaleiro das Pétalas, Feiticeiro, Bruxo, Mago","ritual":false,"concentration":true,"desc":"Um ponto de névoa púrpura surge em um local dentro do alcance e então se expande, formando uma esfera contorcida de 3 metros de raio cheia de ecos fantasmagóricos de yokais menores do Reino das Sombras. Todas as criaturas na esfera devem realizar um teste de resistência de Carisma, sofrendo 2d10 de dano psíquico em uma falha ou metade em um sucesso. A esfera é terreno difícil, e todos os testes de resistência de Força e Destreza feitos por criaturas dentro dela sofrem uma penalidade igual à metade do seu bônus de proficiência, arredondado para baixo. Quando uma criatura entra na área pela primeira vez em um turno ou começa o turno ali, deve realizar novamente o teste contra o mesmo dano. Em cada um de seus turnos após conjurar a magia, você pode usar uma ação bônus para mover a esfera para outro ponto a até 9 metros de sua posição atual. Quando a magia termina, a área dentro da esfera continua revolvida por ecos de yokai e permanece terreno difícil até o início do seu próximo turno.","higher":"Se você conjurar esta magia usando um espaço de magia de 3º nível ou superior, o dano aumenta em 1d10 para cada nível do espaço acima do 2º, e o raio da esfera aumenta em 1,5 metro para cada dois níveis de espaço acima do 1º.","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":561,"category":"Lyre's Guide to Retia","traits":["Daemoturgia"]},{"id":"lyre-hydro-cage","name":"Jaula Aquática","originalName":"Hydro Cage","level":4,"school":"Conjuração","time":"1 ação","range":"27 metros","comp":"V, S, M (uma pequena gota de água)","material":"uma pequena gota de água","duration":"Concentração, até 1 minuto","classes":"Inscritor, Cavaleiro das Pétalas, Druida, Feiticeiro, Mago","ritual":false,"concentration":true,"desc":"Você conjura uma esfera de água de 1,5 metro de raio em um ponto que possa ver dentro do alcance. Ela pode pairar, mas não mais que 3 metros acima do chão, e permanece pela duração. Qualquer criatura no espaço da esfera deve realizar um teste de resistência de Força. Em um sucesso, é ejetada para o espaço desocupado mais próximo à sua escolha fora da esfera. Criaturas maiores que a esfera obtêm sucesso automaticamente, e criaturas menores podem escolher falhar. Em uma falha, a criatura fica impedida pela esfera e submersa na água. Ao final de cada um de seus turnos, um alvo impedido pode repetir o teste, encerrando o efeito em um sucesso. A esfera pode conter até quatro criaturas Médias ou menores, ou uma criatura Grande. Se uma criatura adicional exceder essa capacidade, uma criatura aleatória já impedida cai para fora e fica caída em um espaço a até 1,5 metro.\nCom uma ação, você pode mover a esfera até 9 metros em linha reta. Se ela passar sobre um fosso, penhasco ou outra queda, desce com segurança até pairar 3 metros acima do chão. Criaturas impedidas se movem com ela. Você pode colidir a esfera contra criaturas, obrigando-as a realizar o teste. Quando a magia termina, a esfera cai ao chão e apaga todas as chamas normais a até 9 metros. Qualquer criatura impedida fica caída no espaço onde a esfera caiu, e a água então desaparece.","higher":"Quando você conjura esta magia usando um espaço de magia de 5º nível ou superior, escolha um dos efeitos a seguir para cada nível do espaço acima do 4º:\n• O raio da esfera aumenta em 3 metros.\n• Você pode criar esferas adicionais, dividindo entre elas o raio total que uma única esfera teria. Cada esfera deve ter raio múltiplo de 1,5 metro. Quando usar uma ação para mover uma esfera, pode mover qualquer quantidade delas; se várias estiverem em espaços adjacentes, você pode combiná-las durante o movimento.","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":561,"category":"Lyre's Guide to Retia","traits":["Legado 5.19"],"sourceNote":"A fonte identifica esta entrada como uma magia Legacy/revisada da edição 5.19; suas regras foram preservadas como uma versão própria de Lyre."},{"id":"lyre-hydro-wall","name":"Muralha Aquática","originalName":"Hydro Wall","level":3,"school":"Evocação","time":"1 ação","range":"18 metros","comp":"V, S, M (uma gota de água)","material":"uma gota de água","duration":"Concentração, até 10 minutos","classes":"Inscritor, Cavaleiro das Pétalas, Druida, Feiticeiro, Mago","ritual":false,"concentration":true,"desc":"Você cria uma muralha de água no chão em um ponto que possa ver dentro do alcance. Ela pode ter até 9 metros de comprimento, 3 metros de altura e 30 centímetros de espessura, ou formar um anel de até 6 metros de diâmetro, 6 metros de altura e 30 centímetros de espessura. A muralha desaparece quando a magia termina. O espaço dela é terreno difícil. Qualquer ataque com arma à distância que entre na muralha tem desvantagem, e dano de fogo é reduzido à metade se o efeito de fogo atravessar a água para alcançar o alvo. Magias que causam dano de frio e atravessam a muralha congelam a parte pela qual passam, no mínimo uma seção de 1,5 metro. Cada seção congelada de 1,5 metro tem CA 5 e 15 pontos de vida. Reduzi-la a 0 pontos de vida a destrói, e a água da muralha não preenche o espaço destruído.\nSe uma criatura Grande ou menor ocupar o mesmo espaço da muralha, você pode usar uma ação bônus para movê-la até 18 metros até outro ponto da muralha, arrastando-a pela corrente. Se ela não for voluntária, deve ser bem-sucedida em um teste de resistência de Força. Em uma falha, também fica impedida pela água até o início do seu próximo turno.","higher":"Quando você conjura esta magia usando um espaço de magia de 4º nível ou superior, para cada nível do espaço acima do 3º o comprimento da muralha aumenta em 3 metros, o diâmetro do anel em 1,5 metro e a altura em 1,5 metro.","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":561,"category":"Lyre's Guide to Retia","traits":[]},{"id":"lyre-igniting-smite","name":"Destruição Incendiária","originalName":"Igniting Smite","level":1,"school":"Evocação","time":"1 ação bônus","range":"Pessoal","comp":"V","material":"","duration":"Concentração, até 1 minuto","classes":"Alma Favorecida, Patrulheiro, Paladino","ritual":false,"concentration":true,"desc":"Na próxima vez que você acertar uma criatura com um ataque com arma corpo a corpo durante a duração, sua arma brilha com intensidade incandescente. O ataque causa 1d6 de dano de fogo adicional e faz o alvo ficar Incendiado. O alvo sofre 1d6 de dano de fogo a cada turno enquanto estiver Incendiado dessa forma. No início de cada um de seus turnos até a magia terminar, ele deve realizar um teste de resistência de Constituição para apagar as chamas, sofrendo 1d6 de dano de fogo em uma falha ou encerrando o efeito em um sucesso.","higher":"Quando você conjura esta magia no 2º nível ou superior, escolha um dos efeitos a seguir para cada nível do espaço acima do 1º:\n• O dano inicial e o dano causado pela condição Incendiado aumentam em 1d6.\n• O efeito persiste por um ataque adicional depois do momento em que normalmente terminaria.","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":562,"category":"Lyre's Guide to Retia","traits":[]},{"id":"lyre-incantation","name":"Encantação","originalName":"Incantation","level":0,"school":"Evocação","time":"1 ação bônus","range":"Pessoal","comp":"V","material":"","duration":"1 rodada","classes":"Inscritor, Bruxo, Mago","ritual":false,"concentration":false,"desc":"Esta magia é ignorada por todas as regras que limitam quantas magias você pode conjurar em um único turno, desde que possua ações suficientes para fazê-lo. Na próxima vez que você conjurar uma magia antes do início do seu próximo turno, pode optar por gastar um espaço de magia adicional. Se fizer isso, o nível do espaço usado para conjurar a outra magia é tratado como superior: ele aumenta em metade do nível do espaço adicional gasto, arredondado para baixo, sem poder ultrapassar o 9º nível. Se você não tiver espaços suficientes para conjurar uma magia em seu nível base, mas tiver conjurado esta magia, ainda pode conjurá-la desde que use este efeito para produzir um nível de espaço igual ou superior ao nível da magia-alvo. Você não realiza um teste de queimadura eidomântica para esta magia. Em vez disso, realiza um para a magia afetada, tratando-a como uma magia de eidomancia conjurada no nível de espaço elevado resultante.","higher":"","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":562,"category":"Lyre's Guide to Retia","traits":["Eidomancia"],"sourceNote":"Regra de grupo — Eidomancia: todo dano causado por uma magia de eidomancia é considerado dano eidólico. Após conjurar a magia, realize um teste de resistência de Constituição de CD 10 + o nível em que a magia foi conjurada + o número de turnos após o primeiro em que ela permaneceu ativa sob concentração. Se não exigir concentração, o teste é feito imediatamente após a conjuração. Em uma falha, você sofre níveis de exaustão iguais à metade do nível da magia, arredondado para baixo (mínimo 1), e não pode conjurá-la novamente por sete dias. Se a falha elevaria a exaustão a 6, ela fica em 5 e você é imediatamente reduzido a 0 pontos de vida. Se falhar em um teste de concentração para manter uma magia de eidomancia, você pode usar sua reação para rolar um d20 e usar esse resultado no lugar do d20 do teste de concentração."},{"id":"lyre-ilsrabaes-veil","name":"Véu de Ilsrabae","originalName":"Ilsrabae’s Veil","level":1,"school":"Abjuração","time":"1 ação","range":"Pessoal","comp":"V, S, M (um punhado de água)","material":"um punhado de água","duration":"1 hora","classes":"Bruxo","ritual":false,"concentration":false,"desc":"Uma força mágica protetora o envolve, manifestando-se como um véu de frio congelante que protege você e seus equipamentos. Você recebe 5 pontos de vida temporários pela duração e, até a magia terminar, possui resistência a dano de frio. Se uma criatura o acertar com um ataque corpo a corpo enquanto você tiver esses pontos de vida temporários, ela sofre 5 de dano de frio.","higher":"Quando você conjura esta magia usando um espaço de magia de 2º nível ou superior, tanto os pontos de vida temporários quanto o dano de frio aumentam em 5 para cada nível do espaço acima do 1º.","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":562,"category":"Lyre's Guide to Retia","traits":["Legado 5.19"],"sourceNote":"A fonte identifica esta entrada como uma magia Legacy/revisada da edição 5.19; suas regras foram preservadas como uma versão própria de Lyre."},{"id":"lyre-incineration-tower","name":"Torre de Incineração","originalName":"Incineration Tower","level":8,"school":"Evocação","time":"1 ação","range":"45 metros","comp":"V, S, M (uma esfera de obsidiana no valor de pelo menos 100 po, que a magia consome)","material":"uma esfera de obsidiana no valor de pelo menos 100 po, que a magia consome","duration":"Instantânea","classes":"Feiticeiro, Bruxo","ritual":false,"concentration":false,"desc":"Você transforma o componente da magia em um ponto de luz branca incandescente que voa até um local que possa ver dentro do alcance. O ponto irrompe em um pilar de fogo com raio entre 3 e 9 metros e altura três vezes maior que o raio escolhido. Todas as criaturas na área devem realizar um teste de resistência de Destreza, sofrendo 12d8 de dano de fogo em uma falha ou metade em um sucesso. Criaturas reduzidas a 0 pontos de vida por esta magia morrem instantaneamente e seus restos são reduzidos a cinzas, exceto itens mágicos. Além disso, qualquer criatura a até duas vezes o raio do pilar, incluindo os alvos iniciais, deve ser bem-sucedida em um teste de resistência de Constituição ou fica cega. Criaturas cegas dessa forma podem repetir o teste ao final de cada um de seus turnos, encerrando o efeito em um sucesso.","higher":"","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":562,"category":"Lyre's Guide to Retia","traits":["Sangue de Cineris"]},{"id":"lyre-inflict-terror","name":"Infligir Terror","originalName":"Inflict Terror","level":1,"school":"Encantamento","time":"1 ação","range":"18 metros","comp":"V","material":"","duration":"Instantânea","classes":"Bardo","ritual":false,"concentration":false,"desc":"Você sussurra uma frase ameaçadora e dissonante que apenas uma criatura à sua escolha dentro do alcance pode ouvir, enchendo-a de pavor. O alvo deve realizar um teste de resistência de Sabedoria. Em uma falha, sofre 3d6 de dano psíquico e deve usar imediatamente sua reação, se disponível, para se mover o máximo possível para longe de você, sem entrar em locais obviamente perigosos, como fogo ou um fosso. Em um sucesso, sofre metade do dano e não precisa se afastar. Uma criatura surda obtém sucesso automaticamente no teste.","higher":"Quando você conjura esta magia no 2º nível ou superior, escolha um dos efeitos a seguir para cada nível do espaço acima do 1º:\n• A magia causa 1d6 de dano adicional.\n• (2 níveis de espaço) Você pode escolher um alvo adicional dentro do alcance.\n• (2 níveis de espaço) Se um alvo falhar no teste, fica amedrontado por você até o final do seu próximo turno. Enquanto estiver amedrontado, deve usar sua ação para Disparar e se afastar o máximo possível. Se não puder se afastar mais ou se a única opção for se aproximar de você, usa Esquivar em vez disso.","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":563,"category":"Lyre's Guide to Retia","traits":["Legado 5.19"],"sourceNote":"A fonte identifica esta entrada como uma magia Legacy/revisada da edição 5.19; suas regras foram preservadas como uma versão própria de Lyre."},{"id":"lyre-infused-weapon","name":"Arma Infundida","originalName":"Infused Weapon","level":1,"school":"Transmutação","time":"1 ação","range":"Toque","comp":"V, S","material":"","duration":"Concentração, até 1 hora","classes":"Alma Favorecida, Inscritor, Cavaleiro das Pétalas, Patrulheiro, Druida, Paladino","ritual":false,"concentration":true,"desc":"Uma arma que você toca fica envolta em energia elemental. Escolha ácido, frio, fogo, elétrico ou trovejante. Pela duração, a arma recebe bônus de aprimoramento +1, somado às jogadas de ataque e dano, e causa 1d4 de dano adicional do tipo escolhido quando acerta.","higher":"Quando você conjura esta magia no 2º nível ou superior, escolha um dos efeitos a seguir para cada nível do espaço acima do 1º:\n• O dano adicional aumenta em 1d4.\n• O bônus de aprimoramento passa a +2 (2 níveis de espaço), +3 (4 níveis) ou +4 (6 níveis).\n• (2 níveis de espaço) Você não precisa se concentrar nos efeitos desta magia durante a duração.","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":563,"category":"Lyre's Guide to Retia","traits":["Legado 5.19"],"sourceNote":"A fonte identifica esta entrada como uma magia Legacy/revisada da edição 5.19; suas regras foram preservadas como uma versão própria de Lyre."},{"id":"lyre-inuyaris-bestial-stride","name":"Passo Bestial de Inuyari","originalName":"Inuyari’s Bestial Stride","level":6,"school":"Transmutação","time":"1 ação","range":"Toque","comp":"V, S, M (uma estatueta de cabeça de lobo no valor de pelo menos 200 po, que a magia consome)","material":"uma estatueta de cabeça de lobo no valor de pelo menos 200 po, que a magia consome","duration":"Concentração, até 1 minuto","classes":"Feiticeiro, Bruxo","ritual":false,"concentration":true,"desc":"Uma criatura que você toca é infundida com as qualidades bestiais de um senhor yokai dos lobos. Pela duração, recebe os benefícios a seguir:\n• Vantagem em testes de Sabedoria (Percepção) e Sabedoria (Sobrevivência).\n• Pode rastrear criaturas pelo cheiro e recebe percepção às cegas até 18 metros.\n• Seu deslocamento base aumenta para 18 metros, a menos que já seja maior, e também pode ser usado como deslocamento de escalada.\n• Resistência a dano psíquico e necrótico.\n• Pode conjurar uma lança de presa de lobo e atacar com ela em seu turno. A arma é uma lança mágica com a qual possui proficiência, tem as propriedades acuidade e arremesso (24/72 m) e causa 3d8 + seu modificador do atributo de conjuração de dano perfurante em um acerto. Ela pode aparecer e desaparecer nas mãos do alvo conforme necessário a cada ataque.\n• Pode usar uma ação bônus para realizar um ataque com a lança de presa de lobo ou usar Disparar ou Desengajar.\n• Quando falhar em um teste de resistência, pode rolar um d20 e usar esse resultado no lugar do anterior. Se obtiver sucesso dessa forma, não sofre dano do efeito mesmo que normalmente sofresse metade. Pode fazer isso um número de vezes igual à metade do seu bônus de proficiência, arredondado para baixo.\n• Durante esse período, ombros e pele ficam cobertos por fina pelagem negra fumegante, os dentes ficam afiados e a linguagem corporal se torna mais animalesca.","higher":"Se conjurada em nível superior, a lança de presa de lobo causa 1d8 de dano adicional quando usada com um espaço de 8º nível; se conjurada no 9º nível, a lança pode ser arremessada até 150 metros sem desvantagem por alcance longo.","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":563,"category":"Lyre's Guide to Retia","traits":["Daemoturgia"]},{"id":"lyre-investiture-of-lightning","name":"Investidura de Relâmpagos","originalName":"Investiture of Lightning","level":7,"school":"Transmutação","time":"1 ação","range":"Pessoal","comp":"V, S","material":"","duration":"Concentração, até 1 minuto","classes":"Inscritor, Feiticeiro, Bruxo","ritual":false,"concentration":true,"desc":"Até a magia terminar, relâmpagos envolvem você e aceleram seus sentidos e movimentos, concedendo os benefícios a seguir:\n• Seu deslocamento dobra.\n• Você fica imune a dano elétrico.\n• Quando uma criatura o acerta com um ataque com arma corpo a corpo a até 1,5 metro, ela sofre 1d10 de dano elétrico.\nComo ação bônus em seu turno, você pode invocar um bastão de relâmpago para atingir uma criatura a até 3 metros com um ataque corpo a corpo com magia. Em um acerto, o alvo sofre 6d10 de dano elétrico e deve realizar um teste de resistência de Constituição. Em uma falha, fica Lento até o início do seu próximo turno.","higher":"Se você conjurar esta magia usando um espaço de 9º nível, pode fazer dois ataques com o bastão de relâmpago em vez de um. Se ambos acertarem, o alvo deve realizar um teste de resistência de Constituição; em uma falha, fica atordoado até o início do próximo turno dele.","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":563,"category":"Lyre's Guide to Retia","traits":["Arcana da Guardiã dos Céus"]},{"id":"lyre-irresistible-dance","name":"Dança Irresistível","originalName":"Irresistible Dance","level":6,"school":"Encantamento","time":"1 ação","range":"9 metros","comp":"V","material":"","duration":"Concentração, até 1 minuto","classes":"Bardo, Mago","ritual":false,"concentration":true,"desc":"Escolha uma criatura que possa ver dentro do alcance. O alvo começa uma dança cômica no lugar — arrastando os pés, sapateando e saltitando — pela duração. Criaturas imunes a ser enfeitiçadas são imunes a esta magia. Uma criatura dançando deve usar todo o movimento para dançar sem sair de seu espaço e tem desvantagem em testes de resistência de Destreza e jogadas de ataque. Enquanto estiver afetada, outras criaturas têm vantagem nas jogadas de ataque contra ela. Com uma ação, a criatura pode realizar um teste de resistência de Sabedoria para recuperar o controle. Em um sucesso, a magia termina.","higher":"","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":564,"category":"Lyre's Guide to Retia","traits":["Legado 5.19"],"sourceNote":"A fonte identifica esta entrada como uma magia Legacy/revisada da edição 5.19; suas regras foram preservadas como uma versão própria de Lyre."},{"id":"lyre-jackals-luck","name":"Sorte do Chacal","originalName":"Jackal’s Luck","level":1,"school":"Adivinhação","time":"1 ação","range":"18 metros","comp":"V, S, M (um peridoto no valor de 50 po ou mais, que a magia consome)","material":"um peridoto no valor de 50 po ou mais, que a magia consome","duration":"10 minutos","classes":"Bardo, Druida, Paladino","ritual":false,"concentration":false,"desc":"Você concede um momento de sorte a uma criatura voluntária que possa ver dentro do alcance. Quando essa criatura fizer uma jogada de ataque, teste de atributo ou teste de resistência, pode gastar esta bênção para rolar um d20 adicional e escolher qual resultado será usado. Como alternativa, quando for alvo de um ataque, pode gastar a bênção para rolar um d20 adicional e escolher usar seu próprio resultado ou o resultado do d20 do atacante para determinar o ataque. Depois de usada, a magia termina.","higher":"Quando você conjura esta magia usando um espaço de magia de 3º nível ou superior, o alvo recebe um uso adicional desta bênção antes de a magia terminar para cada dois níveis do espaço acima do 1º.","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":564,"category":"Lyre's Guide to Retia","traits":["Grimório do Espreitador"]},{"id":"lyre-joyful-toxin","name":"Toxina Jubilosa","originalName":"Joyful Toxin","level":3,"school":"Transmutação","time":"1 ação","range":"Pessoal","comp":"V, S, M (uma dose de veneno no valor de pelo menos 100 po)","material":"uma dose de veneno no valor de pelo menos 100 po","duration":"1 minuto","classes":"Cavaleiro das Pétalas, Druida","ritual":false,"concentration":false,"desc":"Pela duração, você fica imune a dano de veneno e não pode ficar envenenado. Quando sofreria dano de veneno, em vez disso recupera pontos de vida iguais à metade do dano que teria sofrido, arredondado para baixo.","higher":"","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":564,"category":"Lyre's Guide to Retia","traits":[]},{"id":"lyre-karmatic-resilience","name":"Resiliência Cármica","originalName":"Karmatic Resilience","level":2,"school":"Abjuração","time":"1 reação, realizada quando você falha em um teste de resistência","range":"Pessoal","comp":"V","material":"","duration":"1 minuto","classes":"Cavaleiro das Pétalas, Patrulheiro, Feiticeiro, Mago","ritual":false,"concentration":false,"desc":"Quando você falha em um teste de resistência e conjura esta magia, pode repetir o teste com vantagem, mesmo que tivesse desvantagem antes, e deve usar o novo resultado. Se isso fizer você obter sucesso, todos os testes de resistência posteriores feitos com o mesmo atributo são realizados com desvantagem pela duração da magia. O efeito termina se você fizer um desses testes em que todos os resultados de d20 rolados teriam falhado individualmente. Por exemplo, em um teste de Destreza CD 15 com bônus +3, resultados 11 e 9 encerrariam o efeito; resultados 14 e 9 não o encerrariam.","higher":"","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":564,"category":"Lyre's Guide to Retia","traits":["Daemoturgia"]},{"id":"lyre-kellias-deceptive-mark","name":"Marca Enganosa de Kellia","originalName":"Kellia’s Deceptive Mark","level":3,"school":"Ilusão","time":"1 ação bônus","range":"9 metros","comp":"V, S","material":"","duration":"Concentração, até 1 minuto","classes":"Inscritor, Druida, Bruxo","ritual":false,"concentration":true,"desc":"Escolha um alvo dentro do alcance. Ele deve realizar um teste de resistência de Sabedoria ou fica marcado por esta magia. Pela duração, uma faixa invisível aparece sobre os olhos do alvo; apenas criaturas capazes de ver objetos invisíveis percebem a faixa, como um pedaço de tecido enrolado ao redor da cabeça. Criaturas marcadas por esta magia não conseguem ver você e o tratam como se estivesse invisível.","higher":"Quando você conjura esta magia usando um espaço de magia de 4º nível ou superior, pode escolher uma criatura adicional dentro do alcance para cada nível do espaço acima do 3º.","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":564,"category":"Lyre's Guide to Retia","traits":["Grimório do Espreitador"]},{"id":"lyre-laborious-flight","name":"Voo Laborioso","originalName":"Laborious Flight","level":2,"school":"Transmutação","time":"1 ação","range":"9 metros","comp":"V, S","material":"","duration":"10 minutos","classes":"Alma Favorecida, Patrulheiro, Feiticeiro, Bruxo, Mago","ritual":false,"concentration":false,"desc":"Até três criaturas à sua escolha dentro do alcance recebem asas arcanas etéreas que brotam de suas costas e lhes permitem voar pela duração, embora sejam difíceis de usar. Elas recebem deslocamento de voo laborioso de 6 metros. Além disso, se uma criatura afetada já possuir deslocamento de voo laborioso, esse deslocamento se torna deslocamento de voo normal pela duração, sem receber os metros adicionais fornecidos por esta magia.","higher":"Quando você conjura esta magia no 3º nível ou superior, escolha um dos efeitos a seguir para cada nível do espaço acima do 2º:\n• O deslocamento de voo laborioso concedido aumenta em 3 metros.\n• Você pode escolher uma criatura adicional dentro do alcance.\n• A duração da magia dobra.","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":564,"category":"Lyre's Guide to Retia","traits":[]},{"id":"lyre-lands-fury","name":"Fúria da Terra","originalName":"Land’s Fury","level":5,"school":"Evocação","time":"1 ação","range":"36 metros","comp":"V, S","material":"","duration":"Concentração, até 1 minuto","classes":"Cavaleiro das Pétalas, Patrulheiro, Druida","ritual":false,"concentration":true,"desc":"Você chama os espíritos da natureza e os incita contra seus inimigos. Escolha um ponto que possa ver dentro do alcance. Árvores, rochas e gramíneas em um cubo de 18 metros centrado nesse ponto ficam animadas até a magia terminar.\nGramíneas e Vegetação Rasteira. Qualquer chão do cubo coberto por grama ou vegetação é terreno difícil para seus inimigos.\nÁrvores. No início de cada um de seus turnos, cada inimigo a até 3 metros de qualquer árvore no cubo deve ser bem-sucedido em um teste de resistência de Destreza ou sofre 4d6 de dano cortante dos galhos chicoteantes.\nRaízes e Vinhas. Ao final de cada um de seus turnos, uma criatura à sua escolha em contato com o chão do cubo deve ser bem-sucedida em um teste de resistência de Força ou fica impedida até a magia terminar. Uma criatura impedida pode usar uma ação para realizar um teste de Força (Atletismo) contra sua CD de resistência de magia, encerrando o efeito em um sucesso.\nRochas. Como ação bônus no seu turno, você pode fazer uma pedra solta no cubo ser arremessada contra uma criatura que possa ver dentro dele. Faça um ataque à distância com magia; em um acerto, o alvo sofre 3d8 de dano de concussão não mágico e deve ser bem-sucedido em um teste de resistência de Força ou fica caído.","higher":"Quando você conjura esta magia usando um espaço de magia de 6º nível ou superior, escolha um dos efeitos a seguir para cada nível do espaço acima do 5º:\n• O lado do cubo aumenta em 9 metros.\n• A distância ao redor das árvores na qual criaturas sofrem dano aumenta em 1,5 metro.\n• Os danos das Árvores e das Rochas aumentam em 1d6 e 1d8, respectivamente.\n• Ao usar a ação bônus para arremessar rochas, pode atingir um alvo adicional dentro do alcance.","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":565,"category":"Lyre's Guide to Retia","traits":["Legado 5.19"],"sourceNote":"A fonte identifica esta entrada como uma magia Legacy/revisada da edição 5.19; suas regras foram preservadas como uma versão própria de Lyre."},{"id":"lyre-lashing-willow","name":"Salgueiro Açoitador","originalName":"Lashing Willow","level":6,"school":"Conjuração","time":"1 ação","range":"18 metros","comp":"V, S, M (uma semente capaz de crescer e tornar-se uma árvore)","material":"uma semente capaz de crescer e tornar-se uma árvore","duration":"Concentração, até 1 minuto","classes":"Druida, Feiticeiro, Bruxo","ritual":false,"concentration":true,"desc":"Em um ponto que você possa ver a até 18 metros, uma árvore surge e ocupa todos os espaços ao redor. A árvore é um objeto Grande com CA igual à sua CD de resistência de magia e pontos de vida iguais a 10 × o nível em que esta magia foi conjurada. Ela não é afetada por efeitos que exijam teste ou teste de resistência de Inteligência, Sabedoria ou Carisma. A árvore permanece até a magia terminar ou ser destruída; então murcha e morre.\nSempre que uma criatura hostil a você começar o turno a até 3 metros da árvore ou entrar pela primeira vez em um espaço nesse raio em um turno, vinhas e raízes chicoteiam e tentam prendê-la. O alvo deve ser bem-sucedido em um teste de resistência de Força ou fica impedido pela árvore. Criaturas que falham e são menores que a árvore são puxadas para um dos espaços ocupados por ela, onde a casca cresce ao redor e as mantém presas. Uma criatura pode ser mantida dessa forma por espaço ocupado pela árvore. Criaturas presas conseguem respirar através dela, mas ficam cegas e surdas enquanto estiverem no interior. Uma criatura impedida pode usar uma ação para realizar um teste de Força contra sua CD de resistência de magia e escapar em um sucesso. Se causar um acerto crítico contra a árvore, também escapa automaticamente.\nUma criatura que terminar o turno impedida pela árvore é golpeada por ela e sofre 3d10 de dano de concussão. Em seu turno, você pode comandar a árvore para não golpear criaturas capturadas, golpear apenas criaturas específicas, voltar a golpear todas ou libertar criaturas específicas. Como ação bônus, pode comandá-la a reorganizar a posição das criaturas capturadas, movendo qualquer criatura menor que ela para um espaço que a comporte a até 3 metros.","higher":"Se você conjurar esta magia usando um espaço de 7º nível ou superior, escolha um dos efeitos a seguir para cada nível do espaço acima do 6º:\n• O tamanho da árvore aumenta em uma categoria e ela recebe 5 pontos de vida adicionais por nível de espaço.\n• O dano de concussão da árvore aumenta em 1d10.\n• A Classe de Armadura da árvore aumenta em 2.","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":565,"category":"Lyre's Guide to Retia","traits":["Tomo Sussurrante"]},{"id":"lyre-legendary-protection","name":"Proteção Lendária","originalName":"Legendary Protection","level":5,"school":"Abjuração","time":"1 ação","range":"Toque","comp":"V, S, M (um punhado de pó de ouro no valor de pelo menos 250 po, que a magia consome)","material":"um punhado de pó de ouro no valor de pelo menos 250 po, que a magia consome","duration":"10 minutos","classes":"Inscritor, Bardo, Clérigo, Bruxo, Mago","ritual":false,"concentration":false,"desc":"Uma criatura que você toca é protegida por uma defesa que altera o destino. Nas próximas três vezes em que realizar um teste de resistência, qualquer resultado do d20 inferior a 15 é tratado como 15.","higher":"Quando você conjura esta magia no 7º nível ou superior, o número de vezes que o efeito pode ser ativado antes de a magia terminar aumenta em um para cada dois níveis do espaço acima do 5º.","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":566,"category":"Lyre's Guide to Retia","traits":["Convocação Cromática"],"sourceNote":"Regra de grupo — Convocação Cromática: quando a magia mencionar energia ou dano cromático, escolha fogo, frio, ácido, elétrico ou veneno; a escolha vale para todas as ocorrências daquela invocação. Ao conjurar uma magia da Convocação Cromática, faça um teste com o atributo de conjuração (CD 10 + nível da magia). Em uma falha, seu máximo de pontos de vida é reduzido em duas vezes o nível da magia até concluir um Descanso Longo; a fonte chama esse efeito de Queima da Alma. A característica de conjuração da criatura pode dispensá-la desse teste."},{"id":"lyre-lightning-hurl","name":"Arremesso Relampejante","originalName":"Lightning Hurl","level":3,"school":"Transmutação","time":"1 ação bônus","range":"Pessoal","comp":"V, S","material":"","duration":"Concentração, até 1 minuto","classes":"Alma Favorecida, Inscritor","ritual":false,"concentration":true,"desc":"Na próxima vez que você fizer um ataque com arma à distância durante a duração, a munição da arma — ou a própria arma, se for arremessada — transforma-se em um raio. Faça a jogada de ataque normalmente. O alvo sofre 4d8 de dano elétrico em um acerto ou metade em um erro, no lugar do dano normal da arma. Acertando ou errando, cada criatura a até 3 metros do alvo deve realizar um teste de resistência de Destreza, sofrendo 2d8 de dano elétrico em uma falha ou metade em um sucesso. A munição ou arma então retorna à forma normal.","higher":"Quando você conjura esta magia no 4º nível ou superior, escolha um dos efeitos a seguir para cada nível do espaço acima do 3º:\n• O dano da magia aumenta em 1d8.\n• A jogada de ataque feita como parte da magia recebe +1.\n• A magia também causa o dano normal da arma além do dano elétrico, mas apenas em um acerto.\n• O raio ao redor do alvo no qual outras criaturas são afetadas aumenta em 1,5 metro.","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":566,"category":"Lyre's Guide to Retia","traits":["Legado 5.19"],"sourceNote":"A fonte identifica esta entrada como uma magia Legacy/revisada da edição 5.19; suas regras foram preservadas como uma versão própria de Lyre."},{"id":"lyre-lightning-storm","name":"Tempestade de Relâmpagos","originalName":"Lightning Storm","level":3,"school":"Conjuração","time":"1 ação","range":"36 metros","comp":"V, S","material":"","duration":"Concentração, até 1 minuto","classes":"Alma Favorecida, Inscritor, Cavaleiro das Pétalas, Druida","ritual":false,"concentration":true,"desc":"Uma nuvem de tempestade aparece na forma de um cilindro com 3 metros de altura e 18 metros de raio, centrada em um ponto no ar que você possa ver dentro do alcance diretamente acima de você. A magia falha se você não puder ver um ponto no ar onde a nuvem possa surgir, como em uma sala pequena demais. Ao conjurar a magia, escolha um ponto que possa ver sob a nuvem. Um relâmpago desce até esse ponto. Cada criatura a até 1,5 metro deve realizar um teste de resistência de Destreza, sofrendo 3d10 de dano elétrico em uma falha ou metade em um sucesso. Em cada um de seus turnos até a magia terminar, você pode usar sua ação para chamar outro relâmpago dessa forma, no mesmo ponto ou em outro. Se estiver ao ar livre em condições tempestuosas ao conjurar esta magia, você assume o controle da tempestade existente em vez de criar uma nova; nessas condições, o dano aumenta em 1d10.","higher":"Quando você conjura esta magia no 4º nível ou superior, escolha um dos efeitos a seguir para cada nível do espaço acima do 3º:\n• O dano aumenta em 1d10.\n• Ao conjurar a magia e sempre que usar sua ação para atingir um ponto com relâmpago, você pode escolher um ponto adicional. Uma criatura só sofre dano de um relâmpago, mesmo que as áreas se sobreponham.","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":566,"category":"Lyre's Guide to Retia","traits":["Legado 5.19"],"sourceNote":"A fonte identifica esta entrada como uma magia Legacy/revisada da edição 5.19; suas regras foram preservadas como uma versão própria de Lyre."},{"id":"lyre-literal-manifest","name":"Manifestação Literal","originalName":"Literal Manifest","level":0,"school":"Ilusão","time":"1 ação","range":"Pessoal","comp":"S","material":"","duration":"Instantânea","classes":"Inscritor, Mago","ritual":false,"concentration":false,"desc":"Enquanto toca uma folha de papel em branco, você observa rapidamente tudo dentro do seu campo de visão. Um registro documental completo do que enxerga é copiado para o papel em expoentrum — tinta arcana — em texto que pode ser pequeno demais para ser lido normalmente. Quando outra criatura toca a folha, pode usar sua ação para se concentrar nela e testemunhar visualmente uma reprodução perfeita de tudo que você conseguia ver, ficando cega para todo o resto enquanto permanecer em contato com o papel.","higher":"","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":566,"category":"Lyre's Guide to Retia","traits":[]},{"id":"lyre-link-spell","name":"Magia de Elo","originalName":"Link Spell","level":1,"school":"Evocação","time":"Especial","range":"Especial","comp":"S","material":"","duration":"Instantânea","classes":"Cavaleiro das Pétalas, Patrulheiro, Bardo, Clérigo, Paladino, Feiticeiro, Mago","ritual":false,"concentration":false,"desc":"Quando você conjura uma magia com tempo de conjuração de 1 ação, pode conjurar esta magia imediatamente antes para mudar o tempo da outra magia para 1 ação bônus. Esta magia deve ser conjurada em um nível igual à metade do nível da magia afetada, arredondado para cima. Quando realizar o teste de queimadura de eidomancia para esta magia, faça-o como se esta magia tivesse sido conjurada no mesmo nível da magia que você está afetando.","higher":"","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":566,"category":"Lyre's Guide to Retia","traits":["Eidomancia","Épico da Dualidade"],"sourceNote":"Regra de grupo — Eidomancia: todo dano causado por uma magia de eidomancia é considerado dano eidólico. Após conjurar a magia, realize um teste de resistência de Constituição de CD 10 + o nível em que a magia foi conjurada + o número de turnos após o primeiro em que ela permaneceu ativa sob concentração. Se não exigir concentração, o teste é feito imediatamente após a conjuração. Em uma falha, você sofre níveis de exaustão iguais à metade do nível da magia, arredondado para baixo (mínimo 1), e não pode conjurá-la novamente por sete dias. Se a falha elevaria a exaustão a 6, ela fica em 5 e você é imediatamente reduzido a 0 pontos de vida. Se falhar em um teste de concentração para manter uma magia de eidomancia, você pode usar sua reação para rolar um d20 e usar esse resultado no lugar do d20 do teste de concentração."},{"id":"lyre-luciels-grandbolt","name":"Grande Raio de Luciel","originalName":"Luciel’s Grandbolt","level":8,"school":"Evocação","time":"1 ação bônus","range":"Pessoal","comp":"V, S, M (uma lança de metal em miniatura)","material":"uma lança de metal em miniatura","duration":"Concentração, até 10 minutos","classes":"Inscritor, Feiticeiro, Bruxo","ritual":false,"concentration":true,"desc":"Um raio luminoso se acumula em sua palma e assume a forma de uma lança retorcida de quartzo branco. A lança permanece em sua posse pela duração. Como ação bônus em seu turno — e uma vez quando conjura a magia — você pode carregar a lança com energia radiante e celestial e liberar a força combinada em uma linha de 15 metros originada de você. Todas as criaturas na linha devem realizar um teste de resistência de Destreza, sofrendo 8d6 de dano radiante e 8d6 de dano necrótico em uma falha ou metade em um sucesso. Você também pode usar uma ação para realizar um ataque corpo a corpo com magia com a lança contra uma criatura a até 3 metros, causando 6d10 de dano radiante ou 6d10 de dano necrótico, à sua escolha no momento do ataque, em um acerto. Se a magia terminar porque você perdeu a concentração involuntariamente, pode usar sua reação para fazer a lança detonar, escolhendo a criatura que encerrou sua concentração como alvo do mesmo teste e possível dano do efeito em linha da ação bônus.","higher":"","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":567,"category":"Lyre's Guide to Retia","traits":[]},{"id":"lyre-lycrothemias-lunar-devastation","name":"Devastação Lunar de Lycrothemia","originalName":"Lycrothemia’s Lunar Devastation","level":9,"school":"Conjuração","time":"1 ação","range":"36 metros","comp":"V, S, M (uma réplica de mão de Lycrothemia, a lua menor de Somnus Domina, cercada por seis encaixes para gemas e no valor de pelo menos 1.000 po; cada encaixe deve conter um rubi-estrela no valor de pelo menos 750 po, que a magia consome)","material":"uma réplica de mão de Lycrothemia, a lua menor de Somnus Domina, cercada por seis encaixes para gemas e no valor de pelo menos 1.000 po; cada encaixe deve conter um rubi-estrela no valor de pelo menos 750 po, que a magia consome","duration":"Concentração, até 1 minuto","classes":"Lista especial / não especificada","ritual":false,"concentration":true,"desc":"Uma enorme rede de sigilos e círculos arcanos aparece a até 150 metros no céu sobre um ponto dentro do alcance, formando coletivamente um círculo de 36 metros de raio. Ao surgir, os círculos reúnem radiação eidomântica ambiente e a disparam como uma lança de energia pura contra qualquer ponto abaixo à sua escolha, explodindo em uma esfera de 18 metros de raio; se desejar, você pode reduzir o raio até 3 metros. Todas as criaturas na área devem realizar um teste de resistência de Destreza, sofrendo 7d10 de dano elétrico e 7d10 de dano radiante em uma falha ou metade em um sucesso. No início de cada um dos seus turnos, o grande círculo gera 1d4 cargas, que conserva até serem gastas ou a magia terminar. Você pode gastá-las nos efeitos a seguir:\nResistência à Abjuração. Criaturas que tentarem dissipar esta magia realizam com desvantagem os testes com atributo de conjuração necessários para isso.\nLança Arcana. Em seu turno, você pode usar uma ação para gastar qualquer número de cargas e escolher a mesma quantidade de criaturas a até 72 metros do centro da magia, realizando um ataque à distância com magia contra cada uma. As lanças de puro poder arcano causam 3d10 de dano elétrico e 3d10 de dano radiante em um acerto. Esses ataques ignoram cobertura. Você não pode escolher a mesma criatura duas vezes com a mesma ação. Se escolher apenas uma criatura, pode lançar a lança como ação bônus.\nDecomposição. Qualquer criatura reduzida a 0 pontos de vida por esta magia é completamente destruída, como pela magia desintegrar.\nInterceptar. Se estiver sob o círculo, não estiver incapacitado e for alvo de um ataque com arma à distância, você pode gastar 1 carga para interceptar o ataque com uma lança arcana, aplicando -10 à jogada de ataque.\nBarragem da Queda Lunar. Você pode usar uma ação para gastar 10 cargas, encerrando a magia e escolhendo todas as criaturas que desejar dentro do alcance como alvos dos mesmos ataques à distância descritos em Lança Arcana.\nTeletransporte. Como ação bônus, você pode gastar 2 cargas para se teletransportar a qualquer espaço desocupado sob o círculo, desde que não esteja incapacitado e possa executar componentes somáticos. Depois disso, não pode usar movimento até o início do seu próximo turno.\nOs componentes materiais desta magia não são consumidos se um dos rubis na réplica da lua for a gema primal de Vestias.","higher":"","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":567,"category":"Lyre's Guide to Retia","traits":["Eidomancia","Arcana da Guardiã dos Céus"],"sourceNote":"Regra de grupo — Eidomancia: todo dano causado por uma magia de eidomancia é considerado dano eidólico. Após conjurar a magia, realize um teste de resistência de Constituição de CD 10 + o nível em que a magia foi conjurada + o número de turnos após o primeiro em que ela permaneceu ativa sob concentração. Se não exigir concentração, o teste é feito imediatamente após a conjuração. Em uma falha, você sofre níveis de exaustão iguais à metade do nível da magia, arredondado para baixo (mínimo 1), e não pode conjurá-la novamente por sete dias. Se a falha elevaria a exaustão a 6, ela fica em 5 e você é imediatamente reduzido a 0 pontos de vida. Se falhar em um teste de concentração para manter uma magia de eidomancia, você pode usar sua reação para rolar um d20 e usar esse resultado no lugar do d20 do teste de concentração."},{"id":"lyre-magic-aura","name":"Aura Mágica","originalName":"Magic Aura","level":2,"school":"Ilusão","time":"1 ação","range":"Toque","comp":"V, S, M (um pequeno quadrado de seda)","material":"um pequeno quadrado de seda","duration":"24 horas","classes":"Inscritor, Mago","ritual":false,"concentration":false,"desc":"Você coloca uma ilusão sobre uma criatura ou objeto que toca para que magias de adivinhação revelem informações falsas sobre ele. O alvo pode ser uma criatura voluntária ou um objeto que não esteja sendo vestido nem carregado. Ao conjurar a magia, escolha um ou ambos os efeitos a seguir. Eles duram pela duração. Se você conjurar esta magia sobre a mesma criatura ou objeto todos os dias durante 30 dias, aplicando o mesmo efeito a cada vez, a ilusão dura até ser dissipada.\nAura Falsa. Você muda a forma como o alvo aparece para magias e efeitos mágicos que detectam auras mágicas, como detectar magia. Pode fazer um objeto não mágico parecer mágico, um objeto mágico parecer não mágico ou alterar sua aura para aparentar pertencer a uma escola de magia específica. Em um objeto, você também pode fazer a magia falsa ser aparente a qualquer criatura que manuseie o item.\nMáscara. Você muda a forma como o alvo aparece para magias e efeitos que detectam tipos de criatura, como o Sentido Divino de um paladino ou o gatilho da magia símbolo. Escolha um tipo de criatura; outras magias e efeitos mágicos tratam o alvo como se fosse uma criatura desse tipo ou alinhamento.","higher":"","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":568,"category":"Lyre's Guide to Retia","traits":["Legado 5.19"],"sourceNote":"A fonte identifica esta entrada como uma magia Legacy/revisada da edição 5.19; suas regras foram preservadas como uma versão própria de Lyre."},{"id":"lyre-magnesias-smothering-voice","name":"Voz Sufocante de Magnesia","originalName":"Magnesia’s Smothering Voice","level":3,"school":"Ilusão","time":"1 ação","range":"Pessoal (raio de 6 metros)","comp":"V","material":"","duration":"Concentração, até 1 minuto","classes":"Lista especial / não especificada","ritual":false,"concentration":true,"desc":"Você pronuncia uma frase ordenando silêncio, compreendida por todas as criaturas a até 6 metros. Todas as criaturas nessa área devem realizar um teste de resistência de Sabedoria. Em uma falha, perdem a capacidade de compreender outras criaturas ou ler qualquer idioma escrito pela duração, exceto linguagem originada de você; toda outra linguagem lhes parece incompreensível. Elas ainda conseguem compreender e produzir suas próprias palavras. Pela duração, você pode falar telepaticamente com qualquer criatura sob este efeito enquanto ambos estiverem no mesmo plano.","higher":"Quando você conjura esta magia usando um espaço de magia de 4º nível ou superior, o alcance dobra para cada nível do espaço acima do 3º.","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":568,"category":"Lyre's Guide to Retia","traits":["Grimório do Espreitador"]},{"id":"lyre-magnificent-mansion","name":"Mansão Magnífica","originalName":"Magnificent Mansion","level":7,"school":"Conjuração","time":"1 minuto","range":"90 metros","comp":"V, S, M (um portal em miniatura esculpido em marfim, um pequeno pedaço de mármore polido e uma minúscula colher de prata, cada item no valor de pelo menos 5 po)","material":"um portal em miniatura esculpido em marfim, um pequeno pedaço de mármore polido e uma minúscula colher de prata, cada item no valor de pelo menos 5 po","duration":"24 horas","classes":"Inscritor, Bardo, Mago","ritual":false,"concentration":false,"desc":"Você conjura uma moradia extradimensional dentro do alcance, que permanece pela duração, e determina a localização de sua única entrada: um portal de brilho tênue com 1,5 metro de largura e 3 metros de altura. Você e qualquer criatura designada ao conjurar a magia podem entrar enquanto o portal estiver aberto. Você pode abrir ou fechar o portal se estiver a até 9 metros dele. Quando fechado, ele fica invisível. Além do portal existe um saguão com numerosos aposentos. A atmosfera é limpa, fresca e agradável. Você pode criar qualquer planta que desejar, mas o espaço não pode exceder 50 cubos de 3 metros de lado. A moradia é mobiliada e decorada conforme sua escolha. Ela contém comida suficiente para servir um banquete de nove pratos a até 100 pessoas, e uma equipe de 100 servos quase transparentes atende todos que entram, obedecendo completamente às suas ordens; você determina a aparência e as roupas deles. Cada servo pode realizar tarefas que um servo humano normal faria, mas não pode atacar nem realizar ações que causem dano direto a outra criatura. Assim, podem buscar objetos, limpar, consertar, dobrar roupas, acender fogueiras, servir comida, servir vinho e assim por diante. Eles podem ir a qualquer lugar da mansão, mas não podem sair. Móveis e outros objetos criados por esta magia se dissipam em fumaça se forem retirados. Quando a magia termina, quaisquer criaturas ou objetos deixados no espaço extradimensional são expelidos para os espaços desocupados mais próximos da entrada.","higher":"","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":568,"category":"Lyre's Guide to Retia","traits":["Legado 5.19","Memórias de Ossenheimer"],"sourceNote":"A fonte identifica esta entrada como uma magia Legacy/revisada da edição 5.19; suas regras foram preservadas como uma versão própria de Lyre."},{"id":"lyre-manipulate-earth","name":"Manipular Terra","originalName":"Manipulate Earth","level":0,"school":"Transmutação","time":"1 ação","range":"9 metros","comp":"S","material":"","duration":"Instantânea ou 1 hora (veja abaixo)","classes":"Druida, Feiticeiro, Mago","ritual":false,"concentration":false,"desc":"Escolha uma porção de terra ou pedra que possa ver dentro do alcance e que caiba em um cubo de 1,5 metro. Manipule-a de uma das formas a seguir:\n• Se escolher terra solta, você pode escavá-la instantaneamente, movê-la pelo chão e depositá-la a até 1,5 metro. Esse movimento não possui força suficiente para causar dano.\n• Você faz formas, cores ou ambos aparecerem na terra ou pedra, formando palavras, imagens ou padrões. As alterações duram 1 hora.\n• Se a terra ou pedra estiver no chão, você a torna terreno difícil. Como alternativa, pode tornar o chão terreno normal caso já seja difícil. Essa alteração dura 1 hora.\nSe conjurar esta magia várias vezes, pode manter no máximo dois efeitos não instantâneos ativos ao mesmo tempo e pode encerrar um desses efeitos com uma ação.","higher":"","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":568,"category":"Lyre's Guide to Retia","traits":["Legado 5.19"],"sourceNote":"A fonte identifica esta entrada como uma magia Legacy/revisada da edição 5.19; suas regras foram preservadas como uma versão própria de Lyre."},{"id":"lyre-manipulate-ego","name":"Manipular Ego","originalName":"Manipulate Ego","level":0,"school":"Encantamento","time":"1 ação","range":"Pessoal","comp":"S, M (uma pequena quantidade de maquiagem aplicada ao rosto enquanto a magia é conjurada)","material":"uma pequena quantidade de maquiagem aplicada ao rosto enquanto a magia é conjurada","duration":"Concentração, até 1 minuto","classes":"Inscritor, Bardo, Feiticeiro, Bruxo, Mago","ritual":false,"concentration":true,"desc":"Pela duração, você tem vantagem em todos os testes de Carisma direcionados a uma criatura à sua escolha que não seja hostil a você. Quando a magia termina, a criatura percebe que você usou magia para influenciar o humor dela e se torna hostil a você.","higher":"","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":569,"category":"Lyre's Guide to Retia","traits":["Legado 5.19"],"sourceNote":"A fonte identifica esta entrada como uma magia Legacy/revisada da edição 5.19; suas regras foram preservadas como uma versão própria de Lyre."},{"id":"lyre-manipulate-water","name":"Manipular Água","originalName":"Manipulate Water","level":0,"school":"Transmutação","time":"1 ação","range":"9 metros","comp":"S","material":"","duration":"Instantânea ou 1 hora (veja abaixo)","classes":"Druida, Feiticeiro, Mago","ritual":false,"concentration":false,"desc":"Escolha uma área de água que possa ver dentro do alcance e que caiba em um cubo de 1,5 metro. Manipule-a de uma das formas a seguir:\n• Você move instantaneamente ou altera o fluxo da água, redirecionando-a até 1,5 metro em qualquer direção. O movimento não possui força suficiente para causar dano.\n• Você faz a água assumir formas simples e as anima conforme sua orientação. A alteração dura 1 hora.\n• Você muda a cor ou opacidade da água. Toda a água afetada deve ser alterada da mesma forma. A mudança dura 1 hora.\n• Você congela a água, desde que não haja criaturas nela. Ela descongela após 1 hora.\nSe conjurar esta magia várias vezes, pode manter no máximo dois efeitos não instantâneos ativos ao mesmo tempo e pode encerrar um deles com uma ação.","higher":"","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":569,"category":"Lyre's Guide to Retia","traits":[]},{"id":"lyre-mass-burdened-blood","name":"Sangue Sobrecarregado em Massa","originalName":"Mass Burdened Blood","level":5,"school":"Evocação","time":"1 ação","range":"9 metros","comp":"V, S, M (um frasco de sangue)","material":"um frasco de sangue","duration":"Instantânea","classes":"Cavaleiro das Pétalas, Patrulheiro, Clérigo, Feiticeiro, Bruxo","ritual":false,"concentration":false,"desc":"Até seis criaturas à sua escolha dentro do alcance recebem fortitude ampliada, ganhando pontos de vida temporários iguais a 4d6 + seu modificador do atributo de conjuração. Esses pontos desaparecem após 1 minuto. Sempre que uma dessas criaturas fizer uma jogada de ataque, pode escolher perder 5 desses pontos para obter vantagem nesse ataque e/ou perder outros 5 para anular qualquer desvantagem que teria.","higher":"Quando você conjura esta magia usando um espaço de magia de 6º nível ou superior, os pontos de vida temporários recebidos aumentam em 1d6 para cada nível do espaço acima do 5º.","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":569,"category":"Lyre's Guide to Retia","traits":["Daemoturgia"]},{"id":"lyre-mass-command","name":"Comando em Massa","originalName":"Mass Command","level":8,"school":"Encantamento","time":"1 ação","range":"18 metros","comp":"V","material":"","duration":"1 rodada","classes":"Inscritor, Clérigo","ritual":false,"concentration":false,"desc":"Você pronuncia um comando de uma única palavra para qualquer número de criaturas dentro do alcance que possam ouvi-lo. Cada alvo deve ser bem-sucedido em um teste de resistência de Sabedoria ou segue o comando em seu próximo turno. A magia não tem efeito sobre mortos-vivos, criaturas que não compreendam seu idioma ou se o comando for diretamente nocivo a elas. Depois de cumprir o comando da melhor forma possível, o alvo encerra o turno. O comando pode ser do mesmo tipo descrito na magia comando, incluindo os exemplos a seguir. Se o alvo for incapaz de obedecer, o efeito termina sobre ele.\nAproxime-se. O alvo se move em sua direção pela rota mais curta e direta, encerrando o turno se chegar a até 1,5 metro de você.\nLargue. O alvo larga tudo que estiver segurando e encerra o turno.\nFuja. O alvo passa o turno se afastando de você pelo meio mais rápido disponível.\nHumilhe-se. O alvo fica caído e encerra o turno.\nPare. O alvo não se move nem realiza ações. Uma criatura voadora permanece no ar se puder; se precisar se mover para continuar voando, percorre apenas a distância mínima necessária.","higher":"","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":569,"category":"Lyre's Guide to Retia","traits":["Legado do Ouro"]},{"id":"lyre-mental-fortification","name":"Fortificação Mental","originalName":"Mental Fortification","level":3,"school":"Abjuração","time":"1 ação","range":"9 metros","comp":"V","material":"","duration":"Concentração, até 1 hora","classes":"Bardo, Feiticeiro, Bruxo, Mago","ritual":false,"concentration":true,"desc":"Pela duração, você ou uma criatura voluntária que possa ver dentro do alcance recebe resistência a dano psíquico e vantagem em testes de resistência de Inteligência, Sabedoria e Carisma. Se uma criatura tentar ler os pensamentos do alvo enquanto ele estiver sob este efeito, o alvo percebe a tentativa e pode escolher encerrar a magia para bloquear automaticamente essa criatura de sua mente por 24 horas.","higher":"Quando você conjura esta magia usando um espaço de magia de 4º nível ou superior, pode escolher uma criatura adicional para cada nível do espaço acima do 3º. As criaturas devem estar a até 9 metros umas das outras quando forem escolhidas.","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":569,"category":"Lyre's Guide to Retia","traits":["Legado 5.19","Memórias de Ossenheimer"],"sourceNote":"A fonte identifica esta entrada como uma magia Legacy/revisada da edição 5.19; suas regras foram preservadas como uma versão própria de Lyre."},{"id":"lyre-mental-tether","name":"Elo Mental","originalName":"Mental Tether","level":2,"school":"Adivinhação","time":"1 ação","range":"18 metros","comp":"S","material":"","duration":"Concentração, até 1 hora","classes":"Inscritor, Feiticeiro, Bruxo, Mago","ritual":false,"concentration":true,"desc":"Você alcança a mente de uma criatura que possa ver dentro do alcance. O alvo deve realizar um teste de resistência de Sabedoria, sofrendo 3d8 de dano psíquico em uma falha; além disso, a localização dele fica conhecida por você até a magia terminar, desde que ambos estejam no mesmo plano de existência. Enquanto possuir esse conhecimento, o alvo não pode se esconder de você e, se estiver invisível, não recebe benefício dessa condição contra você. Em um sucesso, sofre metade do dano e sua localização não é revelada. Se algo romper este efeito porque você encerrou involuntariamente a concentração — como mudar de plano, sofrer dano e falhar no teste de concentração ou ter a magia dissipada — o alvo sofre novamente o dano da magia.","higher":"Quando você conjura esta magia usando um espaço de magia de 3º nível ou superior, escolha um dos efeitos a seguir para cada nível do espaço acima do 2º:\n• O dano aumenta em 1d8.\n• Você pode escolher uma criatura adicional dentro do alcance. Se o vínculo se romper conforme descrito, o dano se aplica a todos os alvos cujo vínculo foi rompido.","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":569,"category":"Lyre's Guide to Retia","traits":["Legado 5.19"],"sourceNote":"A fonte identifica esta entrada como uma magia Legacy/revisada da edição 5.19; suas regras foram preservadas como uma versão própria de Lyre."},{"id":"lyre-mind-whip","name":"Chicote Mental","originalName":"Mind Whip","level":2,"school":"Encantamento","time":"1 ação","range":"27 metros","comp":"V","material":"","duration":"1 rodada","classes":"Inscritor, Feiticeiro, Mago","ritual":false,"concentration":false,"desc":"Você açoita psiquicamente uma criatura que possa ver dentro do alcance, obrigando-a a realizar um teste de resistência de Inteligência. Em uma falha, o alvo sofre 3d6 de dano psíquico e não pode usar reações até o final do próximo turno. Além disso, no próximo turno deve escolher entre movimento, ação ou ação bônus e recebe apenas uma dessas três opções. Em um sucesso, sofre metade do dano e nenhum dos demais efeitos.","higher":"Quando você conjura esta magia usando um espaço de magia de 3º nível ou superior, escolha um dos efeitos a seguir para cada nível do espaço acima do 2º:\n• O dano psíquico aumenta em 1d6.\n• Você pode escolher uma criatura adicional. As criaturas devem estar a até 9 metros umas das outras quando forem escolhidas.","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":570,"category":"Lyre's Guide to Retia","traits":["Legado 5.19"],"sourceNote":"A fonte identifica esta entrada como uma magia Legacy/revisada da edição 5.19; suas regras foram preservadas como uma versão própria de Lyre."},{"id":"lyre-miraculous-evasion","name":"Evasão Milagrosa","originalName":"Miraculous Evasion","level":1,"school":"Abjuração","time":"1 ação","range":"9 metros","comp":"V, S, M (um número de pérolas igual ao nível em que a magia é conjurada, no valor de 50 po cada)","material":"","duration":"10 minutos","classes":"Cavaleiro das Pétalas, Bardo, Clérigo","ritual":false,"concentration":false,"desc":"Escolha um número de criaturas que possa ver dentro do alcance igual ao nível em que esta magia foi conjurada. Cada uma recebe 1 ponto de vida temporário — essa quantidade não pode ser alterada por nenhum efeito — que permanece até a magia terminar. Quando qualquer quantidade de dano reduziria os pontos de vida de uma dessas criaturas enquanto ela ainda possui esse ponto de vida temporário, ela rola 1d100 + seu modificador do atributo de conjuração. Com resultado 51 ou maior, o dano do efeito é reduzido a 1 ponto, ignorando imunidades, vulnerabilidades e resistências. Caso contrário, o dano é reduzido à metade, arredondado para baixo.","higher":"","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":570,"category":"Lyre's Guide to Retia","traits":["Grimório do Espreitador"]},{"id":"lyre-minor-gate","name":"Portal Menor","originalName":"Minor Gate","level":6,"school":"Conjuração","time":"1 ação","range":"150 metros","comp":"V, S","material":"","duration":"Concentração, até 10 minutos","classes":"Inscritor, Feiticeiro, Bruxo, Mago","ritual":false,"concentration":true,"desc":"Você cria portais de teletransporte conectados que permanecem abertos pela duração. Escolha dois pontos no chão que possa ver: um a até 3 metros de você e outro a até 150 metros. Um portal circular de 3 metros de diâmetro se abre sobre cada ponto. Se um portal surgiria no espaço ocupado por uma criatura, a magia falha e a conjuração é perdida. Os portais são anéis bidimensionais brilhantes preenchidos por névoa, pairando poucos centímetros acima do chão e perpendiculares a ele. Um anel só é visível de um lado, à sua escolha, que é o lado funcional. Qualquer criatura ou objeto que entre por um portal sai pelo outro como se ambos fossem adjacentes; atravessá-lo pelo lado não funcional não tem efeito. A névoa dentro de cada portal é opaca e bloqueia a visão. No seu turno, você pode girar os anéis como ação bônus para fazer o lado ativo apontar em outra direção.","higher":"","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":570,"category":"Lyre's Guide to Retia","traits":["Legado 5.19"],"sourceNote":"A fonte identifica esta entrada como uma magia Legacy/revisada da edição 5.19; suas regras foram preservadas como uma versão própria de Lyre."},{"id":"lyre-minute-meteors","name":"Meteoros Minúsculos","originalName":"Minute Meteors","level":3,"school":"Evocação","time":"1 ação","range":"Pessoal","comp":"V, S, M (salitre, enxofre e alcatrão de pinho moldados em uma esfera)","material":"salitre, enxofre e alcatrão de pinho moldados em uma esfera","duration":"Concentração, até 10 minutos","classes":"Inscritor, Cavaleiro das Pétalas, Feiticeiro, Mago","ritual":false,"concentration":true,"desc":"Você cria seis pequenos meteoros em seu espaço. Eles flutuam no ar e orbitam você pela duração. Ao conjurar a magia e como ação bônus em cada turno posterior, você pode gastar um ou dois meteoros, enviando-os em direção a um ou mais pontos à sua escolha a até 36 metros. Quando um meteoro chega ao destino ou colide com uma superfície sólida, explode. Qualquer criatura a até 1,5 metro do ponto da explosão deve realizar um teste de resistência de Destreza, sofrendo 2d6 de dano de fogo em uma falha ou metade em um sucesso.","higher":"Quando você conjura esta magia usando um espaço de magia de 4º nível ou superior, escolha um dos efeitos a seguir para cada nível do espaço acima do 3º:\n• O número de meteoros criados aumenta em dois.\n• Cada meteoro causa 1d6 de dano de fogo adicional.\n• O raio de efeito de cada meteoro aumenta em 1,5 metro.","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":570,"category":"Lyre's Guide to Retia","traits":["Legado 5.19"],"sourceNote":"A fonte identifica esta entrada como uma magia Legacy/revisada da edição 5.19; suas regras foram preservadas como uma versão própria de Lyre."},{"id":"lyre-mythical-double","name":"Duplo Mítico","originalName":"Mythical Double","level":8,"school":"Ilusão","time":"1 ação bônus","range":"9 metros","comp":"V, S, M (um instrumento adornado com joias no valor de pelo menos 1.000 po, que deve conter pelo menos um peridoto de Baco)","material":"um instrumento adornado com joias no valor de pelo menos 1.000 po, que deve conter pelo menos um peridoto de Baco","duration":"Concentração, até 1 rodada","classes":"Inscritor, Bardo","ritual":false,"concentration":true,"desc":"Escolha uma criatura voluntária dentro do alcance. Um duplo ilusório e heroico dessa criatura é conjurado em um espaço desocupado à sua escolha a até 36 metros e permanece até o início do seu próximo turno. O duplo compartilha seu turno e, sob seu comando, pode realizar uma ação e uma ação bônus, mover-se até o deslocamento da criatura original e usar uma única reação antes de desaparecer. Ele pode realizar qualquer ação e usar qualquer característica como se fosse a criatura copiada, inclusive usar os itens e conjurar as magias dela. Suas ações consomem normalmente usos e cargas correspondentes de itens mágicos possuídos pela criatura original, bem como seus espaços de magia. Se houver dúvida, o duplo não pode realizar ações lendárias nem ações de covil. Ele tem a mesma Classe de Armadura do original e, se sofrer dano, você deve realizar um teste de concentração com CD igual ao dano sofrido pelo duplo; em uma falha, a magia termina. O clone ilusório pode se concentrar em magias, mas perde a concentração quando desaparece; nesse momento, você pode escolher assumir a concentração, se for capaz.","higher":"","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":571,"category":"Lyre's Guide to Retia","traits":["Épico da Dualidade"]},{"id":"lyre-necrosis","name":"Necrose","originalName":"Necrosis","level":0,"school":"Necromancia","time":"1 ação","range":"Toque","comp":"V, S","material":"","duration":"Instantânea","classes":"Bardo, Druida, Feiticeiro, Bruxo","ritual":false,"concentration":false,"desc":"Você toca uma criatura e apodrece o corpo dela no ponto de contato. Faça um ataque corpo a corpo com magia. Em um acerto, o alvo sofre 1d10 de dano necrótico. Se a criatura estiver com seu máximo de pontos de vida e ainda não tiver sofrido dano, ela sofre 1d10 de dano adicional. Se esse dano reduzir a criatura a 0 pontos de vida, você recebe pontos de vida temporários iguais à metade do dano causado por esse ataque, arredondado para baixo.\nAprimoramento de Truque. O dano base aumenta em 1d10 no 5º nível (2d10), 11º nível (3d10) e 17º nível (4d10).","higher":"","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":571,"category":"Lyre's Guide to Retia","traits":["Daemoturgia"]},{"id":"lyre-nightmare-cell","name":"Cela de Pesadelo","originalName":"Nightmare Cell","level":6,"school":"Ilusão","time":"1 ação","range":"18 metros","comp":"S","material":"","duration":"Concentração, até 1 minuto","classes":"Inscritor, Feiticeiro, Bruxo, Mago","ritual":false,"concentration":true,"desc":"Você tenta prender uma criatura em uma cela ilusória que apenas ela percebe. Uma criatura que possa ver dentro do alcance deve realizar um teste de resistência de Inteligência. O alvo obtém sucesso automaticamente se for imune a ser enfeitiçado. Em um sucesso, sofre 5d10 de dano psíquico e a magia termina. Em uma falha, sofre 5d10 de dano psíquico e você faz a área imediatamente ao redor do espaço do alvo parecer perigosa de alguma forma. Pode fazê-lo acreditar que está cercado por fogo, lâminas flutuantes ou bocas horríveis cheias de dentes. Qualquer que seja a forma da ilusão, o alvo não consegue ver nem ouvir nada além dela — é tratado como cego para tudo fora da área — e fica impedido pela duração. Se o alvo for movido para fora da ilusão, realizar um ataque corpo a corpo através dela ou estender qualquer parte do corpo através dela, sofre 10d10 de dano psíquico e a magia termina.","higher":"","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":571,"category":"Lyre's Guide to Retia","traits":["Legado 5.19"],"sourceNote":"A fonte identifica esta entrada como uma magia Legacy/revisada da edição 5.19; suas regras foram preservadas como uma versão própria de Lyre."},{"id":"lyre-nogistunes-negative-edge","name":"Fio Negativo de Nogistune","originalName":"Nogistune’s Negative Edge","level":9,"school":"Necromancia","time":"1 ação bônus","range":"Pessoal","comp":"V, S","material":"","duration":"Instantânea","classes":"Inscritor, Druida, Feiticeiro, Bruxo","ritual":false,"concentration":false,"desc":"Você conjura uma lâmina flutuante de pura força necromântica conectada diretamente ao Plano de Energia Negativa, que assume a forma de uma glaive ou uchigatana e permanece em sua posse conforme descrito pela magia. Ao conjurá-la, você pode realizar até dois ataques corpo a corpo com magia usando a lâmina, cada um contra uma criatura ou objeto feito de matéria viva a até 4,5 metros. Em um acerto, o alvo sofre 4d12 de dano necrótico. O ataque causa acerto crítico com resultado 18 ou maior no d20 e, em um crítico, causa 4d12 de dano necrótico adicional; metade desse dano adicional reduz o máximo de pontos de vida do alvo. Como ação bônus no seu turno, você pode realizar mais dois ataques corpo a corpo com magia com essa arma ou arremessá-la como um único ataque à distância com magia contra um alvo a até 18 metros, depois do qual ela retorna à sua mão.","higher":"","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":571,"category":"Lyre's Guide to Retia","traits":[]},{"id":"lyre-nogistunes-soulbound-vessel","name":"Receptáculo de Alma Vinculada de Nogistune","originalName":"Nogistune’s Soulbound Vessel","level":8,"school":"Necromancia","time":"1 reação, realizada quando uma criatura morre ou é reduzida a 0 pontos de vida dentro do alcance","range":"36 metros","comp":"V, S, M (um recipiente revestido de diamantes negros no valor de pelo menos 5.000 po)","material":"um recipiente revestido de diamantes negros no valor de pelo menos 5.000 po","duration":"Instantânea","classes":"Lista especial / não especificada","ritual":false,"concentration":false,"desc":"O alvo deve realizar um teste de resistência de Carisma. Em uma falha, a alma dele é capturada e selada dentro do componente material desta magia, de onde não pode escapar a menos que você permita. O recipiente não pode ser destruído por meios não mágicos e é tratado como tendo CA 30, 150 pontos de vida, imunidade a dano não mágico e resistência a todos os tipos de dano exceto dano de energia. Ao amanhecer de cada dia, recupera todos os pontos de vida perdidos e restaura sua integridade física. Ele obtém sucesso automático em todos os testes de resistência e sofre metade do dano de ataques com magia. Esta magia não pode ser encerrada por efeitos que anulem magia ou magias.\nEnquanto estiver selada no recipiente, a alma não pode ser ressuscitada, reencarnada nem devolvida a outro plano ou corpo. O recipiente não pode ser aberto por outra criatura que não seja você, a menos que você permita. Uma criatura em contato com o recipiente pode falar telepaticamente com a alma contida. O recipiente não pode voltar a ser usado como componente material desta magia enquanto não estiver vazio.","higher":"","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":571,"category":"Lyre's Guide to Retia","traits":[]},{"id":"lyre-notetakers-gamble","name":"Aposta do Anotador","originalName":"Notetaker’s Gamble","level":5,"school":"Conjuração","time":"1 ação bônus","range":"36 metros","comp":"V, S, M (um recipiente de vidro com tampa de topázio no valor de pelo menos 500 po)","material":"um recipiente de vidro com tampa de topázio no valor de pelo menos 500 po","duration":"Concentração, até 24 horas","classes":"Inscritor, Patrulheiro, Bardo, Druida, Feiticeiro","ritual":false,"concentration":true,"desc":"Escolha uma criatura dentro do alcance e descreva uma ação especial ou magia que você saiba que ela é capaz de realizar ou conjurar. Não pode ser o Ataque Múltiplo dela nem uma magia de nível superior ao espaço usado para conjurar esta magia. O alvo deve realizar um teste de resistência de Inteligência. Em uma falha, sofre 5d10 de dano psíquico e você copia uma manifestação física daquela ação, guardada no componente material desta magia como um pequeno fiapo de energia mágica. Enquanto mantiver a ação armazenada, a criatura não pode recarregá-la nem usá-la; se for um ataque com arma, ela pode usá-lo, mas tem desvantagem nas jogadas de ataque. Ao armazenar a ação, você compreende imediatamente por completo seus efeitos. Você pode usar essa ação uma vez, usando o mesmo tipo de ação descrito originalmente, liberando a manifestação armazenada e escolhendo uma criatura dentro do alcance original. Quando usada, a magia termina e a ação é realizada como se tivesse sido usada pela criatura da qual se originou.","higher":"","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":572,"category":"Lyre's Guide to Retia","traits":[]},{"id":"lyre-okeis-plaything","name":"Brinquedo de Okei","originalName":"Okei’s Plaything","level":9,"school":"Transmutação","time":"1 ação","range":"Toque","comp":"V, S, M (uma estatueta de madeira sem feições que represente o tipo de criatura do alvo, que a magia consome)","material":"uma estatueta de madeira sem feições que represente o tipo de criatura do alvo, que a magia consome","duration":"Até ser dissipada","classes":"Inscritor, Feiticeiro, Mago","ritual":false,"concentration":false,"desc":"Magia rodopiante envolve uma criatura que você toca, retorcendo e alterando sua forma física. O alvo deve realizar um teste de resistência de Carisma, sofrendo 8d8 de dano psíquico em uma falha enquanto começa a se transformar em brinquedo. Ele perde todos os deslocamentos exceto natação e caminhada e não pode realizar mais de um ataque por turno. Ao final de cada um de seus turnos, deve repetir o teste de Carisma, sofrendo novamente o dano em uma falha. Após três falhas, o alvo e todas as suas posses se transformam em um brinquedo. Após três sucessos, o efeito termina e ele volta ao normal.\nUma criatura transformada em brinquedo fica amaldiçoada e permanece assim até esta magia ser dissipada. Se remover maldição for conjurada sobre ela, funciona como dissipar magia e exige um teste de atributo contra a CD de resistência desta magia. A criatura permanece totalmente consciente, mas perde todos os traços, características e estatísticas, exceto seus valores de Inteligência, Sabedoria e Carisma. Ela é tratada como sem proficiências, níveis de classe ou tipo original, passando a ser um constructo Minúsculo com 1 ponto de vida e CA igual à CD de resistência desta magia. Não pode realizar ações nem movimento de qualquer tipo e não pode sofrer dano de magias ou efeitos mágicos. Possui percepção às cegas a 3 metros e ouve tudo que ocorra a até 9 metros. Não pode falar, mas pode se comunicar se outra criatura falar telepaticamente com ela ou ler sua mente.\nSe o brinquedo for destruído, a forma da criatura é restaurada e o efeito termina. Os efeitos desta magia não terminam por campo antimagia ou efeitos semelhantes. Se o brinquedo possuir itens que você deseje recuperar, pode usar uma ação para retirar um item e restaurá-lo à forma original; isso rompe qualquer sintonização que a criatura tivesse com ele. Quando restaurada, a criatura retorna ao estado, idade, pontos de vida e condições que possuía ao ser transformada. Se for restaurada pela destruição do brinquedo, sofre 10d10 de dano psíquico.","higher":"","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":572,"category":"Lyre's Guide to Retia","traits":[]},{"id":"lyre-orbs-of-spelljamming","name":"Orbes de Interferência Mágica","originalName":"Orbs of Spelljamming","level":2,"school":"Abjuração","time":"1 ação","range":"Pessoal","comp":"V, S, M (uma coleção de gemas no valor de pelo menos 10 po cada, em quantidade igual ao número de orbes criados, que a magia consome)","material":"uma coleção de gemas no valor de pelo menos 10 po cada, em quantidade igual ao número de orbes criados, que a magia consome","duration":"10 minutos","classes":"Bardo, Paladino, Feiticeiro, Mago","ritual":false,"concentration":false,"desc":"Você conjura quatro orbes perfeitos de gelo transparente, cada um contendo uma pequena quantidade de energia mágica que brilha suavemente. Pela duração, quando você for alvo de uma magia, pode gastar orbes para absorver a energia mágica que se aproxima. Aplique os efeitos a seguir em ordem:\n• Se puder gastar uma quantidade de orbes igual ao nível em que a magia-alvo foi conjurada, essa magia falha e os orbes são destruídos.\n• Se não tiver orbes suficientes para anulá-la e a magia-alvo tiver sido conjurada acima de seu nível base, os primeiros orbes consumidos reduzem o nível do espaço usado em um para cada orbe, até chegar ao nível base da magia.\n• Se a magia não foi anulada, está no nível base e causaria dano a você, todos os orbes restantes são consumidos. Role 1d10 para cada um e reduza o dano sofrido pelo total. Se isso reduzir o dano inicial a 0, a magia não produz qualquer outro efeito sobre você.\n• Se a magia não foi anulada, está no nível base e não causa dano, sempre que você falhar em um teste de resistência contra ela um orbe é consumido. Role então 1d20 e recalcule o teste usando esse novo resultado. Isso se repete até você obter sucesso ou ficar sem orbes.","higher":"Quando você conjura esta magia no 3º nível ou superior, ela cria um orbe adicional para cada nível do espaço acima do 2º.","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":572,"category":"Lyre's Guide to Retia","traits":["Artes Arcanas de Altissima-Cor"]},{"id":"lyre-ossenheimers-archive","name":"Arquivo de Ossenheimer","originalName":"Ossenheimer’s Archive","level":4,"school":"Transmutação","time":"1 minuto","range":"3 metros","comp":"V, S, M (um livro com páginas em branco suficientes para igualar o maior livro dentro do alcance)","material":"um livro com páginas em branco suficientes para igualar o maior livro dentro do alcance","duration":"Até ser dissipada","classes":"Inscritor, Bardo, Mago","ritual":true,"concentration":false,"desc":"Você apresenta o componente material desta magia — um diário em branco — e concentra energia mágica nele. Todos os livros e textos dentro do alcance, exceto grimórios, pergaminhos de magia e conteúdos de itens mágicos ou artefatos, são copiados para o diário, sobrepostos uns aos outros. As dimensões das páginas são ajustadas ao livro em branco usado, portanto o texto pode ocupar uma quantidade diferente de páginas. Com isso, o diário se transforma em um item mágico.\nVocê e as criaturas cujos nomes escrever na primeira página podem usar uma ação para mudar o conteúdo do arquivo recém-criado, alternando todo o texto para uma das fontes copiadas. Também podem usar uma ação para percorrer uma lista interna dessas fontes, organizada por comprimento da menor para a maior. O arquivo permanece assim por 1 semana; você pode manter o efeito por mais uma semana conjurando a magia novamente. Se conjurar esta magia sobre o livro uma vez por dia durante 30 dias, o efeito se torna permanente. Se alguma fonte contiver mais texto do que o livro em branco consegue exibir, a informação é abruptamente cortada no ponto em que excederia sua capacidade.","higher":"","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":573,"category":"Lyre's Guide to Retia","traits":["Ritual","Memórias de Ossenheimer"]},{"id":"lyre-otherworldly-guise","name":"Aparência Extramundana","originalName":"Otherworldly Guise","level":6,"school":"Transmutação","time":"1 ação bônus","range":"Pessoal","comp":"V, S, M (um objeto gravado com um símbolo dos Planos Exteriores, no valor de pelo menos 500 po)","material":"um objeto gravado com um símbolo dos Planos Exteriores, no valor de pelo menos 500 po","duration":"Concentração, até 1 minuto","classes":"Inscritor, Feiticeiro","ritual":false,"concentration":true,"desc":"Pronunciando uma encantação, você extrai magia dos Planos Inferiores ou dos Planos Superiores, à sua escolha, para transformar-se. Até a magia terminar, recebe os benefícios a seguir:\n• Imunidade a dano de fogo e veneno se escolher os Planos Inferiores, ou a dano radiante e necrótico se escolher os Planos Superiores.\n• Imunidade à condição envenenado, nos Planos Inferiores, ou enfeitiçado, nos Planos Superiores.\n• Asas espectrais surgem em suas costas, concedendo deslocamento de voo de 12 metros.\n• +2 na CA.\n• Todos os seus ataques com armas são mágicos e, ao realizar um ataque com arma, você pode usar seu modificador do atributo de conjuração no lugar de Força ou Destreza nas jogadas de ataque e dano.\n• Você pode atacar duas vezes, em vez de uma, quando usa a ação Atacar no seu turno. Ignore este benefício se já possuir uma característica, como Ataque Extra, que permita atacar mais de uma vez ao usar a ação Atacar.","higher":"","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":573,"category":"Lyre's Guide to Retia","traits":["Legado 5.19"],"sourceNote":"A fonte identifica esta entrada como uma magia Legacy/revisada da edição 5.19; suas regras foram preservadas como uma versão própria de Lyre."},{"id":"lyre-path-to-victory","name":"Caminho para a Vitória","originalName":"Path to Victory","level":3,"school":"Encantamento","time":"1 ação","range":"Toque","comp":"V, S","material":"","duration":"1 minuto","classes":"Inscritor, Bardo, Paladino, Mago","ritual":false,"concentration":false,"desc":"Uma criatura que você toca tem suas capacidades naturais de combate ampliadas. Pela duração, quando usa a ação Atacar pode realizar dois ataques em vez de um. Se já pudesse fazer a quantidade de ataques concedida por esta magia, como por Ataque Extra, em vez disso seu primeiro ataque com arma de cada turno tem vantagem.","higher":"Quando você conjura esta magia usando um espaço de magia de 6º nível ou superior, o alvo pode realizar três ataques em vez de um; se já puder fazer isso, passa a ter vantagem em todos os ataques que realizar.","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":573,"category":"Lyre's Guide to Retia","traits":["Legado do Ouro"]},{"id":"lyre-perfect-silence","name":"Silêncio Perfeito","originalName":"Perfect Silence","level":4,"school":"Ilusão","time":"1 ação","range":"18 metros","comp":"S","material":"","duration":"Concentração, até 1 minuto","classes":"Patrulheiro, Bardo, Clérigo, Bruxo","ritual":false,"concentration":true,"desc":"Ao conjurar esta magia, você tenta impor silêncio completo a um alvo que possa ver dentro do alcance. Se ele não for voluntário, deve realizar um teste de resistência de Carisma e não é afetado em um sucesso. Em uma falha, escolha um dos efeitos a seguir, que permanece até a magia terminar:\nSilêncio Total. O alvo fica completamente silenciado. Ele não consegue ouvir outras criaturas e nada além dos sons incidentais de seu movimento, roupas e semelhantes pode ser ouvido. Enquanto estiver sob este efeito, tem dificuldade para formar palavras e não pode executar componentes verbais. Você pode encerrar este efeito como uma ação bônus, fazendo a aura de silêncio explodir para fora e liberar de uma só vez todos os sons sufocados. A criatura que estava presa deve realizar um teste de resistência de Constituição, sofrendo 4d8 de dano trovejante mais 1d8 adicional para cada turno em que esteve sob o efeito em uma falha, ou metade em um sucesso.\nMovimentos Abafados. O alvo recebe um estado ampliado de silêncio que abafa seus movimentos, exceto aquilo que ele queira que seja ouvido. Pela duração, tem vantagem em testes de Destreza (Furtividade), não produz vibrações nem som, e criaturas que tentem localizá-lo pelo som falham automaticamente. O alvo tem vantagem em jogadas de ataque com ataques baseados em Destreza.","higher":"Quando você conjura esta magia usando um espaço de magia de 5º nível ou superior, escolha um dos efeitos a seguir para cada nível do espaço acima do 4º:\n• A duração dobra.\n• Você pode escolher um alvo adicional dentro do alcance e selecionar efeitos diferentes para cada um. Se usar uma ação bônus para encerrar Silêncio Total, pode escolher quais criaturas terão o efeito encerrado naquele momento e excluir as demais.","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":573,"category":"Lyre's Guide to Retia","traits":["Épico da Dualidade"]},{"id":"lyre-phantasmal-shroud","name":"Mortalha Fantasmagórica","originalName":"Phantasmal Shroud","level":3,"school":"Necromancia","time":"1 ação bônus","range":"Pessoal","comp":"V, S","material":"","duration":"Concentração, até 1 minuto","classes":"Alma Favorecida, Inscritor, Clérigo, Paladino, Bruxo, Mago","ritual":false,"concentration":true,"desc":"Você cria uma mortalha de energia que se forma ao seu redor, emanando de seu corpo e fortalecendo suas ações. Até a magia terminar, qualquer ataque seu que atinja uma criatura a até 3 metros causa 1d8 de dano adicional. Ao conjurar a magia, escolha se esse dano será radiante, necrótico ou frio. Uma criatura que sofrer esse dano não pode recuperar pontos de vida até o início do seu próximo turno. Além disso, qualquer criatura à sua escolha que você possa ver e que comece o turno a até 3 metros de você tem seu deslocamento reduzido em 3 metros até o início do seu próximo turno.","higher":"Quando você conjura esta magia usando um espaço de magia de 4º nível ou superior, escolha um dos efeitos a seguir para cada nível do espaço acima do 3º:\n• O alcance do dano adicional e da redução de deslocamento dobra.\n• Criaturas cujo deslocamento for reduzido perdem 1,5 metro adicional de deslocamento.\n• (2 níveis de espaço) O dano aumenta em 1d8.","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":574,"category":"Lyre's Guide to Retia","traits":["Legado 5.19"],"sourceNote":"A fonte identifica esta entrada como uma magia Legacy/revisada da edição 5.19; suas regras foram preservadas como uma versão própria de Lyre."},{"id":"lyre-phantom-guardian","name":"Guardião Fantasma","originalName":"Phantom Guardian","level":6,"school":"Conjuração","time":"1 ação","range":"Pessoal","comp":"V, S, M (um diamante no valor de pelo menos 1.000 po)","material":"um diamante no valor de pelo menos 1.000 po","duration":"1 hora","classes":"Inscritor, Mago","ritual":false,"concentration":false,"desc":"Você manifesta um guardião etéreo que vela por você e impede que seja ferido. Você recebe 60 pontos de vida temporários, que perde quando a magia termina; inversamente, a magia termina se você perder todos eles. Enquanto o guardião o protege, você pode ver criaturas invisíveis e criaturas escondidas no Plano Etéreo, pode usar reações contra efeitos ou ataques que não consegue ver e não pode ficar caído nem agarrado.","higher":"Se esta magia for conjurada no 7º nível ou superior, você recebe 10 pontos de vida temporários adicionais para cada nível do espaço acima do 6º.","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":574,"category":"Lyre's Guide to Retia","traits":["Memórias de Ossenheimer"]},{"id":"lyre-phantom-step","name":"Passo Fantasma","originalName":"Phantom Step","level":5,"school":"Conjuração","time":"1 ação bônus","range":"Pessoal","comp":"V","material":"","duration":"Concentração, até 1 minuto","classes":"Feiticeiro, Bruxo, Mago","ritual":false,"concentration":true,"desc":"Você se teletransporta até 18 metros para um espaço desocupado que possa ver. Em cada um de seus turnos antes de a magia terminar, pode usar uma ação bônus para se teletransportar dessa forma novamente. Além disso, enquanto a magia estiver ativa, você possui um deslocamento de teletransporte igual ao seu deslocamento de movimento.","higher":"Quando você conjura esta magia usando um espaço de magia de 6º nível ou superior, escolha um dos efeitos a seguir para cada nível do espaço acima do 5º:\n• A duração aumenta para 10 minutos (1 nível de espaço), 1 hora (2 níveis) ou 24 horas (3 níveis).\n• A magia deixa de exigir concentração, mas termina se você ficar incapacitado ou concluir um Descanso Curto ou Longo.","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":574,"category":"Lyre's Guide to Retia","traits":["Épico da Dualidade","Legado 5.19"],"sourceNote":"A fonte identifica esta entrada como uma magia Legacy/revisada da edição 5.19; suas regras foram preservadas como uma versão própria de Lyre."},{"id":"lyre-piercing-crystal","name":"Cristal Perfurante","originalName":"Piercing Crystal","level":1,"school":"Conjuração","time":"1 ação","range":"18 metros","comp":"S, M (uma gota de água ou um pedaço de gelo)","material":"uma gota de água ou um pedaço de gelo","duration":"Instantânea","classes":"Druida, Mago","ritual":false,"concentration":false,"desc":"Você cria um fragmento de gelo e o arremessa contra uma criatura dentro do alcance. Faça um ataque à distância com magia. Em um acerto, o alvo sofre 1d10 de dano perfurante. Acertando ou errando, o fragmento então explode. O alvo e cada criatura a até 1,5 metro do ponto da explosão devem ser bem-sucedidos em um teste de resistência de Destreza ou sofrem 2d6 de dano de frio.","higher":"Quando você conjura esta magia no 2º nível ou superior, escolha um dos efeitos a seguir para cada nível do espaço acima do 1º:\n• O dano de frio secundário aumenta em 1d6.\n• O raio da explosão dos fragmentos dobra.\n• (2 níveis de espaço) Criaturas que falham no teste ficam congeladas brevemente e impedidas até o início do seu próximo turno. Elas podem usar uma ação para realizar um teste de Força contra sua CD de resistência de magia e quebrar o gelo antes disso.","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":574,"category":"Lyre's Guide to Retia","traits":["Legado 5.19"],"sourceNote":"A fonte identifica esta entrada como uma magia Legacy/revisada da edição 5.19; suas regras foram preservadas como uma versão própria de Lyre."},{"id":"lyre-platinum-shield","name":"Escudo de Platina","originalName":"Platinum Shield","level":6,"school":"Abjuração","time":"1 ação bônus","range":"18 metros","comp":"V, S, M (uma escama de dragão banhada a platina, no valor de pelo menos 500 po)","material":"uma escama de dragão banhada a platina, no valor de pelo menos 500 po","duration":"Concentração, até 1 minuto","classes":"Inscritor, Feiticeiro, Mago","ritual":false,"concentration":true,"desc":"Você cria um campo de luz prateada que envolve uma criatura à sua escolha dentro do alcance, podendo escolher você mesmo. O campo emite meia-luz em um raio de 1,5 metro. Enquanto estiver envolvida, a criatura recebe os benefícios a seguir:\nCobertura. A criatura possui meia cobertura.\nResistência a Dano. A criatura tem resistência a dano ácido, frio, fogo, elétrico e veneno.\nEvasão. Se for submetida a um efeito que permita um teste de resistência de Destreza para sofrer apenas metade do dano, em vez disso não sofre dano em um sucesso e sofre apenas metade em uma falha.\nComo ação bônus nos turnos seguintes, você pode mover o campo para outra criatura a até 18 metros do próprio campo.","higher":"","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":574,"category":"Lyre's Guide to Retia","traits":["Legado 5.19"],"sourceNote":"A fonte identifica esta entrada como uma magia Legacy/revisada da edição 5.19; suas regras foram preservadas como uma versão própria de Lyre."},{"id":"lyre-planar-detection","name":"Detecção Planar","originalName":"Planar Detection","level":3,"school":"Adivinhação","time":"10 minutos","range":"36 metros","comp":"V, S, M (um apanhador de sonhos tecido com fio de prata, no valor de pelo menos 100 po)","material":"um apanhador de sonhos tecido com fio de prata, no valor de pelo menos 100 po","duration":"8 horas","classes":"Patrulheiro, Bardo, Clérigo, Druida, Paladino, Mago","ritual":true,"concentration":false,"desc":"Você entrelaça um encanto na área, centrado na sua posição quando conclui a conjuração. Enquanto estiver dentro do alcance da magia, você percebe quando uma criatura nativa de outro plano está presente na área. Ao conjurá-la, pode designar criaturas específicas para serem ignoradas. Se estiver dormindo quando isso ocorrer, você e qualquer pessoa escolhida durante a conjuração recebem um alarme mental que os desperta ou perturba suavemente o descanso. Ao detectar criaturas dessa forma, vocês sabem a direção em que estão, quantas são e seus tamanhos. Também percebem se elas estão assumindo uma forma diferente da verdadeira. Uma criatura pode evitar a detecção sendo bem-sucedida em um teste de Destreza (Furtividade) contra sua CD de resistência de magia, mas realiza esse teste com desvantagem.","higher":"","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":574,"category":"Lyre's Guide to Retia","traits":["Daemoturgia","Ritual"]},{"id":"lyre-power-word-break","name":"Palavra de Poder: Quebrar","originalName":"Power Word Break","level":5,"school":"Evocação","time":"1 ação","range":"9 metros","comp":"V","material":"","duration":"Instantânea","classes":"Inscritor, Cavaleiro das Pétalas, Bardo, Bruxo","ritual":false,"concentration":false,"desc":"Você pronuncia uma palavra de poder que destrói armas, armaduras e objetos. Escolha até seis alvos dentro do alcance, que devem ser armas não mágicas, peças de armadura, portas, constructos ou outros objetos sem vida. Se o item for uma criatura ou estiver sendo segurado ou vestido por uma criatura, ela deve realizar um teste de resistência de Constituição; em um sucesso, o item não é afetado. Em uma falha — ou automaticamente se nenhum teste for necessário — os alvos se rompem violentamente e ficam inutilizados. Se um alvo tiver pontos de vida, como uma criatura, porta ou muralha, sofre 10d10 de dano de energia em uma falha ou metade em um sucesso.","higher":"Quando você conjura esta magia usando um espaço de magia de 6º nível ou superior, pode escolher dois alvos adicionais e o dano de energia aumenta em 1d10 para cada nível do espaço acima do 5º. Se conjurada no 7º nível ou superior, alvos com 100 pontos de vida ou menos falham automaticamente no teste inicial de Constituição, conforme o texto da fonte.","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":575,"category":"Lyre's Guide to Retia","traits":[]},{"id":"lyre-power-word-clarity","name":"Palavra de Poder: Clareza","originalName":"Power Word Clarity","level":7,"school":"Encantamento","time":"1 ação","range":"18 metros","comp":"V","material":"","duration":"1 minuto","classes":"Inscritor, Bardo, Feiticeiro, Mago","ritual":false,"concentration":false,"desc":"Você pronuncia uma palavra de poder, escolhendo até seis criaturas dentro do alcance. Os alvos recebem visão verdadeira, podendo enxergar portas secretas, interruptores ocultos e criaturas invisíveis, atravessar ilusões com a visão e discernir a forma verdadeira de metamorfos ou criaturas transformadas por magia. O alcance dessa visão verdadeira é igual ao alcance de qualquer sentido especial que a criatura possua, como visão no escuro, percepção às cegas ou visão do diabo, com mínimo de 9 metros.","higher":"","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":575,"category":"Lyre's Guide to Retia","traits":[]},{"id":"lyre-power-word-dispel","name":"Palavra de Poder: Dissipar","originalName":"Power Word Dispel","level":7,"school":"Abjuração","time":"1 ação","range":"18 metros","comp":"V","material":"","duration":"1 minuto","classes":"Inscritor, Bardo, Feiticeiro, Bruxo, Mago","ritual":false,"concentration":false,"desc":"Você pronuncia uma palavra amaldiçoada de poder e escolhe uma criatura a até 18 metros, que deve realizar um teste de resistência de Inteligência. Em uma falha, todos os efeitos mágicos que tenham o alvo ou dos quais ele esteja se beneficiando terminam imediatamente. Se o alvo tiver 100 pontos de vida ou menos, todos esses efeitos originados por uma magia de 7º nível ou inferior terminam imediatamente mesmo se ele obtiver sucesso. Além disso, em uma falha, por 1 minuto o alvo não pode ser alvo de efeitos mágicos benéficos cuja duração não seja instantânea, não pode ativar itens mágicos que exijam sintonização nem se sintonizar com novos itens. Ao final de cada um de seus turnos, pode repetir o teste de Inteligência, encerrando o efeito em um sucesso. O Mestre determina quais efeitos são benéficos, considerando a natureza desta magia como uma maldição destinada a escolher aquilo que seria mais prejudicial ao alvo.","higher":"Se você conjurar esta magia no 8º nível ou superior, sua duração muda. No 8º nível, os efeitos duram 1 hora, com novos testes para encerrá-los ocorrendo a cada minuto, e a duração é descrita pela fonte como se tornando permanente. No 9º nível, novos testes só ocorrem ao final de cada Descanso Longo.","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":575,"category":"Lyre's Guide to Retia","traits":[]},{"id":"lyre-power-word-forget","name":"Palavra de Poder: Esquecer","originalName":"Power Word Forget","level":5,"school":"Encantamento","time":"1 ação","range":"18 metros","comp":"V","material":"","duration":"Instantânea","classes":"Inscritor, Cavaleiro das Pétalas, Bardo, Mago","ritual":false,"concentration":false,"desc":"Escolha até três criaturas que possa ver dentro do alcance e que estejam se concentrando em magias ou efeitos que exijam concentração. Você pronuncia uma palavra de distorção que confunde suas mentes, obrigando-as a realizar um teste de resistência de Inteligência. Em uma falha, perdem a concentração imediatamente, sofrem 3d12 de dano psíquico e, se estavam se concentrando em uma magia, não podem conjurar essa magia novamente. Sempre que uma dessas criaturas concluir um Descanso Longo, pode repetir o teste de Inteligência com vantagem, encerrando o efeito e recuperando o uso da magia em um sucesso. Se esta magia for conjurada usando um espaço de 7º nível ou superior, criaturas com 100 pontos de vida ou menos falham automaticamente no teste inicial de Inteligência.","higher":"","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":575,"category":"Lyre's Guide to Retia","traits":[]},{"id":"lyre-power-word-fury","name":"Palavra de Poder: Fúria","originalName":"Power Word Fury","level":6,"school":"Evocação","time":"1 ação","range":"18 metros","comp":"V","material":"","duration":"10 minutos","classes":"Bardo, Feiticeiro, Bruxo","ritual":false,"concentration":false,"desc":"Uma criatura voluntária dentro do alcance que possa ouvi-lo recebe 100 pontos de vida temporários. Enquanto tiver esses pontos de vida temporários, ela fica Enfurecida conforme a condição do sistema e recebe também os efeitos a seguir:\n• Seu deslocamento dobra.\n• Ela fica imune a ser enfeitiçada, amedrontada ou Enfurecida, exceto por este efeito.\n• Em cada turno recebe uma ação de fúria, que pode ser usada para realizar um ataque com uma arma corpo a corpo; esse ataque causa 1d10 de dano adicional. A ação de fúria deve ser usada para atacar a primeira criatura que entrar ao alcance corpo a corpo naquele turno, inclusive uma criatura que já esteja ao alcance quando o turno começar.\nSempre que a criatura terminar o turno sem usar a ação de fúria, seus pontos de vida temporários restantes são reduzidos à metade, arredondando para cima; se isso os reduzir para menos de 5, ela perde o restante. A magia termina se a criatura começar o turno sem esses pontos de vida temporários. Quando termina, a criatura sofre 1 ponto de Fadiga de Combate. Uma criatura sob este efeito não pode se beneficiar de acelerar nem sofrer os efeitos prejudiciais de lentidão.","higher":"Quando você conjura esta magia no 7º nível ou superior, escolha um dos efeitos a seguir para cada nível do espaço acima do 6º:\n• O dano adicional da ação de fúria aumenta em 1d10.\n• O alvo recebe 15 pontos de vida temporários adicionais.\n• A ação de fúria pode ser usada para mover até o deslocamento base normal da criatura, desde que ela não seja obrigada primeiro a usá-la para atacar.","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":575,"category":"Lyre's Guide to Retia","traits":["Convocação Cromática"],"sourceNote":"Regra de grupo — Convocação Cromática: quando a magia mencionar energia ou dano cromático, escolha fogo, frio, ácido, elétrico ou veneno; a escolha vale para todas as ocorrências daquela invocação. Ao conjurar uma magia da Convocação Cromática, faça um teste com o atributo de conjuração (CD 10 + nível da magia). Em uma falha, seu máximo de pontos de vida é reduzido em duas vezes o nível da magia até concluir um Descanso Longo; a fonte chama esse efeito de Queima da Alma. A característica de conjuração da criatura pode dispensá-la desse teste."},{"id":"lyre-power-word-lethargy","name":"Palavra de Poder: Letargia","originalName":"Power Word Lethargy","level":8,"school":"Necromancia","time":"1 ação","range":"18 metros","comp":"V, S","material":"","duration":"Instantânea","classes":"Inscritor, Bardo, Clérigo, Druida, Bruxo, Mago","ritual":false,"concentration":false,"desc":"Escolha até seis criaturas dentro do alcance e pronuncie uma palavra de exaustão debilitante. Qualquer uma delas que tenha 100 pontos de vida ou menos deve realizar um teste de resistência de Constituição. Em uma falha, recebe imediatamente dois níveis de exaustão; em um sucesso, recebe apenas um. Criaturas exauridas dessa forma repetem o teste ao final de cada um de seus turnos, encerrando o efeito em um sucesso e removendo toda exaustão causada por esta magia. Se uma criatura falhar por 10 ou mais, recebe imediatamente níveis suficientes de exaustão para ficar com quatro níveis no total.","higher":"","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":576,"category":"Lyre's Guide to Retia","traits":["Daemoturgia"]},{"id":"lyre-power-word-misfortune","name":"Palavra de Poder: Infortúnio","originalName":"Power Word Misfortune","level":3,"school":"Encantamento","time":"1 reação, realizada quando uma criatura obtém um acerto crítico","range":"18 metros","comp":"V, S","material":"","duration":"Instantânea","classes":"Inscritor, Bardo, Feiticeiro, Bruxo, Mago","ritual":false,"concentration":false,"desc":"Quando uma criatura dentro do alcance obtém um acerto crítico, você pronuncia uma palavra de poder que a faz perder o equilíbrio e rouba sua boa sorte. O acerto crítico é reduzido a um acerto normal. Outra criatura à sua escolha dentro do alcance recebe a sorte roubada e ganha um bônus na próxima jogada de ataque, teste de resistência ou teste de atributo que realizar dentro de 1 minuto igual à metade do bônus de proficiência da criatura que desencadeou o efeito, arredondado para baixo.","higher":"Quando você conjura esta magia usando um espaço de magia de 4º nível ou superior, uma criatura adicional à sua escolha dentro do alcance recebe o bônus na próxima jogada de ataque, teste de resistência ou teste de atributo para cada nível do espaço acima do 3º.","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":576,"category":"Lyre's Guide to Retia","traits":["Daemoturgia"]},{"id":"lyre-power-word-repel","name":"Palavra de Poder: Repelir","originalName":"Power Word Repel","level":3,"school":"Evocação","time":"1 ação","range":"9 metros","comp":"V","material":"","duration":"Instantânea","classes":"Inscritor, Cavaleiro das Pétalas, Bardo, Mago","ritual":false,"concentration":false,"desc":"Você pronuncia uma palavra de poder e uma criatura dentro do alcance é atingida por uma explosão de energia, devendo realizar um teste de resistência de Força. Em uma falha, é empurrada 9 metros em uma direção à sua escolha e fica caída. Criaturas Enormes ou maiores têm vantagem nesse teste. Se o alvo atingir uma superfície sólida que interrompa o movimento, deve realizar um teste de resistência de Constituição e sofre 2d6 de dano de concussão para cada 3 metros que deixou de percorrer em uma falha, ou metade em um sucesso. Ele só sofre esse dano se tiver sido empurrado pelo menos 3 metros antes de parar. Se você escolher empurrar a criatura para cima, a distância do empurrão é reduzida pela metade.","higher":"Ao conjurar esta magia no 4º nível ou superior, a distância forçada aumenta em 4,5 metros para cada nível do espaço acima do 3º. Se conjurada usando um espaço de 7º nível ou superior, criaturas com 100 pontos de vida ou menos falham automaticamente no teste inicial de Força.","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":576,"category":"Lyre's Guide to Retia","traits":[]},{"id":"lyre-power-word-stillness","name":"Palavra de Poder: Imobilidade","originalName":"Power Word Stillness","level":7,"school":"Encantamento","time":"1 ação","range":"18 metros","comp":"V","material":"","duration":"Instantânea","classes":"Inscritor, Clérigo, Feiticeiro, Mago","ritual":false,"concentration":false,"desc":"Você pronuncia uma palavra de poder que torna uma criatura imóvel, congelando-a não apenas fisicamente, mas também no espaço e no tempo. Se o alvo tiver 100 pontos de vida ou menos, fica imobilizado dessa forma; caso contrário, a magia não tem efeito. Enquanto estiver imóvel, seu deslocamento é reduzido a 0 e ele não pode realizar ações ou reações. Para de envelhecer, não pode ser movido, não precisa de ar nem alimento e nada em seu corpo pode ser movido sem mover todo o restante, como se tudo estivesse fixado relativamente no espaço. A criatura recebe resistência a todo dano e não pode ser alvo de qualquer outra magia ou efeito mágico, embora os efeitos desta magia possam ser alvo, como por dissipar magia. Quaisquer efeitos mágicos que já estejam afetando a criatura ficam suspensos até esta magia terminar. Ao final de cada um de seus turnos, o alvo pode realizar um teste de resistência de Carisma, encerrando o efeito em um sucesso. Se falhar nesses testes por 1 minuto ou mais, deixa de fazê-los a cada turno e passa a repeti-los a cada 24 horas.","higher":"","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":576,"category":"Lyre's Guide to Retia","traits":[]},{"id":"lyre-power-word-slow","name":"Palavra de Poder: Lentidão","originalName":"Power Word Slow","level":7,"school":"Encantamento","time":"1 ação","range":"18 metros","comp":"V","material":"","duration":"Instantânea","classes":"Bardo, Feiticeiro, Mago","ritual":false,"concentration":false,"desc":"Escolha até seis criaturas que possa ver dentro do alcance e pronuncie uma palavra de debilitação. Elas devem realizar um teste de resistência de Carisma. Em uma falha, o deslocamento delas é reduzido para 3 metros e nenhum outro efeito pode aumentá-lo acima desse valor. Criaturas afetadas repetem o teste ao final de cada um de seus turnos, encerrando o efeito em um sucesso.","higher":"Quando você conjura esta magia usando um espaço de magia de 8º nível ou superior, seus efeitos mudam. No 8º nível, pode escolher até doze alvos; no 9º nível, pode escolher qualquer número de criaturas a até 18 metros. Além disso, qualquer criatura com 100 pontos de vida ou menos falha automaticamente no primeiro teste contra a magia.","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":576,"category":"Lyre's Guide to Retia","traits":[]},{"id":"lyre-power-word-suffer","name":"Palavra de Poder: Sofrer","originalName":"Power Word Suffer","level":7,"school":"Encantamento","time":"1 ação","range":"18 metros","comp":"V","material":"","duration":"Instantânea","classes":"Inscritor, Feiticeiro, Bruxo, Mago","ritual":false,"concentration":false,"desc":"Você pronuncia uma palavra de poder que faz ondas de dor intensa atacarem uma criatura que possa ver dentro do alcance. Se o alvo tiver 100 pontos de vida ou menos, fica sujeito a dor incapacitante; caso contrário, a magia não tem efeito. Um alvo imune a ser enfeitiçado também não é afetado. Enquanto sofrer essa dor, nenhum de seus deslocamentos pode ser superior a 3 metros. O alvo também tem desvantagem em jogadas de ataque, testes de atributo e testes de resistência, exceto testes de resistência de Constituição. Por fim, se tentar conjurar uma magia, deve primeiro ser bem-sucedido em um teste de resistência de Constituição; em uma falha, a conjuração falha e a magia é desperdiçada. Ao final de cada um de seus turnos, o alvo pode realizar um teste de resistência de Constituição, encerrando a dor em um sucesso.","higher":"Quando você conjura esta magia usando um espaço de 8º nível ou superior, o alcance dobra para cada nível do espaço acima do 7º.","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":577,"category":"Lyre's Guide to Retia","traits":["Legado 5.19"],"sourceNote":"A fonte identifica esta entrada como uma magia Legacy/revisada da edição 5.19; suas regras foram preservadas como uma versão própria de Lyre."},{"id":"lyre-power-word-truth","name":"Palavra de Poder: Verdade","originalName":"Power Word Truth","level":8,"school":"Encantamento","time":"1 ação","range":"Pessoal (raio de 9 metros)","comp":"V","material":"","duration":"Concentração, até 1 minuto","classes":"Inscritor, Bardo, Mago","ritual":false,"concentration":true,"desc":"Você pronuncia uma palavra de poder que obriga o mundo ao seu redor a abandonar mentiras e disfarces. Todos os efeitos ilusórios e magias de ilusão em um raio de 9 metros ao seu redor são dissipados ou suprimidos pela duração. Além disso, se uma criatura dentro desse alcance falar e tentar mentir ou enganar outra criatura, ou realizar deliberadamente uma ação desonesta, deve realizar um teste de resistência de Carisma. Em uma falha, em vez disso pronuncia a versão honesta do que pretendia dizer ou realiza a versão honesta daquela ação. Uma criatura que obtiver sucesso fica livre para repetir a mesma mentira ou a mesma ação desonesta pelo restante da duração sem voltar a provocar este efeito.","higher":"","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":577,"category":"Lyre's Guide to Retia","traits":[]},{"id":"lyre-primordial-warp","name":"Distorção Primordial","originalName":"Primordial Warp","level":3,"school":"Evocação","time":"1 ação","range":"18 metros","comp":"S","material":"","duration":"Instantânea","classes":"Inscritor, Feiticeiro, Bruxo, Mago","ritual":false,"concentration":false,"desc":"Você cria um sigilo arcano diante de si, do qual dispara uma explosão de luz prismática contra uma criatura ou ponto dentro do alcance. Faça um ataque à distância com magia contra o alvo inicial, causando 6d10 de dano de energia em um acerto. Cada criatura a até 1,5 metro do alvo deve ser bem-sucedida em um teste de resistência de Destreza ou sofre o mesmo dano de energia. Se qualquer alvo atingido por esta magia possuir pontos de vida temporários, uma quantidade do dano desta magia igual aos pontos de vida temporários dele é dobrada.","higher":"Quando você conjura esta magia no 4º nível ou superior, escolha um dos efeitos a seguir para cada nível do espaço acima do 3º:\n• A magia causa 2d10 de dano de energia adicional.\n• O alcance da magia dobra.\n• O alcance usado para considerar alvos secundários dobra.\n• A magia passa a ser conjurada como uma ação bônus em vez de uma ação.","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":577,"category":"Lyre's Guide to Retia","traits":["Eidomancia"],"sourceNote":"Regra de grupo — Eidomancia: todo dano causado por uma magia de eidomancia é considerado dano eidólico. Após conjurar a magia, realize um teste de resistência de Constituição de CD 10 + o nível em que a magia foi conjurada + o número de turnos após o primeiro em que ela permaneceu ativa sob concentração. Se não exigir concentração, o teste é feito imediatamente após a conjuração. Em uma falha, você sofre níveis de exaustão iguais à metade do nível da magia, arredondado para baixo (mínimo 1), e não pode conjurá-la novamente por sete dias. Se a falha elevaria a exaustão a 6, ela fica em 5 e você é imediatamente reduzido a 0 pontos de vida. Se falhar em um teste de concentração para manter uma magia de eidomancia, você pode usar sua reação para rolar um d20 e usar esse resultado no lugar do d20 do teste de concentração."},{"id":"lyre-private-sanctum","name":"Santuário Particular","originalName":"Private Sanctum","level":4,"school":"Abjuração","time":"10 minutos","range":"36 metros","comp":"V, S, M (uma fina folha de chumbo, um pedaço de vidro opaco, um chumaço de algodão ou tecido e crisólita em pó)","material":"uma fina folha de chumbo, um pedaço de vidro opaco, um chumaço de algodão ou tecido e crisólita em pó","duration":"24 horas","classes":"Mago","ritual":false,"concentration":false,"desc":"Você torna magicamente segura uma área dentro do alcance. A área é um cubo com lados entre 1,5 e 30 metros. A magia dura pela duração ou até você usar uma ação para encerrá-la. Ao conjurá-la, escolha qualquer quantidade das propriedades a seguir:\n• Som não atravessa a barreira nos limites da área protegida.\n• A barreira parece escura e enevoada, impedindo a visão através dela, inclusive visão no escuro.\n• Sensores criados por magias de adivinhação não podem surgir dentro da área nem atravessar a barreira.\n• Criaturas na área não podem ser alvo de magias de adivinhação.\n• Nada pode se teletransportar para dentro ou para fora da área.\n• Viagem planar é bloqueada dentro da área.\nConjurar esta magia no mesmo local todos os dias durante um ano torna o efeito permanente.","higher":"Quando você conjura esta magia usando um espaço de magia de 5º nível ou superior, pode aumentar o lado máximo do cubo em 30 metros para cada nível do espaço acima do 4º. Assim, com um espaço de 5º nível, pode proteger um cubo com até 60 metros de lado.","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":578,"category":"Lyre's Guide to Retia","traits":["Legado 5.19","Memórias de Ossenheimer"],"sourceNote":"A fonte identifica esta entrada como uma magia Legacy/revisada da edição 5.19; suas regras foram preservadas como uma versão própria de Lyre."},{"id":"lyre-protective-gale","name":"Vendaval Protetor","originalName":"Protective Gale","level":2,"school":"Evocação","time":"1 ação","range":"Pessoal","comp":"V","material":"","duration":"Concentração, até 10 minutos","classes":"Alma Favorecida, Cavaleiro das Pétalas, Bardo, Druida, Feiticeiro, Mago","ritual":false,"concentration":true,"desc":"Um vento forte, de cerca de 32 km/h, sopra ao seu redor em um raio de 3 metros, move-se com você e permanece centrado em você. Pela duração, o vento produz os efeitos a seguir:\n• Ensurdece você e outras criaturas na área.\n• Apaga chamas desprotegidas do tamanho de uma tocha ou menores na área.\n• Afasta vapor, gás e névoa que possam ser dispersos por vento forte.\n• A área é terreno difícil para criaturas que não sejam você.\n• Ataques com armas à distância têm desvantagem se entrarem ou saírem do vento.\n• Se você sofrer dano de queda, sofre apenas metade do dano normal.\n• Se você empurrar uma criatura ou derrubá-la enquanto ela estiver dentro do raio, ela é empurrada para um espaço fora do raio.","higher":"Se você conjurar esta magia usando um espaço de magia de 3º nível ou superior, escolha um dos efeitos a seguir para cada nível do espaço acima do 2º:\n• O raio do vento aumenta em 1,5 metro.\n• Seu deslocamento aumenta em 1,5 metro enquanto o vento o impulsiona.","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":578,"category":"Lyre's Guide to Retia","traits":["Legado 5.19"],"sourceNote":"A fonte identifica esta entrada como uma magia Legacy/revisada da edição 5.19; suas regras foram preservadas como uma versão própria de Lyre."},{"id":"lyre-psychic-cleaver","name":"Cutelo Psíquico","originalName":"Psychic Cleaver","level":0,"school":"Evocação","time":"1 ação bônus","range":"Pessoal","comp":"S","material":"","duration":"Instantânea","classes":"Inscritor, Feiticeiro, Bruxo","ritual":false,"concentration":false,"desc":"Quando você usa a ação Atacar ou conjura uma magia que envolva uma jogada de ataque, pode conjurar este truque para criar em sua outra mão uma arma feita de energia psíquica. Você imediatamente realiza um ataque com essa arma: um ataque corpo a corpo com magia contra alvos próximos ou um ataque à distância com magia se a arremessar. Em um acerto, a arma causa 1d6 de dano psíquico e então desaparece. Ela é tratada como possuindo as propriedades leve e arremesso (6/18 m).\nAprimoramento de Truque. O dano psíquico aumenta para 1d8 no 5º nível, 1d10 no 11º e 2d6 no 17º.","higher":"","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":578,"category":"Lyre's Guide to Retia","traits":[]},{"id":"lyre-psychic-lance","name":"Lança Psíquica","originalName":"Psychic Lance","level":4,"school":"Encantamento","time":"1 ação","range":"36 metros","comp":"V","material":"","duration":"Instantânea","classes":"Inscritor, Bardo, Feiticeiro, Bruxo, Mago","ritual":false,"concentration":false,"desc":"Você dispara da testa uma lança cintilante de poder psíquico contra uma criatura que possa ver dentro do alcance. Como alternativa, pode pronunciar o nome de uma criatura. Se o alvo nomeado estiver dentro do alcance, ele se torna o alvo mesmo que você não consiga vê-lo. Se não estiver, a lança se dissipa sem efeito. O alvo deve realizar um teste de resistência de Inteligência. Em uma falha, sofre 7d6 de dano psíquico e fica incapacitado até o início do seu próximo turno. Em um sucesso, sofre metade do dano e não fica incapacitado.","higher":"Quando você conjura esta magia usando um espaço de magia de 5º nível ou superior, o dano aumenta em 1d6 para cada nível do espaço acima do 4º.","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":578,"category":"Lyre's Guide to Retia","traits":["Legado 5.19"],"sourceNote":"A fonte identifica esta entrada como uma magia Legacy/revisada da edição 5.19; suas regras foram preservadas como uma versão própria de Lyre."},{"id":"lyre-psychic-sliver","name":"Farpa Mental","originalName":"Psychic Sliver","level":0,"school":"Encantamento","time":"1 ação","range":"18 metros","comp":"V","material":"","duration":"1 rodada","classes":"Inscritor, Feiticeiro, Bruxo, Mago","ritual":false,"concentration":false,"desc":"Você crava um espinho desorientador de energia psíquica na mente de uma criatura que possa ver dentro do alcance. O alvo deve ser bem-sucedido em um teste de resistência de Inteligência ou sofre 1d6 de dano psíquico e subtrai 1d4 do próximo teste de resistência que fizer antes do final do seu próximo turno.\nAprimoramento de Truque. O dano aumenta em 1d6 no 5º nível (2d6), 11º (3d6) e 17º (4d6).","higher":"","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":578,"category":"Lyre's Guide to Retia","traits":["Legado 5.19"],"sourceNote":"A fonte identifica esta entrada como uma magia Legacy/revisada da edição 5.19; suas regras foram preservadas como uma versão própria de Lyre."},{"id":"lyre-punishing-gleam","name":"Brilho Punitivo","originalName":"Punishing Gleam","level":4,"school":"Evocação","time":"1 ação","range":"36 metros","comp":"V, S","material":"","duration":"Concentração, até 10 minutos","classes":"Cavaleiro das Pétalas, Feiticeiro, Bruxo, Mago","ritual":false,"concentration":true,"desc":"Uma luz esverdeada e fraca se espalha em uma esfera de 9 metros de raio centrada em um ponto à sua escolha dentro do alcance. A luz contorna esquinas e permanece até a magia terminar. Quando uma criatura entra na área pela primeira vez em um turno ou começa o turno ali, deve ser bem-sucedida em um teste de resistência de Constituição ou sofre 4d10 de dano radiante, recebe um nível de exaustão e passa a emitir luz esverdeada fraca em um raio de 1,5 metro. Essa luz impede a criatura de se beneficiar de invisibilidade. A luz e todos os níveis de exaustão causados por esta magia desaparecem quando a magia termina.","higher":"Quando você conjura esta magia usando um espaço de magia de 5º nível ou superior, escolha um dos efeitos a seguir para cada nível do espaço acima do 4º:\n• O raio da esfera aumenta em 1,5 metro.\n• O dano aumenta em 1d10.\n• (2 níveis de espaço) Criaturas que obtiverem sucesso no teste contra a magia sofrem um nível de Fadiga de Combate. Esses níveis desaparecem quando a magia termina.","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":579,"category":"Lyre's Guide to Retia","traits":["Sangue de Cineris","Legado 5.19"],"sourceNote":"A fonte identifica esta entrada como uma magia Legacy/revisada da edição 5.19; suas regras foram preservadas como uma versão própria de Lyre."},{"id":"lyre-quintillic-battery","name":"Bateria Quintílica","originalName":"Quintillic Battery","level":5,"school":"Abjuração","time":"1 ação","range":"Pessoal","comp":"V, S, M (uma esfera de gema no valor de pelo menos 25 po, que a magia consome; é necessária uma esfera para cada bateria individual)","material":"uma esfera de gema no valor de pelo menos 25 po, que a magia consome; é necessária uma esfera para cada bateria individual","duration":"1 minuto","classes":"Inscritor, Bardo, Mago","ritual":false,"concentration":false,"desc":"Uma esfera cristalina de 30 centímetros de raio aparece em um espaço desocupado a até 9 metros de você, irradiando energia mágica que flui livremente. Cada uma dessas esferas — baterias — possui 25 pontos de vida, CA 15 e deslocamento de voo igual ao seu deslocamento base. Como ação bônus no seu turno, você pode comandar uma ou todas elas a se moverem até 9 metros. Se uma bateria ficar a mais de 9 metros de você, torna-se inerte e inutilizável até retornar ao alcance. Se estiver inerte quando seu turno terminar, é destruída, a menos que esteja a até 4,5 metros de outra bateria.\nAs baterias são criadas com 0 cargas. A cada turno, você pode usar sua ação bônus para conceder 1 carga a todas as suas baterias, ou gastar qualquer quantidade de cargas de uma bateria para receber 1d8 pontos de vida temporários por carga. Você também pode receber esses pontos da mesma maneira como reação ao sofrer dano, mas isso destrói a bateria.\nComo ação bônus, você pode gastar 5 cargas de uma única bateria para receber um surto de energia mágica, destruindo a bateria. Escolha jogadas de ataque, testes de atributo ou testes de resistência. Até a magia terminar, você recebe um bônus d4 no tipo de rolagem escolhido; se já possuir um bônus desta magia para esse tipo, ele aumenta para d6, depois d8, d10 e d12. Se conjurar esta magia enquanto já estiver sob seus efeitos, a conjuração anterior termina.","higher":"Quando você conjura esta magia no 6º nível ou superior, escolha um dos efeitos a seguir para cada nível do espaço acima do 5º:\n• Uma bateria adicional é invocada.\n• Todas as baterias recebem 10 pontos de vida adicionais.\n• Todas as baterias começam com 1 carga para cada vez que você escolher este efeito.","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":579,"category":"Lyre's Guide to Retia","traits":["Convocação Cromática","Eidomancia"],"sourceNote":"Regra de grupo — Convocação Cromática: quando a magia mencionar energia ou dano cromático, escolha fogo, frio, ácido, elétrico ou veneno; a escolha vale para todas as ocorrências daquela invocação. Ao conjurar uma magia da Convocação Cromática, faça um teste com o atributo de conjuração (CD 10 + nível da magia). Em uma falha, seu máximo de pontos de vida é reduzido em duas vezes o nível da magia até concluir um Descanso Longo; a fonte chama esse efeito de Queima da Alma. A característica de conjuração da criatura pode dispensá-la desse teste. Regra de grupo — Eidomancia: todo dano causado por uma magia de eidomancia é considerado dano eidólico. Após conjurar a magia, realize um teste de resistência de Constituição de CD 10 + o nível em que a magia foi conjurada + o número de turnos após o primeiro em que ela permaneceu ativa sob concentração. Se não exigir concentração, o teste é feito imediatamente após a conjuração. Em uma falha, você sofre níveis de exaustão iguais à metade do nível da magia, arredondado para baixo (mínimo 1), e não pode conjurá-la novamente por sete dias. Se a falha elevaria a exaustão a 6, ela fica em 5 e você é imediatamente reduzido a 0 pontos de vida. Se falhar em um teste de concentração para manter uma magia de eidomancia, você pode usar sua reação para rolar um d20 e usar esse resultado no lugar do d20 do teste de concentração."},{"id":"lyre-radiant-smite","name":"Destruição Radiante","originalName":"Radiant Smite","level":3,"school":"Evocação","time":"1 ação bônus","range":"Pessoal","comp":"V","material":"","duration":"Concentração, até 1 minuto","classes":"Alma Favorecida, Paladino","ritual":false,"concentration":true,"desc":"Na próxima vez que você acertar uma criatura com um ataque com arma corpo a corpo durante a duração, sua arma reluz com luz intensa e o ataque causa 3d8 de dano radiante adicional. Além disso, o alvo deve ser bem-sucedido em um teste de resistência de Constituição ou fica cego até a magia terminar. Uma criatura cega por esta magia repete o teste de Constituição ao final de cada um de seus turnos, encerrando a cegueira em um sucesso.","higher":"Quando você conjura esta magia no 4º nível ou superior, escolha um dos efeitos a seguir para cada nível do espaço acima do 3º:\n• O efeito persiste por um ataque adicional depois do momento em que normalmente terminaria.\n• O dano radiante aumenta em 1d8.","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":579,"category":"Lyre's Guide to Retia","traits":["Legado 5.19"],"sourceNote":"A fonte identifica esta entrada como uma magia Legacy/revisada da edição 5.19; suas regras foram preservadas como uma versão própria de Lyre."},{"id":"lyre-redmanes-furious-yell","name":"Grito Furioso de Redmane","originalName":"Redmane’s Furious Yell","level":5,"school":"Evocação","time":"1 ação","range":"esfera de 9 metros de raio","comp":"V","material":"","duration":"Instantânea","classes":"Inscritor, Cavaleiro das Pétalas","ritual":false,"concentration":false,"desc":"Um chamado vibrante e crescente à aventura preenche uma esfera de 9 metros de raio centrada em você. Todas as criaturas hostis na área devem realizar um teste de resistência de Carisma enquanto são atingidas por esse brado espirituoso capaz de abalar o mundo. Em uma falha, uma criatura fica caída, sofre 8d6 de dano de energia e, se estiver agarrando outra criatura, o agarrão termina imediatamente. No mesmo raio, todas as criaturas não hostis recebem 1d10 pontos de vida temporários, criaturas inconscientes despertam e qualquer criatura com 0 pontos de vida que não esteja morta recupera 1d8 pontos de vida.","higher":"Quando você conjura esta magia no 6º nível ou superior, o raio da esfera aumenta em 3 metros para cada nível do espaço acima do 5º.","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":579,"category":"Lyre's Guide to Retia","traits":[]},{"id":"lyre-resilient-sphere","name":"Esfera Resiliente","originalName":"Resilient Sphere","level":4,"school":"Evocação","time":"1 ação","range":"9 metros","comp":"V, S, M (uma peça hemisférica de cristal transparente e uma peça hemisférica correspondente de goma arábica)","material":"uma peça hemisférica de cristal transparente e uma peça hemisférica correspondente de goma arábica","duration":"Concentração, até 1 minuto","classes":"Mago","ritual":false,"concentration":true,"desc":"Uma esfera cintilante de energia envolve uma criatura ou objeto Grande ou menor dentro do alcance. Uma criatura não voluntária deve realizar um teste de resistência de Destreza. Em uma falha, fica encerrada na esfera pela duração. Nada — objetos físicos, energia ou outros efeitos de magia — pode atravessar a barreira para dentro ou para fora, embora uma criatura na esfera consiga respirar. A esfera é imune a todo dano, e uma criatura ou objeto dentro dela não pode ser ferido por ataques ou efeitos originados do lado de fora, nem uma criatura interna pode causar dano ao que estiver fora. A esfera não tem peso e é apenas grande o bastante para conter o alvo. Uma criatura encerrada pode usar uma ação para empurrar as paredes e fazer a esfera rolar até metade de seu deslocamento. A esfera também pode ser apanhada e movida. Uma magia desintegrar direcionada ao globo o destrói sem ferir o que estiver dentro.","higher":"","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":580,"category":"Lyre's Guide to Retia","traits":["Legado 5.19"],"sourceNote":"A fonte identifica esta entrada como uma magia Legacy/revisada da edição 5.19; suas regras foram preservadas como uma versão própria de Lyre."},{"id":"lyre-resonant-weapon","name":"Arma Ressonante","originalName":"Resonant Weapon","level":5,"school":"Evocação","time":"1 ação bônus","range":"Toque","comp":"V, S","material":"","duration":"Concentração, até 1 hora","classes":"Cavaleiro das Pétalas, Patrulheiro, Bardo, Clérigo","ritual":false,"concentration":true,"desc":"Você toca uma arma e a infunde com uma melodia viva que ecoa a cada golpe. A arma se torna mágica pela duração, causa 2d8 de dano trovejante adicional em um acerto e, sempre que uma criatura a até 9 metros dela realizar um teste de concentração, exceto o conjurador desta magia, o teste é feito com desvantagem. Quando a magia termina, o portador pode usar sua reação para realizar um ataque final, golpeando em direção a uma criatura a até 9 metros. Uma onda sonora atinge essa criatura, que deve realizar um teste de resistência de Constituição. Em uma falha, sofre 6d8 de dano trovejante e fica surda até o final do próximo turno; em um sucesso, não sofre dano.","higher":"","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":580,"category":"Lyre's Guide to Retia","traits":["Épico da Dualidade"]},{"id":"lyre-reverse-gravity","name":"Inverter Gravidade","originalName":"Reverse Gravity","level":7,"school":"Transmutação","time":"1 ação","range":"30 metros","comp":"V, S, M (uma magnetita e limalhas de ferro)","material":"uma magnetita e limalhas de ferro","duration":"Concentração, até 1 minuto","classes":"Druida, Feiticeiro","ritual":false,"concentration":true,"desc":"Esta magia inverte a gravidade em um cilindro de 15 metros de raio e 30 metros de altura centrado em um ponto dentro do alcance. Todas as criaturas e objetos na área que não estejam ancorados ao chão caem para cima e alcançam o topo quando a magia é conjurada. Uma criatura pode realizar um teste de resistência de Destreza para agarrar um objeto fixo ao alcance e evitar a queda. Se encontrar uma superfície sólida, como um teto, os objetos e criaturas a atingem como em uma queda normal. Se chegarem ao topo sem atingir nada, permanecem ali, oscilando levemente, pela duração. Ao final, caem de volta para baixo. Criaturas com deslocamento de aceleração em gravidade zero podem escolher não ser afetadas e tratar a área como um ambiente de gravidade zero. Contudo, ataques à distância e qualquer objeto que deixe a posse dessas criaturas são afetados normalmente.","higher":"Quando você conjura esta magia no 8º nível ou superior, as dimensões dobram: raio de 30 metros no 8º e 60 metros no 9º. O alcance também aumenta para 60 metros e 120 metros, respectivamente.","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":580,"category":"Lyre's Guide to Retia","traits":["Legado 5.19"],"sourceNote":"A fonte identifica esta entrada como uma magia Legacy/revisada da edição 5.19; suas regras foram preservadas como uma versão própria de Lyre."},{"id":"lyre-samarus-traumatic-aggravation","name":"Agravamento Traumático de Samaru","originalName":"Samaru’s Traumatic Aggravation","level":4,"school":"Encantamento","time":"1 ação","range":"9 metros","comp":"V, S","material":"","duration":"Concentração, até 1 minuto","classes":"Lista especial / não especificada","ritual":false,"concentration":true,"desc":"Uma criatura à sua escolha dentro do alcance vivencia versões horríveis de memórias de sua vida, retorcidas em cenas de carnificina e imagens traumáticas. O alvo deve realizar um teste de resistência de Inteligência. Em uma falha, sofre 6d10 de dano psíquico e fica atordoado por 1 minuto. Em um sucesso, sofre metade do dano e não fica atordoado. Se a criatura sofrer dano, for obrigada a realizar qualquer teste de resistência ou teste de atributo, ou se outra criatura usar uma ação para sacudi-la, ela deixa de ficar atordoada.","higher":"Quando você conjura esta magia no 5º nível ou superior, pode escolher um alvo adicional para cada nível do espaço acima do 4º.","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":580,"category":"Lyre's Guide to Retia","traits":["Daemoturgia"]},{"id":"lyre-sea-dwellers-aspect","name":"Aspecto do Habitante do Mar","originalName":"Sea-Dweller’s Aspect","level":2,"school":"Transmutação","time":"1 ação","range":"Pessoal","comp":"S, M (um cordão de conchas)","material":"um cordão de conchas","duration":"1 hora","classes":"Patrulheiro, Druida, Feiticeiro","ritual":false,"concentration":false,"desc":"Seu corpo se altera para se adaptar melhor à atividade subaquática. Pela duração, você pode respirar ar e água, caminhar sobre a superfície da água — mas não de outros líquidos —, recebe deslocamento de natação de 18 metros e não sofre penalidades relacionadas a temperaturas de águas profundas, correntes agitadas ou torrenciais nem às penalidades normais de combate subaquático. Enquanto estiver submerso, recebe visão no escuro até 72 metros e sua voz é conduzida pela água para criaturas a até 18 metros. Você pode executar componentes verbais debaixo d'água sem problemas.","higher":"","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":580,"category":"Lyre's Guide to Retia","traits":["Artes Arcanas de Altissima-Cor"]},{"id":"lyre-seizing-bolt","name":"Raio Aprisionador","originalName":"Seizing Bolt","level":1,"school":"Evocação","time":"1 ação","range":"9 metros","comp":"V, S, M (um galho de uma árvore atingida por um raio)","material":"um galho de uma árvore atingida por um raio","duration":"Concentração, até 1 minuto","classes":"Bruxo, Mago","ritual":false,"concentration":true,"desc":"Um feixe de energia azul crepitante dispara contra uma criatura dentro do alcance, formando um arco elétrico contínuo entre você e o alvo. Faça um ataque à distância com magia. Em um acerto, o alvo sofre 1d12 de dano elétrico e, em cada um de seus turnos pela duração, você pode usar sua ação para causar automaticamente mais 1d12 de dano elétrico ao alvo. A magia termina se você usar sua ação para qualquer outra coisa. Também termina se o alvo sair do alcance ou tiver cobertura total contra você.","higher":"Quando você conjura esta magia no 2º nível ou superior, escolha um dos efeitos a seguir para cada nível do espaço acima do 1º:\n• O dano inicial aumenta em 1d12.\n• (2 níveis de espaço) O dano inicial e o dano contínuo aumentam em 1d12.\n• (2 níveis de espaço) Você pode escolher uma criatura adicional. Usar sua ação para continuar o efeito causa dano a todos os alvos.\n• (2 níveis de espaço) Você pode usar uma ação bônus no lugar de sua ação para causar o dano secundário, mas só pode causar esse dano extra uma vez por turno.","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":581,"category":"Lyre's Guide to Retia","traits":["Legado 5.19"],"sourceNote":"A fonte identifica esta entrada como uma magia Legacy/revisada da edição 5.19; suas regras foram preservadas como uma versão própria de Lyre."},{"id":"lyre-self-curse","name":"Automaldição","originalName":"Self-Curse","level":1,"school":"Necromancia","time":"1 reação, realizada quando você falha em um teste de resistência","range":"Pessoal","comp":"V, S, M (uma pequena lâmina capaz de perfurar sua pele)","material":"uma pequena lâmina capaz de perfurar sua pele","duration":"Instantânea","classes":"Patrulheiro, Druida, Feiticeiro, Mago","ritual":false,"concentration":false,"desc":"Você troca seu próprio sangue e bem-estar por um breve aumento de capacidade. Você obtém sucesso em um teste de resistência no qual teria falhado, mas sofre 1d6 pontos de dano irredutível multiplicados pela diferença entre o resultado do teste que falhou e a CD que precisava superar.","higher":"Quando você conjura esta magia no 2º nível ou superior, pode reduzir o dano sofrido por ela em 5 pontos para cada nível do espaço acima do 1º.","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":581,"category":"Lyre's Guide to Retia","traits":["Daemoturgia"]},{"id":"lyre-sending","name":"Enviar Mensagem","originalName":"Sending","level":3,"school":"Evocação","time":"1 ação","range":"Ilimitado","comp":"V, S, M (um pequeno pedaço de fio de cobre fino)","material":"um pequeno pedaço de fio de cobre fino","duration":"1 rodada","classes":"Inscritor, Bardo, Clérigo, Mago","ritual":false,"concentration":false,"desc":"Você envia uma mensagem curta de até vinte e cinco palavras a uma criatura com a qual esteja familiarizado. A criatura ouve a mensagem em sua mente, reconhece você como remetente se o conhecer e pode responder imediatamente da mesma forma. A magia permite que criaturas com Inteligência 1 ou maior compreendam o significado da mensagem. Você pode enviá-la a qualquer distância e até para outros planos de existência, mas se o alvo estiver em um plano diferente existe 5% de chance de a mensagem não chegar.","higher":"Quando você conjura esta magia no 4º nível ou superior, a quantidade de palavras que você e o alvo podem trocar aumenta para cada nível do espaço acima do 3º: 50 no 4º, 100 no 5º, 250 no 6º, 500 no 7º, 1.000 no 8º e 2.000 no 9º.","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":581,"category":"Lyre's Guide to Retia","traits":["Legado 5.19"],"sourceNote":"A fonte identifica esta entrada como uma magia Legacy/revisada da edição 5.19; suas regras foram preservadas como uma versão própria de Lyre."},{"id":"lyre-shaded-weapon","name":"Arma Sombria","originalName":"Shaded Weapon","level":2,"school":"Ilusão","time":"1 ação bônus","range":"Pessoal","comp":"V, S","material":"","duration":"Concentração, até 1 minuto","classes":"Feiticeiro, Bruxo, Mago","ritual":false,"concentration":true,"desc":"Você entrelaça fios de sombra para criar em sua mão uma arma de escuridão solidificada, que permanece até a magia terminar. Ela conta como uma arma corpo a corpo simples com a qual você é proficiente, causa 2d8 de dano psíquico em um acerto e possui as propriedades acuidade, leve e arremesso (6/18 m). Além disso, quando você usa a arma para atacar um alvo em meia-luz ou escuridão, realiza a jogada de ataque com vantagem. Se largar ou arremessar a arma, ela se dissipa ao final do turno. Depois disso, enquanto a magia persistir, você pode usar uma ação bônus para fazê-la reaparecer em sua mão.","higher":"Quando você conjura esta magia no 4º nível ou superior, escolha um dos efeitos a seguir para cada dois níveis do espaço acima do 2º:\n• A arma causa 1d8 de dano psíquico adicional.\n• Você cria uma segunda Arma Sombria na outra mão, idêntica à primeira.\n• O alcance normal de arremesso aumenta em 9 metros e o alcance longo em 27 metros.","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":581,"category":"Lyre's Guide to Retia","traits":["Legado 5.19"],"sourceNote":"A fonte identifica esta entrada como uma magia Legacy/revisada da edição 5.19; suas regras foram preservadas como uma versão própria de Lyre."},{"id":"lyre-shadow-flame","name":"Chama Sombria","originalName":"Shadow Flame","level":4,"school":"Necromancia","time":"1 ação","range":"Pessoal","comp":"V, S, M (um globo ocular de morto-vivo encapsulado em uma gema no valor de pelo menos 150 po)","material":"um globo ocular de morto-vivo encapsulado em uma gema no valor de pelo menos 150 po","duration":"Concentração, até 1 minuto","classes":"Bruxo","ritual":false,"concentration":true,"desc":"Sombras semelhantes a chamas envolvem seu corpo até a magia terminar, deixando você fortemente obscurecido para os demais. As sombras transformam a meia-luz a até 3 metros de você em escuridão e a luz plena na mesma área em meia-luz. Até a magia terminar, você possui resistência a dano radiante. Além disso, sempre que uma criatura a até 3 metros acertar você com um ataque, as sombras a chicoteiam, causando 2d8 de dano necrótico.","higher":"Quando você conjura esta magia usando um espaço de magia de 5º nível ou superior, escolha um dos efeitos a seguir para cada nível do espaço acima do 4º:\n• O dano necrótico aumenta em 1d8.\n• O raio no qual as sombras alteram a iluminação e retaliam contra ataques aumenta em 3 metros.","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":581,"category":"Lyre's Guide to Retia","traits":["Legado 5.19"],"sourceNote":"A fonte identifica esta entrada como uma magia Legacy/revisada da edição 5.19; suas regras foram preservadas como uma versão própria de Lyre."},{"id":"lyre-shadow-flare","name":"Explosão Sombria","originalName":"Shadow Flare","level":7,"school":"Conjuração","time":"1 ação","range":"36 metros","comp":"V, S, M (uma esfera de cristal para concentrar os efeitos da magia, no valor de pelo menos 100 po)","material":"uma esfera de cristal para concentrar os efeitos da magia, no valor de pelo menos 100 po","duration":"Instantânea","classes":"Inscritor, Clérigo, Bruxo","ritual":false,"concentration":false,"desc":"Escolha um ponto que possa ver dentro do alcance. Diversos pequenos portais para várias camadas dos Infernos se abrem ali e suas energias se misturam em uma esfera de caos cromático. A esfera explode, preenchendo um raio de 12 metros centrado no ponto. A explosão contorna esquinas e atravessa frestas com mais de 2,5 centímetros. Todas as criaturas atingidas pela energia negativa devem realizar um teste de resistência de Carisma, sofrendo 8d10 + 30 de dano necrótico em uma falha ou metade em um sucesso. Qualquer criatura que falhar fica atordoada e assediada por energia necrótica. Por 1 minuto, tem desvantagem em jogadas de ataque e testes de atributo. Ao final de cada um de seus turnos, repete o teste, encerrando o efeito em um sucesso. O efeito também termina se a criatura receber mais de 20 pontos de cura em um único turno ou se uma magia como remover maldição ou restauração menor for conjurada sobre ela. Uma criatura que encerrar o efeito por sucesso no teste não pode voltar a sofrer os efeitos debilitantes desta magia por 24 horas.","higher":"","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":582,"category":"Lyre's Guide to Retia","traits":["Convocação Cromática"],"sourceNote":"Regra de grupo — Convocação Cromática: quando a magia mencionar energia ou dano cromático, escolha fogo, frio, ácido, elétrico ou veneno; a escolha vale para todas as ocorrências daquela invocação. Ao conjurar uma magia da Convocação Cromática, faça um teste com o atributo de conjuração (CD 10 + nível da magia). Em uma falha, seu máximo de pontos de vida é reduzido em duas vezes o nível da magia até concluir um Descanso Longo; a fonte chama esse efeito de Queima da Alma. A característica de conjuração da criatura pode dispensá-la desse teste."},{"id":"lyre-shadow-gate","name":"Portal Sombrio","originalName":"Shadow Gate","level":5,"school":"Conjuração","time":"1 ação","range":"9 metros","comp":"V, S, M (qualquer objeto do Reino das Sombras, ou que tenha permanecido lá por um ano ininterrupto em algum momento)","material":"qualquer objeto do Reino das Sombras, ou que tenha permanecido lá por um ano ininterrupto em algum momento","duration":"Instantânea","classes":"Cavaleiro das Pétalas, Bardo, Paladino, Feiticeiro","ritual":true,"concentration":false,"desc":"Você e até oito criaturas voluntárias dentro do alcance criam um caminho para o Reino das Sombras, desaparecendo em uma exibição impressionante de névoa e vento. Criaturas nativas do Reino das Sombras dentro do alcance que você queira levar, se forem voluntárias, não contam contra esse limite. Criaturas que não sejam nativas e se teletransportem dessa forma não podem descansar enquanto estiverem lá, devido ao desgaste mental causado pela magia. Você e as criaturas escolhidas reaparecem no Reino das Sombras em um local com o qual esteja familiarizado ou do qual tenha conhecimento. A magia o leva para as proximidades gerais da área desejada ou para uma área semelhante, a menos que você já tenha estado lá; nesse caso, vai diretamente ao local escolhido.\nSe estiver no Reino das Sombras, pode conjurar esta magia para retornar ao último plano para o qual a usou. Você aparece a até 1,6 quilômetro do local onde a conjurou por último e pode levar novamente até oito criaturas voluntárias.\nComo alternativa, ao conjurar esta magia você pode escolher qualquer número de criaturas dentro do alcance. Se alguma delas for nativa do Reino das Sombras, deve realizar um teste de resistência de Carisma. Em uma falha, todas são banidas para o mesmo local aleatório no Reino das Sombras e não podem retornar ao plano em que você está por nenhum meio durante 24 horas. Uma criatura pode conjurar dissipar magia em você para escolher este efeito como alvo e encerrá-lo em um sucesso. Da mesma forma, se você entrar em um campo antimagia, não é considerado presente no plano para os fins dessa restrição.","higher":"Quando você conjura esta magia usando um espaço de magia de 6º nível ou superior, pode dobrar o número de criaturas que teletransporta com você para cada nível do espaço acima do 5º: 16 no 6º, 32 no 7º, 64 no 8º e 128 no 9º. Se usá-la para banir nativos do Reino das Sombras, o alcance dobra para cada nível acima do 5º, e o tempo antes que possam retornar aumenta para 1 semana no 6º, 1 mês no 7º, 1 ano no 8º e se torna permanente enquanto você estiver vivo no 9º.","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":582,"category":"Lyre's Guide to Retia","traits":["Daemoturgia","Ritual"]},{"id":"lyre-shamwood-stakeout","name":"Vigília de Shamewood","originalName":"Shamwood Stakeout","level":3,"school":"Conjuração","time":"1 minuto","range":"3 metros","comp":"V, S","material":"","duration":"8 horas","classes":"Inscritor","ritual":false,"concentration":false,"desc":"Um vigia espectral aparece em um espaço dentro do alcance e observa a área de forma invisível. Você pode definir critérios para tudo aquilo que ele deve observar enquanto existir. Enquanto permanecer, desde que você esteja a até 1,6 quilômetro do vigia, ele o alerta sobre qualquer coisa suspeita que veja nos termos mais básicos possíveis, como “inimigo”, “espreitador”, “monstro” e semelhantes. Ele realiza testes de Sabedoria (Percepção) usando seu modificador do atributo de conjuração + seu bônus de proficiência como modificador da perícia, e possui Percepção passiva igual à sua CD de resistência de magia. Possui visão no escuro até 36 metros e é cego além dessa distância. Se você estiver dormindo quando ele alertar, desperta imediatamente. Se normalmente seria surpreendido por inimigos, mas for despertado por esta magia, pode agir normalmente. Uma criatura que consiga ver criaturas invisíveis pode atacar o vigia, que possui CA igual à sua CD de resistência de magia e realiza todos os testes de resistência com seu modificador do atributo de conjuração + seu bônus de proficiência. Ele nunca sofre dano de efeitos contra os quais obtiver sucesso no teste de resistência. Se sofrer qualquer dano, a magia termina antecipadamente.","higher":"","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":582,"category":"Lyre's Guide to Retia","traits":[]},{"id":"lyre-shield-maidens","name":"Donzelas do Escudo","originalName":"Shield Maidens","level":4,"school":"Conjuração","time":"1 ação","range":"Pessoal","comp":"V, S, M (uma pequena figura de você com dois escudos de cristal amarrados a ela, no valor de 100 po cada, que a magia consome)","material":"uma pequena figura de você com dois escudos de cristal amarrados a ela, no valor de 100 po cada, que a magia consome","duration":"Concentração, até 1 minuto","classes":"Alma Favorecida, Inscritor, Mago","ritual":false,"concentration":true,"desc":"Você conjura duas donzelas do escudo fantasmagóricas que permanecem ao seu lado pela duração, impondo desvantagem em ataques feitos contra você a até 9 metros. Além disso, enquanto estiver sob este efeito você pode usar sua reação para reproduzir os efeitos da magia escudo, mas esses efeitos terminam ao final do turno em que forem invocados.","higher":"Se você conjurar esta magia no 5º nível ou superior, o alcance dobra para cada nível do espaço acima do 4º: 18 metros no 5º, 36 metros no 6º, 72 metros no 7º e assim por diante.","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":582,"category":"Lyre's Guide to Retia","traits":["Memórias de Ossenheimer"]},{"id":"lyre-shield-of-summer","name":"Escudo do Verão","originalName":"Shield of Summer","level":1,"school":"Abjuração","time":"1 reação, realizada quando você é atingido por um ataque","range":"Pessoal","comp":"V, S","material":"","duration":"1 rodada","classes":"Alma Favorecida, Inscritor, Cavaleiro das Pétalas, Patrulheiro, Druida","ritual":false,"concentration":false,"desc":"Um escudo de energia quase invisível, composto por múltiplas camadas, surge e protege você. Até o início do seu próximo turno, você recebe +5 de bônus na sua Classe de Armadura, inclusive contra o ataque que desencadeou esta magia. Se você for atingido por um ataque enquanto esta magia estiver ativa, pode optar por encerrá-la antecipadamente para reduzir em 5 o dano que esse ataque causaria a você.","higher":"Quando você conjura esta magia no 2º nível ou superior, pode escolher um dos efeitos a seguir para cada nível da magia acima do 1º:\n• O bônus na sua Classe de Armadura aumenta em 1.\n• A quantidade de dano reduzida por esta magia aumenta em 10.\n• Esta magia pode reduzir o dano de uma fonte adicional de dano antes de terminar.","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":583,"category":"Lyre's Guide to Retia","traits":["Tomo da Madeira Sussurrante"]},{"id":"lyre-shockwave","name":"Onda de Choque","originalName":"Shockwave","level":5,"school":"Evocação","time":"1 ação","range":"Pessoal (raio de 9 metros)","comp":"V","material":"","duration":"Instantânea","classes":"Alma Favorecida, Paladino","ritual":false,"concentration":false,"desc":"Você golpeia o chão, criando uma explosão de energia divina que se propaga para fora de você. Cada criatura à sua escolha a até 9 metros de você deve realizar um teste de resistência de Constituição. Em caso de falha, sofre 5d6 de dano trovejante ou de energia, à sua escolha, além de 5d6 de dano radiante ou necrótico, também à sua escolha. Se um alvo falhar, ele sofre um efeito secundário baseado no tipo de dano escolhido entre trovejante e energia: se for trovejante, fica caído; se for de energia, é empurrado 9 metros para longe de você e sofre 1d6 de dano de concussão adicional se colidir com uma superfície sólida que o impeça de percorrer os 9 metros completos. Uma criatura que obtiver sucesso no teste sofre metade do dano e não fica caída nem é empurrada.","higher":"Se você conjurar esta magia no 6º nível ou superior, pode escolher um dos efeitos a seguir para cada nível do espaço acima do 5º:\n• O dano trovejante ou de energia aumenta em 2d6.\n• O raio da magia aumenta em 4,5 metros.\n• (3 níveis de espaço) A magia causa 5d6 de dano adicional, trovejante ou de energia; deve ser o tipo que você não escolheu inicialmente. Alvos que falharem são empurrados para trás e ficam caídos.","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":583,"category":"Lyre's Guide to Retia","traits":["Legado 5.19"],"sourceNote":"A fonte identifica esta entrada como uma magia Legacy/revisada da edição 5.19; suas regras foram preservadas como uma versão própria de Lyre."},{"id":"lyre-shrieking-mars","name":"Marte Estridente","originalName":"Shrieking Mars","level":2,"school":"Ilusão","time":"1 ação","range":"9 metros","comp":"V, S","material":"","duration":"Concentração, até 1 minuto","classes":"Inscritor, Cavaleiro das Pétalas, Bardo, Feiticeiro, Bruxo","ritual":false,"concentration":true,"desc":"Você solta um brado de guerra intimidador e pode ter como alvo todas as criaturas a até 9 metros de você. Essas criaturas devem realizar um teste de resistência de Sabedoria. Em caso de falha, ficam amedrontadas por 1 minuto e, enquanto estiverem amedrontadas dessa forma, não podem realizar mais de um único ataque com arma em qualquer turno, independentemente de características, itens mágicos ou efeitos de magia.","higher":"Quando você conjura esta magia no 5º nível ou superior, pode excluir do efeito quaisquer criaturas à sua escolha quando conjurá-la.","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":583,"category":"Lyre's Guide to Retia","traits":[]},{"id":"lyre-silencing-smite","name":"Destruição Silenciadora","originalName":"Silencing Smite","level":1,"school":"Evocação","time":"1 ação bônus","range":"Pessoal","comp":"V","material":"","duration":"Concentração, até 1 minuto","classes":"Alma Favorecida, Cavaleiro das Pétalas, Paladino","ritual":false,"concentration":true,"desc":"Na próxima vez que você atingir uma criatura com um ataque corpo a corpo com arma durante a duração desta magia, seu ataque causa 1d6 de dano trovejante adicional. Além disso, se o alvo for uma criatura, ele deve realizar um teste de resistência de Sabedoria. Em caso de falha, fica silenciado até a magia terminar. Enquanto estiver silenciado, a criatura não pode falar nem produzir ruídos vocalmente; se tentar conjurar uma magia que exija componentes verbais, não consegue produzi-los. Sempre que a criatura tentar conjurar uma magia e ao final de cada um dos turnos dela, repete o teste de resistência de Sabedoria, encerrando o efeito em caso de sucesso.","higher":"","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":583,"category":"Lyre's Guide to Retia","traits":[]},{"id":"lyre-slash-wind","name":"Vento Cortante","originalName":"Slash Wind","level":5,"school":"Conjuração","time":"1 ação","range":"9 metros","comp":"S, M (uma arma corpo a corpo no valor de pelo menos 1 pp)","material":"uma arma corpo a corpo no valor de pelo menos 1 pp","duration":"Instantânea","classes":"Cavaleiro das Pétalas, Patrulheiro, Mago","ritual":false,"concentration":false,"desc":"Você floreia a arma usada na conjuração e então desaparece para golpear como o vento. Escolha até cinco criaturas que você possa ver dentro do alcance. Faça um ataque corpo a corpo com magia contra cada alvo. Em um acerto, o alvo sofre 6d10 de dano de energia. Esses ataques não contam como ataques com arma para efeitos de características como Destruição Divina, Ataque Furtivo e semelhantes, mesmo que a arma utilizada normalmente qualificasse para o efeito. Em seguida, você pode se teletransportar para um espaço desocupado que possa ver a até 1,5 metro de um dos alvos que tenha acertado ou errado.","higher":"Quando você conjura esta magia usando um espaço de 6º nível ou superior, pode escolher um dos efeitos a seguir para cada nível do espaço acima do 5º:\n• Você pode escolher dois alvos adicionais dentro do alcance.\n• O dano aumenta em 1d10.\n• O alcance da magia aumenta em 6 metros.","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":583,"category":"Lyre's Guide to Retia","traits":["Legado 5.19"],"sourceNote":"A fonte identifica esta entrada como uma magia Legacy/revisada da edição 5.19; suas regras foram preservadas como uma versão própria de Lyre."},{"id":"lyre-snap-freeze","name":"Congelamento Súbito","originalName":"Snap Freeze","level":5,"school":"Evocação","time":"1 ação","range":"9 metros","comp":"V, S","material":"","duration":"1 minuto","classes":"Clérigo, Feiticeiro, Mago","ritual":false,"concentration":false,"desc":"O corpo de uma criatura dentro do alcance é envolvido por um frio intenso, congelando-a de dentro para fora a ponto de possivelmente impedi-la de se mover. Ela deve realizar um teste de resistência de Constituição. Em caso de falha, sofre 7d10 + 10 de dano de frio e fica impedida por 1 minuto enquanto o corpo se enrijece; em caso de sucesso, sofre metade do dano e não fica impedida. Criaturas imunes a dano de frio não ficam impedidas. Um alvo impedido pode repetir o teste de resistência ao final de cada um de seus turnos. Sempre que sofrer dano de fogo, também pode repetir o teste com vantagem. Obter sucesso em qualquer desses testes encerra ambos os efeitos antecipadamente.","higher":"Quando você conjura esta magia no 6º nível ou superior, pode escolher um dos efeitos a seguir para cada nível do espaço acima do 5º:\n• Você pode escolher uma criatura adicional dentro do alcance.\n• O dano de frio da magia contra seus alvos aumenta em 1d10.","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":583,"category":"Lyre's Guide to Retia","traits":["Artes Arcanas de Altissima-Cor"]},{"id":"lyre-snowball-storm","name":"Tempestade de Bolas de Neve","originalName":"Snowball Storm","level":2,"school":"Evocação","time":"1 ação","range":"27 metros","comp":"V, S, M (um pedaço de gelo ou uma pequena lasca de pedra branca)","material":"um pedaço de gelo ou uma pequena lasca de pedra branca","duration":"Instantânea","classes":"Lista especial / não especificada","ritual":false,"concentration":false,"desc":"Uma rajada de bolas de neve mágicas irrompe de um ponto à sua escolha dentro do alcance. Cada criatura em uma esfera de 1,5 metro de raio centrada nesse ponto deve realizar um teste de resistência de Destreza. Uma criatura sofre 3d6 de dano de frio em caso de falha, ou metade desse dano em caso de sucesso.","higher":"Quando você conjura esta magia no 3º nível ou superior, pode escolher um dos efeitos a seguir para cada nível do espaço acima do 2º:\n• O raio da magia aumenta em 1,5 metro.\n• O dano de frio aumenta em 1d6.\n• (3 níveis de espaço) Cada criatura que falhar no teste tem seu deslocamento reduzido à metade até o fim do próximo turno dela.","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":584,"category":"Lyre's Guide to Retia","traits":["Legado 5.19"],"sourceNote":"A fonte identifica esta entrada como uma magia Legacy/revisada da edição 5.19; suas regras foram preservadas como uma versão própria de Lyre."},{"id":"lyre-solar-implosion","name":"Implosão Solar","originalName":"Solar Implosion","level":3,"school":"Transmutação","time":"1 ação","range":"36 metros","comp":"S, M (uma luva vermelha, manopla ou algum tipo de revestimento sobre sua mão)","material":"uma luva vermelha, manopla ou algum tipo de revestimento sobre sua mão","duration":"Instantânea","classes":"Cavaleiro das Pétalas, Clérigo, Paladino, Feiticeiro","ritual":false,"concentration":false,"desc":"Você ergue a mão na direção de um ponto que possa ver dentro do alcance e a fecha em punho, provocando uma detonação gravitacional seguida de uma implosão imediata em uma esfera de 6 metros de raio centrada nesse ponto. Todas as criaturas nessa área são arremessadas para fora e então puxadas rapidamente para dentro, devendo realizar um teste de resistência de Força. Em caso de falha, uma criatura sofre 4d8 de dano de energia e fica caída. As criaturas que falharem também são puxadas 3 metros em direção ao centro da implosão, parando se colidirem com algo sólido. Criaturas que obtiverem sucesso sofrem metade do dano e não ficam caídas nem são puxadas.","higher":"Quando você conjura esta magia no 4º nível ou superior, pode escolher uma das opções a seguir para cada nível da magia acima do 3º:\n• O dano de energia aumenta em 1d8.\n• O raio da esfera aumenta em 3 metros, e a distância pela qual as criaturas são puxadas aumenta em 1,5 metro.","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":584,"category":"Lyre's Guide to Retia","traits":["Legado do Ouro"]},{"id":"lyre-somatic-lattice","name":"Malha Somática","originalName":"Somatic Lattice","level":1,"school":"Abjuração","time":"Especial","range":"Pessoal","comp":"S","material":"","duration":"Especial","classes":"Feiticeiro, Mago","ritual":false,"concentration":false,"desc":"Quando você conjura uma magia que não seja da escola de eidomancia, você reorienta sua conexão com a Teia Eidomântica e a reprograma. Você conjura esta magia ao mesmo tempo que conjura a magia-alvo. Os ataques e o dano dessa magia tornam-se eidólicos até que seus efeitos terminem. Se qualquer criatura tentar usar sua reação para anular sua magia, como por meio de contramágica ou dissipar magia, e precisar realizar um teste de atributo para isso, esse teste é feito com desvantagem. Ataques com magia realizados por você por meio da magia-alvo têm vantagem. Você não precisa realizar um teste eidomântico para esta magia, mas deve realizar um para a magia-alvo como se ela fosse eidomântica. Quando você conjura esta magia para afetar outra magia que esteja sendo conjurada no 4º nível ou superior, esta magia deve ser conjurada em um nível igual a um terço do nível da magia-alvo, arredondado para cima: 2º nível para um alvo de 4º, 5º ou 6º nível; e 3º nível para um alvo de 7º, 8º ou 9º nível.","higher":"","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":584,"category":"Lyre's Guide to Retia","traits":["Eidomancia"],"sourceNote":"Regra de grupo — Eidomancia: todo dano causado por uma magia de eidomancia é considerado dano eidólico. Após conjurar a magia, realize um teste de resistência de Constituição de CD 10 + o nível em que a magia foi conjurada + o número de turnos após o primeiro em que ela permaneceu ativa sob concentração. Se não exigir concentração, o teste é feito imediatamente após a conjuração. Em uma falha, você sofre níveis de exaustão iguais à metade do nível da magia, arredondado para baixo (mínimo 1), e não pode conjurá-la novamente por sete dias. Se a falha elevaria a exaustão a 6, ela fica em 5 e você é imediatamente reduzido a 0 pontos de vida. Se falhar em um teste de concentração para manter uma magia de eidomancia, você pode usar sua reação para rolar um d20 e usar esse resultado no lugar do d20 do teste de concentração."},{"id":"lyre-song-of-harmony","name":"Canção da Harmonia","originalName":"Song of Harmony","level":7,"school":"Evocação","time":"1 ação","range":"4,5 metros","comp":"V, S","material":"","duration":"Instantânea","classes":"Bardo","ritual":false,"concentration":false,"desc":"Uma melodia revigorante banha todas as criaturas à sua escolha dentro do alcance. Essas criaturas recuperam 8d10 pontos de vida e são curadas de qualquer exaustão ou envenenamento que as esteja afligindo. Qualquer criatura caída que receba essa cura pode usar sua reação para se levantar imediatamente. Esta magia não produz efeito em mortos-vivos ou constructos.","higher":"","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":584,"category":"Lyre's Guide to Retia","traits":["Épico da Dualidade"]},{"id":"lyre-song-of-inspiration","name":"Canção da Inspiração","originalName":"Song of Inspiration","level":2,"school":"Encantamento","time":"1 ação","range":"Pessoal (raio de 9 metros)","comp":"V, S","material":"","duration":"Concentração, até 1 minuto","classes":"Inscritor, Bardo","ritual":false,"concentration":true,"desc":"Uma melodia agradável acompanha você durante a duração da magia, protegendo aqueles ao seu redor do desespero. Todas as criaturas amigáveis a até 9 metros de você que possam ouvir a canção não podem ter desvantagem em jogadas de ataque, testes de atributo ou testes de resistência. Contudo, se algum efeito ou condição normalmente lhes concedesse desvantagem, elas também não podem obter vantagem nessa jogada.","higher":"Quando você conjura esta magia usando um espaço de 3º nível ou superior, ela afeta criaturas em mais 3 metros de alcance para cada nível do espaço acima do 2º. Se for conjurada usando um espaço de 5º nível ou superior, criaturas afetadas por esta magia podem obter vantagem mesmo quando normalmente teriam desvantagem em suas jogadas.","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":584,"category":"Lyre's Guide to Retia","traits":["Épico da Dualidade"]},{"id":"lyre-spacial-hoist","name":"Elevação Espacial","originalName":"Spacial Hoist","level":6,"school":"Conjuração","time":"1 ação","range":"90 metros","comp":"V, S, M (um laço de corda com pelo menos 3 metros de comprimento ou um chicote)","material":"um laço de corda com pelo menos 3 metros de comprimento ou um chicote","duration":"Instantânea","classes":"Feiticeiro, Mago","ritual":false,"concentration":false,"desc":"Você tenta puxar para perto de si um alvo que possa ver dentro do alcance, seja uma criatura ou um objeto Enorme ou menor. Escolha um alvo e um espaço desocupado, mais próximo de você do que o alvo, no qual ele possa caber. O alvo deve obter sucesso em um teste de resistência de Sabedoria ou será puxado para esse espaço através de um portal arcano que se abre ao lado dele. Você pode optar por agarrá-lo imediatamente caso ele seja movido para dentro do seu alcance e você seja capaz de fazê-lo. Caso contrário, se ele for elevado a mais de 3 metros acima do solo, fica suspenso no ar até o início do seu próximo turno, quando então despenca. Se o alvo estiver sendo montado por outra criatura ou estiver impedido, agarrado ou retido por outra criatura ou efeito, ele tem vantagem no teste de resistência contra esta magia.","higher":"","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":585,"category":"Lyre's Guide to Retia","traits":["Eidomancia"],"sourceNote":"Regra de grupo — Eidomancia: todo dano causado por uma magia de eidomancia é considerado dano eidólico. Após conjurar a magia, realize um teste de resistência de Constituição de CD 10 + o nível em que a magia foi conjurada + o número de turnos após o primeiro em que ela permaneceu ativa sob concentração. Se não exigir concentração, o teste é feito imediatamente após a conjuração. Em uma falha, você sofre níveis de exaustão iguais à metade do nível da magia, arredondado para baixo (mínimo 1), e não pode conjurá-la novamente por sete dias. Se a falha elevaria a exaustão a 6, ela fica em 5 e você é imediatamente reduzido a 0 pontos de vida. Se falhar em um teste de concentração para manter uma magia de eidomancia, você pode usar sua reação para rolar um d20 e usar esse resultado no lugar do d20 do teste de concentração."},{"id":"lyre-split-ranks","name":"Dividir Fileiras","originalName":"Split Ranks","level":6,"school":"Conjuração","time":"1 ação","range":"9 metros","comp":"V","material":"","duration":"Instantânea","classes":"Inscritor, Feiticeiro, Bruxo, Mago","ritual":false,"concentration":false,"desc":"O ar vibra ao redor de até cinco criaturas à sua escolha que você possa ver dentro do alcance. Você teletransporta cada alvo afetado para um espaço desocupado que esteja sobre o chão ou uma superfície e que você possa ver a até 36 metros de você. Uma criatura involuntária deve obter sucesso em um teste de resistência de Sabedoria para resistir a esta magia.","higher":"Quando você conjura esta magia usando um espaço de 7º nível ou superior, pode escolher um dos efeitos a seguir para cada nível do espaço acima do 6º:\n• O alcance da magia aumenta em 9 metros.\n• Os alvos podem ser movidos para um espaço a até 18 metros adicionais que você possa ver.\n• Você pode escolher até três alvos adicionais.","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":585,"category":"Lyre's Guide to Retia","traits":["Épico da Dualidade","Legado 5.19"],"sourceNote":"A fonte identifica esta entrada como uma magia Legacy/revisada da edição 5.19; suas regras foram preservadas como uma versão própria de Lyre."},{"id":"lyre-springmoons-holy-shield","name":"Escudo Sagrado de Springmoon","originalName":"Springmoon’s Holy Shield","level":7,"school":"Abjuração","time":"1 ação bônus","range":"Pessoal","comp":"V, S","material":"","duration":"Concentração, até 1 minuto","classes":"Clérigo, Bruxo","ritual":false,"concentration":true,"desc":"Você produz os efeitos de uma barreira sagrada que o protege quando é atacado. Você recebe resistência a todo dano durante a duração da magia e, quando realiza um teste de resistência, pode usar sua reação para rolar um d20 adicional e escolher qual resultado manter entre a rolagem original e a nova.","higher":"","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":585,"category":"Lyre's Guide to Retia","traits":["Grimório do Espreitador"]},{"id":"lyre-starfall-mantle","name":"Manto da Queda Estelar","originalName":"Starfall Mantle","level":7,"school":"Evocação","time":"1 ação","range":"Pessoal","comp":"V, S","material":"","duration":"1 hora","classes":"Inscritor, Feiticeiro, Bruxo, Mago","ritual":false,"concentration":false,"desc":"Sete motes de luz semelhantes a estrelas aparecem e orbitam você até a magia terminar. Você pode usar uma ação bônus para enviar um dos motes em direção a uma criatura ou objeto a até 36 metros de você. Ao fazê-lo, realize um ataque à distância com magia. Em um acerto, o alvo sofre 4d12 de dano radiante. Acertando ou errando, o mote é gasto. A magia termina antecipadamente se você gastar o último mote. Se quatro ou mais motes permanecerem, eles emitem luz plena em um raio de 9 metros e meia-luz por mais 9 metros. Se restarem de um a três motes, eles emitem meia-luz em um raio de 9 metros. Quando uma criatura atingir você com um ataque corpo a corpo a até 1,5 metro, você pode obrigá-la a realizar um teste de resistência de Destreza. Em caso de falha, você pode tratá-la como se tivesse sido atingida por um dos motes, gastando um mote no processo.","higher":"Quando você conjura esta magia usando um espaço de 8º nível ou superior, pode escolher um dos efeitos a seguir para cada nível do espaço acima do 7º:\n• O número de motes aumenta em dois.\n• O dano de cada mote aumenta em 1d12.\n• Sempre que um mote atingir uma criatura, ela deve obter sucesso em um teste de resistência de Constituição ou fica cega até o fim do próximo turno dela.\n• Você pode lançar um mote adicional sempre que usar sua ação bônus para disparar um. Eles devem ter criaturas diferentes como alvo e cada um exige sua própria jogada de ataque à distância com magia.","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":585,"category":"Lyre's Guide to Retia","traits":["Legado 5.19"],"sourceNote":"A fonte identifica esta entrada como uma magia Legacy/revisada da edição 5.19; suas regras foram preservadas como uma versão própria de Lyre."},{"id":"lyre-sunlight-crest","name":"Brasão da Luz Solar","originalName":"Sunlight Crest","level":5,"school":"Evocação","time":"1 ação","range":"18 metros","comp":"V, S, M (um pingente em forma de explosão solar no valor de pelo menos 100 po)","material":"um pingente em forma de explosão solar no valor de pelo menos 100 po","duration":"Concentração, até 1 minuto","classes":"Alma Favorecida, Clérigo, Paladino, Mago","ritual":false,"concentration":true,"desc":"A luz da alvorada brilha sobre um local que você especifica dentro do alcance. Até a magia terminar, um cilindro de luz plena com 9 metros de raio e 12 metros de altura reluz nesse local. Essa luz é luz solar. Quando o cilindro aparece, cada criatura dentro dele deve realizar um teste de resistência de Constituição, sofrendo 4d10 de dano radiante em caso de falha ou metade desse dano em caso de sucesso. Uma criatura também deve realizar esse teste sempre que terminar seu turno dentro do cilindro. Se você estiver a até 18 metros do cilindro, pode movê-lo até 18 metros como uma ação bônus no seu turno.","higher":"Quando você conjura esta magia usando um espaço de 5º nível ou superior, pode escolher um dos efeitos a seguir para cada nível do espaço acima do 5º, conforme apresentado na fonte:\n• O raio e a altura do cilindro aumentam em 1,5 metro e 3 metros, respectivamente.\n• O dano radiante aumenta em 1d10.\n• Você pode optar por disparar o efeito da magia em um cone de luz solar originado em você, com comprimento igual ao dobro da altura do cilindro. Criaturas no alcance realizam o teste imediatamente, sofrendo o dobro de dados de dano radiante em caso de falha ou metade disso em caso de sucesso. O efeito então termina.","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":586,"category":"Lyre's Guide to Retia","traits":["Legado 5.19","Legado do Ouro"],"sourceNote":"A fonte identifica esta entrada como uma magia Legacy/revisada da edição 5.19; suas regras foram preservadas como uma versão própria de Lyre."},{"id":"lyre-supreme-hand","name":"Mão Suprema","originalName":"Supreme Hand","level":5,"school":"Evocação","time":"1 ação","range":"36 metros","comp":"V, S, M (uma casca de ovo e uma luva de pele de cobra)","material":"uma casca de ovo e uma luva de pele de cobra","duration":"Concentração, até 1 minuto","classes":"Feiticeiro, Mago","ritual":false,"concentration":true,"desc":"Você cria uma mão Grande de energia cintilante e translúcida em um espaço desocupado que possa ver dentro do alcance. A mão permanece pela duração e se move sob seu comando, imitando os movimentos da sua própria mão. A mão é um objeto com CA 20 e pontos de vida iguais ao seu máximo de pontos de vida. Se cair a 0 pontos de vida, a magia termina. Ela possui Força 26 (+8) e Destreza 10 (+0).\nA mão não ocupa seu espaço. Quando você conjura a magia e, nos turnos seguintes, como uma ação bônus, pode mover a mão até 18 metros e então provocar um dos efeitos a seguir.\nPunho Cerrado. A mão golpeia uma criatura ou objeto a até 1,5 metro dela. Faça um ataque corpo a corpo com magia para a mão usando suas estatísticas de jogo. Em um acerto, o alvo sofre 4d8 de dano de energia.\nMão Poderosa. A mão tenta empurrar uma criatura a até 1,5 metro dela em uma direção à sua escolha. Faça um teste de Força da mão, resistido por um teste de Força (Atletismo) do alvo. Se o alvo for Médio ou menor, você tem vantagem no teste. Se vencer, a mão empurra o alvo até 1,5 metro mais uma quantidade de metros igual a 1,5 vez o seu modificador do atributo de conjuração. A mão se move com o alvo para permanecer a até 1,5 metro dele.\nMão Agarradora. A mão tenta agarrar uma criatura Enorme ou menor a até 1,5 metro dela. Você usa o valor de Força da mão para resolver o agarrão. Se o alvo for Médio ou menor, você tem vantagem no teste. Enquanto a mão estiver agarrando o alvo, você pode usar uma ação bônus para fazê-la esmagá-lo. Ao fazer isso, o alvo sofre dano de concussão igual a 2d6 + seu modificador do atributo de conjuração.\nMão Interposta. A mão se coloca entre você e uma criatura à sua escolha até você dar um comando diferente. Ela se move para permanecer entre você e o alvo, concedendo meia cobertura contra essa criatura. O alvo não pode atravessar o espaço da mão se o valor de Força dele for menor ou igual ao da mão. Se for maior, o alvo pode se mover em sua direção através do espaço da mão, mas esse espaço é terreno difícil para ele.","higher":"Quando você conjura esta magia usando um espaço de 6º nível ou superior, o dano da opção Punho Cerrado aumenta em 2d8 e o dano da Mão Agarradora aumenta em 2d6 para cada nível do espaço acima do 5º.","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":586,"category":"Lyre's Guide to Retia","traits":["Legado 5.19"],"sourceNote":"A fonte identifica esta entrada como uma magia Legacy/revisada da edição 5.19; suas regras foram preservadas como uma versão própria de Lyre."},{"id":"lyre-sword-of-the-archmage","name":"Espada do Arquimago","originalName":"Sword of the Archmage","level":7,"school":"Evocação","time":"1 ação","range":"18 metros","comp":"V, S, M (uma espada de platina em miniatura com empunhadura e pomo de cobre e zinco, no valor de 250 po)","material":"uma espada de platina em miniatura com empunhadura e pomo de cobre e zinco, no valor de 250 po","duration":"Concentração, até 1 minuto","classes":"Bardo, Mago","ritual":false,"concentration":true,"desc":"Você cria um plano de energia em forma de espada que paira dentro do alcance. Ele permanece pela duração. Quando a espada aparece, você realiza dois ataques corpo a corpo com magia contra um alvo à sua escolha a até 1,5 metro da espada. Em um acerto, o alvo sofre 2d10 de dano de energia mais metade do seu nível, arredondado para baixo, considerando a classe pela qual você aprendeu esta magia. Nos turnos subsequentes, até a magia terminar, você pode usar uma ação bônus em cada um dos seus turnos para mover a espada até 9 metros para um ponto que possa ver e realizar dois ataques com ela, conforme descrito acima. Você pode abrir mão de um desses ataques para fazê-la se mover até 9 metros adicionais e realizar o ataque restante com vantagem. Sempre que fizer a espada atacar um alvo, todos os ataques dela naquele turno devem ser contra esse mesmo alvo. Quando uma criatura entrar em um espaço a até 1,5 metro da espada ou sair de um desses espaços, você pode usar sua reação para realizar, com a espada, um ataque de oportunidade contra essa criatura conforme descrito acima.","higher":"","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":586,"category":"Lyre's Guide to Retia","traits":["Legado 5.19","Memórias de Ossenheimer"],"sourceNote":"A fonte identifica esta entrada como uma magia Legacy/revisada da edição 5.19; suas regras foram preservadas como uma versão própria de Lyre."},{"id":"lyre-synchral-disjunction","name":"Disjunção Sincral","originalName":"Synchral Disjunction","level":9,"school":"Abjuração","time":"1 ação","range":"9 metros","comp":"V","material":"","duration":"24 horas","classes":"Inscritor, Mago","ritual":false,"concentration":false,"desc":"Um alvo à sua escolha dentro do alcance é assolado por energia mágica que reduz seus itens mágicos aos componentes mais básicos. O alvo deve realizar um teste de resistência de Carisma. Em caso de falha, todos os itens mágicos que esteja carregando ou com os quais esteja sintonizado tornam-se mundanos e perdem suas propriedades mágicas por 24 horas, e todas as magias das quais esteja se beneficiando ou nas quais esteja se concentrando terminam. Se qualquer item em posse do alvo for um artefato ou tiver raridade lendária, ele tem vantagem no teste de resistência e pode repeti-lo no início de cada um de seus turnos. Em caso de sucesso, esses itens específicos recuperam suas propriedades mágicas. Esta magia pode ser conjurada mesmo dentro de um campo antimagia ou efeito semelhante que suprima magia; se for, o alvo tem vantagem no teste de resistência.","higher":"","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":587,"category":"Lyre's Guide to Retia","traits":["Memórias de Ossenheimer"]},{"id":"lyre-system-flush","name":"Purga do Sistema","originalName":"System Flush","level":1,"school":"Abjuração","time":"1 ação","range":"9 metros","comp":"M (um kit de curandeiro ou item que restaure pontos de vida ao ser usado, do qual a magia consome um uso)","material":"um kit de curandeiro ou item que restaure pontos de vida ao ser usado, do qual a magia consome um uso","duration":"Instantânea","classes":"Patrulheiro, Clérigo, Druida, Paladino","ritual":false,"concentration":false,"desc":"Escolha uma criatura dentro do alcance que esteja sofrendo os efeitos de estar envenenada ou doente. Um desses efeitos termina, incluindo quaisquer outros efeitos que estejam causando essa condição. A criatura recebe 1d8 pontos de vida temporários, que perde após 1 minuto.","higher":"Quando você conjura esta magia no 2º nível ou superior, pode escolher um dos efeitos a seguir para cada nível do espaço acima do 1º:\n• Escolha uma criatura adicional dentro do alcance como alvo.\n• Um efeito adicional termina sobre o alvo ou alvos.\n• A criatura recebe 1d8 pontos de vida temporários adicionais.","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":587,"category":"Lyre's Guide to Retia","traits":[]},{"id":"lyre-tamamos-arrowfall","name":"Chuva de Flechas de Tamamo","originalName":"Tamamo’s Arrowfall","level":4,"school":"Conjuração","time":"1 ação","range":"Pessoal","comp":"V, S","material":"","duration":"Não informada no PDF","classes":"Cavaleiro das Pétalas, Bardo, Druida, Feiticeiro, Bruxo","ritual":false,"concentration":false,"desc":"Você conjura uma série de projéteis de energia que flutuam ao seu redor em um padrão circular. Como uma ação bônus em cada um de seus turnos, você pode comandar até três grupos desses projéteis para assumirem um tipo específico de energia e dispará-los contra alvos que você possa ver a até 18 metros de você, cada grupo realizando um ataque à distância com magia separado. Vários grupos podem atacar o mesmo alvo no mesmo turno, mas continuam sendo ataques distintos. Cada grupo que atingir causa 2d10 de dano do tipo de energia escolhido. Quando dispara os grupos, você deve escolher um dos seguintes tipos de dano, que todos os projéteis assumem: fogo, elétrico, frio, ácido ou trovejante. Você pode mudar o tipo de dano a cada vez que disparar os grupos.","higher":"Quando você conjura esta magia usando um espaço de 5º nível ou superior, pode disparar um grupo adicional a cada turno para cada nível do espaço acima do 4º.","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":587,"category":"Lyre's Guide to Retia","traits":["Grimório do Espreitador"],"sourceNote":"A duração não é informada no bloco da magia no PDF fornecido; o Grimório preserva essa ausência em vez de presumir um valor."},{"id":"lyre-telepathic-bond","name":"Vínculo Telepático","originalName":"Telepathic Bond","level":5,"school":"Adivinhação","time":"1 ação","range":"9 metros","comp":"V, S, M (pedaços de casca de ovo de dois tipos diferentes de criaturas)","material":"pedaços de casca de ovo de dois tipos diferentes de criaturas","duration":"1 hora","classes":"Alma Favorecida, Inscritor, Bardo, Mago","ritual":true,"concentration":false,"desc":"Você forja uma ligação telepática entre até oito criaturas voluntárias à sua escolha dentro do alcance, conectando psiquicamente cada criatura a todas as outras pela duração. Criaturas com Inteligência 2 ou menor não são afetadas por esta magia. Até a magia terminar, os alvos podem se comunicar telepaticamente através do vínculo, tenham ou não um idioma em comum. A comunicação é possível a qualquer distância, embora não possa se estender a outros planos de existência.","higher":"","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":587,"category":"Lyre's Guide to Retia","traits":["Legado 5.19","Ritual"],"sourceNote":"A fonte identifica esta entrada como uma magia Legacy/revisada da edição 5.19; suas regras foram preservadas como uma versão própria de Lyre."},{"id":"lyre-telepathic-cord","name":"Cordão Telepático","originalName":"Telepathic Cord","level":8,"school":"Evocação","time":"1 ação","range":"Ilimitado","comp":"V, S, M (um par de anéis de prata interligados)","material":"um par de anéis de prata interligados","duration":"24 horas","classes":"Inscritor, Mago","ritual":false,"concentration":false,"desc":"Você cria uma ligação telepática entre você e uma criatura voluntária com a qual esteja familiarizado. A criatura pode estar em qualquer lugar no mesmo plano de existência que você. A magia termina se você ou o alvo deixarem de estar no mesmo plano. Até a magia terminar, você e o alvo podem compartilhar instantaneamente palavras, imagens, sons e outras mensagens sensoriais um com o outro através da ligação, e o alvo reconhece você como a criatura com a qual está se comunicando. A magia permite que uma criatura com Inteligência de pelo menos 1 compreenda o significado das suas palavras e assimile o conteúdo das mensagens sensoriais que você enviar.","higher":"","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":587,"category":"Lyre's Guide to Retia","traits":["Legado 5.19"],"sourceNote":"A fonte identifica esta entrada como uma magia Legacy/revisada da edição 5.19; suas regras foram preservadas como uma versão própria de Lyre."},{"id":"lyre-therpientis-stunning-mimicry","name":"Mimetismo Atordoante de Therpientis","originalName":"Therpientis’ Stunning Mimicry","level":5,"school":"Ilusão","time":"1 ação","range":"9 metros","comp":"V, S","material":"","duration":"Concentração, até 1 minuto","classes":"Lista especial / não especificada","ritual":false,"concentration":true,"desc":"Você escolhe uma criatura dentro do alcance da magia, que deve realizar um teste de resistência de Inteligência. Em caso de falha, ela esquece brevemente sua aparência e características exatas e começa a alucinar, vendo dezenas de outras versões de você espalhadas pela área, todas com pequenas variações de aparência. Durante a duração da magia, ela tem desvantagem em todos os ataques que realizar contra você e não pode, voluntariamente, escolher você como alvo de ataques à distância, magias ou efeitos especiais que não exijam um ataque corpo a corpo. Na primeira vez em cada turno em que você a obrigar a realizar um teste de resistência ou a atingir com um ataque, ela pode repetir o teste de Inteligência, encerrando o efeito em caso de sucesso.","higher":"","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":587,"category":"Lyre's Guide to Retia","traits":[]},{"id":"lyre-thought-shard","name":"Fragmento de Pensamento","originalName":"Thought Shard","level":0,"school":"Encantamento","time":"1 ação","range":"Pessoal","comp":"S","material":"","duration":"Até 8 horas","classes":"Inscritor, Feiticeiro, Mago","ritual":false,"concentration":false,"desc":"Colocando um dedo na cabeça, você retira de sua mente uma memória, ideia ou mensagem e a transforma em um fio tangível de energia luminosa chamado fragmento de pensamento, que persiste pela duração ou até você conjurar esta magia novamente. O fragmento aparece em um espaço desocupado a até 1,5 metro de você como um objeto Minúsculo, sem peso e semissólido, que pode ser segurado e transportado como uma fita; caso contrário, permanece estacionário. Como alternativa, você pode imbuir o fragmento em um objeto Pequeno ou Minúsculo, onde ele permanece pela duração. Se você conjurar esta magia enquanto se concentra em uma magia ou habilidade que lhe permita ler ou manipular os pensamentos de outros, como detectar pensamentos ou modificar memória, pode transformar os pensamentos ou memórias que leu, em vez dos seus próprios, em um fragmento de pensamento. Conjurar esta magia enquanto segura um fragmento permite que você receba instantaneamente qualquer memória, ideia ou mensagem contida nele; conjurar detectar pensamentos sobre o fragmento produz o mesmo efeito. Como alternativa, uma criatura que saiba que se trata de um fragmento de pensamento, enquanto estiver em contato com ele, pode tentar um teste de Arcanismo com CD igual à sua CD de magia e, em caso de sucesso, ler seu conteúdo.","higher":"","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":588,"category":"Lyre's Guide to Retia","traits":["Legado 5.19"],"sourceNote":"A fonte identifica esta entrada como uma magia Legacy/revisada da edição 5.19; suas regras foram preservadas como uma versão própria de Lyre."},{"id":"lyre-throes-of-mortality","name":"Agonias da Mortalidade","originalName":"Throes of Mortality","level":3,"school":"Necromancia","time":"1 ação","range":"18 metros","comp":"V, S, M (anéis de vidro presos em uma corrente de ferro, cada anel no valor de pelo menos 50 po; a magia consome um anel para cada alvo afetado)","material":"anéis de vidro presos em uma corrente de ferro, cada anel no valor de pelo menos 50 po; a magia consome um anel para cada alvo afetado","duration":"1 hora","classes":"Bruxo","ritual":false,"concentration":false,"desc":"Escolha até cinco criaturas que você possa ver dentro do alcance. Cada uma deve realizar um teste de resistência de Carisma. Um anel retorcido de glifos aparece ao redor do pescoço e da testa de qualquer criatura que falhar, causando dor intensa durante a duração da magia; enquanto isso, ela está amaldiçoada. Enquanto amaldiçoada por esses glifos, qualquer cura que a criatura receber é reduzida à metade, arredondada para baixo. Se possuir imunidade ou resistência a qualquer tipo de energia cromática, imunidades tornam-se resistências e resistências são ignoradas, respectivamente, durante a duração da magia. Criaturas que iniciarem o turno sob os efeitos desta magia sofrem 1d6 de dano psíquico. Se a criatura que conjurou esta magia for reduzida a 0 pontos de vida ou ficar inconsciente, a magia termina imediatamente. Além disso, se uma criatura amaldiçoada por esta magia for reduzida a 0 pontos de vida, ela falha imediatamente em um teste de resistência contra a morte e, então, os efeitos da magia terminam sobre ela.","higher":"Quando esta magia é conjurada no 4º nível ou superior, ela recebe um dos efeitos a seguir para cada nível do espaço acima do 3º:\n• O alcance da magia dobra.\n• A magia pode ter uma criatura adicional como alvo.\n• (2 níveis de espaço) O dano psíquico da magia aumenta em 1d6.","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":588,"category":"Lyre's Guide to Retia","traits":["Convocação Cromática"],"sourceNote":"Regra de grupo — Convocação Cromática: quando a magia mencionar energia ou dano cromático, escolha fogo, frio, ácido, elétrico ou veneno; a escolha vale para todas as ocorrências daquela invocação. Ao conjurar uma magia da Convocação Cromática, faça um teste com o atributo de conjuração (CD 10 + nível da magia). Em uma falha, seu máximo de pontos de vida é reduzido em duas vezes o nível da magia até concluir um Descanso Longo; a fonte chama esse efeito de Queima da Alma. A característica de conjuração da criatura pode dispensá-la desse teste."},{"id":"lyre-throw-image","name":"Arremessar Imagem","originalName":"Throw Image","level":2,"school":"Ilusão","time":"Especial","range":"36 metros","comp":"Especial","material":"","duration":"Especial","classes":"Inscritor, Bardo, Clérigo, Feiticeiro, Mago","ritual":false,"concentration":false,"desc":"Quando você conjura outra magia, pode optar por conjurar esta magia sobre ela ao mesmo tempo. Ao fazê-lo, uma projeção sua aparece em um espaço desocupado que você possa ver dentro do alcance desta magia e pode agir como o conjurador da outra magia para determinar seu alcance e seus efeitos. Se a magia normalmente afetaria a área ao seu redor, ela passa a ser centrada na projeção. Se possuir alcance, esse alcance é medido como se tivesse origem na projeção. Seus sentidos não são projetados nela; portanto, se a magia exigir linha de visão ou que você veja os espaços escolhidos, você ainda deve ser capaz de vê-los. No início do seu próximo turno, a projeção desaparece e a magia volta a considerar você como conjurador ou centro de seus efeitos. Se ela não puder continuar devido à sua nova proximidade em relação aos efeitos, eles terminam. Se você estiver consciente, mas incapaz de realizar componentes somáticos, pode usar esta magia para fazer a projeção realizar os componentes verbais e/ou somáticos da outra magia em seu lugar.","higher":"","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":588,"category":"Lyre's Guide to Retia","traits":["Épico da Dualidade"]},{"id":"lyre-thunder-spiral","name":"Espiral Trovejante","originalName":"Thunder Spiral","level":4,"school":"Evocação","time":"1 ação","range":"Pessoal (cone de 18 metros)","comp":"V, S, M (um espelho de mão rachado)","material":"um espelho de mão rachado","duration":"Instantânea","classes":"Alma Favorecida, Bardo, Feiticeiro, Mago","ritual":false,"concentration":false,"desc":"Uma onda de som trovejante irrompe de suas mãos e reverbera para a frente em um cone de 18 metros. Cada criatura na área deve realizar um teste de resistência de Constituição. Em caso de falha, sofre 6d10 de dano trovejante; em caso de sucesso, sofre metade desse dano. Uma criatura que falhar também fica caída.","higher":"Quando você conjura esta magia no 5º nível ou superior, o dano aumenta em 1d8 para cada nível do espaço acima do 4º.","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":588,"category":"Lyre's Guide to Retia","traits":[]},{"id":"lyre-thunderous-leap","name":"Salto Trovejante","originalName":"Thunderous Leap","level":3,"school":"Conjuração","time":"1 ação","range":"27 metros","comp":"V","material":"","duration":"Instantânea","classes":"Cavaleiro das Pétalas, Feiticeiro, Bruxo, Mago","ritual":false,"concentration":false,"desc":"Você se teletransporta para um espaço desocupado que possa ver dentro do alcance. Imediatamente depois de desaparecer, um estrondo trovejante ressoa, e cada criatura a até 3 metros do espaço que você deixou deve realizar um teste de resistência de Constituição, sofrendo 3d10 de dano trovejante em caso de falha ou metade em caso de sucesso. O trovão pode ser ouvido a até 90 metros de distância. Você pode levar objetos desde que o peso deles não exceda sua capacidade de carga. Também pode teletransportar uma criatura voluntária do seu tamanho ou menor, carregando equipamento até a capacidade de carga dela. Essa criatura deve estar a até 1,5 metro de você quando a magia for conjurada, e deve haver um espaço desocupado a até 1,5 metro do seu destino para ela aparecer. Caso contrário, ela fica para trás.","higher":"Quando você conjura esta magia usando um espaço de 4º nível ou superior, pode escolher um dos efeitos a seguir para cada nível do espaço acima do 3º:\n• O dano aumenta em 1d10.\n• O alcance da magia aumenta em 12 metros.\n• A distância na qual uma criatura pode ser escolhida para acompanhá-lo, a distância na qual ela pode ser depositada e o raio em que criaturas podem sofrer dano aumentam todos em 1,5 metro.","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":588,"category":"Lyre's Guide to Retia","traits":["Legado 5.19"],"sourceNote":"A fonte identifica esta entrada como uma magia Legacy/revisada da edição 5.19; suas regras foram preservadas como uma versão própria de Lyre."},{"id":"lyre-tormented-scream","name":"Grito Atormentado","originalName":"Tormented Scream","level":9,"school":"Encantamento","time":"1 ação","range":"27 metros","comp":"S","material":"","duration":"Instantânea","classes":"Inscritor, Bardo, Feiticeiro, Bruxo, Mago","ritual":false,"concentration":false,"desc":"Você libera o poder da sua mente para devastar o intelecto de até dez criaturas à sua escolha que possa ver dentro do alcance. Criaturas com Inteligência 2 ou menor não são afetadas. Cada alvo deve realizar um teste de resistência de Inteligência. Em caso de falha, sofre 14d6 de dano psíquico e fica atordoado. Em caso de sucesso, sofre metade do dano e não fica atordoado. Se um alvo morrer por esse dano, sua cabeça explode, supondo que possua uma. Um alvo atordoado pode realizar um teste de resistência de Inteligência ao final de cada um de seus turnos, encerrando o atordoamento em caso de sucesso. Você pode concentrar este efeito em uma única criatura que possa tocar, tornando-a o único alvo. Toda a força da magia é despejada apenas na mente dela e, se falhar no teste, ela sofre 20d6 de dano psíquico em vez disso. Os demais efeitos permanecem iguais.","higher":"","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":589,"category":"Lyre's Guide to Retia","traits":["Legado 5.19"],"sourceNote":"A fonte identifica esta entrada como uma magia Legacy/revisada da edição 5.19; suas regras foram preservadas como uma versão própria de Lyre."},{"id":"lyre-transfer-vice","name":"Transferir Vício","originalName":"Transfer Vice","level":1,"school":"Necromancia","time":"1 reação, realizada quando uma criatura é morta","range":"36 metros","comp":"V, S, M (uma estatueta de vime)","material":"uma estatueta de vime","duration":"Instantânea","classes":"Inscritor, Cavaleiro das Pétalas, Clérigo, Druida, Feiticeiro, Bruxo, Mago","ritual":false,"concentration":false,"desc":"Quando uma criatura dentro do alcance é morta ou reduzida a 0 pontos de vida enquanto sofre um efeito prejudicial, como estar envenenada ou sofrer dano contínuo de uma magia, você pode escolher outra criatura dentro do alcance e tentar transferir esses efeitos para ela. O novo alvo deve realizar um teste de resistência de Carisma. Em caso de falha, todos os efeitos prejudiciais que você escolher do primeiro alvo são transferidos para o segundo, inclusive suas durações restantes. Efeitos de duração indefinida capazes de durar mais de 1 hora não podem ser transferidos dessa forma, nem efeitos incapazes de afetar a nova criatura.","higher":"Se você conjurar esta magia usando um espaço de 3º nível ou superior, os efeitos são copiados em vez de transferidos, e ambas as criaturas continuam sofrendo-os. Se algum efeito exigir concentração de outra criatura ou puder afetar apenas uma criatura por vez, você deve escolher qual delas é afetada.","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":589,"category":"Lyre's Guide to Retia","traits":["Daemoturgia"]},{"id":"lyre-treaties-hellgate","name":"Portal Infernal de Treaties","originalName":"Treaties’ Hellgate","level":9,"school":"Evocação","time":"1 ação","range":"esfera de 36 metros de raio","comp":"V, S, M (um item forjado no quarto círculo do inferno)","material":"um item forjado no quarto círculo do inferno","duration":"Concentração, até 10 minutos","classes":"Inscritor, Feiticeiro, Bruxo","ritual":false,"concentration":true,"desc":"Você é imune a qualquer efeito produzido por esta magia que exija teste de resistência ou teste de atributo. A área dentro do alcance da magia, centrada em você, é brevemente exposta às condições do quarto círculo do inferno. Cada criatura nessa área que não seja imune a dano de fogo deve realizar um teste de resistência de Constituição quando você conjura esta magia, sofrendo um nível de exaustão e 5d10 de dano de fogo em caso de falha. Depois disso, a magia produz os efeitos a seguir.\nAr Ardente. Durante a duração da magia, sempre que uma criatura começar seu turno na área, deve realizar outro teste de resistência de Constituição, sofrendo 3d10 de dano de fogo e 1 ponto de Fadiga de Combate em caso de falha; esse dano aumenta para 5d10 se ela iniciar o turno a até 3 metros de você. Se falhar por 10 pontos ou mais, sofre um nível de exaustão em vez de Fadiga de Combate.\nExpansão do Domínio. Ao final de cada um dos seus turnos, os efeitos e o alcance desta magia se expandem mais 18 metros em todas as direções.\nAura de Fogo Infernal. Enquanto a magia estiver ativa, seus ataques com arma causam 2d12 de dano de fogo adicional, e o dano de fogo que você causar não pode ser reduzido por resistências nem por efeitos de magia. Você causa esse dano adicional mesmo que deixe o alcance da magia.\nEvaporação Instantânea. Dentro do alcance da magia, todo dano de frio é reduzido a 0 e todos os líquidos, inclusive congelados, expostos ao ar livre evaporam instantaneamente sem efeito. Quando uma criatura tenta beber uma poção ou aplicar um unguento ou bálsamo, deve obter sucesso em um teste de Destreza contra sua CD de magia; em caso de falha, aplica-o devagar demais e ele queima sem produzir efeito.\nAssassina da Natureza. Plantas e gosmas têm desvantagem em todos os testes de resistência realizados contra os efeitos desta magia. Toda fauna e flora não mágicas com menos de 30 pontos de vida dentro do alcance morrem imediatamente quando a magia é conjurada, ou você pode optar por fazê-las falhar em um teste de resistência contra ela. Efeitos de magia que produzam madeira ou plantas, como emaranhar, terminam imediatamente dentro do alcance, a menos que tenham sido produzidos por um espaço de 6º nível ou superior.\nFardo Final. Quando esta magia termina, você pode usar sua reação para concentrar suas energias em uma única explosão de poder demoníaco, centrada em um alvo dentro do alcance. A criatura deve realizar um teste de resistência de Destreza, sofrendo 10d8 de dano de fogo e 10d8 de dano de veneno em caso de falha, ou metade em caso de sucesso. Você também pode encerrar a magia antecipadamente para usar esse efeito como uma ação bônus. Se for reduzido a 0 pontos de vida, mas não morrer instantaneamente, pode usar este efeito antes de ficar inconsciente.","higher":"","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":589,"category":"Lyre's Guide to Retia","traits":["Daemoturgia","Eidomancia"],"sourceNote":"Regra de grupo — Eidomancia: todo dano causado por uma magia de eidomancia é considerado dano eidólico. Após conjurar a magia, realize um teste de resistência de Constituição de CD 10 + o nível em que a magia foi conjurada + o número de turnos após o primeiro em que ela permaneceu ativa sob concentração. Se não exigir concentração, o teste é feito imediatamente após a conjuração. Em uma falha, você sofre níveis de exaustão iguais à metade do nível da magia, arredondado para baixo (mínimo 1), e não pode conjurá-la novamente por sete dias. Se a falha elevaria a exaustão a 6, ela fica em 5 e você é imediatamente reduzido a 0 pontos de vida. Se falhar em um teste de concentração para manter uma magia de eidomancia, você pode usar sua reação para rolar um d20 e usar esse resultado no lugar do d20 do teste de concentração."},{"id":"lyre-trudging-circle","name":"Círculo Penoso","originalName":"Trudging Circle","level":4,"school":"Abjuração","time":"1 ação","range":"Pessoal","comp":"V, S, M (um relógio de mão)","material":"um relógio de mão","duration":"Concentração, até 1 minuto","classes":"Cavaleiro das Pétalas, Bardo, Feiticeiro, Mago","ritual":false,"concentration":true,"desc":"Você cria um campo de energia mágica que absorve efeitos que aumentariam o deslocamento das criaturas dentro dele. O campo é uma esfera de 15 metros de raio centrada em você e se move com você. Qualquer criatura dentro dele, inclusive você, que tente realizar a ação Disparada deve obter sucesso em um teste de resistência de Carisma; caso contrário, não recebe deslocamento adicional por realizá-la. Todos os efeitos que aumentam o deslocamento-base das criaturas falham e não produzem efeito dentro desse raio.","higher":"Quando você conjura esta magia usando um espaço de 7º nível ou superior, pode escolher livremente quem é afetado pelo campo. Se for conjurada no 9º nível, o deslocamento de todas as criaturas dentro dele, exceto as que você excluir, é reduzido a 3 metros, e nenhuma criatura pode realizar a ação Disparada.","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":590,"category":"Lyre's Guide to Retia","traits":["Daemoturgia"]},{"id":"lyre-true-strike","name":"Ataque Certeiro","originalName":"True Strike","level":0,"school":"Adivinhação","time":"1 ação bônus","range":"9 metros","comp":"S","material":"","duration":"Concentração, até 1 minuto","classes":"Inscritor, Bardo, Feiticeiro, Bruxo, Mago","ritual":false,"concentration":true,"desc":"Você estende a mão e aponta para um alvo dentro do alcance, que deve realizar um teste de resistência de Carisma. Em caso de falha, você identifica uma abertura que pode explorar e escolhe mais uma criatura dentro do alcance, podendo escolher a si mesmo. Até que a segunda criatura atinja o alvo primário, ela tem vantagem nas jogadas de ataque contra ele; depois do acerto, a magia termina.\nAprimoramento de Truque. Conforme você sobe de nível, pode escolher criaturas secundárias adicionais para se beneficiarem desta magia, e o efeito termina para todas elas quando qualquer uma acertar. Você pode escolher duas criaturas secundárias no 5º nível, três no 11º e quatro no 17º.","higher":"","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":590,"category":"Lyre's Guide to Retia","traits":["Legado 5.19"],"sourceNote":"A fonte identifica esta entrada como uma magia Legacy/revisada da edição 5.19; suas regras foram preservadas como uma versão própria de Lyre."},{"id":"lyre-tunnel-knot","name":"Nó de Túnel","originalName":"Tunnel Knot","level":5,"school":"Transmutação","time":"1 ação","range":"9 metros","comp":"V, S, M (uma pena de escrever com ponta de diamante, no valor de pelo menos 1.000 po)","material":"uma pena de escrever com ponta de diamante, no valor de pelo menos 1.000 po","duration":"Concentração, até 1 rodada","classes":"Cavaleiro das Pétalas, Druida, Mago","ritual":false,"concentration":true,"desc":"Uma seção de parede com 30 centímetros de espessura fecha uma passagem formada por materiais não mágicos e inanimados; ela emerge das paredes de ambos os lados e forma uma nova parede. Todos os cantos da parede que você cria devem estar dentro do alcance da magia. Essa nova parede leva 1 rodada para se formar, concluindo o processo no início do seu próximo turno. Se sua concentração for quebrada durante esse tempo, o efeito não se estabelece. Criaturas no espaço da parede quando ela termina de se formar são deslocadas para um lado ou outro; porém, se forem maiores que a parede, a magia falha e a parede não se forma ao redor delas. Uma vez criada, a parede possui a durabilidade do material do qual é feita, resistência a todo dano exceto aquele causado por armas de cerco e CA igual à sua CD de magia, a menos que já fosse maior. A seção inteira possui 5d10 pontos de vida e, quando reduzida a 0, desmorona por completo. Se for feita de material quebradiço ou instável, como neve, gelo ou terra, possui metade dos pontos de vida e nenhuma resistência a dano. A parede pode ter até 3 metros de largura e 3 metros de altura, preenchendo a passagem na qual é criada. Após 1 hora ela desmorona por conta própria, e você não pode criar uma segunda parede com esta magia a menos de 9 metros de outra sem que o material da primeira seja puxado para formar a segunda.","higher":"Quando você conjura esta magia no 6º nível ou superior, as dimensões horizontal e vertical máximas da parede podem ser dobradas para cada nível do espaço acima do 5º, caso haja espaço suficiente; sua espessura dobra a cada dois níveis do espaço acima do 5º, e a parede recebe 5d10 pontos de vida adicionais. Quando conjurada no 9º nível, a parede surge instantaneamente e não exige uma rodada inteira para se formar.","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":590,"category":"Lyre's Guide to Retia","traits":[]},{"id":"lyre-turning-surge","name":"Surto Reversor","originalName":"Turning Surge","level":4,"school":"Abjuração","time":"1 ação bônus","range":"Pessoal","comp":"V, S, M (um fragmento de crânio de um unicórnio e um fragmento de crânio de um pesadelo)","material":"um fragmento de crânio de um unicórnio e um fragmento de crânio de um pesadelo","duration":"Concentração, até 1 minuto","classes":"Paladino, Feiticeiro","ritual":false,"concentration":true,"desc":"Uma aura ondulante de energia profana envolve seu corpo durante a duração da magia. Enquanto estiver banhado por essa aura, você não pode se beneficiar de efeitos positivos de qualquer outra magia ou efeito mágico que tenha você como alvo, incluindo bônus na Classe de Armadura, jogadas de ataque, testes de resistência, efeitos que concedam pontos de vida ou pontos de vida temporários, ações adicionais de qualquer tipo ou benefícios ao deslocamento. Você ainda recebe os benefícios de traços e efeitos não mágicos. Além disso, enquanto estiver envolto na aura, pode realizar uma segunda ação de Ataque ou Multiataque em cada um de seus turnos. Se possuir outra característica que conceda benefício semelhante, como Surto de Ação, não pode usá-la no mesmo turno em que realizar a ação adicional desta magia. Seus ataques não podem ter vantagem nem desvantagem enquanto estiver sob os efeitos desta magia. Sempre que realizar a ação adicional de Ataque ou Multiataque concedida pela magia, você sofre 1 ponto de Fadiga de Combate.","higher":"","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":590,"category":"Lyre's Guide to Retia","traits":["Convocação Cromática","Eidomancia"],"sourceNote":"Regra de grupo — Convocação Cromática: quando a magia mencionar energia ou dano cromático, escolha fogo, frio, ácido, elétrico ou veneno; a escolha vale para todas as ocorrências daquela invocação. Ao conjurar uma magia da Convocação Cromática, faça um teste com o atributo de conjuração (CD 10 + nível da magia). Em uma falha, seu máximo de pontos de vida é reduzido em duas vezes o nível da magia até concluir um Descanso Longo; a fonte chama esse efeito de Queima da Alma. A característica de conjuração da criatura pode dispensá-la desse teste. Regra de grupo — Eidomancia: todo dano causado por uma magia de eidomancia é considerado dano eidólico. Após conjurar a magia, realize um teste de resistência de Constituição de CD 10 + o nível em que a magia foi conjurada + o número de turnos após o primeiro em que ela permaneceu ativa sob concentração. Se não exigir concentração, o teste é feito imediatamente após a conjuração. Em uma falha, você sofre níveis de exaustão iguais à metade do nível da magia, arredondado para baixo (mínimo 1), e não pode conjurá-la novamente por sete dias. Se a falha elevaria a exaustão a 6, ela fica em 5 e você é imediatamente reduzido a 0 pontos de vida. Se falhar em um teste de concentração para manter uma magia de eidomancia, você pode usar sua reação para rolar um d20 e usar esse resultado no lugar do d20 do teste de concentração."},{"id":"lyre-twin-talent","name":"Talento Gêmeo","originalName":"Twin Talent","level":3,"school":"Ilusão","time":"1 ação","range":"Pessoal (9 metros) ou Toque","comp":"V, S","material":"","duration":"Concentração, até 1 hora","classes":"Inscritor, Bardo, Clérigo","ritual":false,"concentration":true,"desc":"Você cria um clone ilusório de si mesmo ou de uma criatura voluntária Média que possa tocar. O clone aparece a até 9 metros de você, e você pode imediatamente ordená-lo a realizar qualquer ação que o original poderia realizar e que exija um teste de atributo ou perícia, usando o modificador que o original usaria, como tentar abrir uma fechadura, agarrar uma criatura ou limpar um espaço. Quando se move, ele provoca as mesmas reações físicas que você provocaria. O clone possui CA igual à sua CD de magia, os mesmos testes de resistência do original e desaparece se sofrer qualquer dano. Uma vez ordenado a realizar uma tarefa, continua agindo: ao final de cada um dos seus turnos, inclusive o primeiro, ele realiza uma ação e pode se mover até 9 metros para executar a tarefa. Se falhar em alcançar a CD de um teste associado à atividade atribuída por dois turnos consecutivos, desaparece.","higher":"Quando você conjura esta magia usando um espaço de 4º nível ou superior, cria um clone ilusório adicional para cada nível do espaço acima do 3º. Você pode dar uma tarefa diferente a cada um, ou ordenar que qualquer clone use a ação Ajudar para auxiliar outro.","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":590,"category":"Lyre's Guide to Retia","traits":["Épico da Dualidade"]},{"id":"lyre-unlore","name":"Apagar Saber","originalName":"Unlore","level":9,"school":"Adivinhação","time":"1 hora","range":"Toque","comp":"V, S, M (incenso no valor de pelo menos 1.000 po, que a magia consome, e um tomo com pelo menos 1.000 páginas fechado por uma trava metálica)","material":"incenso no valor de pelo menos 1.000 po, que a magia consome, e um tomo com pelo menos 1.000 páginas fechado por uma trava metálica","duration":"Permanente","classes":"Inscritor, Bardo, Bruxo, Mago","ritual":false,"concentration":false,"desc":"Escolha uma criatura, objeto ou lugar com o qual esteja em contato. Se for um lugar, ele pode ocupar uma área de até 2,6 km², mas deve possuir um nome ou tema unificado, como uma guilda, castelo ou tesouro, que o Mestre determine ser um assunto válido para uma magia como lendas e histórias. Você passa o tempo de conjuração removendo a identidade histórica desse alvo. Se for uma criatura, ela realiza um teste de resistência de Carisma a cada 10 minutos durante a conjuração; se obtiver três sucessos, a magia falha. Quando a magia é concluída, o tomo utilizado na conjuração fica preenchido com todo conhecimento possível sobre o alvo e passa a se atualizar no futuro conforme novos acontecimentos ocorrem. Quem estiver de posse desse livro pode colocar a mão sobre ele e pensar em qualquer informação que deseje encontrar para tornar-se psiquicamente ciente da resposta. Enquanto o tomo existir, todos os registros feitos sobre o alvo desaparecem após 1 hora; escritores e historiadores que o pesquisarem perdem casualmente o interesse no assunto. Todas as tentativas de adivinhar seu passado ou futuro falham automaticamente, revelando que não há e nunca haverá nada a saber sobre ele. Criaturas com conhecimento de segunda mão sobre o assunto têm lembranças vagas dos detalhes, mas aquelas com experiências em primeira mão não são afetadas e recordam claramente suas próprias vivências. Criaturas que usem magias para tentar identificar o alvo ou obter informações sobre ele fazem um teste de resistência de Sabedoria no lugar do resultado normal e, em caso de sucesso, percebem que uma magia está ocultando a verdade. Se a fechadura do tomo for aberta, a magia termina e a história do alvo é restaurada. O tomo é imune a efeitos que anulam ou dissipam magia; dentro desses efeitos, simplesmente deixa de transmitir informações e volta a funcionar quando removido deles. Quebrar ou arrombar a fechadura exige um teste de Força ou Destreza (Ferramentas de Ladrão) CD 30. Qualquer tentativa de destruir o tomo o trata como tendo CA igual à sua CD de magia, resistência a todo dano, imunidade a magias que exijam testes de resistência e 50 pontos de vida, restaurados a cada hora.","higher":"","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":591,"category":"Lyre's Guide to Retia","traits":["Arcana da Guardiã dos Céus"]},{"id":"lyre-unsealed-bravery","name":"Bravura Deslacrada","originalName":"Unsealed Bravery","level":4,"school":"Abjuração","time":"1 ação bônus","range":"Pessoal","comp":"S","material":"","duration":"Concentração, até 1 minuto","classes":"Alma Favorecida, Cavaleiro das Pétalas, Clérigo, Paladino","ritual":false,"concentration":true,"desc":"Quando você conjura esta magia, qualquer armadura leve, média ou pesada e qualquer escudo que esteja usando são magicamente arremessados para longe do seu corpo em uma explosão de luz vermelha e dourada. Se um item for mágico ou possuir bônus de aprimoramento, ele é apenas descartado; se sua armadura for não mágica, ela é destruída. Durante a duração da magia, o ar ao seu redor brilha com uma aura dourada crepitante e você recebe os seguintes benefícios:\n• Sua Classe de Armadura é calculada como 10 + seu modificador de Destreza + seu modificador do atributo de conjuração, ou é igual à sua CD de magia, o que for maior.\n• Você recebe resistência a dano perfurante, cortante ou de concussão, à sua escolha quando conjura a magia.\n• Você tem vantagem em testes de concentração, bem como em testes de resistência para evitar ficar amedrontado ou enfeitiçado.\n• Uma vez por turno, pode anular qualquer desvantagem que tenha em um ataque corpo a corpo com arma e/ou obter vantagem nele. Se vestir qualquer tipo de armadura ou escudo ou calcular sua Classe de Armadura por outro método durante a duração, a magia termina imediatamente.","higher":"Se você conjurar esta magia no 5º nível ou superior, pode escolher uma das opções a seguir para cada nível do espaço acima do 4º:\n• Você recebe resistência a um tipo de dano adicional entre perfurante, cortante e concussão.\n• Você recebe imunidade a um dos tipos de dano aos quais esta magia lhe conceda resistência, mas apenas contra ataques não mágicos.\n• A duração da magia aumenta para 10 minutos (1 nível de espaço), 1 hora (2 níveis), 8 horas (3 níveis), 24 horas (4 níveis) ou 1 semana (5 níveis). Durante esse período, você não precisa dormir.","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":591,"category":"Lyre's Guide to Retia","traits":["Legado do Ouro"]},{"id":"lyre-unveiling-gaze","name":"Olhar Revelador","originalName":"Unveiling Gaze","level":3,"school":"Adivinhação","time":"1 ação","range":"Pessoal (9 metros)","comp":"V","material":"","duration":"Concentração, até 10 minutos","classes":"Cavaleiro das Pétalas, Patrulheiro, Clérigo","ritual":false,"concentration":true,"desc":"Seus olhos se tornam perspicazes. Durante a duração da magia, sempre que olhar para uma criatura dentro do alcance, você sabe se ela não está assumindo sua forma verdadeira, como por ter sido polimorfada, transformada ou ter usado outra característica para alterar sua forma, embora não descubra qual é sua forma verdadeira. A qualquer momento durante os efeitos da magia, se vir uma criatura que não esteja em sua forma verdadeira, você pode usar uma ação bônus para obrigá-la a realizar um teste de resistência de Carisma. Em caso de falha, esta magia termina e o alvo é compelido a usar sua reação para retornar à forma verdadeira, a menos que algo o impeça, como uma maldição ou uma transformação causada por desejo. Em caso de sucesso, ele não é compelido e percebe que algo tentou forçá-lo a mudar de forma.","higher":"","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":592,"category":"Lyre's Guide to Retia","traits":["Artes dos Nove Ramos"]},{"id":"lyre-unweave","name":"Desfiar Magia","originalName":"Unweave","level":7,"school":"Abjuração","time":"1 ação","range":"18 metros","comp":"V, S, M (uma esfera amarrada de espinhos secos)","material":"uma esfera amarrada de espinhos secos","duration":"10 minutos","classes":"Inscritor, Feiticeiro, Bruxo, Mago","ritual":false,"concentration":false,"desc":"Você cria uma esfera de 6 metros de raio de influência profana, centrada em um ponto dentro do alcance, fazendo com que uma réplica corrompida da Teia Eidomântica tente sobrepor-se à teia existente nesse espaço. Esse campo pode ser visto por qualquer criatura com visão verdadeira ou capaz de enxergar auras mágicas. O campo permanece pela duração da magia e, sempre que uma criatura tentar conjurar uma magia que não seja de demonologia dentro da esfera ou tendo como alvo algo dentro dela, deve realizar um teste de resistência de Carisma. Em caso de falha, o espaço de magia é gasto sem produzir efeito. Magias que falham dessa forma não consomem seus materiais. Se a magia conjurada tiver sido obtida através da lista de magias de paladino, clérigo ou cavaleiro das pétalas, a criatura tem desvantagem no teste contra este efeito. Se esta magia for conjurada no mesmo local uma vez a cada 24 horas durante 1 mês, o efeito se torna permanente até ser dissipado.","higher":"Quando você conjura esta magia usando um espaço de nível superior, sua duração aumenta para 1 hora no 8º nível e 1 dia no 9º nível.","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":592,"category":"Lyre's Guide to Retia","traits":["Daemoturgia"]},{"id":"lyre-valkyrie-strike","name":"Golpe da Valquíria","originalName":"Valkyrie Strike","level":1,"school":"Transmutação","time":"1 ação bônus","range":"Pessoal","comp":"V","material":"","duration":"Concentração, até 1 minuto","classes":"Alma Favorecida, Cavaleiro das Pétalas, Patrulheiro","ritual":false,"concentration":true,"desc":"Você se move como o vento. Até a magia terminar, seu movimento não provoca ataques de oportunidade. Uma vez antes de a magia terminar, você pode conceder a si mesmo vantagem em uma jogada de ataque com arma no seu turno. Esse ataque causa 1d8 de dano de energia adicional em um acerto. Acertando ou errando, seu deslocamento de caminhada aumenta em 9 metros até o fim desse turno.","higher":"Quando você conjura esta magia usando um espaço de 2º nível ou superior, pode escolher um dos efeitos a seguir para cada nível do espaço acima do 1º:\n• O dano aumenta em 1d8.\n• O bônus ao seu deslocamento de caminhada aumenta em 3 metros.\n• (2 níveis de espaço) O dano adicional se aplica a um acerto adicional, que deve ocorrer no mesmo turno que o primeiro.","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":592,"category":"Lyre's Guide to Retia","traits":["Legado 5.19"],"sourceNote":"A fonte identifica esta entrada como uma magia Legacy/revisada da edição 5.19; suas regras foram preservadas como uma versão própria de Lyre."},{"id":"lyre-valkyries-binding-rings","name":"Anéis de Vinculação da Valquíria","originalName":"Valkyrie’s Binding Rings","level":3,"school":"Transmutação","time":"1 ação bônus","range":"Pessoal","comp":"V, M (dois anéis de prata ou ouro grandes o bastante para envolver seus pulsos, no valor de pelo menos 300 po cada)","material":"dois anéis de prata ou ouro grandes o bastante para envolver seus pulsos, no valor de pelo menos 300 po cada","duration":"Concentração, até 10 minutos","classes":"Clérigo, Paladino, Feiticeiro, Bruxo","ritual":false,"concentration":true,"desc":"Os anéis usados como componentes desta magia criam grandes aros de energia radiante pontilhados por escrita Celestial. Uma vez quando você conjura esta magia e, depois, como uma ação bônus em seus turnos subsequentes, você pode escolher uma criatura a até 18 metros e lançar esses anéis contra ela para tentar prendê-la no lugar. O alvo deve obter sucesso em um teste de resistência de Destreza ou fica impedido até o início do seu próximo turno.","higher":"Quando você conjura esta magia usando um espaço de 4º nível ou superior, pode escolher uma criatura adicional dentro do alcance sempre que usar o efeito desta magia para cada nível do espaço acima do 3º.","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":592,"category":"Lyre's Guide to Retia","traits":[]},{"id":"lyre-valkyries-wrath","name":"Ira da Valquíria","originalName":"Valkyrie’s Wrath","level":4,"school":"Evocação","time":"1 ação","range":"9 metros","comp":"V, S, M (uma lança, azagaia, lança curta, flecha grande ou arma semelhante que possa ser arremessada contra um alvo; ela é destruída depois se não for mágica)","material":"uma lança, azagaia, lança curta, flecha grande ou arma semelhante que possa ser arremessada contra um alvo; ela é destruída depois se não for mágica","duration":"Instantânea","classes":"Alma Favorecida, Paladino, Feiticeiro, Bruxo","ritual":false,"concentration":false,"desc":"O componente material desta magia se transforma em um arco de luz, que você arremessa contra uma criatura dentro do alcance realizando um ataque à distância com magia. Em um acerto, em vez de causar o dano ou os efeitos normais da arma, o alvo é erguido do chão e atingido por dezenas de feixes de poder radiante, sofrendo 8d8 de dano radiante. Se a criatura não for mais de duas categorias de tamanho maior que você, ela também fica caída.","higher":"Quando você conjura esta magia no 5º nível ou superior, ela causa 1d8 de dano radiante adicional para cada nível do espaço acima do 4º. Se for conjurada no 7º nível ou superior, você pode realizar esse ataque com vantagem.","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":592,"category":"Lyre's Guide to Retia","traits":[]},{"id":"lyre-valms-irritating-question","name":"Pergunta Irritante de Valm","originalName":"Valm’s Irritating Question","level":5,"school":"Encantamento","time":"1 minuto","range":"Toque","comp":"V, S, M (uma página em branco, que registra a pergunta e a resposta)","material":"uma página em branco, que registra a pergunta e a resposta","duration":"Instantânea","classes":"Inscritor, Cavaleiro das Pétalas, Clérigo, Feiticeiro, Bruxo","ritual":false,"concentration":false,"desc":"Você faz uma pergunta a uma criatura que possa tocar. Se ela puder compreender suas palavras, é compelida a responder, embora não necessariamente em um idioma que você compreenda. Se der uma resposta honesta, você percebe que ela falou a verdade. Se der uma resposta enganosa ou tentar mentir, deve realizar um teste de resistência de Inteligência, sofrendo 8d10 de dano psíquico em caso de falha enquanto sua mente é atormentada por culpa e dor, revelando externamente a mentira. Em caso de sucesso, a magia a reconhece como se tivesse falado a verdade. Se o alvo não tiver como saber uma resposta verdadeira ou estiver sendo compelido por outro efeito a mentir contra a própria vontade, a magia revela esse fato e ele não sofre consequência alguma, independentemente da resposta.","higher":"Se esta magia for conjurada no 6º nível ou superior, você pode fazer uma pergunta adicional para cada nível do espaço acima do 5º, e duas perguntas não podem ser idênticas nem representar a mesma pergunta com palavras diferentes. Nesse caso, o alvo realiza o teste de resistência na primeira vez em que tentar enganar ou mentir e sofre os 8d10 completos de dano psíquico na primeira vez em que falhar. Se falhar e continuar mentindo, cada mentira subsequente provoca outro teste de Inteligência, mas causa apenas 2d10 de dano psíquico em caso de falha.","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":593,"category":"Lyre's Guide to Retia","traits":[]},{"id":"lyre-vampiric-mist","name":"Névoa Vampírica","originalName":"Vampiric Mist","level":7,"school":"Necromancia","time":"1 ação","range":"Pessoal (raio de 6 metros)","comp":"S","material":"","duration":"Instantânea","classes":"Druida, Feiticeiro, Bruxo","ritual":false,"concentration":false,"desc":"Uma nuvem de geada aparece em um raio de 6 metros centrado em você, mordendo todas as outras criaturas nessa área. Todas as criaturas dentro do alcance devem realizar um teste de resistência de Constituição, sofrendo 10d6 de dano de frio em caso de falha ou metade em caso de sucesso. Você absorve uma parcela da força vital dessas criaturas e recupera 2d12 pontos de vida para cada criatura dentro do alcance que falhar no teste. Esta magia não produz efeito em mortos-vivos ou constructos.","higher":"","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":593,"category":"Lyre's Guide to Retia","traits":["Artes Arcanas de Altissima-Cor"]},{"id":"lyre-vanquish-magic","name":"Subjugar Magia","originalName":"Vanquish Magic","level":5,"school":"Abjuração","time":"1 ação","range":"36 metros","comp":"V, S","material":"","duration":"Instantânea","classes":"Inscritor, Bardo, Feiticeiro, Mago","ritual":false,"concentration":false,"desc":"Escolha uma criatura, objeto ou efeito mágico dentro do alcance. Para cada magia que esteja afetando o alvo, faça um teste de atributo usando seu atributo de conjuração. A CD é igual a 10 + o nível da magia. Em caso de sucesso, essa magia termina sobre o alvo e sobre quaisquer outros alvos adicionais que estejam sendo afetados pela mesma conjuração.","higher":"Quando você conjura esta magia no 6º nível ou superior, pode escolher um objeto, criatura ou efeito adicional dentro do alcance para cada nível do espaço acima do 5º.","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":593,"category":"Lyre's Guide to Retia","traits":["Arcana da Guardiã dos Céus"]},{"id":"lyre-vengeful-beckoning","name":"Chamado Vingativo","originalName":"Vengeful Beckoning","level":6,"school":"Conjuração","time":"1 ação","range":"9 metros","comp":"V, S, M (um anel de rubi no valor de pelo menos 300 po, que esta magia consome)","material":"um anel de rubi no valor de pelo menos 300 po, que esta magia consome","duration":"Concentração, até 1 minuto","classes":"Feiticeiro, Bruxo, Mago","ritual":false,"concentration":true,"desc":"Você arranca do corpo o espírito de uma criatura morta ou moribunda dentro do alcance e lhe concede uma forma espiritual vingativa. Uma forma yokai retorcida da criatura, que deve estar com 0 pontos de vida ou morta, manifesta-se em um espaço desocupado a até 9 metros do corpo. Esse corpo espiritual age então na iniciativa anterior da criatura, ou rola iniciativa caso ainda não tivesse uma, e age como desejar. Se a criatura estava morta, não pode ter morrido há mais de 1 hora. O espírito possui as estatísticas da criatura original, com as seguintes exceções:\n• A criatura possui 0 pontos de vida, mas recebe pontos de vida temporários iguais a (1d6 + seu modificador do atributo de conjuração) multiplicado por seu bônus de proficiência. Ela morre e a magia termina se perder esses pontos de vida temporários. Não pode receber pontos de vida de nenhuma outra forma.\n• A criatura ignora terreno difícil.\n• A criatura não pode receber bônus em seus modificadores de jogada de ataque ou testes de resistência.\n• O tipo da criatura também é considerado corruptor (yokai), além de seus tipos habituais.\n• A criatura não pode se mover a mais de 18 metros do próprio cadáver.\n• Se seu cadáver for atacado, a criatura pode usar sua reação para transferir o dano à forma espiritual.\n• A criatura tem vantagem nas jogadas de ataque contra o inimigo que reduziu seu corpo vivo a 0 pontos de vida.\n• A criatura possui uma cópia espectral de todo seu equipamento e itens, mas, se usar essas versões, considera-se que está usando a contraparte real. Se um item for removido do corpo físico, desaparece da forma espiritual yokai. Enquanto a forma espiritual estiver ativa, o corpo da criatura não realiza testes de resistência contra a morte, embora ainda possa acumular falhas se o corpo sofrer dano. Se o corpo morrer, o espírito não desaparece até a magia terminar. Se o conjurador perder a concentração, o corpo espiritual desaparece imediatamente. Depois que uma criatura receber esta forma vingativa, não pode recebê-la novamente por 24 horas.","higher":"Se você conjurar esta magia usando um espaço de 7º nível ou superior, o corpo espiritual recebe 5 pontos de vida temporários adicionais e um bônus cumulativo de +1 em seus testes de resistência para cada nível do espaço acima do 6º.","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":593,"category":"Lyre's Guide to Retia","traits":["Daemoturgia"]},{"id":"lyre-vibrance-sap","name":"Drenar Vivacidade","originalName":"Vibrance Sap","level":1,"school":"Necromancia","time":"1 ação","range":"9 metros","comp":"V, S","material":"","duration":"Instantânea","classes":"Patrulheiro, Druida, Feiticeiro, Mago","ritual":false,"concentration":false,"desc":"Uma explosão de energia na forma de um yokai menor é disparada contra um alvo dentro do alcance como um ataque à distância com magia. Em um acerto, o alvo sofre 2d8 de dano necrótico e deve realizar um teste de resistência de Constituição. Em caso de falha, no próximo turno ele pode realizar uma ação ou uma ação bônus, mas não ambas.","higher":"Quando você conjura esta magia usando um espaço de 2º nível ou superior, o dano aumenta em 1d8 para cada nível do espaço acima do 1º. Se for conjurada no 5º nível ou superior, uma criatura que falhar no teste de Constituição pode realizar apenas 1 ataque com arma no próximo turno, independentemente de suas características ou itens mágicos.","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":594,"category":"Lyre's Guide to Retia","traits":["Daemoturgia"]},{"id":"lyre-violent-pillar","name":"Pilar Violento","originalName":"Violent Pillar","level":5,"school":"Evocação","time":"1 ação","range":"18 metros","comp":"S, M (uma haste de metal com pelo menos 90 centímetros de comprimento, ou uma lança, azagaia ou bordão, que a magia consome)","material":"uma haste de metal com pelo menos 90 centímetros de comprimento, ou uma lança, azagaia ou bordão, que a magia consome","duration":"Concentração, até 10 minutos","classes":"Alma Favorecida, Inscritor, Druida, Feiticeiro, Bruxo","ritual":false,"concentration":true,"desc":"Você ergue o componente material da magia e o arremessa contra um alvo que possa ver dentro do alcance. A criatura deve obter sucesso em um teste de resistência de Força ou sofre 8d10 de dano de concussão, é arremessada 4,5 metros para trás, fica caída e a magia termina. Se houver uma parede ou superfície sólida dentro desses 4,5 metros, ela se choca contra a superfície e a lança a mantém presa ali, deixando-a impedida. Ela, ou outra criatura adjacente, pode usar uma ação para realizar um teste de Força contra sua CD de magia e arrancar a lança, encerrando o efeito em caso de sucesso. Esta magia só é capaz de impedir criaturas até uma categoria de tamanho maior que você.","higher":"","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":594,"category":"Lyre's Guide to Retia","traits":["Artes dos Nove Ramos"]},{"id":"lyre-vitality-balance","name":"Equilíbrio de Vitalidade","originalName":"Vitality Balance","level":3,"school":"Necromancia","time":"1 ação","range":"9 metros","comp":"V, S","material":"","duration":"Instantânea","classes":"Clérigo, Mago","ritual":false,"concentration":false,"desc":"Você sacrifica parte da própria saúde para reparar os ferimentos de outra criatura. Você sofre 4d8 de dano necrótico, que não pode ser reduzido de nenhuma forma, e uma criatura à sua escolha que possa ver dentro do alcance recupera uma quantidade de pontos de vida igual ao dobro do dano necrótico sofrido por você. Se esta magia fosse reduzir você a 0 pontos de vida, o dano necrótico é reduzido de modo que você permaneça com 1 ponto de vida, e a cura é ajustada proporcionalmente.","higher":"Quando você conjura esta magia usando um espaço de 4º nível ou superior, pode escolher um dos efeitos a seguir para cada nível do espaço acima do 3º:\n• O dano aumenta em 1d8.\n• Antes de sofrer o dano necrótico, você recebe 2d8 pontos de vida temporários. A quantidade de d8 aumenta em 1d8 cada vez que escolher este efeito. Esses pontos de vida temporários desaparecem depois que você sofre o dano necrótico.","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":594,"category":"Lyre's Guide to Retia","traits":["Legado 5.19"],"sourceNote":"A fonte identifica esta entrada como uma magia Legacy/revisada da edição 5.19; suas regras foram preservadas como uma versão própria de Lyre."},{"id":"lyre-void-of-endless-depth","name":"Vazio de Profundidade Infinita","originalName":"Void of Endless Depth","level":8,"school":"Evocação","time":"1 ação","range":"45 metros","comp":"V, M (uma gota de piche misturada com uma gota de mercúrio)","material":"uma gota de piche misturada com uma gota de mercúrio","duration":"Concentração, até 10 minutos","classes":"Inscritor, Bruxo, Mago","ritual":false,"concentration":true,"desc":"Escuridão mágica se espalha de um ponto à sua escolha dentro do alcance, preenchendo uma esfera de 18 metros de raio até a magia terminar; ela pode contornar cantos quando o espaço exigir. Uma criatura com visão no escuro não consegue enxergar através dessa escuridão. Luz não mágica e luz criada por magias de 8º nível ou inferior não conseguem iluminar a área. Gritos, balbucios e risadas insanas podem ser ouvidos dentro da esfera. Sempre que uma criatura iniciar o turno na esfera, deve realizar um teste de resistência de Sabedoria, sofrendo 8d8 de dano psíquico em caso de falha ou metade em caso de sucesso.","higher":"","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":594,"category":"Lyre's Guide to Retia","traits":["Legado 5.19"],"sourceNote":"A fonte identifica esta entrada como uma magia Legacy/revisada da edição 5.19; suas regras foram preservadas como uma versão própria de Lyre."},{"id":"lyre-volcanic-ash","name":"Cinza Vulcânica","originalName":"Volcanic Ash","level":5,"school":"Conjuração","time":"1 ação","range":"18 metros (raio de 6 metros)","comp":"V, S","material":"","duration":"Concentração, até 1 minuto","classes":"Lista especial / não especificada","ritual":false,"concentration":true,"desc":"Uma nuvem de cinzas vulcânicas ardentes jorra de um ponto à sua escolha dentro do alcance, preenchendo uma esfera de 6 metros de raio. A nuvem permanece pela duração da magia. Qualquer criatura dentro da nuvem quando ela aparece deve realizar um teste de resistência de Constituição, sofrendo 8d6 de dano de fogo em caso de falha ou metade em caso de sucesso. Qualquer criatura que terminar seu turno dentro da nuvem ou entrar nela pela primeira vez em seu turno deve realizar o teste novamente e sofrer o dano conforme o resultado. No seu turno, você pode mover o centro da nuvem até 9 metros como uma ação bônus. Criaturas sem resistência a dano de fogo ficam cegas e não conseguem respirar enquanto estiverem na nuvem de cinzas, e tudo dentro dela fica sob obscurecimento pesado. Você não fica cego por sua própria nuvem e, quando realiza um teste contra ela, não sofre dano em caso de sucesso e sofre metade em caso de falha.","higher":"Quando você conjura esta magia usando um espaço de 6º nível ou superior, pode escolher um dos efeitos a seguir para cada nível do espaço acima do 5º:\n• O raio da magia aumenta em 1,5 metro.\n• O dano de fogo da magia aumenta em 1d6.","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":594,"category":"Lyre's Guide to Retia","traits":[]},{"id":"lyre-vorpal-flames","name":"Chamas Vorpais","originalName":"Vorpal Flames","level":3,"school":"Conjuração","time":"1 ação bônus","range":"Pessoal","comp":"V, S","material":"","duration":"Concentração, até 1 minuto","classes":"Inscritor, Cavaleiro das Pétalas, Bardo, Feiticeiro, Bruxo","ritual":false,"concentration":true,"desc":"Você invoca chamas que se unem na forma de uma uchigatana e se solidificam em sua mão. Essa uchigatana mágica, tratada como uma espada grande, permanece até a magia terminar. Ela conta como uma arma marcial corpo a corpo com a qual você é proficiente, possui as propriedades pesada e alcance, emite luz plena por 6 metros e meia-luz por mais 6 metros e causa 3d8 de dano de fogo em um acerto. Você pode soltar a espada e fazê-la desaparecer livremente e pode chamá-la de volta à mão como uma ação bônus enquanto a magia persistir. Ao atacar com ela, pode usar Força ou seu atributo de conjuração nas jogadas de ataque e dano. Quando esta espada atingir uma criatura do tipo Planta ou Morto-vivo, causa 1d8 de dano de fogo adicional.","higher":"Quando você conjura esta magia usando um espaço de 5º nível ou superior, sua proficiência com esta arma aumenta. Com um espaço de 5º nível ou superior, você pode realizar dois ataques, em vez de um, com ela como parte da ação de Ataque. No 7º nível ou superior, isso aumenta para três ataques em vez de um. Se for conjurada usando um espaço de 9º nível, esta arma obtém um acerto crítico em um resultado 18, 19 ou 20 no d20.","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":595,"category":"Lyre's Guide to Retia","traits":["Artes dos Nove Ramos"]},{"id":"lyre-vortex-quiver","name":"Aljava de Vórtice","originalName":"Vortex Quiver","level":3,"school":"Transmutação","time":"1 ação bônus","range":"Toque","comp":"V, S","material":"","duration":"Concentração, até 1 minuto","classes":"Inscritor, Cavaleiro das Pétalas, Patrulheiro, Bardo, Druida","ritual":false,"concentration":false,"desc":"Você imbui uma arma com um redemoinho em espiral. Quando realiza um ataque à distância com essa arma, seus acertos causam 1d8 de dano de energia adicional e, se o alvo não for mais de uma categoria de tamanho maior que o tamanho de criatura para o qual a arma foi projetada, ele deve realizar um teste de resistência de Força. Em caso de falha, ocorre um dos efeitos a seguir, à sua escolha:\n• O alvo é empurrado 3 metros para trás, parando se colidir com uma superfície sólida. Para cada 3 metros que deixar de percorrer, sofre 1d6 de dano de concussão.\n• O alvo fica caído.","higher":"Quando você conjura esta magia usando um espaço de 4º nível ou superior, escolha um dos efeitos a seguir para cada nível do espaço acima do 3º:\n• A categoria de tamanho das criaturas que podem ser afetadas pelo teste de Força aumenta em uma.\n• O alvo é empurrado 3 metros adicionais.\n• Para cada dois níveis de espaço acima do 3º, o dano de energia adicional também aumenta em 1d8.","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":595,"category":"Lyre's Guide to Retia","traits":["Épico da Dualidade"]},{"id":"lyre-wakefields-suffocating-darkness","name":"Escuridão Sufocante de Wakefield","originalName":"Wakefield’s Suffocating Darkness","level":7,"school":"Necromancia","time":"1 ação","range":"9 metros","comp":"V, S, M (uma lâmpada apagada da qual emerge escuridão)","material":"uma lâmpada apagada da qual emerge escuridão","duration":"Concentração, até 1 minuto","classes":"Lista especial / não especificada","ritual":false,"concentration":true,"desc":"Você conjura uma escuridão horrenda que se estende até um alvo dentro do alcance e cobre agressivamente seu corpo, deixando-o como uma carcaça enegrecida e abafada. O alvo deve realizar um teste de resistência de Inteligência. Em caso de falha, fica obscurecido por 1 minuto; durante esse tempo, fica cego e surdo, sua voz é distorcida de modo que não consegue se comunicar nem realizar componentes verbais de magias, e sofre 3d8 de dano psíquico no início de cada um de seus turnos. Enquanto estiver coberta por sombras dessa forma, você pode usar sua ação em cada um dos seus turnos para obrigar todas as criaturas sob esse efeito a realizar outro teste de resistência de Inteligência. Em caso de falha, uma criatura se move até metade do seu deslocamento em direção a uma criatura à sua escolha e é manipulada para atacar uma criatura ao alcance dela como um ataque corpo a corpo com magia; ela não é considerada cega para esse ataque desde que você possa ver o alvo. Em um acerto, o alvo atingido deve realizar um teste de resistência de Inteligência ou também fica afetado por esta magia e coberto pela mesma escuridão até a magia terminar. Se uma criatura afetada iniciar o turno no raio de uma luz mágica ou for submetida a um efeito mágico que cause brevemente um grande clarão de luz, como uma bola de fogo ou spray prismático, ela pode repetir o teste de resistência de Inteligência, encerrando o efeito sobre si em caso de sucesso.","higher":"Quando você conjura esta magia no 8º nível ou superior, pode escolher uma criatura adicional como alvo para cada nível do espaço acima do 7º.","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":595,"category":"Lyre's Guide to Retia","traits":[]},{"id":"lyre-wall-of-radiance","name":"Muralha de Radiância","originalName":"Wall of Radiance","level":5,"school":"Evocação","time":"1 ação","range":"36 metros","comp":"V, S, M (um espelho de mão)","material":"um espelho de mão","duration":"Concentração, até 10 minutos","classes":"Alma Favorecida, Inscritor, Paladino, Feiticeiro, Bruxo, Mago","ritual":false,"concentration":true,"desc":"Uma muralha cintilante de luz intensa aparece em um ponto à sua escolha dentro do alcance. A muralha pode ter qualquer orientação: horizontal, vertical ou diagonal. Pode flutuar livremente ou repousar sobre uma superfície sólida. Ela pode ter até 18 metros de comprimento, 3 metros de altura e 1,5 metro de espessura. A muralha bloqueia linha de visão, mas criaturas e objetos podem atravessá-la. Ela emite luz plena por 36 metros e meia-luz por mais 36 metros. Quando a muralha aparece, cada criatura em sua área deve realizar um teste de resistência de Constituição. Em caso de falha, sofre 4d8 de dano radiante e fica cega por 1 minuto; em caso de sucesso, sofre metade do dano e não fica cega. Uma criatura cega pode realizar um teste de resistência de Constituição ao final de cada um de seus turnos, encerrando o efeito em caso de sucesso. Uma criatura que terminar seu turno na área da muralha sofre 4d8 de dano radiante. Até a magia terminar, você pode usar uma ação para lançar um feixe de radiância da muralha contra uma criatura que possa ver a até 18 metros dela. Faça um ataque à distância com magia; em um acerto, o alvo sofre 4d8 de dano radiante. Acertando ou errando, reduza o comprimento da muralha em 3 metros. Se o comprimento cair a 0, a magia termina.","higher":"Quando você conjura esta magia usando um espaço de 6º nível ou superior, pode escolher um dos efeitos a seguir para cada nível do espaço acima do 5º:\n• O dano aumenta em 1d8.\n• Quando você dispara um feixe da muralha, cada criatura a até 1,5 metro do alvo deve realizar um teste de resistência de Destreza. Em caso de falha, sofre metade do dano inicial.\n• O comprimento da muralha aumenta em 3 metros e sua altura aumenta em 1,5 metro.","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":595,"category":"Lyre's Guide to Retia","traits":["Legado 5.19"],"sourceNote":"A fonte identifica esta entrada como uma magia Legacy/revisada da edição 5.19; suas regras foram preservadas como uma versão própria de Lyre."},{"id":"lyre-weapon-of-domination","name":"Arma de Dominação","originalName":"Weapon of Domination","level":2,"school":"Transmutação","time":"1 ação bônus","range":"Pessoal","comp":"S","material":"","duration":"Instantânea","classes":"Cavaleiro das Pétalas, Clérigo, Paladino","ritual":false,"concentration":false,"desc":"Uma arma corpo a corpo que você esteja empunhando se transforma brevemente em uma versão dourada e gigantesca de si mesma, feita de energia arcana. Ela é muitas vezes maior que você, e você pode usá-la para realizar um único ataque com arma, ignorando as considerações normais de tamanho de arma, contra uma criatura dentro do dobro do alcance da arma. Em um acerto, você causa os dados de dano normais da arma, mas deve rolar esses dados novamente e adicionar o resultado como dano de energia. Esse dano de energia adicional não é ampliado por acertos críticos. A arma então retorna ao estado normal.","higher":"Quando você conjura esta magia no 3º nível ou superior, para cada nível do espaço acima do 2º você rola os dados de dano da arma uma vez adicional e soma o resultado ao dano de energia causado. A cada dois níveis de espaço acima do 2º, o tamanho e o alcance da arma dobram novamente. Se for conjurada no 9º nível, o dano de energia adicional é dobrado.","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":596,"category":"Lyre's Guide to Retia","traits":["Legado do Ouro"]},{"id":"lyre-wings-of-sharp-transition","name":"Asas de Transição Afiada","originalName":"Wings of Sharp Transition","level":5,"school":"Conjuração","time":"1 ação","range":"Pessoal","comp":"V, S","material":"","duration":"Concentração, até 1 minuto","classes":"Alma Favorecida, Inscritor, Feiticeiro, Bruxo","ritual":false,"concentration":true,"desc":"Você cria asas refrativas feitas de energia vermelho-clara, que lhe concedem deslocamento de voo (pairar) de 18 metros e deslocamento de aceleração em gravidade zero de 54 metros. Enquanto possuir essas asas, seu movimento usando esses modos não provoca ataques de oportunidade, e você causa 1d8 de dano de energia adicional a um alvo na primeira vez a cada turno em que causar dano a uma criatura com um ataque ou magia. Como uma ação bônus no seu turno, você pode tentar realizar um ataque corpo a corpo com magia contra uma criatura a até 1,5 metro de você, golpeando-a com uma dessas asas de energia. Em um acerto, o alvo sofre 2d8 de dano de energia. Se você perder ou abandonar a concentração nesta magia, pode se teletransportar para um espaço desocupado que possa ver dentro de uma distância igual ao deslocamento de voo (pairar) concedido pela magia.","higher":"Quando você conjura esta magia no 6º nível ou superior, pode escolher um dos efeitos a seguir para cada nível do espaço acima do 5º:\n• Seus deslocamentos de voo e aceleração em gravidade zero aumentam em 3 metros e 9 metros, respectivamente.\n• Tanto o dano adicional quanto o dano do ataque de asa aumentam em 1d8.\n• A duração da magia aumenta para 10 minutos (1 nível de espaço), 1 hora (2 níveis), 8 horas (3 níveis) ou 24 horas (4 níveis). Para cada dois níveis de espaço acima do 5º, você pode realizar um ataque de asa adicional como parte da mesma ação bônus. Se for conjurada no 9º nível, esta magia não exige concentração.","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":596,"category":"Lyre's Guide to Retia","traits":["Sangue de Cineris"]},{"id":"lyre-wingweight","name":"Peso das Asas","originalName":"Wingweight","level":2,"school":"Transmutação","time":"1 ação","range":"90 metros","comp":"V","material":"","duration":"Concentração, até 10 minutos","classes":"Patrulheiro, Bardo, Feiticeiro","ritual":false,"concentration":true,"desc":"Escolha até três criaturas que você possa ver dentro do alcance. Um símbolo arcano aparece acima delas e só fica visível quando a criatura está voando pelo ar. O alvo deve obter sucesso em um teste de resistência de Força. Em caso de falha, qualquer deslocamento de voo ou voo (pairar) que possua torna-se um deslocamento de voo laborioso; esse efeito passa a valer a partir do início do próximo turno do alvo.","higher":"Quando você conjura esta magia usando um espaço de 3º nível ou superior, ela pode ter até duas criaturas adicionais como alvo para cada nível do espaço acima do 2º.","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":596,"category":"Lyre's Guide to Retia","traits":[]},{"id":"lyre-whirlpool","name":"Redemoinho","originalName":"Whirlpool","level":5,"school":"Evocação","time":"1 ação","range":"36 metros","comp":"V, S, M (papel ou folha em forma de funil)","material":"papel ou folha em forma de funil","duration":"Concentração, até 1 minuto","classes":"Cavaleiro das Pétalas, Druida","ritual":false,"concentration":true,"desc":"Uma massa giratória de água com 1,5 metro de profundidade aparece em um raio de 9 metros centrado em um ponto que você possa ver dentro do alcance. O ponto deve estar no chão ou em um corpo d’água. Até a magia terminar, essa área é terreno difícil, e qualquer criatura que iniciar seu turno nela deve obter sucesso em um teste de resistência de Força ou sofre 6d6 de dano de concussão e é puxada 3 metros em direção ao centro. Criaturas em um espaço que toque o ponto no qual a magia está centrada têm desvantagem no teste de resistência de Força.","higher":"Quando você conjura esta magia usando um espaço de 6º nível ou superior, escolha um dos efeitos a seguir para cada nível do espaço acima do 5º:\n• O raio da água giratória aumenta em 1,5 metro, assim como a distância pela qual as criaturas são puxadas em direção ao centro.\n• O dano de concussão aumenta em 1d6.\n• A profundidade da magia aumenta em 1,5 metro, e as criaturas puxadas para dentro também são puxadas para baixo por uma distância igual à metade da distância de deslocamento para o centro.","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":596,"category":"Lyre's Guide to Retia","traits":["Legado 5.19"],"sourceNote":"A fonte identifica esta entrada como uma magia Legacy/revisada da edição 5.19; suas regras foram preservadas como uma versão própria de Lyre."},{"id":"lyre-words-of-azharul","name":"Palavras de Azharul","originalName":"Words of Azharul","level":8,"school":"Necromancia","time":"1 ação","range":"18 metros","comp":"V, S, M (meio quilo de ossos moídos do esqueleto de um antigo dragão negro)","material":"meio quilo de ossos moídos do esqueleto de um antigo dragão negro","duration":"24 horas","classes":"Inscritor, Bruxo, Mago","ritual":false,"concentration":false,"desc":"Quando conjura esta magia, você escolhe uma criatura que possa ver a até 18 metros e que possa ver e ouvir você. Você canaliza as últimas palavras de um antigo dragão morto, invocando sobre ela uma maldição de morte. A criatura deve realizar um teste de resistência de Carisma. Em caso de falha, fica amaldiçoada por 24 horas. Enquanto estiver amaldiçoada dessa forma, sempre que realizar uma jogada de ataque, teste de atributo ou teste de resistência, o conjurador desta magia pode gastar uma marca para ignorar o resultado e substituí-lo por 1, ainda aplicando os modificadores e sem causar falha automática, inclusive em jogadas de ataque. O conjurador possui cinco marcas para usar; depois que todas forem gastas, a maldição termina. Ao final das 24 horas, a criatura sofre 5d10 de dano para cada marca não utilizada. Se uma criatura conjurar esta magia pela segunda vez sobre uma criatura que já tenha afetado com ela, a maldição anterior termina imediatamente sem causar dano. As marcas de outra instância desta magia não podem ser usadas para fazer a criatura falhar no teste contra esta magia.","higher":"","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":597,"category":"Lyre's Guide to Retia","traits":["Convocação Cromática","Eidomancia"],"sourceNote":"Regra de grupo — Convocação Cromática: quando a magia mencionar energia ou dano cromático, escolha fogo, frio, ácido, elétrico ou veneno; a escolha vale para todas as ocorrências daquela invocação. Ao conjurar uma magia da Convocação Cromática, faça um teste com o atributo de conjuração (CD 10 + nível da magia). Em uma falha, seu máximo de pontos de vida é reduzido em duas vezes o nível da magia até concluir um Descanso Longo; a fonte chama esse efeito de Queima da Alma. A característica de conjuração da criatura pode dispensá-la desse teste. Regra de grupo — Eidomancia: todo dano causado por uma magia de eidomancia é considerado dano eidólico. Após conjurar a magia, realize um teste de resistência de Constituição de CD 10 + o nível em que a magia foi conjurada + o número de turnos após o primeiro em que ela permaneceu ativa sob concentração. Se não exigir concentração, o teste é feito imediatamente após a conjuração. Em uma falha, você sofre níveis de exaustão iguais à metade do nível da magia, arredondado para baixo (mínimo 1), e não pode conjurá-la novamente por sete dias. Se a falha elevaria a exaustão a 6, ela fica em 5 e você é imediatamente reduzido a 0 pontos de vida. Se falhar em um teste de concentração para manter uma magia de eidomancia, você pode usar sua reação para rolar um d20 e usar esse resultado no lugar do d20 do teste de concentração."},{"id":"lyre-writ-block","name":"Escrito de Bloqueio","originalName":"Writ Block","level":2,"school":"Encantamento","time":"1 ação","range":"18 metros","comp":"S","material":"","duration":"Concentração, até 1 minuto","classes":"Inscritor","ritual":false,"concentration":true,"desc":"Você escreve uma linha de texto arcano descrevendo um alvo que possa ver a até 18 metros; você registra seu estado atual e impõe esse texto para impedir que ele seja alterado. Escolha uma das opções a seguir quando conjurar esta magia:\n• Jogadas de ataque.\n• Classe de Armadura.\n• Testes de resistência.\n• Testes de atributo.\nO alvo deve realizar um teste de resistência de Inteligência, no qual pode optar por falhar. Em caso de falha, quaisquer efeitos que alterariam o alvo — por exemplo, concedendo vantagem ou desvantagem, aumentando a CA, reduzindo ou melhorando bônus de ataque e semelhantes — não afetam o tipo de rolagem escolhido, e ele realiza essas rolagens como se nada as estivesse melhorando ou penalizando.","higher":"Quando você conjura esta magia no 3º nível ou superior, pode escolher um alvo adicional dentro do alcance para cada nível do espaço acima do 2º.","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":597,"category":"Lyre's Guide to Retia","traits":[]},{"id":"lyre-writ-bombardment","name":"Escrito de Bombardeio","originalName":"Writ Bombardment","level":2,"school":"Conjuração","time":"1 ação","range":"18 metros","comp":"S","material":"","duration":"Instantânea","classes":"Inscritor","ritual":false,"concentration":false,"desc":"Você escreve uma linha de texto arcano descrevendo projéteis surgindo e sendo lançados contra até três alvos que possa ver a até 18 metros. Os projéteis disparam em direção a eles, e cada alvo deve realizar um teste de resistência de Destreza. Em caso de falha, cada um sofre 4d6 de dano de concussão; em caso de sucesso, sofre metade desse dano. Qualquer criatura que falhar por 5 pontos ou mais fica lenta até o fim do próximo turno dela.","higher":"Quando você conjura esta magia no 3º nível ou superior, para cada nível do espaço acima do 2º escolha uma das duas opções: o dano da magia aumenta em 1d6, ou você escolhe um alvo adicional dentro do alcance.","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":597,"category":"Lyre's Guide to Retia","traits":[]},{"id":"lyre-writ-bookmark","name":"Escrito de Marcador","originalName":"Writ Bookmark","level":1,"school":"Conjuração","time":"1 ação","range":"1,6 km","comp":"S","material":"","duration":"Concentração, até 1 rodada","classes":"Inscritor","ritual":false,"concentration":true,"desc":"Você cria um marcador invisível que se assemelha a um marcador de livro flutuante para quem consegue enxergar objetos invisíveis. A qualquer momento antes de a magia terminar, você pode usar sua reação para se teletransportar, junto de tudo que estiver carregando, de volta ao espaço onde deixou o marcador. O marcador não pode ser movido nem tocado enquanto esse espaço permanecer desocupado. Magias que removem efeitos mágicos podem ter o marcador como alvo se o conjurador souber que ele está ali. Para usar o teletransporte, você deve estar a até 1,6 km e no mesmo plano do marcador, e percebe se já não for possível se mover até esse espaço. Depois de usar este efeito para retornar ao local, a magia termina.","higher":"Quando você conjura esta magia no 2º nível ou superior, a duração aumenta para 1 minuto no 2º nível, 10 minutos no 3º, 1 hora no 4º, 10 horas no 5º, 1 dia no 6º, 1 mês no 7º, 1 ano no 8º e se torna permanente até ser utilizada no 9º. Se for conjurada no 5º nível ou superior, não exige mais concentração.","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":597,"category":"Lyre's Guide to Retia","traits":[]},{"id":"lyre-writ-cannon","name":"Escrito de Canhão","originalName":"Writ Cannon","level":5,"school":"Conjuração","time":"1 ação","range":"18 metros","comp":"S","material":"","duration":"Concentração, até 1 minuto","classes":"Inscritor","ritual":false,"concentration":true,"desc":"Você descreve um canhão em grandes detalhes, invocando o cano de um deles no ar atrás de você. O cano flutua próximo a você, carregado com três projéteis. Uma vez quando você o conjura e, nos turnos seguintes, como uma ação bônus, pode comandá-lo verbalmente para disparar enquanto aponta para um espaço que possa ver a até 18 metros. Ele mira nesse ponto e dispara um de seus projéteis. Todas as criaturas em um cubo de 4,5 metros centrado nesse espaço devem realizar um teste de resistência de Destreza, sofrendo 2d8 de dano de fogo e 2d8 de dano psíquico em caso de falha. Depois que todos os projéteis forem disparados, o canhão desaparece e a magia termina.","higher":"Quando você conjura esta magia no 6º nível ou superior, cria dois projéteis adicionais para cada nível do espaço acima do 5º.","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":597,"category":"Lyre's Guide to Retia","traits":[]},{"id":"lyre-writ-consecration","name":"Escrito de Consagração","originalName":"Writ Consecration","level":4,"school":"Evocação","time":"1 ação","range":"9 metros","comp":"S","material":"","duration":"Instantânea","classes":"Inscritor","ritual":false,"concentration":false,"desc":"Você escreve uma linha de texto sagrado e escolhe até seis criaturas a até 9 metros de você. Essas criaturas ouvem cânticos rosnados de seres celestiais, que as castigam com poder celestial. Seus alvos devem realizar um teste de resistência de Carisma, sofrendo 6d8 de dano radiante em caso de falha ou metade em caso de sucesso. Se forem corruptores, o dano radiante aumenta em 2d10.","higher":"Quando você conjura esta magia no 5º nível ou superior, para cada nível do espaço acima do 4º você pode aumentar o dano radiante em 1d8 ou escolher uma criatura adicional como alvo.","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":597,"category":"Lyre's Guide to Retia","traits":[]},{"id":"lyre-writ-forensic","name":"Escrito Forense","originalName":"Writ Forensic","level":3,"school":"Adivinhação","time":"1 minuto","range":"Toque","comp":"S","material":"","duration":"Concentração, até 10 minutos","classes":"Inscritor","ritual":false,"concentration":true,"desc":"Você escreve uma linha de texto arcano descrevendo o início de um flashback como se relatasse um efeito que tivesse testemunhado. Escolha um raio de 3 metros centrado em um ponto que toque e, em seguida, escolha um momento ocorrido na última semana. Projeções ilusórias de criaturas, objetos e acontecimentos que ocorreram nos 10 minutos seguintes ao momento escolhido se reproduzem dentro do raio, incluindo sons que se originaram nessa área. Criaturas que estavam protegidas de adivinhação por qualquer motivo não aparecem na projeção. Enquanto observa, você pode acelerar ou retroceder a reprodução como se estivesse percorrendo uma gravação, mas ela não pode projetar nada fora dos 10 minutos registrados, mesmo que você a acelere.","higher":"Quando você conjura esta magia no 4º nível ou superior, sua duração e a quantidade de tempo registrada aumentam. Tornam-se 1 hora com um espaço de 4º nível e 1 dia com um de 5º. Com um espaço de 6º nível, ela pode reproduzir acontecimentos de até um mês atrás; até meio ano no 7º, 5 anos no 8º e até 100 anos no 9º. Além disso, o raio da projeção aumenta em 1,5 metro para cada nível do espaço acima do 3º.","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":598,"category":"Lyre's Guide to Retia","traits":[]},{"id":"lyre-writ-entropy","name":"Escrito de Entropia","originalName":"Writ Entropy","level":3,"school":"Ilusão","time":"1 ação","range":"18 metros","comp":"S","material":"","duration":"Instantânea","classes":"Inscritor","ritual":false,"concentration":false,"desc":"Você escreve uma passagem descrevendo uma explosão de energia sobrenatural e escolhe um ponto a até 18 metros, fazendo surgir uma ilusão de outro mundo de uma erupção de poder cósmico. Todas as criaturas em um raio de 4,5 metros ao redor desse ponto devem realizar um teste de resistência de Inteligência, sofrendo 8d6 de dano psíquico em caso de falha. Qualquer criatura que falhar também se sente desacelerada por uma presença fria e semelhante ao vazio pairando sobre ela e, até o início do seu próximo turno, não pode realizar a ação Disparada nem fazer mais de um ataque com arma por turno, independentemente de características. Criaturas capazes de enxergar através de ilusões, como aquelas com visão verdadeira, obtêm sucesso automaticamente no teste de resistência contra este efeito.","higher":"Quando você conjura esta magia no 4º nível ou superior, o raio da esfera aumenta em 1,5 metro e o dano psíquico aumenta em 1d6 para cada nível do espaço acima do 3º.","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":598,"category":"Lyre's Guide to Retia","traits":[]},{"id":"lyre-writ-erase","name":"Escrito de Apagamento","originalName":"Writ Erase","level":2,"school":"Necromancia","time":"1 ação","range":"18 metros","comp":"S","material":"","duration":"Instantânea","classes":"Inscritor","ritual":false,"concentration":false,"desc":"Você copia uma passagem descrevendo o estado de saúde exato de uma criatura que possa ver a até 18 metros, e a passagem tenta impor esse estado. O alvo deve realizar um teste de resistência de Inteligência. Em caso de falha, perde todos os pontos de vida temporários que possui e sofre 2d8 de dano psíquico.","higher":"Quando você conjura esta magia no 3º nível ou superior, o dano psíquico aumenta em 1d8 e você pode escolher uma criatura adicional como alvo para cada nível do espaço acima do 2º.","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":598,"category":"Lyre's Guide to Retia","traits":[]},{"id":"lyre-writ-heroism","name":"Escrito de Heroísmo","originalName":"Writ Heroism","level":1,"school":"Encantamento","time":"1 ação","range":"9 metros","comp":"S","material":"","duration":"Concentração, até 1 minuto","classes":"Inscritor","ritual":false,"concentration":true,"desc":"Você escreve uma frase curta descrevendo as façanhas heroicas de uma criatura aliada que possa ver a até 9 metros e recebe três pontos de heroísmo atribuído associados ao alvo. A qualquer momento antes de a magia terminar, se testemunhar essa criatura realizar um teste de resistência, você pode gastar um ponto de heroísmo atribuído e escrever um pequeno adendo à frase, permitindo que ela role outro d20 e use esse resultado no lugar do d20 original caso seja maior. Você só pode fazer isso uma vez por teste fracassado e deve decidir antes de o Mestre anunciar se o teste obteve sucesso ou falhou. Quando seus pontos de heroísmo atribuído se esgotam, a magia termina.","higher":"Quando você conjura esta magia no 2º nível ou superior, recebe 1 ponto adicional de heroísmo atribuído e pode escolher 1 criatura adicional dentro do alcance para cada nível do espaço acima do 1º. Você deve dividir o total de pontos entre os alvos como desejar.","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":598,"category":"Lyre's Guide to Retia","traits":[]},{"id":"lyre-writ-horror","name":"Escrito de Horror","originalName":"Writ Horror","level":4,"school":"Encantamento","time":"1 ação","range":"18 metros","comp":"S","material":"","duration":"Instantânea","classes":"Inscritor","ritual":false,"concentration":false,"desc":"Você escreve uma passagem sobre uma criatura que possa ver a até 18 metros considerando você aterrorizante. A criatura deve realizar um teste de resistência de Inteligência. Em caso de falha, fica amedrontada por você durante 1 minuto. Enquanto estiver amedrontada por você e puder vê-lo, você pode usar uma ação bônus para escrever outra passagem sobre aterrorizá-la, fazendo-a realizar outro teste de Inteligência. Se falhar nesse teste adicional, ela sofre 2d12 de dano psíquico e deve usar sua reação para se mover até seu deslocamento para longe de você. A criatura pode repetir o teste de resistência de Inteligência ao final de cada um de seus turnos, encerrando o efeito em caso de sucesso.","higher":"Quando você conjura esta magia no 5º nível ou superior, pode escolher uma criatura adicional como alvo para cada nível do espaço acima do 4º. Você pode usar sua ação bônus para aterrorizar um único alvo ou sua ação para aterrorizar todos eles, mas não pode fazer ambos no mesmo turno.","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":598,"category":"Lyre's Guide to Retia","traits":[]},{"id":"lyre-writ-reappropriation","name":"Escrito de Reapropriação","originalName":"Writ Reappropriation","level":3,"school":"Conjuração","time":"1 minuto","range":"9 metros","comp":"V, S, M (um anel de mithril no valor de pelo menos 1.000 po, que a magia consome)","material":"um anel de mithril no valor de pelo menos 1.000 po, que a magia consome","duration":"Concentração, até 1 hora","classes":"Inscritor","ritual":false,"concentration":true,"desc":"Escolha como alvo um item mágico que possa ver dentro do alcance. Você escreve uma descrição desse item, permitindo recriá-lo e recriar seus efeitos em sua posse. Se estiver usando uma peça de equipamento que ocuparia o mesmo espaço, o item existente é enviado para um semiplano inofensivo até a magia terminar, quando então retorna. Você é considerado sintonizado com o item durante a duração se ele exigir sintonização, e essa sintonização não conta para seu limite normal de itens sintonizados; nenhuma outra criatura pode se sintonizar com ele. Enquanto estiver em sua posse, você é considerado proficiente com o item. Quando a magia termina, o item e seus efeitos em andamento desaparecem. A cópia não pode ativar efeitos que exijam uma ação ou ação bônus, nem produzir efeitos de magias. O item copiado deve ser raro, incomum ou comum.","higher":"Quando você conjura esta magia usando um espaço de 5º nível ou superior, pode recriar um item mais raro. Conjurada no 5º nível ou superior, pode recriar um item muito raro. No 8º nível, pode recriar um item de raridade lendária.","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":599,"category":"Lyre's Guide to Retia","traits":[]},{"id":"lyre-writ-recollection","name":"Escrito de Recordação","originalName":"Writ Recollection","level":1,"school":"Ilusão","time":"1 minuto","range":"18 metros","comp":"S","material":"","duration":"1 hora","classes":"Inscritor","ritual":false,"concentration":false,"desc":"Sobre uma superfície imóvel dentro do alcance, você cria uma projeção 2D animada com dimensões de 1,5 metro por 1,5 metro que emite um brilho suave, permitindo que seja vista no escuro. A projeção não possui som, mas reproduz sua perspectiva a partir da memória e mostra o que você viu durante um período de 1 minuto ocorrido no último mês. Você pode percorrer as imagens da recordação, pausando-as, desacelerando-as ou deixando-as reproduzir livremente à vontade. Qualquer coisa sobre a qual você tivesse incerteza visual e pequenos detalhes que não tenha percebido podem estar incorretos, borrados ou ausentes. A projeção permanece pela duração da magia ou desaparece quando você escolher.","higher":"Quando você conjura esta magia usando um espaço de 2º nível ou superior, pode escolher um dos efeitos a seguir para cada nível do espaço acima do 1º:\n• As dimensões da projeção são dobradas.\n• A duração da memória passa a 10 minutos e, em níveis mais altos, a 1 hora, depois 12 horas e depois 1 dia.\n• A duração da magia passa a 12 horas e, em níveis mais altos, a 1 dia e depois 1 semana.\n• Os efeitos sonoros da memória são incluídos e podem ser ouvidos por todos dentro de uma distância igual ao dobro das dimensões da projeção.\n• A memória pode ser extraída de até 6 meses atrás e, em níveis mais altos, de até 1 ano, 5 anos, 10 anos e então de qualquer momento da sua vida. Se esta magia for conjurada usando um espaço de 9º nível, você pode alterar a projeção para mostrar qualquer coisa que desejar como se fosse uma memória, incluindo os benefícios acima provenientes de conjurá-la em nível superior. Quando modificada dessa forma, ela não se beneficia dos detalhes da sua memória.","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":599,"category":"Lyre's Guide to Retia","traits":[]},{"id":"lyre-writ-seizure","name":"Escrito de Apreensão","originalName":"Writ Seizure","level":0,"school":"Ilusão","time":"1 ação","range":"9 metros","comp":"S","material":"","duration":"Instantânea","classes":"Inscritor","ritual":false,"concentration":false,"desc":"Você conjura uma narrativa na mente de um alvo dentro do alcance, obrigando-o a experimentar a sensação de dor física. O alvo deve realizar um teste de resistência de Inteligência, sofrendo 1d10 de dano psíquico em caso de falha.\nAprimoramento de Truque. O dano da magia aumenta para 2d10 quando você alcança o 5º nível, 3d10 no 11º e 4d10 no 17º. Ao conjurar a magia, você pode separar esses d10 para escolher criaturas adicionais dentro do alcance ao mesmo tempo, causando a cada alvo o número de d10 atribuído a ele como dano psíquico caso falhe no teste.","higher":"","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":599,"category":"Lyre's Guide to Retia","traits":[]},{"id":"lyre-writ-slumber","name":"Escrito de Sono","originalName":"Writ Slumber","level":2,"school":"Encantamento","time":"1 ação","range":"36 metros","comp":"S","material":"","duration":"Concentração, até 1 minuto","classes":"Inscritor","ritual":false,"concentration":true,"desc":"Você escreve uma linha de texto arcano e escolhe uma criatura que possa ver a até 36 metros. Ela deve realizar um teste de resistência de Inteligência. Em caso de falha, fica incapacitada por 1 minuto e entra em um estado de sonolência desperta. Enquanto estiver sob esse efeito, todos os ataques contra ela têm vantagem, e ela falha automaticamente em testes de resistência de Destreza e testes de Percepção. A criatura não fica inconsciente nem cai, mas se torna desfocada e exausta. É possível se comunicar com ela, porém ela só consegue responder com frases curtas e em grande parte incoerentes. Ao final do turno do alvo, ele pode repetir o teste de Inteligência, encerrando o efeito em caso de sucesso. Se a criatura sofrer dano ou for sacudida usando uma ação, o efeito termina imediatamente. Quando se recupera, ela se lembra de tudo que testemunhou.","higher":"Quando você conjura esta magia no 3º nível ou superior, pode escolher uma criatura adicional como alvo para cada nível do espaço acima do 2º.","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":599,"category":"Lyre's Guide to Retia","traits":[]},{"id":"lyre-wyrms-breath","name":"Sopro do Dragão","originalName":"Wyrm’s Breath","level":2,"school":"Transmutação","time":"1 ação bônus","range":"Toque","comp":"V, S, M (uma pimenta ardida)","material":"uma pimenta ardida","duration":"Concentração, até 1 minuto","classes":"Feiticeiro, Mago","ritual":false,"concentration":true,"desc":"Você toca uma criatura voluntária e a imbui com o poder de expelir energia mágica pela boca, desde que ela possua uma. Escolha ácido, frio, fogo, elétrico ou veneno. Até a magia terminar, a criatura pode usar uma ação para exalar energia do tipo escolhido em um cone de 4,5 metros. Cada criatura nessa área deve realizar um teste de resistência de Destreza, sofrendo 3d6 de dano do tipo escolhido em caso de falha ou metade em caso de sucesso.","higher":"Quando você conjura esta magia usando um espaço de 3º nível ou superior, pode escolher um dos efeitos a seguir para cada nível do espaço acima do 2º:\n• O dano aumenta em 1d6.\n• O comprimento do cone aumenta em 3 metros.\n• (2 níveis de espaço) O alvo pode usar a arma de sopro como uma ação ou ação bônus, mas apenas uma vez por turno.\n• A criatura que recebe a arma de sopro também ganha resistência ao tipo de dano dela.","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":599,"category":"Lyre's Guide to Retia","traits":["Legado 5.19"],"sourceNote":"A fonte identifica esta entrada como uma magia Legacy/revisada da edição 5.19; suas regras foram preservadas como uma versão própria de Lyre."},{"id":"lyre-yokai-possession","name":"Possessão Yokai","originalName":"Yokai Possession","level":9,"school":"Encantamento","time":"1 ação","range":"18 metros","comp":"V, S","material":"","duration":"Concentração, até 1 hora","classes":"Inscritor, Feiticeiro, Bruxo, Mago","ritual":false,"concentration":true,"desc":"Você conjura um espírito yokai aprisionando energias emocionais traumáticas dentro de uma carapaça mágica, que existe apenas como extensão da magia, e tenta vinculá-lo ao corpo de um alvo dentro do alcance. O alvo deve obter sucesso em um teste de resistência de Carisma ou fica enfeitiçado pela duração. Se o valor de Carisma da criatura for menor que metade da sua CD de magia, arredondado para baixo, ela falha automaticamente. Enquanto estiver enfeitiçada dessa forma, a criatura recebe pontos de vida temporários iguais à sua CD de magia multiplicada por 5. Você pode optar por gastar imediatamente outro espaço de magia de 8º nível ou inferior, concedendo ao alvo 1d12 pontos de vida temporários para cada nível desse espaço. Todos esses pontos de vida temporários desaparecem quando a magia termina. Enquanto o alvo estiver enfeitiçado, sua mente é suprimida e o espírito yokai assume o controle do corpo. A criatura segue suas ordens de forma explícita, e você pode dar comandos a ela telepaticamente. As estatísticas da criatura sofrem as seguintes alterações:\n• O alinhamento da criatura se torna igual ao seu.\n• A criatura se torna imune a qualquer efeito de enfeitiçamento, exceto este.\n• A criatura recebe um ataque de arma natural que pode realizar duas vezes por rodada como uma ação. Esse ataque corpo a corpo com arma usa seu modificador de ataque com magia e causa dano mágico perfurante ou cortante igual ao seu modificador do atributo de conjuração + 1d6 para cada categoria de tamanho acima de Pequeno.\n• A CA da criatura se torna igual à sua CD de magia, a menos que já fosse maior.\n• A criatura não pode recuperar pontos de vida nem pontos de vida temporários.\n• O tipo da criatura também se torna corruptor (yokai), além do tipo normal.\n• A criatura pode conjurar quaisquer magias que conheça, mas usa seus espaços de magia para fazê-lo.\n• A criatura recebe um dos seguintes tipos de movimento, à sua escolha quando conjurar a magia, com deslocamento igual ao deslocamento-base dela: voo, natação ou escalada. Sua anatomia muda durante a duração para acomodar essa alteração.\nQuando os pontos de vida temporários concedidos por esta magia forem reduzidos a 0 e a criatura ainda tiver pelo menos 1 ponto de vida, o alvo passa a realizar um teste de resistência de Carisma com vantagem ao final de cada um de seus turnos e sempre que sofrer dano. Em caso de sucesso, a magia termina e o espírito yokai dentro dele é destruído. Caso contrário, a magia não termina até sua duração acabar, mesmo se a criatura for reduzida a 0 pontos de vida. Se uma criatura obtiver sucesso no teste inicial ou em um teste posterior contra este efeito, fica imune a efeitos de enfeitiçamento provenientes do conjurador desta magia por 24 horas. Esta magia não pode ter mortos-vivos, corruptores, celestiais ou constructos como alvo. Se dissipar o bem e mal ou banimento forem conjurados sobre a criatura-alvo, a magia termina imediatamente e a criatura é tratada como tendo falhado no teste de resistência contra esse efeito.","higher":"","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":600,"category":"Lyre's Guide to Retia","traits":["Daemoturgia"]},{"id":"lyre-zone-of-imprisonment","name":"Zona de Aprisionamento","originalName":"Zone of Imprisonment","level":5,"school":"Abjuração","time":"1 ação","range":"Pessoal (raio de 6 metros)","comp":"V, S, M (30 centímetros de elos de corrente com os símbolos arcanos dracônicos para “prisioneiro” e “cativo” queimados neles)","material":"30 centímetros de elos de corrente com os símbolos arcanos dracônicos para “prisioneiro” e “cativo” queimados neles","duration":"Concentração, até 1 hora","classes":"Inscritor, Bruxo","ritual":false,"concentration":true,"desc":"Você cria diversas camadas de energia arcana que se espalham ao seu redor, preenchendo uma esfera de 6 metros de raio centrada em você com uma proteção mágica. Ela produz os seguintes efeitos:\nRaio de Vinculação. Qualquer criatura que entre nesse espaço pela primeira vez em seu turno ou inicie o turno dentro dele deve realizar um teste de resistência de Força. Em caso de falha, correntes crepitantes de poder arcano irrompem do chão, ou do ar ao redor de você, e prendem o alvo no lugar. A criatura fica impedida e pode usar uma ação para realizar um teste de Força contra sua CD de magia, libertando-se em caso de sucesso. Se a criatura presa realizar esse teste fora do raio da proteção ou for Enorme ou maior, tem vantagem no teste para se libertar.\nCorrentes Protetoras. Quando você for alvo de um ataque que possa ver, pode usar sua reação para manifestar proteções e correntes defensivas que bloqueiam o golpe, adicionando seu modificador do atributo de conjuração à sua Classe de Armadura até o fim desse turno. Se isso fizer um ataque com arma, realizado com uma arma dentro do raio da esfera, errar você, essa arma fica presa no lugar e não pode ser usada até o fim do turno.\nCorrentes de Agarrão. Você pode usar sua ação bônus para projetar as correntes da magia contra uma criatura que possa ver a até 30 metros, realizando um ataque à distância com magia. Em um acerto, a criatura fica impedida como pelo efeito Raio de Vinculação, e você pode puxá-la até 15 metros em linha reta em sua direção.\nMover Criatura. Você pode usar sua ação bônus para mover cada criatura impedida pelos efeitos desta magia em até 7,5 metros em qualquer direção, inclusive para o ar. Se for erguida do chão, ela fica suspensa no lugar.","higher":"","source":"Lyre's Guide to Retia — Land of Industry","sourcePage":600,"category":"Lyre's Guide to Retia","traits":["Convocação Cromática"],"sourceNote":"Regra de grupo — Convocação Cromática: quando a magia mencionar energia ou dano cromático, escolha fogo, frio, ácido, elétrico ou veneno; a escolha vale para todas as ocorrências daquela invocação. Ao conjurar uma magia da Convocação Cromática, faça um teste com o atributo de conjuração (CD 10 + nível da magia). Em uma falha, seu máximo de pontos de vida é reduzido em duas vezes o nível da magia até concluir um Descanso Longo; a fonte chama esse efeito de Queima da Alma. A característica de conjuração da criatura pode dispensá-la desse teste."}];
window.GRIMORIO_REGISTRY.registerSpellCatalog({id:'lyre-spells',sourceId:'lyre',spells:window.GRIMORIO_LYRE_SPELLS});
